(window.GIM_TP=window.GIM_TP||{})["Z.Vayeshev.0"]={"from":0,"a":[[["וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן. רִבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים לה) רַבּוֹת רָעוֹת צַדִּיק וּמִכֻּלָּם יַצִּילֶנוּ יְיָ. תָּא חֲזֵי, כַּמָּה מְקַטְרְגִין אִית לֵיהּ לְבַר נָשׁ מִיּוֹמָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב בֵּיהּ נִשְׁמָתָא (ד\"א ל\"ג לבר נש) (לאתקיימא) בְּהַאי עַלְמָא. דְּכֵיוָן דְּנָפִיק בַר נָשׁ לַאֲוִירָא דְעַלְמָא, מִיָּד אִזְדַּמַּן לְאִשְׁתַּתְּפָא בַּהֲדֵיהּ יֵצֶר הָרָע כְּמָה דְאִתְּמָר. דִּכְתִיב, (בראשית ד׳:ז׳) לַפֶּתַח חַטָּאת רוֹבֵץ וְגו'. וּכְדֵין אִשְׁתַּתַּף בַּהֲדֵיהּ יֵצֶר הָרָע.","וְתָּא חֲזֵי, דְּהָכִי הוּא, דְּהָא בְּעִירֵי מִיּוֹמָא דְּאִתְיַלִּידוּ, כֻּלְּהוּ נָטְרֵי גַרְמַיְיהוּ, וְעָרְקִין מִן גּוֹ נוּרָא, וּמִן כָּל אַתְרִין בִּישִׁין. וּבַר נָשׁ, מִיָּד אָתֵי לַאֲרָמָא גַּרְמֵיהּ גּוֹ נוּרָא, בְּגִין דְּיֵצֶר הָרָע שָׁארֵי בְּגַוִּיהּ, וּמִיָּד אַסְטֵי לֵיהּ לְאָרְחָא בִישָׁא.","וְאוֹקִימְנָא דִּכְתִיב, (קהלת ד׳:י״ג) טוֹב יֶלֶד מִסְכֵּן וְחָכָם מִמֶּלֶךְ זָקֵן וּכְסִיל אֲשֶׁר לא יָדַע לְהִזָּהֵר עוֹד. טוֹב יֶלֶד, דָּא הוּא יֵצֶר טוֹב דְּהוּא יֶלֶד מִיּוֹמִין זְעִירִין עִמֵּיהּ דְּבַר נָשׁ, דְּהָא מִתְּלֵיסַר שְׁנִין וָאֵילָךְ (עמיה) כְּמָה דְאִתְּמָר."],[[0,"וישב יעקב בארץ מגורי אביו וגו':","ר' חייא פתח ואמר, רבות רעות צדיק וגו' כמה מקטרגים יש לו לאדם מיום שנתן לו הקב\"ה נשמה בעולם הזה. דכיון שיצא האדם לאויר העולם, מיד נזדמן יצר הרע להשתתף עמו, כמו שלמדנו, שכתוב, לפתח חטאת רובץ, כי אז נשתתף עמו היצה\"ר."],[1,"ות\"ח דהכי הוא וכו':","ובוא וראה, שכן הוא, כי הבהמות, מיום שנולדו, כולן שומרות את עצמן ובורחות מאש ומכל מקומות הרעים. והאדם, כשנולד, מיד בא להשליך עצמו לתוך האש, והוא משום שהיצה\"ר שורה בתוכו, ומיד מסיתו לדרך רע."],[2,"ואוקימנא, דכתיב, טוב ילד מסכן וגו': טוב ילד,","זהו יצר הטוב, שהוא ילד מימים מועטים עם האדם, כי מי\"ג שנים ואילך הוא עם האדם כמו שלמדנו."]],[[0,"","וַיִּשֱׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן. רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים לד) רַבּוֹת רָעוֹת צַדִּיק וּמִכֻּלָּם יַצִּילֶנּוּ ה' בֹּא רְאֵה כַּמָּה מְקַטְרְגִים יֵשׁ לוֹ לָאָדָם מִן הַיּוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן בּוֹ נְשָׁמָה (ד\"א לאדם) (להתקים) בָּעוֹלָם הַזֶּה, שֶׁכֵּיוָן שֶׁאָדָם יוֹצֵא לַאֲוִיר הָעוֹלָם, מִיָּד מִזְדַּמֵּן לְהִשְׁתַּתֵּף עִמּוֹ יֵצֶר הָרָע, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב (בראשית ד) לַפֶּתַח חַטָּאת רֹבֵץ וְגוֹ', וְאָז מִשְׁתַּתֵּף עִמּוֹ יֵצֶר הָרָע."],[1,"","וּבֹא וּרְאֵה שֶׁכָּךְ הוּא, שֶׁהֲרֵי הַבְּהֵמוֹת מִיּוֹם שֶׁנּוֹלָדִים, שׁוֹמְרִים אֶת עַצְמָם וּבוֹרְחִים מִתּוֹךְ הָאֵשׁ וּמִכָּל הַמְּקוֹמוֹת הָרָעִים, וְאָדָם מִיָּד בָּא לִזְרֹק אֶת עַצְמוֹ לְתוֹךְ הָאֵשׁ, מִשּׁוּם שֶׁיֵּצֶר הָרָע שָׁרוּי בְּתוֹכוֹ, וּמִיָּד מֵסִיט אוֹתוֹ לְדֶרֶךְ רָעָה."],[2,"","וּבֵאַרְנוּ, שֶׁכָּתוּב (קהלת ד) טוֹב יֶלֶד מִסְכֵּן וְחָכָם מִמֶּלֶךְ זָקֵן וּכְסִיל אֲשֶׁר לֹא יָדַע לְהִזָּהֵר עוֹד. טוֹב יֶלֶד - זֶהוּ יֵצֶר הַטּוֹב, שֶׁהוּא יֵצֶר טוֹב שֶׁהוּא יֶלֶד מִיָּמִים מוּעָטִים עִם הָאָדָם, שֶׁהֲרֵי מִשְּׁלֹשָׁה עָשָׂר שָׁנִים וִאֵילָךְ (עמו), כְּמוֹ שֶׁנִּתְבָּאֵר."]]],[["מִמֶּלֶךָ זָקֵן וּכְסִיל. מִמֶּלֶךְ, דָּא הוּא יֵצֶר הָרָע דְּאִיהוּ אִקְרֵי מֶלֶךְ וְשַׁלִּיט בְּעַלְמָא עַל בְּנֵי נָשָׁא. זָקֵן וּכְסִיל, דְּאִיהוּ זָקֵן וַדַּאי, כְּמָה דְאוּקְמוּהָ, דְּכַד אִתְיְלִיד בַר נָשׁ וְנָפִיק לַאֲוִירָא דְעַלְמָא אִיהוּ אִזְדַּמַּן עִמֵּיהּ דְּבַר נָשׁ. וְעַל דָּא אִיהוּ מֶלֶךְ זָקֵן וּכְסִיל.","אֲשֶׁר לא יָדַע לְהִזָּהֵר עוֹד, לְהַזְהִיר לָא כְּתִיב, אֶלָּא לְהִזָּהֵר, בְּגִין דְּאִיהוּ כְסִיל. וְעֲלֵיהּ אָמַר שְׁלֹמֹה עָלָיו הַשָׁלוֹם (קהלת ב׳:י״ד) וְהַכְּסִיל בַּחשֶׁךְ הוֹלֵךְ. דְּהָא מֵסּוּסִיתָא דְּחשֶׁךְ קָא אַתְיָא וְלֵית לֵיהּ נְהוֹרָא לְעָלְמִין.","רִבִּי שִׁמְעוֹן אָמַר, תָּא חֲזֵי, כְּתִיב טוֹב יֶלֶד מִסְכֵּן וְחָכָם. מַאן יֶלֶד מִסְכֵּן, הָא אוּקְמוּהָ וְאִתְּמָר דְּאִיהוּ יֵצֶר טוֹב. אֲבָל טוֹב יֶלֶד, הֲדָא הוּא דִכְתִיב, (תהילים ל״ז:כ״ה) נַעַר הָיִיתִי גַּם זָקַנְתִּי. וְדָא הוּא נַעַר דְּאִיהוּ יֶלֶד מִסְכֵּן דְּלֵית לֵיהּ מִגַּרְמֵיהּ כְּלוּם. וְאַמַּאי אִקְרֵי נַעַר, בְּגִין דְּאִית לֵיהּ חַדְתּוּ דְסִיהֲרָא דְּמִתְחַדְּשָׁא תָּדִיר, וְתָדִיר אִיהוּ יֶלֶד מִסְכֵּן כְּמָה דְּאֲמְרָן. וְחָכָם, בְּגִין דְּחָכְמָה שַׁרְיָא בֵּיהּ.","מִמֶּלֶךָ זָקֵן, דָּא הוּא יֵצֶר הָרָע כְּמָה דְאִתְּמָר. דְּהָא מִן יוֹמָא דְּהֲוָה לָא נָפַק מִמְּסָאֲבוּתֵיהּ לְעָלְמִין, וְאִיהוּ כְסִיל. דְּכָל אָרְחוֹי אִינוּן לְאֹרַח בִּישָׁא, וְאָזִיל וְסָטֵי לִבְנִי נָשָׁא וְלָא יָדַע לְאִזְדַּהֲרָא. וְאִיהוּ אָתֵי עִם בַר נָשׁ בְּתִסְקוּפִין בְּגִין לְאַסְטָאָה לוֹן מֵאֹרַח טָבָא לְאֹרַח בִּישָׁא.","תָּא חֲזֵי, עַל דָּא אַקְדִים עִם בַּר נָשׁ בְּיוֹמָא דְאִתְיְלִיד בְּגִין דִּיְהֵימִין לֵיהּ. דְּהָא כַּד אָתֵי יֵצֶר טוֹב לָא יָכִיל בַר נָשׁ לִמְהֵימְנָא לֵיהּ וְדָמֵי עֲלֵיהּ כְּמָטוּלָא. כְּגַוְונָא דָא תָּנִינָן, מַאן הוּא רָשָׁע עָרוּם, דָּא הוּא מַאן דְּאַקְדִּים לְאַטְעָנָא מִלּוֹי לְקַמֵּי דַיְינָא עַד לָא יֵיתֵי חַבְרֵיהּ מָארֵי דְדִינָא. כְּמָה דְאַתְּ אָמֵר, (משלי י״ח:י״ז) צַדִּיק הָרִאשׁוֹן בְּרִיבוֹ וְגו'.","כְּגַוְונָא דָא (הוא נ\"א האי) רָשָׁע עָרוּם, כְּמָה דְאַתְּ אָמֵר, (בראשית ג׳:א׳) וְהַנָּחָשׁ הָיָה עָרוּם. וְהוּא אַקְדִּים וְשָׁרֵי עִמֵּיהּ דְּבַר נָשׁ עַד לָא יֵיתֵי חַבְרֵיהּ לְאַשְׁרָאָה עֲלֵיהּ. וּבְגִין דְּאִיהוּ אַקְדִּים וְהָא אַטְעִין טַעֲנָתֵיהּ עִמֵּיהּ, כַּד אָתֵי חַבְרֵיהּ דְּאִיהוּ יֵצֶר הַטּוֹב, אַבְאִישׁ לֵיהּ לְבַר נָשׁ בַּהֲדֵיהּ וְלָא יָכִיל לְזָקְפָא רֵישֵׁיהּ, כְּאִילּוּ אַטְעִין עַל כִּתְפֵיהּ כָּל מָטוֹלִין דְּעַלְמָא. בְּגִין הַהוּא רָשָׁע עָרוּם דְאַקְדִּים עִמֵּיהּ. וְעַל דָּא אָמַר שְׁלמֹה (קהלת ט׳:ט״ז) וְחָכְמַת הַמִּסְכֵּן בְּזוּיָה וּדְבָרָיו אֵינָם נִשְׁמָעִים, בְּגִין דְּהָא אַקְדִים אָחֳרָא.","וְעַל דָּא כָּל דַיְינֵי דְּקַבִּיל מִבַּר נָשׁ מִלָּה עַד לָא יֵיתֵי חַבְרֵיהּ, כְּאִילּוּ מְקַבֵּל עֲלֵיהּ טַעֲוָוא אָחֳרָא לִמְהֵימְנוּתָא. אֶלָּא (משלי י״ח:י״ז) וּבָא רֵעֵהוּ וַחֲקָרוֹ, וְדָא הוּא אֹרַח דְּבַר נָשׁ זַכָּאָה, דְּהָא בַר נָשׁ זַכָּאָה דָּא הוּא, דְּלָא הֵימִין לְהַהוּא רָשָׁע עָרוּם דְּיֵצֶר הָרָע, עַד דְּיֵיתֵי חַבְרֵיהּ דְּאִיהוּ יֵצֶר טוֹב. וּבְגִין דָא בְּנֵי נָשָׁא אִינוּן כָּשְׁלִין לְעַלְמָא דְאָתֵי.","אֲבָל הַהוּא זַכָּאָה דְּאִיהוּ דָּחִיל לְמָארֵיהּ, כַּמָּה בִּישִׁין סָבִיל בְּהַאי עַלְמָא בְּגִין דְּלָא יְהֵימִין וְלָא יִשְׁתַּתַּף בְּהַהוּא יֵצֶר הָרָע. וְקוּדְשָׁא בְּרִיךְ הוּא שֵׁזִיב לֵיהּ מִכֻּלְּהוּ, הֲדָא הוּא דִכְתִיב, (תהלים לה) רַבּוֹת רָעוֹת צַדִּיק וּמִכֻּלָּם יַצִּילֶנוּ יְיָ. רַבּוֹת רָעוֹת לַצַּדִּיק לָא כְּתִיב, אֶלָּא צַדִּיק. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בֵּיהּ. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהַהוּא בַר נָשׁ וְשֵׁזִיב לֵיהּ מִכֹּלָּא בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי, זַכָּאָה חוּלָקֵיהּ.","תָּא חֲזֵי, כַּמָּה בִּישִׁין עָבְרוּ עֲלֵיהּ דְּיַעֲקֹב, בְּגִין דְּלָא יִתְדַּבַּק בְּהַהוּא יֵצֶר הָרָע וְיִתְרְחַק מֵחוּלָקֵיהּ. וּבְגִין כָּךְ סָבִיל כַּמָּה עוֹנְשִׁין כַּמָּה בִּישִׁין וְלָא שָׁקִיט. פָּתַח וְאָמַר, (איוב ג׳:כ״ו) לא שָׁלַוְתִּי וְלֹא שָׁקַטְתִּי וְלֹא נַחְתִּי וַיָּבֹא רֹגֶז. תָּא חֲזֵי, כַּמָּה בִּישִׁין סָבְלִין צַדִּיקַיָא בְּהַאי עַלְמָא. בִּישִׁין עַל בִּישִׁין, כְּאֵבִין עַל כְּאֵבִין. בְּגִין לְמִזְכֵּי לוֹן לְעַלְמָא דְאָתֵי.","יַעֲקֹב כַּמָּה סָבִיל בִּישִׁין עַל בִּישִׁין תָּדִיר, כְּמָה דְאַתְּ אָמֵר לֹא שָׁלַוְתִּי, בְּבֵיתָא דְלָבָן, וְלָא יָכִילְנָא לְאִשְׁתְּזָבָא מִנֵּיהּ. וְלא שָׁקַטְתִּי, מֵעֵשָׂו. מֵהַהוּא צַעֲרָא דְּצִעֵר לִי הַהוּא מְמַנָּא דִילֵיהּ, וּלְבָתַר דְּחִילוּ דְעֵשָׂו. וְלֹא נַחְתִּי, מִן דִּינָה וּמִן שְׁכֶם.","וַיָּבֹא רֹגֶז, דָּא רוּגְזָא וְעִרְבּוּבְיָא דְיוֹסֵף דְּאִיהוּ קַשְׁיָא מִכֻּלְּהוּ, מִגּוֹ רְחִימוּתָא דְיַעֲקֹב לְגַבֵּי דְיוֹסֵף דְּאִיהוּ רָזָא דִבְרִית, עָאל בְּמִצְרַיִם. בְּגִין דִּלְבָתַר כְּתִיב, (שמות ו׳:ה׳) וָאֶזְכֹּר אֶת בְּרִיתִי, לְאִשְׁתַּכָּחָא שְׁכִינְתָּא (נ\"א שמש) תַּמָּן בַּהֲדֵיהּ."],[[0,"ממלך זקן וכסיל:","ממלך, זהו היצר הרע, שהוא נקרא מלך ושליט בעולם על בני אדם. \u0003זקן וכסיל,\u0004 הוא ודאי זקן כמו שבארוהו, שמיום שהאדם נולד ויצא לאויר העולם, הוא נמצא עם האדם, וע\"כ הוא מלך זקן וכסיל."],[1,"אשר לא ידע להזהר עוד:","לא כתיב להזהיר, אלא להזהר, משום שהוא כסיל, ועליו אמר שלמה, והכסיל בחשך הולך. כי מפסולת החשך הוא בא. ואין לו אור לעולם אבל מי שאינו יודע להזהיר לאחרים אינו נחשב עוד לכסיל מחמת זה."],[2,"ר' שמעון אמר וכו':","רש\"א, בוא וראה, כתוב, טוב ילד מסכן וחכם. ושואל, מי הוא ילד מסכן. ואומר, הנה בארוה, ולמדנו, שהוא יצר הטוב. אבל \u0003טוב ילד\u0004, זהו שכתוב, נער הייתי גם זקנתי. וזהו נער שהוא ילד מסכן. שאין לו מעצמו כלום. ולמה נקרא נער. הוא משום שיש לו חידוש הלבנה, שהיא מתחדשת תמיד, והוא תמיד ילד מסכן, כמו שאמרנו. וחכם, משום שהחכמה שורה בו."],[2,"","פירוש. ב' מצבים יש אל הנוקבא, א) הוא זמן שליטתה עצמה, שאז גדולה כמו ז\"א, וזהו מצב הארת החכמה שבה, אלא שאינה מאירה מטעם חוסר אור החסדים. ב) הוא זמן הארתה, על ידי זווגה עם ז\"א, שאז מוכרחת להתמעט עד לנקודה, ואין לה אז מעצמה כלום, ומקבלת הכל מז\"א. ומצב הזה היא מצב הארת החסדים שבה. והנוקבא מתלבשת ומאירה במלאך מטטרון מב' מצבים אלו. וכשהוא מקבל מצב ב' של הנוקבא, שהוא הארת החסדים אומר מטטרון, \u0003נער הייתי\u0004, וכן נקרא \u0003ילד,\u0004 כי הארת החסדים ה\"ס ו\"ק המכונה נער או ילד. וכן נקרא \u0003מסכן,\u0004 מפני שבמצב הזה מתמעטת הנוקבא עד לנקודה ואין לה מעצמה כלום. וז\"ש, \u0003ודא הוא נער, דאיהו ילד מסכן, דלית ליה מגרמיה כלום.\u0004 דהיינו כמבואר. וכשהוא מקבל ממצב הא' של הנוקבא, שהוא זמן שליטתה עצמה והיא גדולה כמו ז\"א שהוא מצב הארת החכמה שבה, אז אומר מטטרון \u0003גם זקנתי,\u0004 כי איזה זקן, זהו מי שקנה חכמה. וכן נקרא \u0003חכם\u0004 וז\"ש \u0003וחכם, בגין דחכמה שריא ביה.\u0004 כמבואר."],[2,"","ושואל, \u0003ואמאי אקרי נער,\u0004 למה נקרא המלאך מטטרון תמיד בשם \u0003נער,\u0004 ולא זקן, הרי הוא אמר, \u0003גם זקנתי,\u0004 היה לו להקרא זקן ומשיב, \u0003בגין דאית ליה חדתו דסיהרא, דמתחדשא תדיר,\u0004 משום שיש לו התחדשות הלבנה, שהיא הנוקבא, שה\"ס זווגה עם ז\"א, דהיינו מצב הב', הנ\"ל, שהיא מצב הארת החסדים שבה, הנבחן לו\"ק ונקרא נער, \u0003דמתחדשא תדיר,\u0004 ומצב ההתחדשות נוהג בה תמיד, \u0003ותדיר איהו ילד מסכן,\u0004 דהיינו בקביעות, וע\"כ נקרא נער ולא זקן כי הזקנה שמקבל ממצב הא', שהוא מצב שליטתה עצמה, אין זה בו תמיד, וע\"כ אינו נקרא על שמו."],[3,"ממלך זקן:","זהו היצר הרע, הנמשך מן הלעומת של מטטרון, הנקרא אדם בליעל, כמו שלמדנו, שמיום שהיה, לא יצא מטומאתו לעולם. והוא \u0003כסיל,\u0004 שכל דרכיו הם לדרך הרע, והולך ומדיח בני אדם, ואינו יודע להזהר, והוא בא בעלילה עם בני אדם, כדי להדיח אותם מדרך הטוב אל דרך הרע."],[4,"ת\"ח על דא וכו':","בוא וראה, על כן הקדים עצמו היצר הרע להתחבר עם האדם מיום שנולד בו, בכדי שיאמין לו, וכשיבוא אח\"כ היצר הטוב אין האדם יכול להאמינו ודבריו דומים עליו למשא."],[4,"כגוונא דא תנינן וכו':","כעין זה למדנו, איזה הוא רשע ערום, זה הוא, מי שמקדים עצמו לטעון דבריו לפני הדיין מטרם שיבא חברו בעל הדין. כמש\"א, צדיק הראשון בריבו וגו'."],[5,"כגוונא דא האי וגו':","כעין זה, רשע ערום זה, דהיינו היצר הרע, כמש\"א, והנחש היה ערום, גם הוא מקדים ושורה באדם מטרם שיבא חברו, יצר הטוב, לשרות בו, ומשום שהקדים וכבר טען טענותיו לפניו, כשיבא אח\"כ חברו, שהוא יצר הטוב, רע לאדם להיות עמו, ואינו יכול להרים ראשו כאלו הטעין על כתפו כל המשאות שבעולם. וכל זה הוא, משום שהרשע ערום הקדים עצמו. ועל זה אמר שלמה, וחכמת המסכן בזויה ודבריו אינם נשמעים, משום שהקדימו האחר."],[6,"וע\"ד כל דיינא וכו':","וע\"כ, כל דיין המקבל דבריו של בעל דין, מטרם שיבא חברו, דומה כאלו מקבל עליו אל אחר להאמין בו, אלא ובא רעהו וחקרו, כלומר אחר שיבא רעהו אז ישמע טענותיו. וזהו דרכו של אדם צדיק, כי אדם צדיק, הוא, מי שלא האמין לאותו רשע ערום, שהוא יצר הרע, משום שהקדים טענותיו, מטרם שיבא חברו, שהוא יצר הטוב. שמקיים הכ', ובא רעהו וחקרו. ובדבר זה אנשים נכשלים מלזכות לעולם הבא."],[7,"אבל האי זכאה וכו':","אבל צדיק ההוא, שהוא ירא את רבונו, כמה רעות הוא סובל בעולם הזה, כדי שלא יאמין ולא ישתתף עם היצר הרע, והקב\"ה מצילו מכולם. זהו שכתוב, רבות רעות צדיק ומכולם יצילנו ה', רבות רעות לצדיק לא כתוב, אלא רבות רעות צדיק, שזה יורה שפירושו הוא, שהסובל \u0003רבות רעות\u0004 הוא \u0003צדיק,\u0004 משום שהקב\"ה חפץ בו, כי הרעות שסובל, מרחיקות אותו מן יצר הרע כנ\"ל. ומשום זה הקב\"ה חפץ באדם ההוא, ומציל אותו מכולם, בעולם הזה ובעולם הבא. אשרי חלקו."],[8,"ת\"ח כמה בישין וכו':","בוא וראה כמה רעות עברו על יעקב כדי שלא יתדבק ביצר הרע ההוא, ויתרחק מחלקו, ומשום זה סבל כמה עונשים כמה רעות ולא שקט."],[8,"פתח ואמר לא שלותי וגו':","בוא וראה, כמה רעות סובלים הצדיקים בעולם הזה, רעות על רעות מכאובים על מכאובים, כדי לזכותם לעולם הבא."],[9,"יעקב כמה סביל וכו':","יעקב, כמה סבל תמיד רעות על רעות, כמש\"א, \u0003לא שלותי,\u0004 בבית לבן, ולא יכולתי להנצל ממנו. \u0003ולא שקטתי,\u0004 מעשו, מאותו הצער שציער אותי הממונה שלו. ואח\"כ הפחד מעשו עצמו. \u0003ולא נחתי,\u0004 מן דינה ומן שכם."],[10,"ויבא רגז:","זה הוא הרגז והמבוכה של יוסף, שהוא קשה מכולם, כי מתוך אהבתו של יעקב אל יוסף, שה\"ס הברית, נכנס יעקב למצרים. ועל כן אהב אותו כל כך, משום שלאח\"כ כתוב, ואזכר את בריתי, שכל הגאולה היה בשבילו, להיות השכינה נמצאת שם עמו. עם הברית, שהוא יוסף, וע\"כ היה המבוכה של יוסף, קשה עליו יותר מכל הצרות שבאו עליו."]],[[0,"","מִמֶּלֶךָֹ זָקֵן וּכְסִיל. מִמֶּלֶךְ - זֶה הוּא יֵצֶר הָרָע, שֶׁהוּא נִקְרָא מֶלֶךְ וְשַׁלִּיט בָּעוֹלָם עַל בְּנֵי אָדָם. זָקֵן וּכְסִיל - שֶׁהוּא זָקֵן וַדַּאי, כְּמוֹ שֶׁבֵּאֲרוּהוּ, שֶׁכַּאֲשֶׁר אָדָם נוֹלָד וְיוֹצֵא לַאֲוִיר הָעוֹלָם, הוּא מִזְדַּמֵּן עִם הָאָדָם, וְעַל כֵּן הוּא מֶלֶךְ זָקֵן וּכְסִיל."],[1,"","אֲשֶׁר לֹא יָדַע לְהִזָּהֵר עוֹד, לֹא כָתוּב לְהַזְהִיר אֶלָּא לְהִזָּהֵר, מִשּׁוּם שֶׁהוּא כְּסִיל, וְעָלָיו אָמַר שְׁלֹמֹה, עָלָיו הַשָּׁלוֹם, (קהלת ב) וְהַכְּסִיל בַּחֹשֶׁךְ הוֹלֵךְ, שֶׁהֲרֵי מִפְּסֹלֶת הַחֹשֶׁךְ הוּא בָּא, וְאֵין לוֹ אוֹר לְעוֹלָמִים."],[2,"","רַבִּי שִׁמְעוֹן אָמַר, בּא רְאֵה, כָּתוּב טוֹב יֶלֶד מִסְכֵּן וְחָכָם, מִי זֶה יֶלֶד מִסְכֵּן? הֲרֵי בֵּאֲרוּהָ, וְנִתְבָּאֵר שֶׁהוּא יֵצֶר טוֹב. אֲבָל טוֹב יֶלֶד, זֶהוּ שֶׁכָּתוּב (תהלים לז) נַעַר הָיִיתִי גַּם זָקַנְתִּי, וְזֶה הוּא נַעַר שֶׁהוּא יֶלֶד מִסְכֵּן, שֶׁאֵין לוֹ מֵעַצְמוֹ כְּלוּם. וְלָמָּה נִקְרָא נַעַר? מִשּׁוּם שֶׁיֵּשׁ לוֹ חִדּוּשׁ הַלְּבָנָה שֶׁתָּמִיד מִתְחַדֶּשֶׁת, וְתָמִיד הוּא יֶלֶד מִסְכֵּן, כְּמוֹ שֶׁאָמַרְנוּ. וְחָכָם, מִשּׁוּם שֶׁשּׁוֹרָה בּוֹ חָכְמָה."],[3,"","מִמֶּלֶךָ זָקֵן - זֶהוּ יֵצֶר הָרָע, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁהֲרֵי מִיּוֹם שֶׁהָיָה לֹא יָצָא מִטֻּמְאָתוֹ לְעוֹלָמִים. וְהוּא כְּסִיל, שֶׁכָּל דְּרָכָיו הֵם לְדֶרֶךְ רָעָה, וְהוֹלֵךְ וּמְסַטֶּה אֶת בְּנֵי הָאָדָם וְלֹא יוֹדֵעַ לְהִזָּהֵר, וְהוּא בָּא עִם אָדָם בַּעֲלִילוֹת כְּדֵי לְהַסְטוֹתָם מִדֶּרֶךְ טוֹבָה לְדֶרֶךְ רָעָה."],[4,"","בֹּא רְאֵה, עַל זֶה מַקְדִּים עִם אָדָם בַּיּוֹם שֶׁנּוֹלָד, כְּדֵי שֶׁיַּאֲמִין לוֹ, שֶׁהֲרֵי כְּשֶׁבָּא יֵצֶר הַטּוֹב, לֹא יָכוֹל הָאָדָם לְהַאֲמִין לוֹ, וְדוֹמֶה עָלָיו כְּמַעֲמָסָה. כְּמוֹ זֶה שָׁנִינוּ, מִי הוּא רָשָׁע עָרוּם? זֶהוּ מִי שֶׁמַּקְדִּים לִטְעֹן דְּבָרָיו לִפְנֵי הַדַּיָּן טֶרֶם יָבֹא חֲבֵרוֹ בַּעַל הַדִּין, כְּמוֹ שֶׁנֶּאֱמַר (משלי יח) צַדִּיק הָרִאשׁוֹן בְּרִיבוֹ וְגוֹ'."],[5,"","כְּמוֹ זֶה (הוא נ\"א הזה) רָשָׁע עָרוּם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ג) וְהַנָּחָשׁ הָיָה עָרוּם, וְהוּא מַקְדִּים וְשׁוֹרֶה עִמּוֹ שֶׁל אָדָם בְּטֶרֶם יָבֹא חֲבֵרוֹ לִשְׁרוֹת עָלָיו. וּמִשּׁוּם שֶׁהוּא מַקְדִּים, וְהִנֵּה טוֹעֵן טַעֲנָתוֹ עִמּוֹ - כְּשֶׁבָּא חֲבֵרוֹ, שֶׁהוּא יֵצֶר הַטּוֹב, מֵרֵעַ אֶת הָאָדָם עִמּוֹ וְלֹא יָכוֹל לִזְקֹף רֹאשׁוֹ כְּאִלּוּ הִטְעִין עַל כְּתֵפוֹ כָּל הַמַּשָּׂאוֹת שֶׁל הָעוֹלָם בִּגְלַל אוֹתוֹ רָשָׁע עָרוּם שֶׁהִקְדִּים עִמּוֹ. וְעַל זֶה אָמַר שְׁלֹמֹה (קהלת ט) וְחָכְמַת הַמִּסְכֵּן בְּזוּיָה וּדְבָרָיו אֵינָם נִשְׁמָעִים, מִשּׁוּם שֶׁהִנֵּה הִקְדִּים אַחֵר."],[6,"","וְעַל כֵּן, כָּל דַּיָּן שֶׁמְּקַבֵּל מֵאָדָם דָּבָר בְּטֶרֶם יָבֹא חֲבֵרוֹ, כְּאִלּוּ קִבֵּל עָלָיו תּוֹעֵבָה אַחֶרֶת לָאֱמוּנָה, אֶלָּא (משלי שם) וּבָא רֵעֵהוּ וַחֲקָרוֹ, וְזֶה הוּא דֶּרֶךְ שֶׁל אָדָם צַדִּיק. שֶׁהֲרֵי הָאָדָם הַצַּדִּיק הַזֶּה שֶׁלֹּא הֶאֱמִין לְאוֹתוֹ רָשָׁע עָרוּם שֶׁל יֵצֶר הָרָע בְּטֶרֶם יָבֹא חֲבֵרוֹ, שֶׁהוּא יֵצֶר הַטּוֹב. וּמִשּׁוּם זֶה בְּנֵי אָדָם נִכְשָׁלִים לָעוֹלָם הַבָּא."],[7,"","אֲבָל אוֹתוֹ צַדִּיק שֶׁפּוֹחֵד מֵרִבּוֹנוֹ, כַּמָּה רָעוֹת סוֹבֵל בָּעוֹלָם הַזֶּה כְּדֵי שֶׁלֹּא יַאֲמִין וְלֹא יִשְׁתַּתֵּף עִם אוֹתוֹ יֵצֶר הָרָע, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַצִּיל אוֹתוֹ מִכֻּלָּם. זֶהוּ שֶׁכָּתוּב (תהלים לד) רַבּוֹת רָעוֹת צַדִּיק וּמִכֻּלָּם יַצִּילֶנּוּ ה'. לֹא כָתוּב רַבּוֹת רָעוֹת לַצַּדִּיק, אֶלָּא צַדִּיק, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה בּוֹ, וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה מֵאוֹתוֹ הָאָדָם וּמַצִּיל אוֹתוֹ מִן הַכֹּל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. אַשְׁרֵי חֶלְקוֹ."],[8,"","בֹּא רְאֵה כַּמָּה רָעוֹת עָבְרוּ עָלָיו עַל יַעֲקֹב כְּדֵי שֶׁלֹּא יִתְדַּבֵּק בְּאוֹתוֹ הַיֵּצֶר הָרָע וְיִתְרַחֵק מֵחֶלְקוֹ, וּמִשּׁוּם כָּךְ סָבַל כַּמָּה עֳנָשִׁים וְכַמָּה רָעוֹת וְלֹא שָׁקַט. פָּתַח וְאָמַר, (איוב ג) לֹא שָׁלַוְתִּי וְלֹא שָׁקַטְתִּי וְלֹא נַחְתִּי וַיָּבא רֹגֶז. בּא רְאֵה כַּמָּה רָעוֹת סוֹבְלִים הַצַּדִּיקִים בָּעוֹלָם הַזֶּה, רָעוֹת עַל רָעוֹת, כְּאֵבִים עַל כְּאֵבִים, כְּדֵי לְזַכּוֹת אוֹתָם לָעוֹלָם הַבָּא."],[9,"","יַעָקֹב כַּמָּה רָעוֹת סָבַל, רָעוֹת עַל רָעוֹת תָּמִיד, כְּמוֹ שֶׁנֶּאֱמַר לֹא שָׁלַוְתִּי - בְּבֵית לָבָן, וְלֹא יָכֹלְתִּי לְהִנָּצֵל מִמֶּנּוּ. וְלֹא שָׁקַטְתִּי - מֵעֵשָׂו, מֵאוֹתוֹ הַצַּעַר שֶׁצִּעֵר אוֹתִי הַמְמֻנֶּה הַהוּא שֶׁלּוֹ, וְאַחַר כָּךְ הַפַּחַד שֶׁל עֵשָׂו. וְלֹא נַחְתִּי - מִן דִּינָה וּמִן שְׁכֶם."],[10,"","וַיָּבֹא רֹגֶז - זֶה הָרֹגֶז וְהָעִרְבּוּבְיָה שֶׁל יוֹסֵף שֶׁהוּא קָשֶׁה מִן הַכֹּל, וּמִתּוֹךְ אַהֲבָתוֹ שֶׁל יַעֲקֹב אֶל יוֹסֵף, שֶׁהוּא סוֹד הַבְּרִית, נִכְנַס לְמִצְרַיִם, כִּי אַחַר כָּךְ כָּתוּב (שמות ו) וָאֶזְכֹּר אֶת בְּרִיתִי, שֶׁתִּמָּצֵא הַשְּׁכִינָה (נ\"א: שמש) שָׁם עִמּוֹ."]]],[["וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן, רִבִּי יוֹסֵי פָּתַח, (ישעיהו נ״ז:א׳) הַצַּדִּיק אָבַד וְאֵין אִישׁ שָׂם עַל לֵב וְאַנְשֵׁי חֶסֶד נְאֱסָפִים בְּאֵין מֵבִין כִּי מִפְּנֵי הָרָעָה נְאֱסַף הַצַּדִּיק. הַצַּדִּיק אָבַד, בְּזִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא אַשְׁגַּח בְּעַלְמָא וְלָא הֲוֵי עַלְמָא כְּדְקָא יְאוּת, וְאִזְדַּמַּן דִּינָא לְשַׁרְיָיא עַל עַלְמָא. כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא נָטִיל זַכָּאָה דְּאִשְׁתַּכַּח בֵּינַיְיהוּ, בְּגִין דְּיִשְׁרֵי דִּינָא עַל כֻּלְּהוּ אָחֳרָנִין, וְלָא יִשְׁתַּכַּח מַאן דְּיָגִין עֲלַיְיהוּ.","דְּהָא כָּל זִמְנָא דְּזַכָּאָה שָׁארֵי בְּעַלְמָא, דִּינָא לָא יָכִיל לְשַׁלְטָאָה עַל עַלְמָא. מְנָלָן מִמּשֶׁה, דִּכְתִיב, (תהילים ק״ו:כ״ג) וַיֹּאמֶר לְהַשְׁמִידָם לוּלֵי משֶׁה בְחִירוֹ עָמַד בַּפֶּרֶץ לְפָנָיו וְגו'. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא נָטִיל לְזַכָּאָה מִבֵּינַיְיהוּ וְסַלִּיק לֵיהּ מֵעַלְמָא, וּכְדֵין אִתְפְּרַע וְגָבֵי דִילֵיהּ. סוֹפֵיהּ דִּקְרָא, כִּי מִפְּנֵי הָרָעָה נְאֱסַף הַצַּדִּיק. עַד דְּלָא יֵיתֵי רָעָה לְשַׁלְטָאָה עַל עַלְמָא נֶאֱסַף הַצַּדִּיק. (ד\"א כי מפני הרעה נאסף עד לא ישלוט הרעה בעלמא) דָּבָר אַחֵר כִּי מִפְּנֵי הָרָעָה, דָּא יֵצֶר הָרָע.","תָּא חֲזֵי, יַעֲקֹב שְׁלִימוּ דַאֲבָהָן הֲוָה וְאִיהוּ קָאִים לְקָיְימָא בְּגָלוּתָא. אֲבָל מִגּוֹ דְּאִיהוּ צַדִּיק אִתְעַכַּב דִּינָא דְּלָא שָׁלְטָא בְּעַלְמָא. דְּהָא כָּל יוֹמֵי דְיַעֲקֹב לָא שָׁרָא דִּינָא עַל עַלְמָא, וְכַפְנָא אִתְבַּטְלַת.","וְאוּף הָכִי בְּיוֹמוֹי דְיוֹסֵף דְּאִיהוּ דִּיוּקְנָא דְּאֲבוֹי (כיון דאיהו מת מיד). לָא שְׁרָא גָלוּתָא (דינא על עלמא). בְּגִין דְּאִיהוּ אָגִין עֲלַיְיהוּ כָּל יוֹמוֹי, כֵּיוָן דְּאִיהוּ מֵת, מִיָּד שָׁרָא עֲלַיְיהוּ גָלוּתָא. כְּמָה דְאַתְּ אָמֵר (שמות א׳:י״ד) וַיָּמָת יוֹסֵף וְגו', וְסָמִיךְ לֵיהּ הָבָה נִתְחַכְּמָה לוֹ. וּכְתִיב וַיְמָרֲרוּ אֶת חַיֵּיהֶם בַּעֲבוֹדָה קָשָׁה בְּחֹמֶר וּבִלְבֵנִים וְגו'.","כְּגַוְונָא דָא בְּכָל אֲתַר דְּשַׁרְיָא זַכָּאָה (על) בְּעַלְמָא בְּגִינֵיהּ קוּדְשָׁא בְּרִיךְ הוּא יָגִין עַל עַלְמָא, וְכָל זִמְנָא דְּאִיהוּ קַיָּים, דִּינָא לָא שָׁרְיָא עַל עַלְמָא וְהָא אִתְּמָר.","תָּא חֲזֵי, וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו, מַאי מְגוּרֵי אָבִיו, כְּמָה דְאַתְּ אָמֵר, (ירמיהו ו׳:כ״ה) מָגוֹר מִסָבִיב, דְּכָל יוֹמוֹי הֲוָה דָחִיל וְהֲוָה בִּדְחִילוּ: וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו. רִבִּי אֶלְעָזָר אָמַר, דְאִתְקַשַּׁר וְיָתִיב בְּהַהוּא אֲתַר דְּאִתְאֲחִיד בַּחשֶׁךְ. אֶרֶץ מְגוּרֵי אָבִיו דַּיְיקָא, בְּאֶרֶץ כְּנָעַן, אִתְקַשַּׁר אַתְרָא בְּאַתְרֵיהּ. מְגוּרֵי אָבִיו, דָּא דִינָא קַשְׁיָא. בְּאֶרֶץ מְגוּרֵי אָבִיו, כְּמָה דְאִתְּמָר הַהוּא דִינָא רַפְיָא דְּאִיהִי אֶרֶץ, דְּאִתְאַחִיד מִן דִּינָא קַשְׁיָא וּבֵיהּ אִתְיַשֵּׁב יַעֲקֹב וְאִתְאַחִיד בֵּיהּ, (וההיא ארץ איהי אספקלריא דלא נהרא):","אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף וְגו', בָּתַר דְּאִתְיַשַּׁב יוֹסֵף בְּיַעֲקֹב וְאִזְדַּוַּוג שִׁמְשָׁא בְּסִיהֲרָא, כְּדֵין שָׁרָא לְמֶעְבַּד תּוֹלְדוֹת, וּמַאן אִיהוּ דְּעֲבִיד תּוֹלְדוֹת, אַהֲדַר וְאָמַר יוֹסֵף, דְּהָא הַהוּא נָהָר דְּנָגִיד וְנָפִיק אִיהוּ עָבִיד תּוֹלְדוֹת בְּגִין דְּלָא פָּסְקִין מֵימוֹי לְעָלְמִין, וְאִיהוּ עָבִיד תּוֹלְדוֹת בְּהַאי אֶרֶץ וּמִנֵּיהּ נָפְקִין תּוֹלְדוֹת לְעַלְמָא.","דְּהָא שִׁמְשָׁא אַף עַל גַּב דְּאִתְקַרַב בְּסִיהֲרָא לָא עָבִיד אִיבִּין בַּר הַהוּא דַרְגָּא דְּאִקְרֵי צַדִּי\"ק, וְיוֹסֵף אִיהוּ דַרְגָּא דְיַעֲקֹב לְמֶעְבַּד אִיבִּין וְלְאֲפָקָא תּוֹלָדִין לְעַלְמָא, וּבְגִין כָּךְ כְּתִיב אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף.","אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף, כָּל מַאן דְּהֲוָה מִסְתַּכֵּל בְּדִיוּקְנָא דְיוֹסֵף הֲוָה אָמַר דְּדָא הוּא דִיוּקְנָא דְיַעֲקֹב. תָּא חֲזֵי, דִּבְכֻלְּהוּ בְּנֵי יַעֲקֹב לָא כְּתִיב אֵלֶּה תּוֹלְדוֹת יַעֲקֹב רְאוּבֵן, בַּר יוֹסֵף, דְּדִיוּקְנִיהּ דָמֵי לְדִיוּקְנָא דְּאֲבוֹי.","בֶּן שְׁבַע עֶשְׂרֵה שָׁנָה. אָמַר רִבִּי אַבָּא, רָמַז לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, דְּהָא כַּד אִתְאֲבִיד מִנֵּיהּ יוֹסֵף בֶּן שְׁבַע עֶשְׂרֵה שְׁנִין הֲוָה. וְכָל אִינוּן יוֹמִין דְּאִשְׁתָּאֲרוּ דְּלָא חָמָא לֵיהּ לְיוֹסֵף הֲוָה בָּכֵי עַל אִינוּן שְׁבַע עֶשְׂרֵה שְׁנִין. וּכְמָּה דְּהֲוָה בָּכֵי עֲלֵיהּ, קוּדְשָׁא בְּרִיךְ הוּא יָהַב לֵיהּ שְׁבַע עֶשְׂרֵה שְׁנִין אָחֳרָנִין דְּאִתְקַיֵּים בְּאַרְעָא דְמִצְרַיִם בְּחֵדוּ בִּיקָרָא וּבִשְׁלִימוּ דְּכֹלָּא. בְּרֵיהּ יוֹסֵף הֲוָה מַלְכָּא, וְכָל בְּנוֹי קַמֵּיהּ הֲווּ, אִינוּן שְׁבַע עֶשְׂרֵה שְׁנִין הֲווּ חַיִּין לְגַבֵּיהּ. וּבְגִין כָּךְ בֶּן שְׁבַע עֶשְׂרֵה שָׁנָה הֲוָה אִיהוּ, כַּד אִתְאֲבִיד מִנֵּיהּ."],[[0,"וישב יעקב בארץ מגורי וגו':","ר' יוסי פתח הצדיק אבד ואין איש שם על לב וגו'. \u0003הצדיק אבד,\u0004 בזמן שהקב\"ה מסתכל בעולם, והעולם אינו כראוי להיות, והדין נזדמן לשרות על העולם, אז לוקח את הצדיק הנמצא ביניהם, כדי שהדין ישרה על כל האחרים, ולא יהיה מי שיגין עליהם."],[1,"דהא כל זמנא וכו':","כי כל זמן שהצדיק שורה בעולם, אין הדין יכול לשלוט על העולם. מאין לנו זה, ממשה, שכתוב, ויאמר להשמידם לולי משה בחירו עמד בפרץ לפניו וגו'. ומשום זה הקב\"ה לוקח את הצדיק מביניהם ומעלה אותו מן העולם, ואז נפרע ומקבל את שלו. סוף הכתוב, \u0003כי מפני הרעה נאסף הצדיק,\u0004 פירושו, מטרם שיבא הרע לשלוט בעולם נאסף הצדיק. פירוש אחר, \u0003כי מפני הרעה,\u0004 זה הוא היצר הרע. שהסית והדיח את העולם."],[2,"ת\"ח יעקב שלימו וכו':","בוא וראה, יעקב בחיר שבאבות היה, והוא היה עומד להמצא בגלות, אבל מתוך שהוא צדיק נעצר הדין, ולא שלט בעולם, כי כל ימיו של יעקב לא שרה הדין על העולם, והרעב נתבטל."],[3,"ואוף הכי ביומוי וכו':","וכמו כן בימיו של יוסף, שהוא צורתו של אביו, לא היתה נמצאת הגלות, משום שהוא הגין עליהם כל ימיו, כיון שהוא מת, מיד שרתה עליהם הגלות, כמש\"א, וימת יוסף וגו', ונסמך לו הבה נתחכמה לו. וכתוב, וימררו את חייהם וגו'."],[4,"כגוונא דא וכו':","כעין זה, בכל מקום שנמצא צדיק בעולם, הקב\"ה מגין על העולם בשבילו, וכל זמן שהוא חי, אין הדין שורה על העולם. וכן למדנו."],[5,"ת\"ח וישב יעקב וגו':","שואל מהו \u0003מגורי אביו.\u0004 ומשיב, הוא כמו שאתה אומר מגור מסביב, כי כל ימיו היה מתיירא והיה בפחד. \u0003וישב יעקב,\u0004 רבי אלעזר אמר, שנתקשר וישב במקום ההוא שנתאחד בחשך. \u0003בארץ מגורי אביו\u0004 הוא בדיוק. כלומר, מלמדנו, שהמגור ופחד הזה הוא של אביו יצחק שהוא קו שמאל. \u0003בארץ כנען,\u0004 נקשר המקום במקומו. פירוש, הנוקבא נקראת ארץ, ובעת שנקשרת בקו שמאל, שהוא אביו של יעקב, היא נקראת ארץ כנען. וז\"ש, \u0003אתקשר אתרא באתריה\u0004 שארץ כנען נקשרה במגורי אביו, שהוא קו שמאל. \u0003מגורי אביו,\u0004 זח דין קשה. שה\"ס קו שמאל דז\"א, \u0003בארץ\u0004 מגורי אביו, הוא כמו שלמדנו שארץ היא דינא רפיא. שהיא ארץ שנתאחדה ונמשכת מדין קשה, שחוא קו שמאל, ובה נתישב יעקכ ונתאחז בה."],[5,"","פירוש, אור ז\"א הוא מלמעלה למטה ולפיכך אם הקו שמאל מאיר בו נמשך ממנו דין קשה מאד, כי ה\"ס חטא דעץ הדעת כנודע, אמנם הנוקבא, שהארתה היא בבחינת אור נקבה המאירה רק ממטה למעלה ואינו נמשך למטה, ע\"כ אפילו מטרם שנכללה בימין, אין בה דין קשה אלא דין רפה. (כנ\"ל וישלח דף פ' ד\"ה ביאור ע\"ש) וז\"ש \u0003בארץ מגורי אביו וכו' ההוא דינא רפיא\u0004 וכו' וביה אתישב יעקב. שהוא נתישב בארץ, שה\"ס הנוקבא, והיא רק דינא רפיא, ולא דינא קשיא כמגורי אביו."],[6,"אלה תולדות יעקב יוסף וגו':","אחר שנתישב יוסף ביעקב, והשמש, שהוא ז\"א, נזדווג עם הלבנה, שהיא הנוקבא, אז התחיל להוליד תולדות. ומי הוא העושה תולדות. חזר הכתוב ואמר, \u0003יוסף,\u0004 כי אותו הנהר הנמשך ויוצא מעדן, שהוא יסוד המכונה יוסף, הוא העושה תולדות, משום שמימיו אינם נפסקים לעולם."],[6,"","פירוש. כי נשמות ישראל נולדות מזווג זו\"ן. אבל אין ז\"א מוליד נשמות מטרם שעולה ומלביש לאו\"א, שזווגייהו לא פסיק לעלמין, שאז משיג יסוד דגדלות, המכונה יוסף, וכן נקרא נהר יוצא מעדן, ששפעו אינו נפסק לעולם. וז\"ש \u0003בתר דאתישב יוסף ביעקב ואזדווג שמשא בסיהרא,\u0004 אחר שז\"א המכונה יעקב עלה והלביש לאו\"א עלאין שאז מתישב יוסף, שהוא יסוד דגדלות, ביעקב, שהוא ז\"א, ושמשא מזדווג בסיהרא, \u0003כדין שרא למעבד תולדות,\u0004 אז מתחיל להוליד תולדות, ולא מקודם לכן, \u0003ומאן איהו דעביד תולדות אהדר ואמר יוסף,\u0004 שהוא יסוד דגדלות, שז\"א משיגו בעת עליתו לאו\"א שהוא מכונה אז ונהר יוצא מעדן, \u0003דלא פסקין מימוי לעלמין,\u0004 כמו או\"א עלאין דזווגייהו לא פסיק לעלמין."],[7,"דהא שמשא אע\"ג וגו':","כי השמש שהוא ז\"א, אע\"פ שנתחבר בלבנה, שהיא הנוקבא, אינו עושה פירות משום מדרגה רק מאותה מדרגה הנקראת צדיק. דהיינו יסוד, וכן נקרא יוסף, שהוא המדרגה של יעקב לעשות פירות ולהוציא תולדות לעולם, ומשום זה כתוב, אלה תולדות יעקב יוסף."],[7,"","פירוש, המדרגה האחרונה של ז\"א, המכונה צדיק או יסוד, היא הנושאת את המסך שעליו מכה אור העליון ואו\"ח עולה ומלבישו, שבדרך זה נאצלות כל הקומות והמדרגות וז\"ש \u0003לא עביד איבין בר ההוא דרגא דאקרי צדיק ויוסף,\u0004 כי הוא הנושא אל המסך, להיותו מדרגה האחרונה, כמבואר."],[8,"אלה תולדות יעקב יוסף וגו':","פירוש אחר, כל מי שהיה מסתכל בצורת יוסף היה אומר שזו היא צורתו של יעקב. בוא וראה, שבכל בני יעקב לא כתוב כזה, כגון אלה תולדות יעקב ראובן או שמעון וכו' רק ביוסף, שכתוב אלה תולדות יעקב יוסף. הוא משום שצורתו היתה דומה לצורת אביו."],[8,"","פירוש, כמו שיעקב שה\"ס ת\"ת הוא קו אמצעי המכריע בין ב' הקוין שמחזה ולמעלה, שהם חסד וגבורה, כן יוסף, שה\"ס יסוד, הוא קו אמצעי ומכריע בין שני הקוין שמחזה ולמטה, דהיינו בין נצח והוד. הרי שזה וזה צורתם שוה, ששניהם צורת קו אמצעי ומכריע בין הקצוות."],[9,"בן שבע עשרה שנה:","אמר ר' אבא, הקב\"ה רמז לו, שבעת שנאבד יוסף היה בן שבע עשרה שנה. וכל אלו הימים שנשארו אחר שהיה בן שבע עשרה שנה, שלא ראה את יוסף, היה בוכה על אלו שבע עשרה שנה. וכמו שהיה בוכה עליהן, נתן לו הקב\"ה שבע עשרה שנה אחרות, שחי בארץ מצרים, בשמחה, בכבוד, ובכל השלמות, בנו יוסף היה מלך, וכל בניו היו לפניו, אלו שבע עשרה שנה היו נחשבות לו חיים. וע\"כ משמיענו הכתוב. כי בן שבע עשרה היה יוסף כאשר נאבד ממנו."],[9,"","פירוש, היסוד, שה\"ס יוסף, מכונה שבע עשרה שנה. מטעם שיש בו סוד לחם משנה, שפירושו אור החכמה ואור החסדים, שהוא תכלית השלמות. והנה אור החכמה שבו מרומז במספר שבע להיותו מאיר רק ממטה למעלה בסוד אור הנוקבא הנקראת שביעי, וחסרה ג\"ר דג\"ר. ואור החסדים שבו מרומז במספר עשרה, להיותו מאיר ממעלה למטה וע\"כ המספר שלם."],[9,"","וז\"ש, \u0003רמז ליה קב\"ה, דהא כד אתאביד מניה יוסף בן שבע עשרה שנין הוה,\u0004 דהיינו שרמז לו שיעור שלמות מדרגתו של יוסף, שהוא שבע עשרה שנה, הכולל כל השלמות הן חכמה והן חסדים כנ\"ל. וע\"כ, \u0003וכל אינון יומין וכו' הוה בכי על אינון שבע עשרה שנין,\u0004 דהיינו על מדרגתו הגדולה של יוסף שנאבדה ממנו. \u0003וכמה דהוה וכו' יהב לו שבע עשרה שנין אחרנין,\u0004 דהיינו אחר שמצא שוב את יוסף במצרים. \u0003אינון שבע עשרה שנין הוו חיין לגביה,\u0004 כי אור החכמה נבחן לאור חיה, בסו\"ה החכמה תחיה את בעליה, וכיון שסוד שבע עשרה שנין כולל גם חכמה, ע\"כ יחשבו לו חיים. משא\"כ בשעה שנאבד יוסף, שהיה לו אז אור חסדים בלי חכמה, לא נחשבו לו לחיים, וכן בטרם שנולד יוסף. וזהו שמשמיענו הכתוב, יוסף בן שבע עשרה שנה."]],[[0,"","וַיִּשֱׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן. רַבִּי יוֹסֵי פָּתַח, (ישעיה נז) הַצַּדִּיק אָבָד וְאֵין אִישׁ שָׂם עַל לֵב וְאַנְשֵׁי חֶסֶד נֶאֱסָפִים בְּאֵין מֵבִין כִּי מִפְּנֵי הָרָעָה נֶאֱסַף הַצַּדִּיק. הַצַּדִּיק אָבָד, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ בָּעוֹלָם וְאֵין הָעוֹלָם כָּרָאוּי, וּמִזְדַּמֵּן הַדִּין לִשְׁרוֹת עַל הָעוֹלָם, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹטֵל אֶת הַצַּדִּיק שֶׁנִּמְצָא בֵּינֵיהֶם כְּדֵי שֶׁיִּשְׁרֶה הַדִּין עַל כָּל הָאֲחֵרִים וְלֹא יִמָּצֵא מִי שֶׁיָּגֵן עֲלֵיהֶם."],[1,"","שֶׁהֲרֵי כָּל זְמַן שֶׁהַצַּדִּיק שׁוֹרֶה בָּעוֹלָם, הַדִּין לֹא יָכוֹל לִשְׁלֹט עַל הָעוֹלָם. מִנַּיִן לָנוּ? מִמֹּשֶׁה, שֶׁכָּתוּב (תהלים קו) וַיֹּאמֶר לְהַשְׁמִידָם לוּלֵי מֹשֶׁה בְחִירוֹ עָמַד בַּפֶּרֶץ לְפָנָיו וְגוֹ'. וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹטֵל אֶת הַצַּדִּיק מִבֵּינֵיהֶם וּמְסַלֵּק אוֹתוֹ מִן הָעוֹלָם, וְאָז נִפְרָע וְגוֹבֶה אֶת שֶׁלּוֹ. סוֹף הַפָּסוּק - כִּי מִפְּנֵי הָרָעָה נֶאֱסַף הַצַּדִּיק. בְּטֶרֶם תָּבֹא הָרָעָה לִשְׁלֹט עַל הָעוֹלָם נֶאֱסַף הַצַּדִּיק (ד\"א כי מפני הרעה נאסף, טרם תשלט הרעה בעולם). דָּבָר אַחֵר כִּי מִפְּנֵי הָרָעָה - זֶה יֵצֶר הָרָע."],[2,"","בֹּא רְאֵה, יַעֲקֹב הָיָה בְּחִיר הָאָבוֹת, וְהוּא עוֹמֵד לְהִתְקַיֵּם בַּגָּלוּת, אֲבָל מִתּוֹךְ שֶׁהוּא צַדִּיק, הִתְעַכֵּב הַדִּין שֶׁלֹּא יִשְׁלֹט בָּעוֹלָם, שֶׁהֲרֵי כָּל יְמֵי יַעֲקֹב לֹא שָׁרָה הַדִּין עַל הָעוֹלָם וְהָרָעָב הִתְבַּטֵּל."],[3,"","וְאַף כָּךְ בִּימֵי יוֹסֵף, שֶׁהוּא דְמוּת אָבִיו, (כיון שהוא מת מיד) לֹא שָׁרְתָה הַגָּלוּת (הדין על העולם), מִשּׁוּם שֶׁהוּא הֵגֵן עֲלֵיהֶם כָּל יָמָיו. כֵּיוָן שֶׁהוּא מֵת, מִיָּד שָׁרְתָה עֲלֵיהֶם הַגָּלוּת, כְּמוֹ שֶׁנֶּאֱמַר (שמות א) וַיָּמָת יוֹסֵף וְגוֹ', וְסָמוּךְ לוֹ - הָבָה נִּתְחַכְּמָה לוֹ. וְכָתוּב וַיְמָרֲרוּ אֶת חַיֵּיהֶם בַּעֲבֹדָה קָשָׁה בְּחֹמֶר וּבִלְבֵנִים וְגוֹ'."],[4,"","כְּמוֹ כֵן בְּכָל מָקוֹם שֶׁשָּׁרוּי צַדִּיק (על) בָּעוֹלָם, בִּשְׁבִילוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא יָגֵן עַל הָעוֹלָם, וְכָל זְמַן שֶׁהוּא קַיָּם, הַדִּין לֹא שׁוֹרֶה עַל הָעוֹלָם, וְהִנֵּה נִתְבָּאֵר."],[5,"","בֹּא רְאֵה, וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו, מַה זֶּה מְגוּרֵי אָבִיו? כְּמוֹ שֶׁנֶּאֱמַר (ירמיה ו) מָגוֹר מִסָּבִיב, שֶׁכָּל יָמָיו הָיָה פּוֹחֵד וְהָיָה בְּפַחַד. וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו. רַבִּי אֶלְעָזָר אָמַר, שֶׁהִתְקַשֵּׁר וְיָשַׁב בְּאוֹתוֹ מָקוֹם שֶׁנֶּאֱחַז בַּחֹשֶׁךְ. אֶרֶץ מְגוּרֵי אָבִיו דַּוְקָא, בְּאֶרֶץ כְּנָעַן, נִקְשַׁר הַמָּקוֹם לִמְקוֹמוֹ. מְגוּרֵי אָבִיו - זֶה הַדִּין הַקָּשֶׁה. בְּאֶרֶץ מְגוּרֵי אָבִיו, כְּמוֹ שֶׁנֶּאֱמַר אוֹתוֹ הַדִּין הָרָפֶה, שֶׁהִיא הָאָרֶץ שֶׁנֶּאֶחְזָה מִן הַדִּין הַקָּשֶׁה, וּבוֹ הִתְיַשֵּׁב יַעֲקֹב וְנֶאֱחַז בּוֹ (ואותה ארץ היא האספקלריה שאינה מאירה)."],[6,"","אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף וְגוֹ'. אַחַר שֶׁהִתְיַשֵּׁב יוֹסֵף עִם יַעֲקֹב וְהִזְדַּוֵּג הַשֶּׁמֶשׁ עִם הַלְּבָנָה, אָז הִתְחִיל לַעֲשׂוֹת תּוֹלָדוֹת. וּמִי הוּא שֶׁעוֹשֶׂה תוֹלָדוֹת? חָזַר וְאָמַר יוֹסֵף. שֶׁהֲרֵי אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא הוּא עוֹשֶׂה תוֹלָדוֹת, מִשּׁוּם שֶׁאֵין מֵימָיו פּוֹסְקִים לְעוֹלָמִים, וְהוּא עוֹשֶׂה תּוֹלָדוֹת בָּאָרֶץ הַזּוֹ וּמִמֶּנּוּ יוֹצְאִים תּוֹלָדוֹת לָעוֹלָם."],[7,"","שֶׁהֲרֵי הַשֶּׁמֶשׁ, אַף עַל גַּב שֶׁהִתְקָרֵב לַלְּבָנָה, לֹא עוֹשֶׂה פֵּרוֹת, רַק אוֹתָהּ הַדַּרְגָּה שֶׁנִּקְרֵאת צַדִּיק, וְיוֹסֵף הוּא הַדַּרְגָּה שֶׁל יַעֲקֹב לַעֲשׂוֹת פֵּרוֹת וּלְהוֹצִיא תוֹלָדוֹת לָעוֹלָם, וּמִשּׁוּם כָּךְ כָּתוּב אֵלֶּה תֹּלְדוֹת יוֹסֵף."],[8,"","אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף - כָּל מִי שֶׁהָיָה מִסְתַּכֵל בִּדְמוּת יוֹסֵף, הָיָה אוֹמֵר שֶׁזּוֹ הִיא דְּמוּת יַעֲקֹב. בֹּא רְאֵה שֶׁבְּכָל בְּנֵי יַעֲקֹב לֹא כָתוּב אֵלֶּה תּוֹלְדוֹת יַעֲקֹב רְאוּבֵן, פְּרָט לְיוֹסֵף, שֶׁדְּמוּתוֹ דּוֹמָה לִדְמוּת אָבִיו."],[9,"","בֶּן שְׁבַע עֶשְׂרֵה שָׁנָה - אָמַר רַבִּי אַבָּא, רָמַז לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִנֵּה כְּשֶׁנֶּאֱבַד מִמֶּנּוּ יוֹסֵף הָיָה בֶּן שְׁבַע עֶשְׂרֵה שָׁנִים, וְכָל אוֹתָם יָמִים שֶׁנִּשְׁאֲרוּ שֶׁלֹּא רָאָה אֶת יוֹסֵף, הָיָה בּוֹכֶה עַל אוֹתָם שְׁבַע עֶשְׂרֵה הַשָּׁנִים, וּכְמוֹ שֶׁהָיָה בּוֹכֶה עָלָיו - הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ שְׁבַע עֶשְׂרֵה שָׁנִים אֲחֵרוֹת שֶׁהִתְקַיֵּם בְּאֶרֶץ מִצְרַיִם בְּשִׂמְחָה, בְּכָבוֹד וּבִשְׁלֵמוּת הַכֹּל. שֶׁבְּנוֹ יוֹסֵף הָיָה מֶלֶךְ, וְכָל בָּנָיו הָיוּ לְפָנָיו. אוֹתָן שְׁבַע עֶשְׂרֵה שָׁנִים הָיוּ חַיִּים אֶצְלוֹ, וּמִשּׁוּם כָּךְ בֶּן שְׁבַע עֶשְׂרֵה שָׁנָה הוּא הָיָה כְּשֶׁנֶּאֱבַד מִמֶּנּוּ."]]],[["רִבִּי חִיָּיא פָּתַח וְאָמַר, (איוב לה) לָכֵן אַנְשֵׁי לֵבָב שִׁמְעוּ לִי חָלִלָה לָאֵל מֵרְשַׁע וְשַׁדַּי מֵעָוֶל. כִּי פֹעַל אָדָם יְשַׁלֶּם לוֹ וּכְאֹרַח אִישׁ יַמְצִאֶנּוּ. תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, עֲבַד לֵיהּ עַל דִּינָא, וְעַל דִּינָא אִתְקַיַּים. וְכָל עוֹבָדִין דְּעַלְמָא אִינוּן קָיְימִין בְּדִינָא. בַּר דְּקוּדְשָׁא בְּרִיךְ הוּא בְּגִין לְקַיְימָא עַלְמָא וְלָא יִתְאֲבִיד, פָּרִישׂ עֲלֵיהּ רַחֲמֵי, וְאִינוּן רַחֲמֵי מְעַכְּבֵי לְדִינָא דְּלָא יִשְׁתְּצֵי עַלְמָא, וְעַל רַחֲמֵי אִתְנַהִיג עַלְמָא וְאִתְקְיַּים בְּגִינִיהּ.","וְאִי תֵימָא דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד דִּינָא בְּבַר נָשׁ בְּלָא דִינָא. הָא אִתְּמָר, דְּכַד דִּינָא שַׁרְיָא עֲלֵיהּ דְּבַר נָשׁ כַּד אִיהוּ זַכָּאָה. בְּגִין רְחִימוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ אִיהִי, כְּמָה דְאִתְּמָר. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא רָחִים עֲלֵיהּ בִּרְחִימוּ לְקָרְבָא לֵיהּ לְגַבֵּיהּ, מְתַבַּר גּוּפָא בְּגִין לְשַׁלְטָאָה נִשְׁמָתָא, וּכְדֵין אִתְקְרִיב בַּר נָשׁ לְגַבֵּיהּ בִּרְחִימוּ כְּדְקָא יְאוּת. וְנִשְׁמָתָא שָׁלְטָא וְגוּפָא אִתְחַלָּשׁ.","וּבַעְיָא גּוּפָא חוּלְשָׁא וְנַפְשָׁא תַּקִּיפָא דְּאִתְתַּקַּף בִּתְקִיפוּ, וּכְדֵין אִיהוּ רְחִימָא דְקוּדְשָׁא בְּרִיךְ הוּא. כְּמָה דַאֲמְרוּ חַבְרַיָיא, יָהַב קוּדְשָׁא בְּרִיךְ הוּא לַצַּדִּיק צַעֲרָא בְּעַלְמָא דֵין, בְּגִין לְמִזְכֵּי לֵיהּ לְעַלְמָא דְאָתֵי.","וְכַד נִשְׁמָתָא חָלְשָׁא וְגוּפָא תַקִיפָא, אִיהוּ שָׂנְאֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא דְּלָא אִתְרָעֵי בֵּיהּ, לָא יָהִיב לֵיהּ צַעֲרָא בְּהַאי עַלְמָא אֶלָּא אוֹרְחוֹי מִתְתַּקְנָן וְהוּא בִּשְׁלִימוּ יַתִּיר. בְּגִין דְּאִי עָבַד צְדָקָה אוֹ טִיבוּ קוּדְשָׁא בְּרִיךְ הוּא מְשַׁלֵּם לֵיהּ אַגְרֵיהּ בְּהַאי עַלְמָא וְלָא יֶהֱוֵי לֵיהּ חוּלַק בְּהַהוּא עַלְמָא. וְדָא הוּא דְּתִרְגֵּם אוּנְקְלוּס (דברים ז׳:י׳) וּמְשַׁלֵּם לְשׂוֹנְאָיו וְגו', וּמְשַׁלֵּם לְשַׂנְאוֹהִי טַבְוָון דְּאִינוּן וְגו' (איהו). וּבְגִין כָּךְ הַהוּא זַכָּאָה דְּאִתְבַּר תָּדִיר אִיהוּ רְחִימָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְהַנֵּי מִילֵי כַּד בָּדַק וְלָא אַשְׁכַּח חוֹבָא בִּידֵיהּ דְּאִתְעַנַּשׁ עֲלֵיהּ.","הָכָא אִית לְאִסְתַּכָּלָא בְּכַמָּה סִטְרִין. חַד, דְּהָא חָמִינָן דִּשְׁכִינְתָּא לָא שַׁרְיָא בְּאֲתַר עֲצִיבוּ אֶלָּא בְּאֲתַר דְּאִית בֵּיהּ חֶדְוָה. אִי חֶדְוָה לֵית בֵּיהּ, לָא שַׁרְיָא שְׁכִינְתָּא בְּהַהוּא אֲתַר. כְּמָה דְאַתְּ אָמֵר, (מלכים ב ג׳:ט״ו) וְעַתָּה קְחוּ לִי מְנַגֵּן וְהָיָה כְנַגֵּן הַמְנַגֵּן וַתְּהִי עָלָיו (יד יי) רוּחַ אֱלהִים, דְּהָא שְׁכִינְתָּא וַדַּאי לָא שַׁרְיָא בְּאֲתַר עֲצִיבוּ. מְנָלָן מִיַּעֲקֹב. דִּבְגִין דְּהֲוָה עָצִיב עֲלֵיהּ דְּיוֹסֵף אִסְתַּלְקַת שְׁכִינְתָּא מִנֵּיהּ, כֵּיוָן דְּאָתָא לֵיהּ חֶדְוָה דִּבְשׂוֹרָה דְיוֹסֵף מִיָּד וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם. הָכָא בְּהַאי זַכָּאָה דְּאִתָּבַר כֵּיוָן דְּאִיהוּ חֲלָשָׁא וְאִתָּבַר בְּמַכְאוֹבִין, אָן הוּא חֶדְוָה דְּהָא אִיהוּ בַּעֲצִיבוּ וְלֵית עִמֵּיהּ חֶדְוָה כְּלָל.","וְחַד דְּהָא חָמִינָן כַּמָּה רְחִימִין הֲווּ צַדִּיקַיָא קַמֵי קוּדְשָׁא בְּרִיךְ הוּא וְלָא אִתָּבְרוּ בְּמַרְעִין וְלָא בְּמַכְאוֹבִין וְלָא אִתְחַלַּשׁ גּוּפָא דִלְהוֹן לְעָלְמִין. אַמַּאי לָאו אִלֵּין כְּאִלֵּין, דְּאִלֵּין אִתָּבְרוּ וְאִלֵּין קָיְימֵי בְּגוּפַיְיהוּ כְּדְקָא יְאוּת.","וְאִם תֹּאמַר דְּהָא אִלֵּין דְּקָיְימוּ בְּקִיּוּמָא כְּדְקָא יְאוּת, בְּגִין דְּאִינוּן צַדִּיקֵי בְּנֵי צַדִּיקֵי אִינְהוּ, כְּמָה דְאוּקְמוּהָ. וְאִלֵּין אָחֳרָנִין צַדִּיקֵי וְלָאו בְּנִי צַדִּיקֵי, הָא קָא חָמֵינָן צַדִּיקֵי בְּנֵי צַדִּיקֵי, דְּהָא אֲבוֹי דְּדֵין זַכָּאָה בַּר זַכָּאָה, וְאִיהוּ זַכָּאָה. אַמַּאי אִתָּבַר גּוּפֵיהּ בְּמַכְאוֹבִין וְכָל יוֹמוֹי בְּצַעֲרָא.","אֶלָּא הָכָא רָזָא אִיהוּ, דְּהָא כָּל עוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא בִּקְשׁוֹט וּזְכוּ (איוב לה) כִּי פֹעַל אָדָם יְשַׁלֶּם לוֹ וּכְאֹרַח אִישׁ יַמְצִיאֶנּוּ. אַשְׁכַּחְנָא בְּסִפְרֵי קַדְמָאֵי רָזָא חָדָא, וּלְגַבֵּיהּ רָזָא אָחֳרָא חַד דְּאִיהוּ תְּרֵין, דְּהָא אִית זִמְנִין דְּסִיהֲרָא אִיהִי בִּפְגִימוּ וְשַׁרְיָא בְּדִינָא וְשִׁמְשָׁא לָא אִשְׁתַּכַּח גַּבָּה. וּבְכָל זִמְנָא וּבְכָל שַׁעְתָּא אִית לָהּ לְאֲפָקָא נִשְׁמָתִין בִּבְנֵי נָשָׁא כְּמָה דְלָקְטָא בְּקַדְמִיתָא, וַאֲפִיקַת לוֹן הַשְׁתָּא בְּזִמְנָא דְאִיהִי קָיְימָא בְּדִינָא. הַאי מַאן דְּנָקִיט לָהּ בְּהַהוּא זִמְנָא לֶיהֱוֵי תָּדִיר בִּגְרִיעוּתָא, וּמִסְכֵּנוּתָא אָזְלָא לְגַבֵּיהּ, וְאִתָּבַר תָּדִיר בְּדִינָא כָּל יוֹמוֹי דְבַר נָשׁ בֵּין חַיָּיבָא בֵּין זַכָּאָה. בַּר דִּצְלוֹתָא בָּטִיל כָּל גִּזְרֵי דִינִין וְיָכִיל לְסַלְקָא בִּצְלוֹתָא.","וְהַהוּא זִמְנָא דְּקָיְימָא הַהוּא דַרְגָּא בִּשְׁלִימוּ, וְהַהוּא נָהָר דְּנָגִיד וְנָפִיק אִשְׁתַּמַּשׁ בָּהּ, כְּדֵין הַהוּא נִשְׁמָתָא דְּנָפְקַת וְאִתְדַּבְּקַת בֵּיהּ בְּהַהוּא בַר נָשׁ, הַהוּא בַּר נָשׁ אִשְׁתַּלִּים בְּכֹלָּא בְּעוּתְרָא בִּבְנִין בִּשְׁלִימוּ דְּגוּפָא."],[[0,"רבי חייא פתח וכו':","ר\"ח פתח ואמר, לכן אנשי לבב שמעו לי וגו'. בוא וראה כאשר ברא הקב\"ה את העולם עשה אותו על דין, והוא מתקיים על דין. וכל מעשי העולם מתקיימים על דין. מלבד שבכדי לקיים העולם שלא יאבד, הקב\"ה פורש עליו רחמים, ורחמים האלו מעכבים את הדין שלא יכלה את העולם, והעולם מתנהג ברחמים ומתקיים על ידו."],[1,"ואי תימא וכו':","ואם תאמר, שהקב\"ה עושה דין באדם בלי משפט, הרי למדנו, כשהדין שורה על האדם, והוא צדיק, הוא, משום אהבת הקב\"ה אליו. כמו שלמדנו, כאשר הקב\"ה מרחם על האדם באהבה, לקרבהו אליו, משבר הגוף בשביל להשליט את הנשמה, ואז מתקרב האדם אליו באהבה כראוי, והנשמה שולטת באדם, והגוף נחלש."],[2,"ובעיא גופא וכו':","וצריך האדם לגוף חלש, ולנפש חזקה שתתגבר בגבורה. ואז הוא אוהבו של הקב\"ה, כמו שאומרים החברים, שהקב\"ה נותן צער אל הצדיק בעולם הזה, בשביל לזכותו לעולם הבא."],[3,"וכד נשמתא חלשא וכו':","וכשהנשמה היא חלשה, והגוף חזק, הוא שונאו של הקב\"ה, שאינו חפץ בו, ואינו נותן לו צער בעולם הזה, אלא דרכיו ישרים, והוא בכל השלמות, משום, שאם עושה צדקה או מעשים טובים, הקב\"ה משלם שכרו בעולם הזה, ולא יהיה לו חלק לעולם הבא. וזהו שתרגם אונקלוס, ומשלם לשונאיו וגו', ומשלם לשנאוהי טכוון דאינון עבדין קדמוהי, בחייהון, לאובדהון. ומשום זה, צדיק ההוא השבור תמיד, הוא אוהבו של הקב\"ה, והדברים אמורים, רק באם בדק ולא מצא בידו שום חטא שיענש על ידו."],[4,"הכא אית לאסתכלא וכו':","יש כאן להסתכל בכמה צדדים, אחד, כי אנו רואים שהשכינה אינה שורה במקום עצבות אלא במקום שיש בו שמחה, ואם אין בו שמחה לא תשרה השכינה במקום ההוא. כמו שאתה אומר, ועתה קחו לי מנגן וגו', כי ודאי שהשכינה אינה שורה במקום עצבות. מאין לנו זה, מיעקב, שמשום שהיה מתאבל על יוסף נסתלקה השכינה ממנו, כיון שבאה לו השמחה של בשורת יוסף, מיד, ותחי רוח יעקב אביהם. ולפי זה קשה, כאן באותו צדיק השבור מצרותיו, כיון שהוא חלש ונשבר במכאובים, איפה הוא השמחה, הרי הוא בעצבות ואין עמו שמחה כלל."],[5,"וחד, דהא חמינן וכו':","ועוד אחד יש להסתכל, הרי אנו רואים, כמה אהובים וצדיקים היו לפני הקב\"ה. ולא נשברו במחלות ולא במכאובים ולא נחלש גופם לעולם, למה אין אלו כאלו, כלומר, מה נשתנו אלו מאלו, שאלו נשברו, ואלו עומדים בגופם כראוי."],[6,"וא\"ת דהא וכו':","ואם תאמר, כי אלו הנמצאים בקיומם כראוי, הוא משום שהם צדיקים בני צדיקים כמו שבארוהו, ואלו האחרים, שגופם נשבר, הם צדיקים ולא בני צדיקים. הרי אנו רואים, צדיקים בני צדיקים, ואשר אפילו אביו היה צדיק בן צדיק והוא צדיק ומ\"מ גופו נשבר במכאובים ולמה נשבר גופו במכאובים. וכל ימיו הוא בצער."],[7,"אלא הכא רזא וכו':","אלא כאן הוא סוד, שהרי כל מעשיו של הקב\"ה הם באמת וצדק, כי פועל אדם ישלם לו וכאורח איש ימציאנו. ומצאתי בספרי הראשונים סוד אחד, ועמו מתגלה סוד אחר, סוד אחד שהוא שנים. כי יש זמנים שהלבנה דהיינו הנוקבא, היא בגרעון, ונמצאת בדין, והשמש, שהוא ז\"א, אינו נמצא אצלה, ובכל זמן ובכל שעה יש לה להוציא נשמות לבני אדם, כמו שלקטה אותן מתחילה מן ז\"א, בכל זמן ובכל שעה. וע\"כ היא מוציאה עתה הנשמות גם בשעת הגרעון בזמן שנמצאת בדין, וכל מי שמקבל אותה בזמן ההוא, יהיה תמיד בגרעון, ועניות נמשכת לו, ונשבר תמיד בדין, וכן הוא בכל ימיו של האדם ההוא, בין צדיק ובין רשע. מלבד התפלה, המבטלת לכל גזרות הדינים, ויכול האדם להעבירם בתפלה."],[8,"וההוא זמנא וכו':","ובזמן ההוא שאותה המדרגה, דהיינו הנוקבא, נמצאת בשלמות, ונהר ההוא הנמשך ויוצא מעדן, שהוא יסוד, משתמש בה, אז, אותה הנשמה היוצאת מהנוקבא, ומתדבקת באדם, הנה האדם ההוא נשלם בכל, בעושר, בבנים, בשלימות הגוף."]],[[0,"","רַבִּי חִיָּיא פָּתַח וְאָמַר, (איוב לד) לָכֵן אַנְשֵׁי לֵבָב שִׁמְעוּ לִי חָלִלָה לָאֵל מֵרֶשַׁע וְשַׁדַּי מֵעָוֶל, כִּי פֹעַל אָדָם יְשַׁלֶּם לוֹ וּכְאֹרַח אִישׁ יַמְצִאֶנּוּ. בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה אוֹתוֹ עַל הַדִּין, וְעַל הַדִּין הִתְקַיֵּם, וְכָל הַמַּעֲשִׂים שֶׁל הָעוֹלָם הֵם עוֹמְדִים בַּדִּין חוּץ מִשֶּׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּדֵי לְקַיֵּם אֶת הָעוֹלָם שֶׁלֹּא יֹאבַד. פָּרַשׂ עָלָיו רַחֲמִים, וְאוֹתָם הָרַחֲמִים מְעַכְּבִים אֶת הַדִּין שֶׁלֹּא יְכַלֶּה אֶת הָעוֹלָם, וְעַל הָרַחֲמִים מִתְנַהֵג הָעוֹלָם וּמִתְקַיֵּם בִּשְׁבִילָם."],[1,"","וְאִם תֹּאמַר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִין בָּאָדָם בְּלִי דִין, הֲרֵי נֶאֱמַר, שֶׁכַּאֲשֶׁר הַדִּין שׁוֹרֶה עַל הָאָדָם כְּשֶׁהוּא צַדִּיק, מִשּׁוּם אַהֲבָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵלָיו הִיא, כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מְרַחֵם עָלָיו בְּאַהֲבָה לְקָרֵב אוֹתוֹ אֵלָיו, מְשַׁבֵּר אֶת הַגּוּף כְּדֵי לְהַשְׁלִיט אֶת הַנְּשָׁמָה, וְאָז מִתְקָרֵב הָאָדָם אֵלָיו בְּאַהֲבָה כָּרָאוּי, וְהַנְּשָׁמָה שׁוֹלֶטֶת וְהַגּוּף נֶחֱלָשׁ."],[2,"","וְצָרִיךְ גּוּף חַלָּשׁ וְנֶפֶשׁ חֲזָקָה שֶׁמִּתְגַּבֶּרֶת בְּחֹזֶק, וְאָז הוּא אָהוּב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁאָמְרוּ הַחֲבֵרִים, נוֹתֵן הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיק צַעַר בָּעוֹלָם הַזֶּה כְּדֵי לְזַכּוֹת אוֹתוֹ לָעוֹלָם הַבָּא."],[3,"","וְכַאֲשֶׁר הַנְּשָׁמָה חַלָּשָׁה וְגוּף חָזָק, הוּא שׂוֹנְאוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאֵינוֹ מְרֻצֶּה בּוֹ, לֹא נוֹתֵן לוֹ צַעַר בָּעוֹלָם הַזֶּה, אֶלָּא דְּרָכָיו מְתֻקָּנוֹת וְהוּא בִּשְׁלֵמוּת יְתֵרָה, מִשּׁוּם שֶׁאִם עוֹשֶׂה צְדָקָה אוֹ חֶסֶד, הַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׁלֵּם לוֹ אֶת שְׂכָרוֹ בָּעוֹלָם הַזֶּה, וְלֹא יִהְיֶה לוֹ חֵלֶק בָּעוֹלָם הַהוּא. וְזֶהוּ שֶׁתִּרְגֵּם אוּנְקְלוּס (דברים ז) וּמְשַׁלֵּם לְשׂוֹנְאָיו וְגוֹ' - מְשַׁלֵּם לְשׂוֹנְאָיו טוֹבוֹת שֶׁהֵם עוֹשִׂים (הוא), וּמִשּׁוּם כָּךְ אוֹתוֹ צַדִּיק שֶׁנִּשְׁבָּר תָּמִיד הוּא אָהוּב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהַדְּבָרִים הַלָּלוּ כְּשֶׁבָּדַק, וְלֹא מָצָא חֵטְא בְּיָדוֹ שֶׁנֶּעֱנַשׁ עָלָיו."],[4,"","כָּאן יֵשׁ לְהִסְתַּכֵּל בְּכַמָּה צְדָדִים, אֶחָד - שֶׁהִנֵּה רָאִינוּ שֶׁאֵין הַשְּׁכִינָה שׁוֹרָה בְּמָקוֹם עָצוּב, אֶלָּא בְּמָקוֹם שֶׁיֵּשׁ בּוֹ שִׂמְחָה. אִם אֵין בּוֹ שִׂמְחָה, אֵין שְׁכִינָה שׁוֹרָה בְּאוֹתוֹ מָקוֹם, כְּמוֹ שֶׁנֶּאֱמַר (מלכים ב ג) וְעַתָּה קְחוּ לִי מְנַגֵּן וְהָיָה כְּנַגֵּן הַמְנַגֵּן וַתְּהִי עָלָיו יַד ה'. שֶׁהֲרֵי וַדַּאי שֶׁשְּׁכִינָה לֹא שׁוֹרָה בְּמָקוֹם עָצוּב. מִנַּיִן לָנוּ? מִיַּעֲקֹב, שֶׁמִּשּׁוּם שֶׁהָיָה עָצוּב עַל יוֹסֵף הִסְתַּלְּקָה מִמֶּנּוּ שְׁכִינָה. כֵּיוָן שֶׁבָּאָה לוֹ הַשִּׂמְחָה עַל בְּשׂוֹרַת יוֹסֵף, מִיָּד וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם. כָּאן בַּצַּדִּיק הַזֶּה שֶׁנִּשְׁבָּר, כֵּיוָן שֶׁהוּא חַלָּשׁ וְנִשְׁבָּר בְּמַכְאוֹבִים, אֵיפֹה הַשִּׂמְחָה? שֶׁהֲרֵי הוּא בְּעֶצֶב וְאֵין עִמּוֹ כְּלָל שִׂמְחָה."],[5,"","וְאֶחָד - שֶׁהִנֵּה רָאִינוּ כַּמָּה אֲהוּבִים הָיוּ צַדִּיקִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא נִשְׁבְּרוּ בָּחֳלָאִים וְלֹא בְּמַכְאוֹבִים, וְלֹא נֶחֱלַשׁ גּוּפָם לְעוֹלָמִים, לָמָּה לֹא אֵלֶּה כְּאֵלֶּה - שֶׁאֵלֶּה נִשְׁבְּרוּ, וְאֵלֶּה עוֹמְדִים בְּגוּפָם כָּרָאוּי?"],[6,"","וְאִם תֹּאמַר שֶׁהִנֵּה אֵלֶּה שֶׁעָמְדוּ בְּקִיּוּם כָּרָאוּי מִשּׁוּם שֶׁהֵם צַדִּיקִים בְּנֵי צַדִּיקִים הֵם, כְּמוֹ שֶׁבֵּאֲרוּהוּ, וְאֵלּוּ הָאֲחֵרִים צַדִּיקִים וְלֹא בְּנֵי צַדִּיקִים - הִנֵּה רָאִינוּ צַדִּיקִים בְּנֵי צַדִּיקִים, שֶׁהִנֵּה אָבִיו שֶׁל זֶה צַדִּיק בֶּן צַדִּיק, וְהוּא צַדִּיק, לָמָּה נִשְׁבָּר גּוּפוֹ בְּמַכְאוֹבִים וְכָל יָמָיו בְּצַעַר?"],[7,"","אֶלָּא כָּאן הוּא סוֹד, שֶׁהִנֵּה כָּל מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא בֶּאֱמֶת וָצֶדֶק, (איוב לד) כִּי פֹעַל אָדָם יְשַׁלֶּם לוֹ וּכְאֹרַח אִישׁ יַמְצִאֶנּוּ. מָצָאנוּ בְּסִפְרֵי הָרִאשׁוֹנִים סוֹד אֶחָד, וְאֶצְלוֹ סוֹד אַחֵר אֶחָד שֶׁהוּא שְׁנַיִם, שֶׁהֲרֵי יֵשׁ לִפְעָמִים שֶׁהַלְּבָנָה בְּחִסָּרוֹן וְשׁוֹרָה בְדִין וְאֵין הַשֶּׁמֶשׁ נִמְצָא אֶצְלָהּ, וּבְכָל זְמַן וּבְכָל שָׁעָה יֵשׁ לָהּ לְהוֹצִיא נְשָׁמוֹת לִבְנֵי אָדָם כְּמוֹ שֶׁלָּקְטָה בָּרִאשׁוֹנָה, וּמוֹצִיאָה אוֹתָם כָּעֵת בִּזְמַן שֶׁהִיא עוֹמֶדֶת בְּדִין, וּמִי שֶׁלּוֹקֵחַ אוֹתָהּ בְּאוֹתוֹ זְמַן, יִהְיֶה תָמִיד בְּחִסָּרוֹן וְהָעֹנִי הוֹלֵךְ אֵלָיו, וְנִשְׁבָּר תָּמִיד בְּדִין כָּל יְמֵי הָאָדָם, בֵּין חַיָּב בֵּין זַכַּאי, רַק שֶׁתְּפִלָּה מְבַטֶּלֶת אֶת כָּל גִּזְרֵי הַדִּינִים וְיָכוֹל לְסַלְּקָם בִּתְפִלָּה."],[8,"","וְאוֹתוֹ הַזְּמַן שֶׁאוֹתָהּ הַדַּרְגָּה עוֹמֶדֶת בִּשְׁלֵמוּת, וְאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מִשְׁתַּמֵּשׁ בָּהּ, אָז אוֹתָהּ הַנְּשָׁמָה שֶׁיָּצְאָה וְנִדְבְּקָה בּוֹ בְּאוֹתוֹ הָאָדָם, אוֹתוֹ הָאָדָם מֻשְׁלָם בַּכֹּל - בְּעֹשֶׁר, בְּבָנִים וּבִשְׁלֵמוּת הַגּוּף."]]],[["וְכֹלָּא בְּגִין הַהוּא מַזָּלָא דְּנָגִיד וְנָפִיק וְאִתְחַבַּר בְּהַהוּא דַרְגָּא לְאִשְׁתַּלְּמָא בֵּיהּ וּלְאִתְבָּרְכָא מִנֵּיהּ, וְעַל דָּא כֹּלָּא בְּמַזָּלָא תַּלְיָא מִלְּתָא. וְעַל דָּא תָּנִינָן, בָּנִי חַיֵּי וּמְזוֹנֵי לָאו בִּזְכוּתָא תַּלְיָא מִלְּתָא אֶלָּא בְּמַזָּלָא תַּלְיָא מִלְּתָא. דְּהָא בִּזְכוּתָא לָאו אִיהוּ אֶלָּא עַד דְּאִתְמַלְּיָא וְאִתְנְהִיר מִן מַזָּלָא.","וּבְגִין כָּךְ כָּל אִינוּן דְּאִתָּבְרוּ בְּהַאי עַלְמָא וְאִינוּן זַכָּאי קְשׁוֹט, כֻּלְּהוּ אִתָּבְרוּ בְּהַאי עַלְמָא וְאִתְדָּנוּ בְּדִינָא. מַאי טַעְמָא, בְּגִין דְּהַהִיא נַפְשָׁא גָּרְמָא לְהוּ, וְעַל דָּא חָיִיס עֲלַיְיהוּ קוּדְשָׁא בְּרִיךְ הוּא לְעַלְמָא דְאָתֵי.","רִבִּי אֶלְעָזָר אָמַר, כָּל מַה דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא בְּדִינָא אִיהוּ, בְּגִין לְדַּכָּאָה לְהַהִיא נַפְשָׁא לְאַיְיתָאָה לָהּ לְעַלְמָא דְאָתֵי. (ובגין כך קודשא בריך הוא כל עובדוי) (נ\"א בגין דכל עובדוי דקודשא בריך הוא) אִינוּן בְּדִינָא וּקְשׁוֹט. וּבְגִין לְאַעֲבָרָא מִנֵּיהּ הַהוּא זוּהֲמָא דְּקַבִּילַת בְּהַאי עַלְמָא וְעַל דָּא אִתָּבַר הַהוּא גּוּפָא וְאִתְדְּכִיאַת נַפְשָׁא. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא עָבִיד לְהַהוּא זַכָּאָה דְּיִסְבּוֹל יִסּוּרִין וּמַכְאוֹבִין בְּהַאי עַלְמָא וְיִתְנְקֵי מִכֹּלָּא וְיִזְכֶּה לְחַיֵּי עָלְמָא. וְעַל דָּא כְּתִיב (תהילים י״א:ה׳) יְיָ צַדִּיק יִבְחָן. וַדַּאי, וְהָא אִתְּמָר.","רִבִּי שִׁמְעוֹן פָּתַח, (ויקרא כ״א:כ״ג) אַךְ אֶל הַפָּרֹכֶת לֹא יָבֹא וְאֶל הַמִּזְבֵּחַ לא יִגָּשׁ כִּי מוּם בּוֹ וְלֹא יְחַלֵּל אֶת מִקְדָּשַׁי כִּי אֲנִי יְיָ מְקַדְּשׁוֹ. אַךְ אֶל הַפָּרֹכֶת לא יָבֹא. תָּא חֲזֵי, בְּהַהִיא שַׁעְתָּא דְּהַהוּא נָהָר דְּנָגִיד וְנָפִיק אַפִּיק כָּל אִינוּן נִשְׁמָתִין וְאִתְעֲבָרַת נוּקְבָא, כֻּלְּהוּ קָיְימִין לְגוֹ בְּקוּרְטָא דִלְגוֹ בְּסִיטוֹ קוּרְטָא.","וְכַד סִיהֲרָא אִתְפְּגִים בְּהַהוּא סִטְרָא דְּחִוְיָא בִישָׁא, כְּדֵין כָּל אִינוּן נִשְׁמָתִין דְּנָפְקִין, אַף עַל גַּב דְּכֻלְּהוּ דַּכְיָין וְכֻלְּהוּ קַדִּישִׁין, הוֹאִיל וְנָפְלוּ בִּפְגִימוּ. בְּכָל אִינוּן אַתְרֵי דְמָטוּ אִינוּן נִשְׁמָתִין כֻּלְּהוּ אִתָּבְרוּ וְאִתְפְּגִימוּ בְּכַמָּה צַעֲרִין בְּכַמָּה כְּאֵבִין, וְאִילֵּין אִינוּן (נשמתין ואתרין) (נ\"א נשמתין דאתרין דפגימו) דְּאִתְרְעֵי בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא לְבָתַר דְּאִתָּבְרוּ, וְאַף עַל גַּב דְּנִשְׁמָתִין בַּעֲצִיבוּ וְלָא בְּחֶדְוָון.","רָזָא דְמִלָּה שַׁרְיָין כְּגַוְונָא דִלְעֵילָא גּוּפָא אִתְפְּגִים, וְנִשְׁמָתָא לְגוֹ כְּגַוְונָא דִלְעֵילָא, וַדַּאי כְּגַוְונָא דְּדָא, וּבְגִין כָּךְ אִלֵּין אִינוּן דְּבַעְיָין לְחַדְתוּתֵי בְּחַדְתוּתָא דְסִיהֲרָא, וְעַל אִלֵּין כְּתִיב, (ישעיהו ס״ו:כ״ג) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ יָבֹא כָל בָּשָׂר לְהִשְׁתַּחֲוֹת לְפָנַי אָמַר יְיָ. כָּל בָּשָׂר וַדַּאי, דְּאִלֵּין יִתְחַדְתוּן בְּכֹלָּא. וּבָעְיָין לְחַדְתוּתֵי בְּחַדְתוּתָא דְסִיהֲרָא.","וְאִלֵּין אִינוּן בְּשׁוּתָּפוּתָא חָדָא בְּסִיהֲרָא פְּגִימִין בְּהַהוּא פְּגִימוּ דִילָהּ, וּבְגִין כָּךְ אִיהִי שַׁרְיָא בְּגַוַּויְיהוּ תָּדִיר דְּלָא שָׁבְקָא לוֹן כְּמָה דְאַתְּ אָמֵר, (ישעיהו נ״ז:ט״ו) וְאֶת דַּכָּא וּשְׁפַל רוּחַ. וּכְתִיב, (תהלים לה) קָרוֹב יְיָ לְנִשְׁבְּרֵי לֵב, לְאִינוּן דְּסָבְלֵי עִם סִיהֲרָא הַהוּא פְּגִימוּ, אִינוּן קְרֵיבִין לָהּ תָּדִיר. וְעַל דָּא לְהַחֲיוֹת לֵב נִדְכָּאִים, בְּאִינוּן חַיִּים דְּאַתְיָין לָהּ לְאִתְחַדְתָא יְהֵא לוֹן חוּלְקֵהוֹן, אִינוּן דְּסָבְלֵי עִמָּהּ יִתְחַדְתוּן עִמָּהּ.","וְאִלֵּין אִקְרוּן יִסּוּרִין שֶׁל אַהֲבָה, שֶׁל אַהֲבָה אִינוּן וְלָא מִנֵּיהּ דְּהַהוּא בַר נָשׁ. שֶׁל אַהֲבָה, אִינוּן דְּאִתְפַּגִּים נְהוֹרָא שֶׁל אַהֲבָה זוּטָא דְּאִתְדַּחְיָיא מֵאַהֲבָה רַבָּה. בְּגִין כָּךְ אִלֵּין אִינוּן חֲבֵרִים מְשׁוּתָּפִים בַּהֲדָהּ. זַכָּאָה חוּלַקְהוֹן בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי, דְּאִינוּן זָכוּ לְהַאי לְמֶהוֵי חֲבֵרִים בַּהֲדָהּ, עֲלַיְיהוּ כְּתִיב, (תהילים קכ״ב:ח׳) לְמַעַן אַחַי וְרֵעָי וְגו'.","פָּתַח וְאָמַר, (ישעיהו נ״ב:י״ג) הִנֵּה יַשְׂכִּיל עַבְדִּי יָרוּם וְנִשָּׂא וְגָבַהּ מְאֹד. זַכָּאָה חוּלַקְהוֹן דְּצַדִּיקַיָיא דְּקוּדְשָׁא בְּרִיךְ הוּא גָּלֵי לוֹן אָרְחֵי דְאוֹרַיְיתָא לְמֵהַךְ בְּהוּ. תָּא חֲזֵי, הַאי קְרָא רָזָא עִלָּאָה אִיהוּ, הִנֵּה יַשְׂכִּיל עַבְדִּי וְאוּקְמוּהָ. אֲבָל תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, עֲבַד לָהּ לְסִיהֲרָא וְאַזְעַר לָהּ נְהוֹרָהָא דְּהָא לֵית לָהּ מִגַרְמָהּ כְּלוּם. וּבְגִין דְּאַזְעִירַת גַּרְמָהּ, אִתְנַהֲרָא בְּגִין שִׁמְשָׁא, וּבְתוּקְפָא דִּנְהוֹרִין עִלָּאִין.","וּבְזִמְנָא דְּהֲוָה בֵּי מַקְדְּשָׁא קַיָּים, יִשְׂרָאֵל הֲווּ מִשְׁתַּדְּלִין בְּקוּרְבָּנִין וְעִלָּוָון וּפוּלְחָנִין, דְּהֲווּ עָבְדִין כַּהֲנִי וְלֵיוָאֵי וְיִשְׂרְאֵלֵי בְּגִין לְקָשְׁרָא קִשְׁרִין וּלְאַנְהָרָא נְהוֹרִין.","וּלְבָתַר דְּאִתְחָרַב בֵּי מַקְדְּשָׁא אִתְחַשַּׁךְ נְהוֹרָא, וְסִיהֲרָא לָא אִתְנְהִירַת מִן שִׁמְשָׁא, וְשִׁמְשָׁא אִסְתַּלַּק מִנָּהּ וְלָא אִתְנְהָרָא, וְלֵית לָךְ יוֹמָא דְּלָא שָׁלְטָא בֵּיהּ לְוָוטִין וְצַעֲרִין וּכְאֵבִין כְּמָה דְאִתְּמָר."],[[0,"וכלא בגין וכו':","וכל זה הוא בשביל מזל ההוא שהוא יסוד, הנמשך ויוצא ומתחבר במדרגה ההיא, דהיינו הנוקבא, להשתלם בו, ולהתברך ממנו. ועל כן הכל תלוי במזל. ועל כן למדנו בנים חיים ומזונות אין הדבר תלוי בזכות אלא במזל תלוי הדבר. כי אין הוא בזכות, אלא עד שהנוקבא מתמלאה ומאירה מן המזל שהוא יסוד."],[1,"ובגין כך כל אינון וכו':","ומשום זה כל אלו שנשברו בעולם הזה, והם צדיקי אמת, כולם נשברו בעולם הזה, ונידונים בדין, מטעם שנפש ההיא שקבלו מהנוקבא בהיותה בגרעון גרמה להם, וע\"כ חס עליהם הקב\"ה לעולם הבא."],[1,"","ביאור המאמר. הוא סובב על הכתוב, כי פעל אדם ישלם לו וגו'. ומבאר שמה שאנו רואים שדינים שורים גם על אדם צדיק, אע\"פ שלא חטא כלום, הוא \u0003בגין רחימותא דקב\"ה ביה איהי, דהא קב\"ה רחים ליה ברחימו לקרבא ליה לגביה,\u0004 (באות כ\"ו) שהיסורים מקרבים אותו לאהבת ה'. ועל זה מקשה ב' קושיות, א) אם גופו של הצדיק הוא ביסורין, א\"כ הוא בעצבות, ואין השכינה שורה רק כשאדם הוא בשמחה. ב) הרי אנו רואים צדיקים, שזכו לאהבת ה' אף על פי שלא היו להם יסורים כלל. ומה נשתנו אלו מאלו, ואין לתרץ שאלו שזכו לאהבת ה' בלי יסורים הוא מחמת היותם צדיקים בני צדיקים. כי אנו מוצאים אפילו בנו של צדיק בן צדיק שהיה כל ימיו ביסורים. ומשיב (באות ל\"ב) \u0003אשכחנא בספרי קדמאי רזא חדא ולגביה רזא אחרא,\u0004 שהם אמרו סוד אחד, דהיינו למה נמצאים צדיקים שהם ביסורים וצדיקים שהם בכל השלמות, ואגב זה מובן ג\"כ סוד אחר, דהיינו שבו מתישב גם מה שהקשה, הרי אין השכינה שורה על האדם מתוך עצבות, (באות כ\"ט) \u0003חד דאיהו תרין,\u0004 תירוץ אחד שיש בו ב' תירוצים על ב' הקושיות."],[1,"","וזה אמרו (באות ל\"ב) \u0003דהא אית זמנין דסיהרא איהי בפגימו\u0004 וכו', דהיינו בזמן שהנוקבא דבוקה בקו שמאל, שאז שורים בה דינים (כנ\"ל דף ו' אות כ' בביאור הכתוב, ארץ מגורי אביו ע\"ש) \u0003ובכל זמנא ובכל שעתא אית לה לאפקא נשמתין בבני נשא,\u0004 דהיינו שמוציאה נשמות לבני אדם מכל קו שבג' הקוין ימין שמאל ואמצע, הכוללים כל הזמנים ועתים שבעולם, שה\"ס כ\"ח עתים (שבספר קהלת ג'), \u0003כמה דלקטא בקדמיתא\u0004 כמו שלקטה את הנשמות מתחילה, שלקטה אותן מג' דוכתי, שהם ג' קוין, כן היא משפעת אותן לבני אדם, וע\"כ \u0003ואפיקת לון השתא בזמנא דאיהי קיימא בדינא,\u0004 שהיא מוציאה נשמות מקו שמאל. שהיא עומדת אז בדין ובגרעון, \u0003האי מאן דנקיט לה בההוא זמנא, להוי תדיר בגרעותא וכו'\u0004 כל מי שמקבל נשמה בזמן ההוא, דהיינו בזמן שליטת קו שמאל בנוקבא, הוא נמצא בהכרח בגרעון ודינים הנמשכים מקו שמאל, \u0003בין חייבא ובין זכאה,\u0004 בין אם האדם המקבלה הוא רשע בין אם הוא צדיק. אכן יש ביניהם הפרש גדול, כי אדם רשע שיש לו נפש מקו שמאל, הוא מתדבק בו ואינו יוצא ממנו לעולם. אבל אדם צדיק שיש לו נפש מקו שמאל, הנה מכח הדינים והיסורים המגיעים לו מקו השמאל, הוא מזדכך ויוצא ממנו ומתקשר בקו ימין וזוכה לאהבת ה' הנמשכת מקו ימין, ולעולם הבא. כמ\"ש להלן (באות ל\"ו) \u0003ועל דא חייס עלייהו קב\"ה לעלמא דאתי.\u0004"],[1,"","וז\"ש \u0003וההוא זמנא דקיימא ההוא דרגא בשלימו וכו',\u0004 דהיינו בעת שליטת קו אמצעי והיא בזווג עם ז\"א, \u0003ההוא בר נש אשתלים בכלא,\u0004 וכו' כי הוא מושלם מכל הבחינות הן מימין והן משמאל וז\"ש \u0003ובגין כך כל אינון דאתברו וכו' בגין דההיא נפשא גרמא להו, ועל דא חייס עלייהו קב\"ה לעלמא דאתי,\u0004 ומיושב היטב הקושיא למה יש צדיקים שהם ביסורים ויש שהם בשלימות, כי אלו שהם בשלמות הוא משום שקבלו נשמתם מן הנוקבא בעת שהיא בזווג עם היסוד, ואלו שהם ביסורין הוא משום שקבלו נשמתם מן הנוקבא בעת שהיא בשליטת קו שמאל, שצריכים יסורים כדי להפרישם משמאל ולקרבם לקו ימין לזכות באהבת ה'. הרי שפעל אדם ישלם לו וכארח איש ימציאנו, כי אע\"פ שאין להם חטא, מכל מקום כיון שיש להם נפש רק משמאל, והם מחוסרי השלמות, ע\"כ הקב\"ה האוהב אותם, מוציאם משם ע\"י היסורין ומביאם לימין, ולסוד עוה\"ב, שהיא הארת הבינה, וזוכים על ידיהם לכל השלמות."],[1,"","ובזה מיושב גם קושיא הב', (באות כ\"ט) שהקשו למה הקב\"ה שולח עליהם יסורים, כיון שצדיקים המה וראוים להשראת השכינה, ואין השכינה שורה אם אינם בשמחה. ועתה מובן היטב שהיסורים מוכרחים להם כדי להפרישם משמאל, וכל זמן שלא נפרשו משמאל מוכרחים להיות בעצבות, והשכינה אינה שורה עליהם. וכמ\"ש להלן (באות ל\"ח) \u0003ואע\"ג דנשמתין בעציבו ולא בחדוון.\u0004 וז\"ש לעיל (באות ל\"ב) \u0003רזא חדא ולגביה רזא אחרא, חד דאיהו תרין,\u0004 כי ב' הקושיות מיושבים בזה."],[2,"ר' אלעזר אמר וכו':","רא\"א, כל מה שעושה הקב\"ה הוא בדין, ואם מביא יסורין על איש צדיק, הוא, כדי לטהר את נפש ההיא, להביאה לעולם הבא, כי כל מעשיו של הקב\"ה הם בדין ובאמת. ובכדי להעביר ממנו אותה הזוהמא שקבלה בעולם הזה, על כן, נשבר אותו הגוף והנפש מטהרת, ועל כן עושה הקב\"ה לאותו צדיק שיסבול יסורין ומכאובים בעולם הזה, ויהיה נקי מכל, ויזכה לחיי העולם הבא. ועל זה כתוב, ה' צדיק יבחן, ודאי, וכבר למדנו זה."],[2,"","ר' אלעזר לא בא לתרץ הקושיות הנ\"ל, אלא בא לבאר, למה הקב\"ה מביא יסורים על הצדיק. ולפי שאומר טעם אחר ממה שנמצא בספרי קדמאי, ע\"כ מביאו הזהר כאן."],[3,"ר\"ש פתח וכו':","ר\"ש פתח, אך אל הפרכת וגו' כי מום בו וגו'. \u0003אך אל הפרכת לא יבא:\u0004 בוא וראה באותה שעה שנהר ההוא הנמשך ויוצא מעדן שהוא יסוד כנ\"ל, מוציא כל אלו הנשמות אל הנוקבא, והנוקבא מתעברת מהן, נמצאות כולן בפנימיות שלה, בחדר שלפנים מחדר שקירותיו מצופים בנייר או בשטיחים. \u0003קורטא\u0004 פירושו חדר, \u0003בסיטו,\u0004 פירושו שטיחים או טאפעטען של נייר המכסים את קירות החדר."],[3,"","פירוש. כל ספירה וספירה של הנוקבא כלולה מג' כלים, המכונים חיצון תיכון פנימי. כלי החיצוני הוא מבחינתה עצמה. כלי התיכוני הוא בחינת ז\"א שבה. כלי הפנימי הוא בחינת בינה שבה. וכל אור מקובל בכלי המיוחס לאור ההוא. וז\"ש \u0003כלהו קיימין לנו, בקורטא דלגו בסיטו קורטא,\u0004 דהיינו ג' כלים זה בתוך זה: קורטא, בסיטו, קורטא. וכיון שהנשמות, הן אורות מבינה, ע\"כ הנוקבא מקבלתן בכלי הפנימי שבה, שהוא בחינת בינה. ומה שהזהר מכנה כלי התיכון בשם בסיטו, שהוא לבוש משטיחים או טאפעטען על קירות הבית, ואינו מכנהו בשם קורטא, שהוא בית, הוא כי השם בית מיוחס רק לנוקבא, וע\"כ כלי החיצון הנמשך מנוקבא עצמה, וכלי פנימי הנמשך מבינה, שהן שתיהן נקבות, מכנה אותם קורטא. אבל כלי התיכון הנמשך מז\"א, שהוא בחינת לבוש ולא בית, ע\"כ מכנה את הכלי שלו בשם \u0003בסיטו,\u0004 שהוא רק לבוש אל הבית."],[4,"וכד סיהרא אתפגים וכו':","וכשהלבנה נפגמת מאותה הבחינה של נחש הרע, אז כל אלו הנשמות שיוצאות בעת ההוא, אף על פי שכולן טהורות, וכולן קדושות, כיון שיצאו בשעת הפגם, הרי בכל המקומות, דהיינו הגופים, שהנשמות מגיעות, כולם נשברים ונפגמים בהרבה צער ובהרבה מכאובים. ואלו הם, שהקב\"ה רוצה ואוהב אותם אחר שנשברים, ואף על פי שהנשמות הן בעצבות ולא בשמחה."],[4,"","ביאור הדברים. יש ב' מיני פגם בלבנה שהיא הנוקבא. א) בעת שהיא בשליטת השמאל, שהיא \u0003בחינת חשך דאמא,\u0004 שמבחינת פגם זה מדברים בספרי קדמאי (לעיל אות ל\"ב) ב) מבחינת הנחש הרע שנגרם בחטא עץ הדעת בסוד \u0003לא זכי הא רע,\u0004 שנגלה מדת הדין שבנוקבא מצמצום א', שאינה ראויה לקבל האור, (כמ\"ש לעיל בהקדמת ספר הזהר דף קכ\"ד אות קכ\"ג ד\"ה אמאי עש\"ה). וזהו שמדייק ר' שמעון, ואומר, \u0003וכד סיהרא אתפגים בההוא סטרא דחויא בישא,\u0004 שהפגם היא מבחינת הנוקבא עצמה, מכח שנגלה, שאינה ראויה לקבל אור, על ידי הנחש הרע בחטא דעצה\"ד. ופגם הזה אינו נוגע לנשמות שבתוכה כלל, כי הנשמות, הן נמשכות מבינה שעליה לא היה שום צמצום, ועם כל זה, גם הן נפגמו עם הנוקבא, וז\"ש \u0003כל אינון נשמתין דנפקין אע\"ג דכלהו דכיין, וכלהו קדישין,\u0004 כי הפגם הזה נוגע רק לנוקבא לבדה, ולא לנשמות הבאות אליה מן הבינה כנ\"ל, עכ\"ז, \u0003הואיל ונפלו בפגימו, בכל אלו אתרי דמטו אינון נשמתין כלהו אתברי ואתפגימו,\u0004 כי להיותן בתוך הנוקבא נפגמו הנשמות ביחד עם הנוקבא, ודומות כמו שהיו חלק מנוקבא, וע\"כ כשהן באות אחר כך ומתלבשות בתוך גוף בן אדם, אע\"פ שהאדם הוא צדיק, נפגם גופו מפאת אותה הנשמה שנתלבשה בו."],[4,"","אמנם הדברים צריכים ביאור, כי איך אפשר לומר זה שהנשמה פוגמת את הגוף. והענין הוא שהוא תקון מיוחד בשביל הצדיק שעל ידי תקון זה, נעשה גופו של הצדיק מוכשר לקבל אורה הגדול של הנשמה, ותקון זה מתחיל מבינה בסוד אמא אוזיפת לברתא מאנהא, כי הבינה ראתה שאין הנוקבא ראויה לקבל המוחין, אז העלתה אליה את הנוקבא ונתמעטה בסבתה לו\"ק חסר ראש, שנשארה במ\"י ואתוון אל\"ה הורידה אל הנוק', ומתוך שהנוקבא קבלה הקטנות של הבינה, הוכשרה אח\"כ לקבל גם הגדלות שלה, (כמ\"ש לעיל בהקדמת ספר הזהר דף כ\"ו ד\"ה וזה אמרו ע\"ש היטב בכל ההמשך) וזסו\"ה ונהר יוצא מעדן להשקות את הגן. כי עדן ה\"ס חכמה, ונהר ה\"ס בינה, וגן ה\"ס מלכות. ואומר שע\"כ יצא הנהר שהיא בינה מן העדן שה\"ס חכמה, ונתמעט לו\"ק חסר ראש, הוא כדי להשקות את הגן, דהיינו ליתן מוחין לנוקבא, כי ע\"י יציאה זו השפיעה הבינה הקטנות אל הנוקבא, ואחר שקבלה הקטנות שלה כבר ראויה לקבל גם הגדלות שלה, וע\"כ מתחיל ר\"ש המאמר, \u0003בההיא שעתא דההוא נהר דנגיד ונפיק וכו',\u0004 כי הוא המכשיר לנוקבא לקבל הקטנות דאמא, שה\"ס עיבור, ועי\"ז יכולה לקבל גם הגדלות. ועל דרך זה אחר שנשלמה הנוקבא והיא רוצה להשפיע נשמות לבני אדם, אשר גופם נמשך מנוקבא מטרם תקונה, ואינם ראוים לקבל אור הנשמה, היא חוזרת ומתמעטת לבחינת ו\"ק בלי ראש, שה\"ס הפגם של נחש הרע כנ\"ל, שעי\"ז נפגמות גם הנשמות שבה כנ\"ל, ומשפעת את נשמות הפגומות לבני אדם, כדי שגופם יקבל את הפגם והקטנות של הנשמות, ואז נעשו הגופים מוכשרים לקבל גם את אור גדלות הנשמות. והבן היטב. הרי שענין הפגם הזה, אשר הנשמות פוגמות את הגופים, הוא לתקון הגוף להכשירו לקבל אור הגדלות."],[4,"","וז\"ש \u0003ואילין אינון דאתרעי בהו קב\"ה לבתר דאתברו,\u0004 כי אחר שהגוף נשבר ע\"י הפגם והקטנות של הנשמה, שנעשה בזה כלי לקבל גם את הגדלות של הנשמה, אז רוצה בהם הקב\"ה. מה שאין כן בטרם שהגוף נשבר מחמת פגם הנשמה, אינו רוצה בהם הקב\"ה. כי אינו ראוי לקבל אור הנשמה, להיותו נמשך מן נוקבא מטרם תקונה, שצמצום א' רוכב עליהם כנ\"ל."],[5,"רזא דמלה שריין וכו':","סוד הדבר, ששורים כמו למעלה, בנוקבא, שהגוף נפגם ובפנימיותו הנשמה, כמות שהיא בנוקבא, אשר בנוקבא הפגומה שורה הנשמה, כן כאן שורה הנשמה בגוף הפגום, וזה כעין זה. ומשום זה, אלו הם הצריכים להתחדש בהתחדשות הלבנה. ועל אלו כתוב, והיה מדי חדש וגו' יבא כל בשר וגו', \u0003כל בשר,\u0004 ודאי, כי אלו יתחדשו לגמרי, וצריכים להתחדש בהתחדשות הלבנה."],[5,"","פירוש. כי לאחר שגופם קבלו הפגם והקטנות של הנשמה, כבר הם ראוים לקבל אורות דגדלות המושפעים בחדש ושבת, שה\"ס אור החיה. וז\"ש \u0003ועל אלין כתיב וכו'.\u0004 ונודע שה' כלים יש בפרצוף, המכונים, מוחא, עצמות, גידין, בשר, עור, שה\"ס כח\"ב תו\"מ. ומטרם שיהיה בפרצוף כלי דבשר אינו ראוי לאור החיה, (כמ\"ש זה לעיל בפ' נח דף מ\"ח ד\"ה ונודע עש\"ה) וז\"ש \u0003כל בשר ודאי, דאלין יתחדתון בכלא,\u0004 כי כלי דבשר, כולה מיוחד להמשכת אור החיה, הנמשך בחדש ושבת, משא\"כ הכלים מוחא עצמות גידין, מקבלים רק חלק מאור הזה, כי הם מיוחדים בעיקר לג' אורות נר\"נ."],[6,"ואלין אינון בשותפותא וכו':","ואלו הצדיקים הם בשותפות תמיד עם הלבנה, שהיא הנוקבא, ופגומים באותו פגם שלה, דהיינו פגם מקטנות הבינה, כמ\"ש לעיל, שע\"כ היא ראויה לאור גדלות הבינה, ומשום זה היא שורה תמיד בתוכם ואינה עוזבתם, כמש\"א, ואת דכא וגו'. וכתוב קרוב ה' לנשברי לב, היינו, לאלו שסבלו עם הלבנה אותו הפגם, מקטנות הבינה, הם קרובים אליה תמיד, כי זוכים מחמת זה לקבל גם מגדלות הבינה. וע\"כ \u0003להחיות לב נדכאים\u0004 באלו החיים הבאים אל הנוקבא להתחדש דהיינו אור החיה, יהיה להם חלקם. כי אלו שסבלו עמה יתחדשו עמה, כי מחמת שקבלו הקטנות מקבלים ג\"כ הגדלות כנ\"ל."],[7,"ואלין אקרון יסורין וכו':","ואלו דהיינו הפגמים שהצדיקים סובלים מחמת קטנות הבינה, הם נקראים יסורין של אהבה, כי \u0003של אהבה\u0004 הם, ולא מחמת האדם עצמו. \u0003של אהבה\u0004 הם, מחמת שנפגם האור של אהבה הקטנה, שהיא הנוקבא, בעת קבלתה מקטנות הבינה, שנדחתה מאהבה רבה, שהיא הבינה בגדלותה. משום זה אלו הצדיקים הם חברים ושותפים עמה, בפגם שלה. אשרי חלקם בעולם הזה ובעולם הבא, כי הם זכו לזה להיות חברים עמה, עליהם כתוב, למען אחי ורעי וגו'."],[8,"פתח ואמר הנה ישכיל עבדי וגו':","אשרי חלקם של הצדיקים שהקב\"ה גילה להם דרכי התורה ללכת בהם, בוא וראה, מקרא זה, הנה ישכיל עבדי, סוד עליון הוא, ובארוהו. אבל בוא וראה, כשברא הקב\"ה את העולם, שה\"ס זו\"ן, עשה את הלבנה. שהאציל את הנוקבא בקומה שוה עם ז\"א, ואח\"כ, מיעט אורותיה, באופן, שאין לה מעצמה כלום רק מה שמקבלת מז\"א, ומשום שמיעטה את עצמה, היא מאירה מן השמש, שהוא ז\"א, ובכח אורות עליונים שבו. (וכבר נתבאר ענין זה לעיל בראשית א' ד\"ה אות ק\"י ד\"ה כד הות סיהרא, ע\"ש כל ההמשך)."],[9,"ובזמנא דהוה וכו':","ובזמן שבית המקדש היה קיים. היו ישראל משתדלים בקרבנות ועולות ועבודות שהיו עובדים הכהנים הלוים והישראלים, כדי ליחד יחודים, ולהאיר האורות בנוקבא."],[10,"ולבתר דאתחרב וכו':","ולאחר שנחרב בית המקדש נחשך האור, והלבנה שהיא הנוקבא, אינה מאירה מן השמש, שהוא ז\"א, והשמש נסתלק ממנה ואינו מאיר. ואין לך יום שאינו שולט בו קללות וצער ומכאובים, כמו שלמדנו."]],[[0,"","וְהַכּל מִשּׁוּם אוֹתוֹ הַמַּזָּל שֶׁשּׁוֹפֵעַ וְיוֹצֵא וּמִתְחַבֵּר בְּאוֹתָהּ הַדַּרְגָּה לְהִשְׁתַּלֵּם בּוֹ וּלְהִתְבָּרֵךְ מִמֶּנּוּ, וְעַל כֵּן הַכֹּל בְּמַזָּל הַדָּבָר תָּלוּי. וְעַל כֵּן שָׁנִינוּ, בָּנִים, חַיִּים וּמְזוֹנוֹת - לֹא בִזְכוּת תְּלוּיִים, אֶלָּא בְּמַזָּל הַדָּבָר תָּלוּי, שֶׁהֲרֵי בִּזְכוּת אֵינוֹ אֶלָּא עַד שֶׁמִּתְמַלֵּאת וּמְאִירָה מִן הַמַּזָּל."],[1,"","וּמִשּׁוּם כָּךְ, כָּל אוֹתָם שֶׁנִּשְׁבְּרוּ בָּעוֹלָם הַזֶּה, וְהֵם צַדִּיקֵי אֱמֶת, כֻּלָּם נִשְׁבָּרִים בָּעוֹלָם הַזֶּה וְנִדּוֹנִים בְּדִין. מָה הַטַּעַם? מִשּׁוּם שֶׁאוֹתָהּ הַנֶּפֶשׁ גָּרְמָה לָהֶם, וְעַל כֵּן חָס עֲלֵיהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לָעוֹלָם הַבָּא."],[2,"","רַבִּי אֶלְעָזָר אָמַר, כָּל מַה שֶּׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא בְּדִין, כְּדֵי לְטַהֵר אוֹתָהּ הַנֶּפֶשׁ לְהָבִיא אוֹתָהּ לָעוֹלָם הַבָּא (ומשום כך כל מעשיו של הקדוש ברוך הוא) (נ\"א: משום שכל מעשי הקדוש ברוך הוא) הֵם בְּדִין וֶאֱמֶת, וּכְדֵי לְהַעֲבִיר מִמֶּנּוּ אוֹתָהּ זֻהֲמָה שֶׁקִּבְּלָה בָּעוֹלָם הַזֶּה, וְעַל כֵּן נִשְׁבָּר אוֹתוֹ הַגּוּף וְנִטְהֶרֶת הַנֶּפֶשׁ, וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לְאוֹתוֹ הַצַּדִּיק שֶׁיִּסְבֹּל יִסּוּרִים וּמַכְאוֹבִים בָּעוֹלָם הַזֶּה וְיִתְנַקֶּה מִן הַכֹּל וְיִזְכֶּה לְחַיֵּי עוֹלָם, וְעַל כֵּן כָּתוּב (תהלים יא) ה' צַדִּיק יִבְחָן, וַדַּאי, וְהִנֵּה נִתְבָּאֵר."],[3,"","רַבִּי שִׁמְעוֹן פָּתַח, (ויקרא כא) אַךְ אֶל הַפָּרֹכֶת לֹא יָבֹא וְאֶל הַמִּזְבֵּחַ לֹא יִגָּשׁ כִּי מוּם בּוֹ וְלֹא יְחַלֵּל אֶת מִקְדָּשַׁי כִּי אֲנִי ה' מְקַדְּשׁוֹ. אַךְ אֶל הַפָּרֹכֶת לֹא יָבא - בֹּא רְאֵה, בְּאוֹתָהּ שָׁעָה שֶׁאוֹתוֹ הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, מוֹצִיא כָּל אוֹתָן הַנְּשָׁמוֹת וְהַנְּקֵבָה מִתְעַבֶּרֶת, כֻּלָּם עוֹמְדִים בִּפְנִים בְּחָצֵר לִפְנִים מֵחָצֵר מְצֻפֶּה שְׁטִיחִים."],[4,"","וּכְשֶׁהַלְּבָנָה נִפְגֶּמֶת בְּאוֹתוֹ צַד שֶׁל הַנָּחָשׁ הָרָע, אָז כָּל אוֹתָן נְשָׁמוֹת שֶׁיּוֹצְאוֹת, אַף עַל גַּב שֶׁכֻּלָּן טְהוֹרוֹת וְכֻלָּן קְדוֹשׁוֹת - הוֹאִיל וְנָפְלוּ בַּפְּגָם, בְּכָל אוֹתָם מְקוֹמוֹת שֶׁהִגִּיעוּ אוֹתָן הַנְּשָׁמוֹת, כֻּלָּם נִשְׁבְּרוּ וְנִפְגְּמוּ בְּכַמָּה צַעַר וְכַמָּה כְאֵבִים, וְאֵלּוּ הֵם (נשמות ומקומות) (נ\"א: נשמות של מקומות של פגם) שֶׁמִּתְרַצֶּה בָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא אַחַר שֶׁנִּשְׁבְּרוּ, וְאַף עַל גַּב שֶׁהַנְּשָׁמוֹת בְּעֵצֶב וְלֹא בִשְׁמָחוֹת."],[5,"","סוֹד הַדָּבָר שׁוֹרִים כְּמוֹ שֶׁלְּמַעְלָה, הַגּוּף נִפְגָּם, וְהַנְּשָׁמָה בִּפְנִים כְּמוֹ שֶׁלְּמַעְלָה, וְזֶה כְּמוֹ זֶה. וּמִשּׁוּם כָּךְ אֵלּוּ הֵם שֶׁצְּרִיכוֹת לְהִתְחַדֵּשׁ בְּהִתְחַדְּשׁוּת הַלְּבָנָה, וְעַל אֵלּוּ כָּתוּב (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ יָבֹא כָל בָּשָׂר לְהִשְׁתַּחֲות לְפָנַי אָמַר ה'. כָּל בָּשָׂר וַדַּאי, שֶׁאֵלּוּ יִתְחַדְּשׁוּ בַּכֹּל. וּצְרִיכִים לְהִתְחַדֵּשׁ בְּהִתְחַדְּשׁוּת הַלְּבָנָה."],[6,"","וְאֵלּוּ הֵם בְּשֻׁתָּפוּת אַחַת עִם הַלְּבָנָה פְּגוּמִים בְּאוֹתוֹ הַפְּגָם שֶׁלָּהּ, וּמִשּׁוּם כָּךְ הִיא תָמִיד שׁוֹרָה בְתוֹכָם, שֶׁאֵינָהּ עוֹזֶבֶת אוֹתָם, כְּמוֹ שֶׁנֶּאֱמַר (שם נז) וְאֶת דַּכָּא וּשְׁפַל רוּחַ, וְכָתוּב (תהלים לד) קָרוֹב ה' לְנִשְׁבְּרֵי לֵב. לְאוֹתָם שֶׁסּוֹבְלִים עִם הַלְּבָנָה, אוֹתוֹ הַפְּגָם הֵם קְרוֹבִים לָהּ תָּמִיד. וְעַל זֶה לְהַחֲיוֹת לֵב נִדְכָּאִים, בְּאוֹתָם הַחַיִּים שֶׁבָּאִים לָהּ לְהִתְחַדֵּשׁ יִהְיֶה לָהֶם חֶלְקָם, אוֹתָם שֶׁסּוֹבְלִים עִמָּהּ יִתְחַדְּשׁוּ עִמָּהּ."],[7,"","וְאֵלּוּ נִקְרָאִים יִסּוּרִים שֶׁל אַהֲבָה. שֶׁל אַהֲבָה הֵם, וְלֹא מֵאוֹתוֹ הָאָדָם. שֶׁל אַהֲבָה, אוֹתָם שֶׁנִּפְגָּם הָאוֹר שֶׁל הָאַהֲבָה הַקְּטַנָּה שֶׁנִּדְחֵית מֵאַהֲבָה רַבָּה. מִשּׁוּם כָּךְ אֵלֶּה הֵם חֲבֵרִים מְשֻׁתָּפִים עִמָּהּ. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהֵם זָכוּ לָזֶה לִהְיוֹת חֲבֵרִים עִמָּהּ, עֲלֵיהֶם כָּתוּב (שם קכב) לְמַעַן אַחַי וְרֵעַי וְגוֹ'."],[8,"","פָּתַח וְאָמַר, (ישעיה נב) הִנֵּה יַשְׂכִּיל עַבְדִּי יָרוּם וְנִשָּׂא וְגָבַהּ מְאֹד. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גִּלָּה לָהֶם דַּרְכֵי הַתּוֹרָה לָלֶכֶת בָּהֶם. בֹּא רְאֵה, הַפָּסוּק הַזֶּה הוּא סוֹד עֶלְיוֹן, הִנֵּה יַשְׂכִּיל עַבְדִּי וּבֵאֲרוּהָ. אֲבָל בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה אֶת הַלְּבָנָה וְהִקְטִין לָהּ אֶת אוֹרָהּ, שֶׁהֲרֵי אֵין לָהּ מֵעַצְמָהּ כְּלוּם. וּמִשּׁוּם שֶׁהִקְטִינָה אֶת עַצְמָהּ, הֵאִירָה בִּגְלַל הַשֶּׁמֶשׁ וּבְחֹזֶק הָאוֹרוֹת הָעֶלְיוֹנִים."],[9,"","וּבִזְמַן שֶׁהָיָה בֵּית הַמִּקְדָּשׁ קַיָּם, יִשְׂרָאֵל הָיוּ מִשְׁתַּדְּלִים בְּקָרְבָּנוֹת וְעוֹלוֹת וַעֲבוֹדוֹת שֶׁהָיוּ עוֹשִׂים הַכֹּהֲנִים וּלְוִיִּם וְיִשְׂרְאֵלִים כְּדֵי לִקְשֹׁר קְשָׁרִים וּלְהָאִיר אוֹרוֹת."],[10,"","וּלְאַחַר שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, נֶחְשַׁךְ הָאוֹר, וְהַלְּבָנָה לֹא הוּאֲרָה מִן הַשֶּׁמֶשׁ, וְהַשֶּׁמֶשׁ הִסְתַּלֵּק מִמֶּנָּה וְלֹא הֵאִירָה, וְאֵין לְךְ יוֹם שֶׁלֹּא שׁוֹלְטִים בּוֹ קְלָלוֹת וְצַעַר וּכְאֵבִים, כְּמוֹ שֶׁנִּתְבָּאֵר."]]],[["וּבְהַהוּא זִמְנָא דְּמְטֵי זִמְנָא דְּסִיהֲרָא לְאִתְנַהֲרָא, מַה כְּתִיב הִנִּה יַשְׂכִּיל עַבְדִּי, עֲלֵיהּ דְּסִיהֲרָא אִתְּמָר הִנֵּה יַשְׂכִּיל עַבְדִּי דָּא הוּא רָזָא דִמְהֵימְנוּתָא. הִנֵּה יַשְׂכִּיל, דְּאִתְעַר אִתְעֲרוּתָא לְעֵילָא כְּמַאן דְאָרַח רֵיחָא וְאָתֵי לְאִתְעָרָא וּלְאִסְתַּכָּלָא. יָרוּם, מִסִּטְרָא דִנְהוֹרָא עִלָּאָה דְּכָל נְהוֹרִין.","יָרוּם, כְּמָה דְאַתְּ אָמֵר, (ישעיהו ל׳:י״ח) וְלָכֵן יָרוּם לְרַחֶמְכֶם. וְנִשָּׂא, מִסִּטְרָא דְאַבְרָהָם. וְגָבַהּ, מִסִּטְרָא דְיִצְחָק. מְאֹד, מִסִּטְרָא דְיַעֲקֹב. וְאַף עַל גַּב דְּאוּקְמוּהָ, וְכֹלָּא חַד בְּרָזָא דְחָכְמְתָא.","וּבְהַהוּא זִמְנָא יִתְעַר קוּדְשָׁא בְּרִיךְ הוּא אִתְעֲרוּתָא עִלָּאָה לְאַנְהָרָא לָהּ לְסִיהֲרָא כְּדְקָא יְאוּת כְּמָה דְאַתְּ אָמֵר, (ישעיהו ל׳:כ״ו) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים. וּבְגִין כָּךְ יִתּוֹסַף בָּהּ רוּחַ עִלָּאָה, וּבְגִין כָּךְ יִתְעָרוּן כְּדֵין כָּל אִינוּן מֵיתַיָא דְּאִינוּן גּוֹ עַפְרָא.","וְדָא הוּא עַבְדִּי, רָזָא דְמַפְתְּחָן דְּמָארֵיהּ בִּידֵיהּ. כְּמָה דְאַתְּ אָמֵר, (אל עבדו זקן ביתו וכמה דאת אמר), (בראשית כ״ד:ב׳) וַיֹּאמֶר אַבְרָהָם אֶל עַבְדוֹ, דָּא סִיהֲרָא כְּמָה דְאִתְּמָר, מטטרו\"ן דְּאִיהוּ עֶבֶד שְׁלִיחָא דְּמָארֵיהּ.","זְקַן בֵּיתוֹ כְּמָה דְאַתְּ אָמֵר, (תהילים ל״ז:כ״ה) נַעַר הָיִיתִי גַּם זָקַנְתִּי. הַמּוֹשֵׁל בְּכָל אֲשֶׁר לוֹ, בְּגִין דְּכָל גְּוָונִין אִתְחֲזוּן בֵּיהּ יָרוֹ\"ק וְחִוָּו\"ר וְסוּמָ\"ק.","שִׂים נָא יָדְךָ תַּחַת יְרֵכִי, דָּא הוּא צַדִּיק רָזָא דְמִלָּה, קִיּוּמָא דְעַלְמָא. דְּהָא כְּדֵין הַאי עֶבֶד מְמַנָּא בְּרָזָא עִלָּאָה לַאֲחָיָיא לוֹן לְדַיְירֵי עַפְרָא וְיִתְעֲבִיד שְׁלִיחָא בְּרוּחָא דִלְעֵילָא וְלְאֲתָבָא רוּחִין וְנִשְׁמָתִין לְאַתְרַיְיהוּ לְאִינוּן גּוּפֵי (ס\"א דאתאכלו) דְּאִתְבָּלוּ וְאִתְרְקָבוּ תְּחוֹת עַפְרָא.","וְאַשְׁבִּיעֲךָ בַּיְיָ אֱלהֵי הַשָּׁמַיִם. וְאַשְׁבִּיעֲךָ, מַאי וְאַשְׁבִּיעֲךָ. לְאִתְלַבְּשָׁא בְּרָזָא דִּשְׁבַע נְהוֹרִין עִלָּאִין דְּאִינוּן רָזָא דִשְׁלִימוּ עִלָּאָה. אֲשֶׁר לֹא תִקַּח אִשָּׁה, דָּא הוּא גוּפָא דִּתְחוֹת עַפְרָא דְּאִית לֵיהּ קִיּוּמָא לַאֲקָמָא מֵעַפְרָא. דְּכָל אִינוּן דְּאִתְקְבָרוּ בָהּ וְזָכוּ לְאִתְקְבָרָא בְּאַרְעָא דְיִשְׂרָאֵל אִינוּן יִתְעָרוּן בְּקַדְמִיתָא, כְּמָה דְאוֹקִימְנָא. דִּכְתִיב, (ישעיהו כ״ו:י״ט) יִחְיוּ מֵתֶיךָ, בְּקַדְמִיתָא אִלֵּין מֵתִין דְאַרְעָא דְיִשְׂרָאֵל. נְבֵלָתִי יְקוּמוּן, אִינוּן מֵתִין דִּשְׁאָר אַרְעָאן. וְעַל דָּא לְאִינוּן גּוּפֵיהוֹן דְּיִשְׂרָאֵל דְּאִתְקְבָרוּ תַּמָּן, וְלָא לְגוּפֵי דִּשְׁאָר עַמִין עוֹבְדֵי עֲבוֹדָה זָּרָה דְּאִסְתָּאֲבָא אַרְעָא מִינַיְיהוּ.","וְעַל דָּא אֲשֶׁר לא תִקַּח אִשָּׁה לִבְנִי. מַאי לִבְנִי. דְּכָל נִשְׁמָתִין דְּעַלְמָא דְּנָפְקֵי מֵהַהוּא נָהָר דְּנָגִיד וְנָפִיק, אִינוּן בְּנִין לְקוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא אֲשֶׁר לֹא תִקַּח אִשָּׁה, דָּא גוּפָא. לִבְנִי, דָּא נִשְׁמָתָא. מִבְּנוֹת הַכְּנַעֲנִי, אִלֵּין גּוּפִין דְּעַמִּין עוֹבְדֵי עֲבוֹדָה זָּרָה, דְּזָמִּין קוּדְשָׁא בְּרִיךְ הוּא לְנַעֲרָא לוֹן מֵאַרְעָא קַדִּישָׁא. כְּמָה דְאַתְּ אָמֵר, (איוב ל״ח:י״ג) וְיִנָּעֲרוּ רְשָׁעִים מִמֶּנָּהּ. כְּמַאן דִּמְנַעֵר טַלִּיתָא מִזּוּהֲמָא דִילָהּ.","כִּי אֶל אַרְצִי וְאֶל מוֹלַדְתִּי תֵּלֵךְ. אַרְצִי, דָּא הִיא אַרְעָא קַדִּישָׁא דְּאִיהוּ קַדְמָאָה לְכָל שְׁאָר אַרְעִין כְּמָה דְאִתְּמָר. (ועל דא כי אל ארצי דא ארעא קדישא דאיהו דיליה בין כל שאר ארעין דפליג לון לממנן אחרנין) וְעַל דָּא כִּי אֶל אַרְצִי, וְאֶל מוֹלַדְתִּי. כֵּיוָן דְּאָמַר אֶל אַרְצִי מַהוּ וְאֶל מוֹלַדְתִּי. אֶלָּא אֶל אַרְצִי כְּמָה דְאִתְּמָר, (מהו) וְאֶל מוֹלַדְתִּי אִלֵּין אִינוּן יִשְׂרָאֵל.","תָּא חֲזֵי, מַה כְּתִיב, וַיִּקַּח הָעֶבֶד כְּמָה דְאִתְּמָר. עֲשָׂרָה גְמַלִּים, אִלֵּין אִינוּן עֲשָׂרָה דַרְגִּין דְּהַאי עֶבֶד שָׁלְטָא עֲלַיְיהוּ, כְּגַוְונָא דִלְעֵילָא. מִגְּמַלֵּי אֲדֹנָיו, דְּאִינוּן כְּהַהוּא גַוְונָא מַמָּשׁ כְּמָה דְאִתְּמָר, וְהַאי עֶבֶד שָׁלְטָא וְאִתְתַּקַּן בְּהוּ.","וְכָל טוּב אֲדֹנָיו בְּיָדוֹ, כָּל הַהוּא טִיבוּ רֵיחִין עִלָּאִין דְּנָפְקֵי מִגּוֹ אִינוּן נְהוֹרִין וּבוֹצִינִין עִלָּאִין. וְכָל טוּב אֲדוֹנָיו, הַהוּא שִׁמּוּשָׁא דְּשִׁמְשָׁא דְּאִתְמַשְּׁכָא בָּהּ בְּסִיהֲרָא.","וַיָּקָם וַיֵּלֶךְ אֶל אֲרַם נַהֲרַיִם, דָּא אֲתַר דְּאַרְעָא קַדִּישָׁא דְּבָכַת תַּמָּן רָחֵל כַּד חָרִיב בֵּי מַקְדְּשָׁא. וַיַּבְרֵךְ הַגְּמַלִּים מִחוּץ לָעִיר אֶל בְּאֵר הַמָּיִם, לְאִתְתַּקְפָא חֵילָהָא בְּתוּקְפָהָא כְּדְקָא יְאוּת עַד לָא תִיעוּל לַאֲקָמָא לוֹן לְאִינוּן גּופִין."],[[0,"ובההוא זמנא דמטי וכו':","ובזמן ההוא, שיגיע זמן הלבנה להאיר מכחה עצמה, דהיינו בגמר התקון מה כתוב, הנה ישכיל עבדי וגו', שנאמר על הלבנה. \u0003הנה ישכיל עבדי,\u0004 זהו סוד האמונה שהיא הנוקבא. \u0003הנה ישכיל,\u0004 פירושו שנתעורר אז התעוררות של מעלה, בדומה למי שמריח ריח ובא להעיר ולהסתכל."],[0,"","פירוש. כי הלשון \u0003הנה ישכיל,\u0004 יורה פתאומיות, וע\"כ מפרש שהוא משום שנשפע אז על הנוקבא התעוררות של מעלה, בלי הקדם של אתערותא דלתתא, וכיון שהריחה בזה באה להעיר ולהסתכל ולהשכיל, וע\"כ נאמר על זה, הנה \u0003ישכיל,\u0004 כמאן דארח ריחא וכו'."],[1,"ירום, מסתרא וכו':","ירום, פירושו, שהנוקבא תתמלא מבחינת אור העליון על כל האורות, דהיינו כתר. \u0003ירום,\u0004 הוא כמו שאתה אומר, ולכן ירום לרחמכם, שהכונה הוא לאור הכתר אף \u0003ירום\u0004 שבכאן הוא כתר. \u0003ונשא\u0004 הוא מצד אברהם, שהוא חסד. \u0003וגבה\u0004 הוא מצד יצחק, שהוא גבורה. \u0003מאד\u0004, מצד יעקב, שהוא ת\"ת. דהיינו שהנוקבא תתמלא מכל המדרגות האלו. ואף על פי \u0003שבארוהו\u0004 בדרך אחר, \u0003הכל הוא אחד בסוד החכמה.\u0004"],[2,"ובההוא זמנא וכו':","ובעת ההוא, יעורר הקב\"ה התעוררות של מעלה להאיר אל הלבנה, שהיא הנוקבא, כראוי, כמש\"א, והיה אור הלבנה כאור החמה ואור החמה וגו'. ומשום זה יתוסף בה אור העליון, ועל כן יתעוררו אז לתחיה כל המתים שהם נקברים תוך העפר."],[3,"ודא הוא עבדי וכו':","וזה הוא שאומר \u0003עבדי,\u0004 אע\"פ שהמדובר הוא בנוקבא, כי הסוד של מפתחות רבונו הוא בידו. וע\"כ מתגלה על ידו שלמות הנוקבא, והוא שליחה. כמו שאתה אומר, ויאמר אברהם אל עבדו, שזהו הלבנה, דהיינו הנוקבא, כמו שלמדנו, והיא מתגלית על ידי מטטרון, שהוא עבד שליח של רבונו, וע\"כ נאמר שם עבדו, אף כאן כן."],[4,"זקן ביתו:","היינו מטטרון שנקרא זקן, כמו שאתה אומר נער הייתי גם זקנתי, שמקרא זה שר העולם אמרו שהוא מטטרון. \u0003המושל בכל אשר לו:\u0004 משום שכל הצבעים נראים בו, שהם ירוק לבן ואדום, פי' שה\"ס ג' גווני הקשת, שהם ג' מלאכים מיכאל גבריאל רפאל, שאין השכינה נראת אלא עמהם (כנ\"ל פרשת וירא דף כ' אות נ\"ג) ומטטרון כולל אותם."],[5,"שים נא ידך תחת ירכי:","זהו צדיק, דהיינו יסוד, וסוד הדבר הוא, מפני שהוא קיומו וחיותו של העולם, כי אז, כשנאחז ביסוד, נעשה עבד הזה ממונה להחיות את שוכני עפר, ונעשה שלם ברוח העליון, להשיב רוחות ונשמות למקומם, אל אלו הגופים שנבלו ונרקבו תחת העפר."],[6,"ואשביעך בה' אלקי השמים:","שואל, כתוב, ואשביעך, מהו ואשביעך. ומשיב, שפירושו, שיתלבש בסוד שבעה האורות העליונים, חג\"ת נהי\"מ, שהם סוד שלימות העליון. ודורש ואשביעך, שהוא מלשון שבעה. \u0003אשר לא תקח אשה:\u0004 זהו הגוף שמתחת העפר בקבר, שיש לו עתה תחיה לקום מעפר, הוא מכונה אשה, שכל אלו שנקברו בו וזכו להקבר בארץ ישראל, הם יתעוררו תחילה לתחיה, כמו שבארנו, שכתוב מתחילה \u0003יחיו מתיך, שהם המתים שבארץ ישראל, ואח\"כ כתוב, נבלתי יקומון,\u0004 הם המתים שבחוץ לארץ. ועם זה רק הגופות של ישראל שנקברו שם, בארץ ישראל, תקמנה, ולא הגופות של עמים האחרים, שהארץ נטמא מהן."],[7,"ועל דא אשר לא תקח אשה לבני:","מהו לבני. ומשיב, שכל נשמות העולם היוצאות מאותו הנהר הנמשך ויוצא מעדן, שהוא יסוד הן בנים אל הקב\"ה. ועל כן, \u0003אשר לא תקח אשה,\u0004 זהו הגוף. \u0003לבני,\u0004 זהו הנשמה. \u0003מבנות הכנעני,\u0004 אלו הם גופות עמים עובדי ע\"ז, שעתיד הקב\"ה לנער אותן מארץ הקדושה, כמש\"א, וינערו רשעים ממנו. כמי שמנער טליתו מזוהמתו."],[8,"כי אל ארצי ואל מולדתי תלך:","ארצי, זה היא ארץ הקדושה, שהיא קודמת לכל ארצות אחרות, כמו שלמדנו. \u0003כי אל ארצי ואל מולדתי,\u0004 שואל, כיון שאומר \u0003אל ארצי,\u0004 מהו שוב, \u0003ואל מולדתי,\u0004 ומשיב, אלא \u0003אל ארצי,\u0004 הוא כמו שאמרנו, שהיא ארץ הקדושה. \u0003ואל מולדתי,\u0004 אלו הם ישראל."],[9,"ת\"ח מה כתיב וכו':","בוא וראה מה כתוב, \u0003ויקח העבד,\u0004 הוא כמו שלמדנו, שהוא מטטרון. \u0003עשרה גמלים,\u0004 אלו הם עשר מדרגות שהעבד ההוא שולט עליהן, שהן כעין של מעלה, כמו מדרגות האצילות. \u0003מגמלי אדוניו,\u0004 שהן כעין גמלי אדוניו ממש, דהיינו מדרגות הנוקבה שבאצילות, שהיא אדונו. כמו שלמדנו. ואותו העבד שולט עליהן ומתתקן בהן."],[10,"וכל טוב אדניו בידו:","היינו כל אותו הטוב וריחות העליונים, היוצאים מתוך אלו האורות והנרות העליונים. פירוש אחר, \u0003וכל טוב אדניו,\u0004 היינו שמוש ההיא של השמש, שהוא ז\"א, הנמשך בלבנה, שהיא הנוקבא.כלומר שעל ידו הוא זווג זו\"ן."],[11,"ויקם וילך אל ארם נהרים:","זה הוא מקום בארץ הקדושה, שבכתה שם רחל כשנחרב בית המקדש. \u0003ויברך הגמלים מחוץ לעיר אל באר המים:\u0004 כדי לחזק את כחותיה על ידי גבורותיה כראוי, מטרם שבא להקים ולהחיות הגופים."],[11,"","פירוש. גמלים ה\"ס מדרגותיו של העבד כנ\"ל, ומפרש הזהר, שע\"כ סידר אותם מחוץ לעיר, ששם מקום הדינים, כדי לתקן הקו שמאל של הנוקבא כראוי לה. ואין לומר שהוא חוצה לארץ, שהרי לא הלך אלא לארץ ישראל כנ\"ל."]],[[0,"","וּבְאוֹתוֹ זְמַן שֶׁהִגִּיעַ זְמַן הַלְּבָנָה לְהָאִיר, מַה כָּתוּב? הִנֵּה יַשְׂכִּיל עַבְדִּי. נֶאֱמַר עַל הַלְּבָנָה הִנֵּה יַשְׂכִּיל עַבְדִּי, זֶהוּ סוֹד הָאֱמוּנָה. הִנֵּה יַשְׂכִּיל - שֶׁמִּתְעוֹרֶרֶת הִתְעוֹרְרוּת שֶׁלְּמַעְלָה, כְּמִי שֶׁהֵרִיחַ רֵיחַ וּבָא לְהִתְעוֹרֵר וּלְהִסְתַּכֵּל. יָרוּם - מִצַּד הָאוֹר הָעֶלְיוֹן שֶׁל כָּל הָאוֹרוֹת."],[1,"","יָרוּם - כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ל) וְלָכֵן יָרוּם לְרַחֶמְכֶם. וְנִשָּׂא - מֵהַצַּד שֶׁל אַבְרָהָם. וְגָבַהּ - מֵהַצַּד שֶׁל יִצְחָק. מְאֹד - מִצִּדּוֹ שֶׁל יַעֲקֹב. וְאַף עַל גַּב שֶׁבֵּאֲרוּהוּ, וְהַכֹּל אֶחָד בַּסּוֹד שֶׁל הַחָכְמָה."],[2,"","וּבְאוֹתוֹ זְמַן יְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְעוֹרְרוּת עֶלְיוֹנָה לְהָאִיר לַלְּבָנָה כָּרָאוּי, כְּמוֹ שֶׁנֶּאֱמַר (שם) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים. וּמִשּׁוּם כָּךְ תִּתּוֹסֵף לָהּ רוּחַ עֶלְיוֹנָה, וּמִשּׁוּם כָּךְ יִתְעוֹרְרוּ אָז כָּל אוֹתָם הַמֵּתִים שֶׁהֵם בְּתוֹךְ הֶעָפָר."],[3,"","וְזֶהוּ עַבְדִּי, הַסּוֹד שֶׁמַּפְתְּחוֹת רִבּוֹנוֹ בְּיָדוֹ, כְּמוֹ שֶׁנֶּאֱמַר (אל עבדו זקן ביתו, וכמו שנאמר) (בראשית כד) וַיֹּאמֶר אַבְרָהָם אֶל עַבְדּוֹ. זוֹ הַלְּבָנָה כְּמוֹ שֶׁנֶּאֱמַר, מטטרו\"ן שֶׁהוּא עֶבֶד שְׁלִיחַ רִבּוֹנוֹ."],[4,"","זְקַן בֵּיתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לז) נַעַר הָיִיתִי גַּם זָקַנְתִּי. הַמֹּשֵׁל בְּכָל אֲשֶׁר לוֹ, מִשּׁוּם שֶׁכָּל הַגְּוָנִים נִרְאִים בּוֹ יָרֹ\"ק וְלָבָ\"ן וְאָדֹ\"ם."],[5,"","שִׂים נָא יָדְךְ תַּחַת יְרֵכִי - זֶהוּ הַצַּדִּיק, סוֹד הַדָּבָר קִיּוּם הָעוֹלָם, שֶׁהֲרֵי אָז הָעֶבֶד הַזֶּה מְמֻנֶּה בְּסוֹד עֶלְיוֹן לְהַחֲיוֹת אֶת שׁוֹכְנֵי הֶעָפָר, וְיֵעָשֶׂה שָׁלִיחַ בְּרוּחַ שֶׁל מַעְלָה לְהָשִׁיב הָרוּחוֹת וְהַנְּשָׁמוֹת לִמְקוֹמָן לְאוֹתָם גּוּפִים (שנאכלו) שֶׁהִתְבַּלּוּ וְנִרְקְבוּ תַּחַת הֶעָפָר."],[6,"","וְאַשְׁבִּיעָךָ בַּה' אֱלֹהֵי הַשָּׁמַיִם. וְאַשְׁבִּיעֲךְ - מַה זֶה וְאַשְׁבִּיעֲךְ? לְהִתְלַבֵּשׁ בְּסוֹד שֶׁל שִׁבְעָה אוֹרוֹת עֶלְיוֹנִים, שֶׁהֵם סוֹד הַשְּׁלֵמוּת הָעֶלְיוֹנָה. אֲשֶׁר לֹא תִקַּח אִשָּׁה - זֶהוּ הַגּוּף שֶׁתַּחַת הֶעָפָר שֶׁיֵּשׁ לוֹ קִיּוּם לְהָקִים מֵהֶעָפָר, שֶׁכּל אוֹתָם שֶׁנִּקְבְּרוּ בָהּ וְזָכוּ לְהִקָּבֵר בְּאֶרֶץ יִשְׂרָאֵל, הֵם יִתְעוֹרְרוּ בָּרִאשׁוֹנָה, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (ישעיה כו) יִחְיוּ מֵתֶיךְ, בָּרִאשׁוֹנָה - אֵלּוּ הַמֵּתִים שֶׁל אֶרֶץ יִשְׂרָאֵל. נְבֵלָתִי יְקוּמוּן - אוֹתָם הַמֵּתִים שֶׁל שְׁאָר הָאֲרָצוֹת. וְעַל זֶה לְאוֹתָם גּוּפִים שֶׁל יִשְׂרָאֵל שֶׁנִּקְבְּרוּ שָׁם, וְלֹא לְגוּפוֹת שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁהָאָרֶץ נִטְמְאָה מֵהֶם."],[7,"","וְעַל כֵּן, אֲשֶׁר לֹא תִקַּח אִשָּׁה לִבְנִי. מַה זֶּה לִבְנִי? שֶׁכָּל נִשְׁמוֹת הָעוֹלָם שֶׁיּוֹצְאוֹת מֵאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, הֵם בָּנִים לַקָּדוֹשׁ- בָּרוּךְ-הוּא. וְעַל זֶה אֲשֶׁר לֹא תִקַּח אִשָּׁה - זֶה הַגּוּף. לִבְנִי - זוֹ הַנְּשָׁמָה. מִבְּנוֹת הַכְּנַעֲנִי - אֵלּוּ גוּפוֹת שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְנַעֵר אוֹתָם מֵהָאָרֶץ הַקְּדוֹשָׁה, כְּמוֹ שֶׁנֶּאֱמַר (איוב לח) וְיִנָּעֲרוּ רְשָׁעִים מִמֶּנָּה, כְּמִי שֶׁמְּנַעֵר טַלִּית מְהַזֻּהֲמָה שֶׁלָּה."],[8,"","כִּי אֶל אַרְצִי וְאֶל מוֹלַדְתִּי תֵּלֵךְ. אַרְצִי - זוֹ הָאָרֶץ הַקְּדוֹשָׁה שֶׁהִיא רִאשׁוֹנָה לְכָל שְׁאָר הָאֲרָצוֹת, כְּמוֹ שֶׁנִּתְבָּאֵר. (ועל זה כי אל ארצי, זו הארץ הקדושה, שהיא שלו בין כל שאר הארצות שחלק אותם לממנים אחרים), וְעַל זֶה כִּי אֶל אַרְצִי וְאֶל מוֹלַדְתִּי. כֵּיוָן שֶׁאָמַר אֶל אַרְצִי, מַה זֶּה וְאֶל מוֹלַדְתִּי? אֶלָּא אֶל אַרְצִי, כְּמוֹ שֶׁנֶּאֱמַר. (מה זה) וְאֶל מוֹלַדְתִּי? אֵלּוּ הֵם יִשְׂרָאֵל"],[9,"","בֹּא רְאֵה מַה כָּתוּב, וַיִּקַּח הָעֶבֶד - כְּמוֹ שֶׁנִּתְבָּאֵר. עֲשָׂרָה גְמַלִּים - אֵלּוּ הֵם עֶשֶׂר דְּרָגוֹת שֶׁהָעֶבֶד הַזֶּה שׁוֹלֵט עֲלֵיהֶם כְּמוֹ שֶׁלְּמַעְלָה. מִגְּמַלֵּי אֲדנָיו - שֶׁהֵם בְּאוֹתוֹ גָוֶן מַמָּשׁ, כְּמוֹ שֶׁנִּתְבָּאֵר, וְהָעֶבֶד הַזֶּה שׁוֹלֵט וְנִתְקָן בָּהֶם."],[10,"","וְכָל טוּב אֲדנָיו בְּיָדוֹ - כָּל אוֹתוֹ טוּב הָרֵיחוֹת הָעֶלְיוֹנִים שֶׁיּוֹצְאִים מִתּוֹךְ אוֹתָם אוֹרוֹת וּמְאוֹרוֹת עֶלְיוֹנִים. וְכָל טוֹב אֲדנָיו - אוֹתוֹ הַשִּׁמּוּשׁ שֶׁל הַשֶּׁמֶשׁ שֶׁנִּמְשְׁכָה בָּהּ בַּלְּבָנָה."],[11,"","וַיָּקָם וַיֵּלֶךְ אֶל אֲרַם נַהֲרַיִם - זֶהוּ הַמָּקוֹם שֶׁל הָאָרֶץ הַקְּדוֹשָׁה שֶׁשָּׁם בָּכְתָה רָחֵל כְּשֶׁחָרַב בֵּית הַמִּקְדָּשׁ. וַיַּבְרֵךְ הַגְּמַלִּים מִחוּץ לָעִיר אֶל בְּאֵר הַמָּיִם - לְהִתְחַזֵּק כֹּחָהּ בְּחָזְקָהּ כָּרָאוּי טֶרֶם תִּכָּנֵס לְהָקִים אֶת אוֹתָם הַגּוּפִים."]]],[["לְעֵת עֶרֶב, מַאי לְעֵת עֶרֶב. דָּא עֶרֶב שַׁבָּת דְּאִיהוּ זִמְנָא דְאֶלֶף שְׁתִיתָאָה. לְעֵת עֶרֶב כְּמָה דְאַתְּ אָמֵר (תהילים ק״ד:כ״ג) וְלַעֲבוֹדָתוֹ עֲדֵי עָרֶב וּכְתִיב, (ירמיהו ו׳:ד׳) כִּי יִנָּטוּ צִלְּלֵי עָרֶב.","לְעֵת צֵאת הַשּׁוֹאֲבוֹת, דְּהַהוּא זִמְנָא זְמִינִין לְמֵיקַם וְלַאֲחָיָיא בְּקַדְמִיתָא מִכָּל שְׁאָר בְּנֵי עַלְמָא, אִינוּן דְּשָׁאֲבֵי מֵימוֹי דְאוֹרַיְיתָא (ושאבין), בְּגִין דְּאִתְעַסְּקוּ לְשָׁאֲבָא מִמֵּימֵי דְאוֹרַיְיתָא, וְאִתְתַּקָּפוּ בְּאִילָנָא דְחַיֵּי, וְאִינוּן יִפְקוּן בְּקַדְמִיתָא, דְּאִילָנָא דְחַיֵּי גָּרְמָא לוֹן דִּיקוּמוּן בְּקַדְמִיתָא כְּמָא דְאִתְּמָר.","וּבְנוֹת אַנְשֵׁי הָעִיר יוֹצְאוֹת. מַאי יוֹצְאוֹת, כְּמָה דְאַתְּ אָמֵר (ישעיהו כ״ו:י״ט) וְאֶרֶץ רְפָאִים תַּפִּיל, דְּזַמִּינָא אַרְעָא לְמִפְלַט מִנָּהּ כָּל רוּחִין דְּאִינוּן בְּגַוָּוהּ, וְעַל דָּא כְּתִיב יוֹצְאוֹת. לִשְׁאוֹב מַיִם, לְנַטְלָא נִשְׁמָתָא וּלְקַבְּלָא לָהּ כְּדְקָא יְאוּת מְתַקְנָא מֵאַתְרָהּ כְּדְקָא חָזֵי.","וְהָיָה הַנַּעֲרָה אֲשֶׁר אֹמַר אֵלֶיהָ הַטִּי נָא כַדֵּךְ וְאֶשְׁתֶּה, בְּגִין דְּהָא אִתְּמָר, דְּכָל אִינוּן נִשְׁמָתִין דְּעַלְמָא דְּאִתְקָיְימוּ בְּהַאי עַלְמָא וְאִשְׁתַּדְּלוּ לְמִנְדַע לְמָארֵיהוֹן בְּרָזָא דְחָכְמְתָא עִלָּאָה. אִיהִי סָלְקַת וְאִתְקָיְימַת בְּדַרְגָּא עִלָּאָה עַל כָּל אִינוּן דְּלָא אִתְדַּבְּקוּ וְלָא יָדְעוּ, וְאִינוּן אִתְקָיְימוּן בְּקַדְמִיתָא. וְדָא הוּא שְׁאֵלְתָּא דְּקָאִים הַהוּא עֶבֶד לְמִנְדַע וּלְמִשְׁאַל, בְּמָּה אִתְעַסְּקַת הַהִיא נִשְׁמָתָא בְּהַאי עָלְמָא.","וְאָמְרָה אֵלַי גַּם אַתָּה שְׁתֵה, אַנְתְּ בָּעֵי לְמִשְׁתֵּי וּלְאִתְשַׁקְיָא בְּקַדְמִיתָא, וּבַתְרָךְ וְגַם לִגְמַלֶּיךָ אַשְׁקֶה. בְּגִין דְּכָל אִינוּן שְׁאָר רְתִיכִין אַף עַל גַּב דְּאִתְשַׁקְיָין מֵהַאי דַרְגָּא, כֻּלְּהוּ אִתְשַׁקְיָין מִפּוּלְחָנָא דְצַדִּיקַיָיא דְּיָדְעֵי פּוּלְחָנָא דְמָארֵיהוֹן כְּדְקָא יְאוּת. דְּצַדִּיקַיָיא יָדְעֵי לְסַפְּקָא לְכָל דַּרְגָּא וְדַרְגָּא כְּדְקָא יְאוּת. וְעַל דָּא וְגַם לִגְמַלֶּיךָ אַשְׁקֶה. וַדַּאי הִיא הָאִשָּׁה אֲשֶׁר הֹכִיחַ יְיָ לְבֶן אֲדֹנִי. וַדַּאי הַהִיא (ס\"א באתערותא דצלותא דילי) אִיהוּ גוּפָא דְּאִזְדַּמַּן לְהַהִיא נִשְׁמָתָא עִלָּאָה.","תָּא חֲזֵי, דְּהָא אִתְּמָר דְּתִיאוּבְתָּא דִדְכוּרָא לְגַבֵּי נוּקְבָא עָבִיד נִשְׁמָתָא. וְתִיאוּבְתָּא דְנוּקְבָא לְגַבֵּי דְכוּרָא סָלְקָא וְאִתְעָרַב בַּהֲדָהּ דִּלְעֵילָא וְאִתְכְּלִיל דָּא בְּדָא וְעָבִיד נִשְׁמָתָא. וּבְגִין כָּךְ הִיא הָאִשָּׁה. דָּא הוּא גוּפָא וַדַּאי דְּאִיהוּ זְמִינָא לְהַהוּא רְעוּתָא דְנִשְׁמָתָא דְּנָפְקָא מִן דְּכוּרָא.","וְאִינוּן גּוּפִין זְמִינִין לְאַתְעָרָא בְּקַדְמִיתָא כִּדְאֲמָרָן. וּלְבָתַר דְּאִלֵּין יְקוּמוּן, יְקוּמוּן כָּל אָחֳרָנִין דְּבִשְׁאָר אַרְעָאן, וְיִתְקַיְימוּן בְּקִיּוּמָא שְׁלִים, וְיִתְחַדְתּוּן בְּחַדְתוּתָא דְּסִיהֲרָא, וְיִתְחַדֵּשׁ עַלְמָא כְּמִלְקַדְּמִין. וּכְדֵין כְּתִיב בְּהַהוּא זִמְנָא (תהילים ק״ד:ל״א) יִשְׂמַח יְיָ בְּמַעֲשָׂיו.","וּבְגִין כָּךְ (ישעיהו נ״ב:י״ג) הִנֵּה יַשְׂכִּיל עַבְדִּי, לְאַהֲדָרָא נִשְׁמָתִין כָּל חַד וְחַד לְאַתְרֵיהּ. יָרוּם וְנִשָּׂא וְגָבַהּ מְאֹד, מִסִּטְרָא דְּכָל אִינוּן דַּרְגִּין עִלָּאִין כִּדְקָאֲמָרָן.","(ישעיהו נ״ב:י״ד) כַּאֲשֶׁר שָׁמְמוּ עָלֶיךָ רַבִּים כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ וְתֹאֲרוֹ מִבְּנֵי אָדָם. תָּא חֲזֵי, דְּהָא אִתְּמָר דְּכַד אִתְחָרַב בֵּי מַקְדְּשָׁא, וּשְׁכִינְתָּא (אתגלי) בְּגוֹ אַרְעָן נוּכְרָאִין בֵּינַיְיהוּ. מַה כְּתִיב, (ישעיהו ל״ג:ז׳) הֵן אֶרְאֱלָם צָעֲקוּ חֻצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן. כֻּלְּהוּ בָּכוּ עַל דָּא, וּקְשִׁירוּ בְּכִיָה וְאֶבְלָא. וְכָל דָּא עֲלָה דִּשְׁכִינְתָּא דְּאִתְגַּלְּיָיא מֵאַתְרָהּ, וְכַמָּה דְאִיהִי מִשְׁתַּנֵּית מִכְּמָה דְּהֲוַת. אוּף הָכִי בַּעֲלָהּ לָא נָהִיר נְהוֹרֵיהּ וְאִשְׁתַּנֵּי מִכְּמָה דְּהֲוָה, דִּכְתִיב, (ישעיהו י״ג:י׳) חָשַׁךְ הַשֶּׁמֶשׁ בְּצֵאתוֹ. וְעַל דָּא כְּתִיב כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ.","דָּבָר אַחֵר כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ, מֵהַאי עֶבֶד דְּאִשְׁתַּנִּי דִיוּקְנֵיהּ וּגְוָונֵיהּ מִכְּמָה דְּהֲוָה. דָּבָר אַחֵר כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ, כְּמָה דְאַתְּ אָמֵר, (ישעיהו נ׳:ג׳) אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. דְּהָא מִיּוֹמָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא לָא קָיְימוּ שָׁמַיִם בִּנְהוֹרָא דִלְהוֹן, וְרָזָא דְמִלָּה בִּרְכָאן לָא שָׁרְיָין אֶלָּא בְּאֲתַר דְּאִשְׁתַּכָּחוּ דְּכַר וְנוּקְבָא, וְאוּקְמוּהָ. כְּמָה דְאַתְּ אָמֵר, (בראשית ב) זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אֹתָם. וּבְגִין כָּךְ מִשְׁחַת מֵאִישׁ מַרְאֵהוּ.","וְדָא הוּא כְּמָה דִכְתִיב, (ישעיהו נ״ז:א׳) הַצַּדִּיק אָבַד, אָבוּד אוֹ נֶאֱבַד לֹא נֶאֱמַר, אֶלָּא אָבַד, דְּלָא שַׁרְיָין בִּרְכָאן אֶלָּא בְּאֲתַר דְּאִשְׁתַּכָּחוּ דְּכַר וְנוּקְבָא כְּחֲדָא כְּמָה דְּאִתְּמָר."],[[0,"לעת ערב:","שואל מהו לעת ערב, ואומר זהו ערב שבת דהיינו יסוד, שהוא הזמן של אלף הששי. כי ששת ימי המעשה ה\"ס שתא אלפי שני, ויום הששי שהוא ערב שבת הוא כנגד אלף הששי, שאז תהיה תחיית המתים. \u0003לעת ערב,\u0004 ומהו, לעת, שלפי הנ\"ל היה לו לומר, בערב. ומשיב שהוא כמש\"א ולעבודתו עדי ערב, וכתוב, כי ינטו צללי ערב, שה\"ס הדינים המתגלים בערב, וכן \u0003לעת ערב\u0004 ה\"ס הדינים, המתגלים בערב שה\"ס היסוד. אשר העבד תקן אותם."],[1,"לעת צאת השואבות:","היינו השואבות מימי התורה, כי בזמן ההוא הם עתידים לקום לתחיה תחילה מכל שאר בני אדם, משום שעסקו לשאוב מימי התורה ונתחזקו בעץ החיים, והם יצאו תחילה לתחיית המתים, כי עץ החיים גרם להם שיקומו מתחילה, כמו שלמדנו."],[1,"","פירוש. קו אמצעי מכונה תורה, גם נקרא עץ החיים, ומימי התורה היינו השפע שלו, ואומר, שאלו הדבקים ומקבלים השפע מקו אמצעי, שהם נקראים \u0003שואבות\u0004 אלו יחיו מתחילה לכל השאר הנמשכים מב' הקוין האחרים."],[2,"ובנות אנשי העיר יוצאות:","שואל, מהו יוצאות. ומשיב, הוא כמו שאתה אומר, וארץ רפאים תפיל, שפירושו שעתידה הארץ להפליט ממנה כל הגופות שבתוכה, ועל כן כתוב כאן יוצאות, שסובב גם כן על אלו הגופות שהארץ תפליט מתוכה בעת התחיה. \u0003לשאוב מים,\u0004 פירושו, לקחת נשמה, ולקבלה כראוי, שתחיה מתוקנת ממקומה כראוי."],[3,"והיה הנערה אשר וגו':","מטעם, כי למדנו, שכל נשמה מנשמות שבעולם, שנתקיימו בעולם הזה והשתדלו לדעת את רבונם, בסוד חכמה העליונה, היא עולה ומתקיימת במדרגה עליונה למעלה מכל אלו הנשמות שלא השיגו ולא ידעו, והן עומדים תחילה לתחיה, וזה הוא השאלה שאותו העבד עומד לשאול ולדעת, במה עסקה הנשמה ההיא בעולם הזה, כדי לברר, אם היא ראויה לתחיה תחלה. וז\"ש הטי נא כדך ואשתה, כמ\"ש לפנינו."],[4,"ואמרה אלי גם אתה שתה:","אתה צריך לשתות ולהיות נשקה מתחילה. ואחריך, \u0003וגם לגמליך אשקה,\u0004 משום שכל אלו שאר המרכבות, אע\"פ שנשקים ממדרגה זו, כולן נשקים בעיקר מעבודת הצדיקים, היודעים עבודת רבונם כראוי, כי הצדיקים יודעים לכלכל לכל מדרגה ומדרגה כראוי. ועל כן אם אמרה \u0003וגם לגמליך אשקה,\u0004 ודאי היא האשה אשר הוכיח ה' לבן אדוני, ודאי, שהוא הגוף המזומן לנשמה ההיא העליונה."],[4,"","ביאור המאמר. כבר נתבאר (לעיל חיי שרה דף כ\"ב אות ע') סוד המיתה, כי חייו של אדם ע' שנה הם כנגד ז' מדות חג\"ת נהי\"מ, שהולך ומתקנם ממעלה למטה מחסד עד מלכות, וכשמגיע למלכות ואינו יכול לתקן אותה מחמת חטא עץ הדעת, אז הוא מת. ע\"ש. והענין הוא, כי ב' נקודות הן במלכות, אחת מעצמה והיא גנוזה. ואחת מבינה שהוא מגולה, כי מבחינת עצמה אינה ראויה לאור (כנ\"ל בראשית א' דף ז' ד\"ה וכבר). וע\"כ נקודתה עצמה צריכה להיות גנוזה. ואם נקודתה מתגלית תכף מסתלקים ממנה האורות שז\"ס זכה הא טוב לא זכה הא רע. ולפיכך כשמגיע האדם לע' שנה, מתגלית אז נקודת המלכות עצמה, וע\"כ אורות החיים מסתלקים מן האדם, והוא מת. ולפיכך לעתיד לבא, כשיהיה זווג הגדול מרישא דעתיק, והמלכות תקבל גמר תיקונה, באופן שתהיה ראויה לקבל אור העליון גם מבחינתה עצמה, תקמנה אז כל הגופות לתחיה, כי לא מתו אלא מחמת פגם המלכות כנ\"ל, ועתה שהיא מתוקנת לקבל אור החיים תקמנה לתחיה."],[4,"","ויש כאן חילוק בין מתי ארץ ישראל למתי חוץ לארץ. פירוש. אותם הצדיקים הדבוקים בקו אמצעי נקראים ישראל, וארצם ארץ ישראל, והם יקומו לתחיה תכף ויקבלו נשמתם כראוי. אבל אותם שאינם דבוקים בקו אמצעי, שהם מתי חוץ לארץ, הם, אע\"פ שהמלכות כבר נתקנה צריכים עוד תקונים רבים עד שיקומו לתחיה ויקבלו את נשמתם, שתקונים הללו נקראים גלגול מחילות, ע\"י תקונים הללו באים לארץ ישראל, ומקבלים את נשמתם."],[4,"","וזהו שיעור הכתובים \u0003ויאמר אברהם,\u0004 ה\"ס החכמה, \u0003אל עבדו,\u0004 ה\"ס מטטרון. כי הארת החכמה הנמשכת מזווג זו\"ן דאצילות לבי\"ע, נכלל במלאך מטטרון. וע\"כ נקרא מטטרון \u0003שר הפנים,\u0004 כי פנים ה\"ס חכמה בסו\"ה חכמת אדם תאיר פניו. וע\"כ נקרא \u0003זקן ביתו,\u0004 כי איזה זקן מי שקנה חכמה. \u0003המושל בכל אשר לו,\u0004 היינו בחכמה וחסדים יחדיו, המתוקנים בסוד ג' קוין ימין ושמאל אמצע. \u0003שים נא ידך תחת ירכי,\u0004 היינו שיכלול את עצמו ביסוד, ויקבל הארת הזווג הגדול לגמר תיקונה של המלכות ואז יהיה מוכשר להחיות המתים. \u0003ואשביעך בה' אלקי השמים וגו'\u0004 היינו שיקבל ז' האורות השלמים, המתקנים את הנוקבא, הנקראת שבעה, בזו השלמות המרומז בהכתוב, והיה אור הלבנה כאור החמה וגו' \u0003אשר לא תקת אשה\u0004, היינו גוף. \u0003לבני\u0004 היינו נשמה, \u0003מבנות הכנעני,\u0004 שהן דבקים בקו שמאל והם טמאים, שאינם ראוים להלביש נשמה קדושה. כמ\"ש לעיל. \u0003כי אל ארצי\u0004 היינו ארץ ישראל, \u0003ומולדתי\u0004 היינו ישראל, דהיינו אותם שבחייהם היו דבקים בקו אמצעי נקראים ישראל, וארצם ארץ ישראל, שהם יעמדו תחילה לתחיית המתים, כנ\"ל. \u0003עשרה גמלים\u0004 היינו הארת החסדים. \u0003וכל טוב אדוניו\u0004 בידו היינו הארת החכמה."],[4,"","וזהו ניחושו של העבד, שאמר \u0003והיה הנערה וגו' ואמרה שתה וגם גמליך אשקה אותה הוכחת לעבדך ליצחק וגו'.\u0004 כי בדק אם הגוף בחייו בעולם הזה, היה דבוק בקו אמצעי, שאז הוא בבחינת ארץ ישראל וראוי לקום תחילה כנ\"ל. כי \u0003שתה\u0004 ה\"ס הארת חכמה, שזהו בחינת העבד עצמו כנ\"ל, \u0003וגם גמליך אשקה,\u0004 הוא בחינת חסדים. ואם בחייו היה ממשיך ב' האורות הללו, סימן הוא שהיה דבוק בקו אמצעי, הכולל ב' אורות הללו, וע\"כ \u0003אותה הוכחת לעבדך ליצחק,\u0004 כי הוא ראוי לקום לתחיה ולקבל את נשמתו שה\"ס יצחק כנ\"ל."],[4,"","וזה אמרו, והיה הנערה וגו' בגין דהא אתמר וכו' ואשתדלו \u0003למנדע\u0004 למאריהון ברזא \u0003דחכמתא עלאה,\u0004 דהיינו שהמשיכו הארת החכמה על ידי הדעת, כי ע\"כ אומר \u0003למנדע\u0004 שה\"ס דעת, ברזא דחכמתא עלאה, שאז יש לו ב' האורות חכמה וחסדים, כי הדעת ה\"ס חסדים כנודע. \u0003ואינון אתקיימין בקדמיתא,\u0004 כי הם בבחינת מתי א\"י שעומדים לתחיה תחילה כנ\"ל. \u0003ודא הוא שאלתא וכו',\u0004 וזהו שאלתו הטי נא כדך וגו' כי היה צריך לדעת אם אותו הגוף ראוי לתחיית המתים תחילה."],[4,"","וז\"ש \u0003אנת בעי למשתי ולאתשקיא בקדמיתא ובתרך וגם לגמליך אשקה\u0004, דהיינו שתחילה צריכים להמשיך הארת חכמה, ואח\"כ הארת החסדים. כי מטרם שממשיך הארת חכמה נבחנים החסדים לו\"ק בלי ראש. וע\"כ צריכים להמשיך תחילה הארת החכמה ואח\"כ החסדים, ואז נבחנים החסדים לג\"ר גמורים, בסוד אוירא דכיא. וז\"ש, \u0003בגין דכל אינון שאר רתיכין,\u0004 משום ששאר המרכבות, דהיינו הגמלים, \u0003אע\"ג דאתשקיין מהאי דרגא\u0004, דהיינו ממדרגת החסדים, \u0003כלהו אתשקיין מפולחנא דצדיקיא, דידעי פולחנא דמאריהון כדקא יאות,\u0004 שהם יודעים להדבק בקו אמצעי ולהמשיך מתחילה חכמה ואח\"כ חסדים, \u0003דצדיקייא ידעי לספקא לכל דרגא ודרגא כדקא יאות,\u0004 שיודעים לכלכל לכל מדרגה ומדרגה ולתקנה כראוי. ואז גם החסדים נעשו בחינת ג\"ר כנ\"ל."],[5,"תא חזי דהא וכו':","בוא וראה כי למדנו, שהשתוקקות הדכר אל הנוקבא, שנמשך עי\"ז הארת החכמה מן הנוקבא, עושה נשמה. והשתוקקות הנוקבא אל הדכר, שנמשך עי\"ז חסדים מן הדכר, עולה ומתערב עמה עם הנשמה למעלה, ונכלל זה בזה, החכמה דנוקבא נכללת עם החסדים דדכר, ועושה את הנשמה, כלומר שגומר אותה. ומשום זה, נחש העבד שאם תאמר גם אתה שתה דהיינו המשכת החכמה, וגם גמליך אשקה דהיינו המשכת החסדים. \u0003היא האשה,\u0004 זהו ודאי הגוף המוכן לרצונה של הנשמה היוצאת מן הדכר, שהוא ז\"א, הכלול מחכמה וחסדים יחד."],[6,"ואינון גופין וכו':","ואלו הגופים עתידים להתעורר תחילה לתחיה, כמו שאמרנו, ואחר שיקומו אלו, יקומו כל האחרים שבחוץ לארץ. ויתקיימו בקיום שלם, ויתחדשו בהתחדשות הלבנה שאז, יהיה אור הלבנה כאור החכמה כנ\"ל. ויתחדש העולם כבתחילה, ואז כתוב על העת ההיא, ישמח ה' במעשיו."],[7,"ובגין כך הנה ישכיל עבדי:","פירושו שהעבד מטטרון ישכיל להחזיר את הנשמות כל אחת ואחת למקומה. דהיינו אל הגוף הראוי לה, כמו שאמרנו. \u0003ירום ונשא וגבה מאד\u0004 היינו מצד כל אלו מדרגות העליונות, כמו שאמרנו לעיל באות מ\"ו."],[8,"כאשר שממו עליך רבים וגו':","בוא וראה, כי למדנו, כשנחרב בית המקדש, וגלתה השכינה, בארצות זרות ביניהם מה כתוב, הן אראלם צעקו חוצה מלאכי שלום מר יבכיון. כולם בכו על זה, וקשרו בכיה ואבלות. וכל זה, על השכינה שגלתה ממקומה."],[8,"וכמה דאיהי משתנית וכו':","וכמו שהיא נשתנתה בגלות, ממה שהיתה, כן בעלה, ז\"א, אינו מאיר אורו, כי אין לו אז למי להאיר ונשתנה ממה שהיה, שכתוב חשך השמש בצאתו. ועל זה כתוב, כן משחת מאיש מראהו."],[9,"דבר אחר. כן משחת מאיש מראהו,","היינו מאותו העבד, מטטרון, שבעת הגלות, נשתנה צורתו וצבעיו, שהם ירוק חוור וסומק (כנ\"ל אות מ\"ט) ממה שהיה. \u0003ד\"א כן משחת מאיש מראהו:\u0004 כמו שאתה אומר, אלביש שמים קדרות ושק אשים כסותם. כי מיום שנחרב בית המקדש לא עמדו שמים, שהם ז\"א, באור שלהם. וסוד הדבר, הברכות אינן שורות אלא במקום שנמצא דכר ונוקבא, ובארוה, כמש\"א, זכר ונקבה בראם ויברך אותם. ובגלות שאין זווג זו\"ן, כתוב משום זה, \u0003משחת מאיש מראהו.\u0004"],[9,"","ההפרש בין פירוש זה לפירוש הנ\"ל באות ס\"ה, הוא, כי לעיל אומר שנחשך אורו של ז\"א, משום הנוקבא שנחשכה בגלות ואינה מקבלת ממנו, ונמצא שאין החסרון בו עצמו, אלא מטעם שאין לו למי להשפיע וע\"כ אינו מקבל אורות. וכאן אומר שהחסרון הוא מטעם העדר הזווג שבזמן הגלות, ונמצא החסרון גם בז\"א, שאין הברכה שורה אלא בזווג זו\"ן."],[10,"ודא הוא כמה וכו':","וזה הוא כמו שכתוב, \u0003הצדיק אבד,\u0004 אבוד או נאבד לא נאמר אלא \u0003אבד,\u0004 שהמשמעות הוא, שהצדיק אבד את הברכות, כי ברכות אינן שורות אלא במקום שנמצאים דכר ונוקבא יחד, כמו שאמרנו."]],[[0,"","לְעֵת עֶרֶב, מַה זֶּה לְעֵת עֶרֶב? זֶה עֶרֶב שַׁבָּת שֶׁהוּא הַזְּמַן שֶׁל הָאֶלֶף הַשִּׁשִּׁי. לְעֵת עֶרֶב - כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) וְלַעֲבוֹדָתוֹ עֲדֵי עָרֶב, וְכָתוּב (ירמיה ו) כִּי יִנָּטוּ צִלֲלֵי עָרֶב."],[1,"","לְעֵת צֵאת הַשּּׁאֲבֹת - שֶׁבְּאוֹתוֹ זְמַן עֲתִידִים לָקוּם וּלְהֵחָיוֹת. בָּרִאשׁוֹנָה מִכָּל שְׁאָר בְּנֵי הָעוֹלָם אוֹתָם שֶׁשּׁוֹאֲבִים מֵימֵי הַתּוֹרָה (ושואבים), כְּדֵי שֶׁיִּתְעַסְּקוּ לִשְׁאֹב מֵימֵי הַתּוֹרָה, וְהִתְחַזְּקוּ בְּעֵץ הַחַיִּים, וְהֵם יָצְאוּ בָרִאשׁוֹנָה, שֶׁעֵץ הַחַיִּים גָּרַם לָהֶם שֶׁיָּקוּמוּ בָּרִאשׁוֹנָה, כְּמוֹ שֶׁנִּתְבָּאֵר."],[2,"","וּבְנוֹת אַנְשֵׁי הָעִיר יצְאֹת, מַה זֶּה יֹצְאֹת? כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כו) וָאָרֶץ רְפָאִים תַּפִּיל, שֶׁעֲתִידָה הָאָרֶץ לִפְלֹט מִמֶּנָּה כָּל הַגּוּפוֹת שֶׁהֵם בְּתוֹכָהּ, וְעַל כָּךְ כָּתוּב יצְאֹת. לִשְׁאֹב מָיִם - לִטֹּל נְשָׁמָה וּלְקַבְּלָהּ כָּרָאוּי מְתֻקֶּנֶת מִמְּקוֹמָהּ כָּרָאוּי."],[3,"","וְהָיָה הַנַּעֲרָה אֲשֶׁר אֹמַר אֵלֶיהָ הַטִּי נָא כַדֵּךְ וְאֶשְׁתֶּה, מִשּׁוּם שֶׁהֲרֵי נִתְבָּאֵר, שֶׁכָּל אוֹתָן נְשָׁמוֹת שֶׁל הָעוֹלָם שֶׁהִתְקַיְּמוּ בָּעוֹלָם הַזֶּה וְהִשְׁתַּדְּלוּ לָדַעַת אֶת רִבּוֹנָם בְּסוֹד הַחָכְמָה הָעֶלְיוֹנָה, הִיא עוֹלָה וּמִתְקַיֶּמֶת בְּדַרְגָּה עֶלְיוֹנָה עַל כָּל אוֹתָם שֶׁלֹּא נִדְבְּקוּ וְלֹא יָדְעוּ, וְהֵם מִתְקַיְּמִים בָּרִאשׁוֹנָה. וְזוֹ הַשְּׁאֵלָה שֶׁעָמַד אוֹתוֹ הָעֶבֶד לָדַעַת וְלִשְׁאֹל, בַּמָּה הִתְעַסְּקָה אוֹתָהּ הַנְּשָׁמָה בָּעוֹלָם הַזֶּה."],[4,"","וְאָמְרָה אֵלַי גַּם אַתָּה שְׁתֵה, אַתָּה צָרִיךְ לִשְׁתּוֹת וְלִהְיוֹת מֻשְׁקֶה בָּרִאשׁוֹנָה, וְאַחֲרֶיךְ - וְגַם (ל) גְמַלֶּיךְ אַשְׁקֶה, מִשּׁוּם שֶׁכָּל אוֹתָם שְׁאָר הַמֶּרְכָּבוֹת, אַף עַל גַּב שֶׁנִּשְׁקִים מֵהַדַּרְגָּה הַזּוֹ, כֻּלָּם נִשְׁקִים מֵעֲבוֹדַת הַצַּדִּיקִים שֶׁיּוֹדְעִים עֲבוֹדַת רִבּוֹנָם כָּרָאוּי, שֶׁהַצַּדִּיקִים יוֹדְעִים לְסַפֵּק לְכָל דַּרְגָּה וְדַרְגָּה כָּרָאוּי. וְעַל זֶה וְגַם (ל) גְמַלֶּיךְ אַשְׁקֶה. וַדַּאי הִיא הָאִשָּׁה אֲשֶׁר הֹכִיחַ ה' לְבֶן אֲדנִי. וַדַּאי הַהִיא (ס\"א בהתעוררות של התפלה שלי) הוּא הַגּוּף שֶׁהִזְדַּמֵּן לְאוֹתָהּ הַנְּשָׁמָה הָעֶלְיוֹנָה."],[5,"","בֹּא רְאֵה, שֶׁהִנֵּה נִתְבָּאֵר שֶׁתְּשׁוּקַת הַזָּכָר לַנְּקֵבָה עוֹשָׂה נְשָׁמָה, וּתְשׁוּקַת הַנְּקֵבָה לַזָּכָר עוֹלֶה וּמִתְעָרֵב עִמָּהּ שֶׁלְּמַעְלָה, וְנִכְלָלִים זֶה עִם זֶה וְעוֹשֶׂה נְשָׁמָה. וּמִשּׁוּם כָּךְ, הִיא הָאִשָּׁה - זֶהוּ הַגּוּף וַדַּאי, שֶׁהוּא זָמִין לְאוֹתוֹ רָצוֹן שֶׁל הַנְּשָׁמָה שֶׁיָּצְאָה מִן הַזָּכָר."],[6,"","וְאוֹתָם הַגּוּפִים עֲתִידִים לְהִתְעוֹרֵר בָּרִאשׁוֹנָה, כְּמוֹ שֶׁאָמַרְנוּ. וּלְאַחַר שֶׁאֵלּוּ יָקוּמוּ, יָקוּמוּ כָּל הָאֲחֵרִים שֶׁבִּשְׁאָר הָאֲרָצוֹת וְיִתְקַיְּמוּ בְּקִיּוּם שָׁלֵם, וְיִתְחַדְּשׁוּ בְּהִתְחַדְּשׁוּת הַלְּבָנָה, וְיִתְחַדֵּשׁ הָעוֹלָם כְּמוֹ מִקֹּדֶם, וְאָז כָּתוּב בְּאוֹתוֹ הַזְּמַן (תהלים קד) יִשְׂמַח ה' בְּמַעֲשָׂיו."],[7,"","וּמִשּׁוּם כָּךְ, הִנֵּה יַשְׂכִּיל עַבְדִּי - לְהַחֲזִיר הַנְּשָׁמוֹת כָּל אַחַת וְאַחַת לִמְקוֹמָהּ. יָרוּם וְנִשָּׂא וְגָבַהּ מְאֹד - מֵהַצַּד שֶׁל כָּל אוֹתָן הַדְּרָגוֹת הָעֶלְיוֹנוֹת, כְּמוֹ שֶׁאָמַרְנוּ."],[8,"","(ישעיה נב) כַּאֲשֶׁר שָׁמְמוּ עָלֶיךְ רַבִּים כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ וְתֹאֲרוֹ מִבְּנֵי אָדָם, בּא רְאֵה, שֶׁהִנֵּה נֶאֱמַר שֶׁכַּאֲשֶׁר נֶחֱרַב בֵּית הַמִּקְדָּשׁ וְהַשְּׁכִינָה גָּלְתָה לְתוֹךְ אֲרָצוֹת נָכְרִיּוֹת בֵּינֵיהֶם, מַה כָּתוּב? (שם לג) הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן, כֻּלָּם בָּכוּ עַל זֶה וְקָשְׁרוּ בְּכִיָּה וְאֵבֶל, וְכָל זֶה עַל הַשְּׁכִינָה שֶׁגָּלְתָה מִמְּקוֹמָהּ. וְכַמָּה שֶׁהִיא מִשְׁתַּנֵּית מִכְּמוֹ שֶׁהָיְתָה, אַף כָּךְ בַּעְלָהּ לֹא מֵאִיר אוֹרוֹ וְהִשְׁתַּנָּה מִכְּמוֹ שֶׁהָיָה, שֶׁכָּתוּב (שם יג) חָשַׁךְ הַשֶּׁמֶשׁ בְּצֵאתוֹ, וְעַל זֶה כָּתוּב כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ."],[9,"","דָּבָר אַחֵר כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ - מֵהָעֶבֶד הַזֶּה שֶׁהִשְׁתַּנָּה דְיוֹקְנוֹ וְגוֹנוֹ מִכְּמוֹ שֶׁהָיָה. דָּבָר אַחֵר כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ - כְּמוֹ שֶׁנֶּאֱמַר (שם נ) אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. שֶׁהֲרֵי מִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ לֹא עָמְדוּ הַשָּׁמַיִם בְּאוֹרָם, וְסוֹד הַדָּבָר - הַבְּרָכוֹת לֹא שׁוֹרוֹת אֶלָּא בְּמָקוֹם שֶׁנִּמְצָאִים זָכָר וּנְקֵבָה, וּבֵאֲרוּהוּ כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אֹתָם, וּמִשּׁוּם כָּךְ מִשְׁחַת מֵאִישׁ מַרְאֵהוּ."],[10,"","וְזְהִוּ כַּכָּתוּב (ישעיה נז) הַצַּדִּיק אָבָד. אָבוּד אוֹ נֶאֱבָד לֹא נֶאֱמַר, אֶלָּא אָבָד, שֶׁאֵין שׁוֹרוֹת בְּרָכוֹת אֶלָּא בְּמָקוֹם שֶׁנִּמְצָאִים זָכָר וּנְקֵבָה יַחַד, כְּמוֹ שֶׁנִּתְבָּאֵר."]]],[["בְּגִין דָּא בְּהַהוּא זִמְנָא דְּלָא אִשְׁתַּכַּח דְּכוּרָא בַּהֲדָהּ, וּכְדֵין כָּל אִינוּן נִשְׁמָתִין דְּנָפְקֵי כֻּלְּהוּ הֲוֵי לְהוּ שִׁנּוּיָא מִכְּמָה דְּהֲווּ בְּזִמְנָא דְּשִׁמְשָׁא אִתְחַבַּר בְּסִיהֲרָא כְּמָה דְּאִתְּמָר. וְעַל דָּא אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף וְגו' וְאִתְּמָר.","וְהוּא נַעַר, בְּגִין דְּלָא מִתְפָּרְשִׁין לְעָלְמִין, צַדִּי\"ק וְצֶדֶ\"ק כְּחֲדָא אִינוּן, כְּמָה דְּאִיהִי אִתְקְרִיאַת בִּשְׁמָא דִדְכוּרָא, הָכִי נָמֵי אִתְקְרֵי אִיהוּ בִּשְׁמָא דִילָהּ דִּכְתִיב וְהוּא נַעַר.","אֶת בְּנֵי בִּלְהָה וְאֶת בְּנִי זִלְפָּה, בְּכֻלְּהוּ קָיְימָא לְחַדְתָּא לוֹן כְּדְקָא יְאוּת וּלְאִשְׁתַּעְשְׁעָא לוֹן בְּחֶדְוָה דִילֵיהּ. דְּכֻלְּהוּ עַנְפִין וְכֻלְּהוּ עָלִין, כֻּלְּהוּ אִתְבָּרְכִין בְּחֶדְוָה דִילֵיהּ.","אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף, כְּמָה דְאִתְּמָר דְּכָל דִּיוּקְנָא דְיַעֲקֹב הֲוָה בֵּיהּ בְּיוֹסֵף, וְכָל מַה דְּאֵירַע לְהַאי אֵירַע לְהַאי, וְתַרְוַויְיהוּ כְּחֲדָא אָזְלֵי. וְדָא הוּא רָזָא דְּאָת ו\"ו דְּאָזְלֵי תַּרְוַויְיהוּ כְּחֲדָא, בְּגִין דְּאִינוּן רָזָא חָדָא וְדִיוּקְנָא חָדָא:","וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה, הָא אוּקְמוּהָ דְּהֲוָה אָמַר לְאֲבוֹי עֲלַיְיהוּ דְּהֲווּ אָכְלֵי שַׁיְיפָא מִבַּעֲלֵי חַיִּין כַּד אִינוּן חַיִּין. וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה, וְכִי הָא בְּמִנְיָינָא הֲווּ אִינוּן בְּנֵי שְׁפָחוֹת, הֵיךְ הֲווּ מְזַלְזְלִין בְּהוֹן בְּנֵי לֵאָה, וְהֵיךְ הֲווּ אָכְלִין אֵבָר מִן הַחַי וְהֲווּ עָבְרִין עַל פִּקּוּדָא דְמָארֵיהוֹן. דְּהָא פַּקִּיד עַל בְּנֵי נֹחַ פִּקּוּדָא דָא. כְּמָה דְאַתְּ אָמֵר, (בראשית ט׳:ד׳) אַךְ בָּשָׂר בְּנַפְשׁוֹ דָּמוֹ לא תֹאכֵלוּ, וְאִינוּן הֲווּ אָכְלֵי לֵיהּ וְעָבְרִין עַל פִּקּוּדָא דְמָארֵיהוֹן. אֶלָּא יוֹסֵף הֲוָה קָאֲמַר, וְעַל דָּא אִתְעַנַּשׁ.","רִבִּי יְהוּדָה אָמַר, אֶת דִּבָּתָם רָעָה, כְּמָה דְאוּקְמוּהָ דְּיַהֲבֵי עֵינַיְיהוּ בִּבְנוֹת אַרְעָא, וְדָא הוּא דִּבָּתָם רָעָה. לְיַנְקָא לְכָל אִינוּן דַּרְגִּין דְּלָא קַדִּישִׁין (ד\"א ל\"ג אף על גב) דְּאַתְיָין מִסִּטְרָא מְסָאֲבָא:","וְיִשְׂרָאֵל אָהַב אֶת יוֹסֵף מִכָּל בָּנָיו כִּי בֶן זְקֻנִים הוּא לוֹ וְעָשָׂה לוֹ כְּתֹנֶת פַּסִּים. רִבִּי אֶלְעָזָר פָּתַח וְאֲמַר, (ישעיהו כ״ו:כ׳) לֵךְ עַמִּי בֹּא בַחֲדָרֶיךָ וּסְגֹר דְּלָתְךָ בַּעֲדֶךָ חֲבִי כִמְעַט רֶגַע עַד יַעֲבָר זַעַם. לֵךְ עַמִּי בֹּא בַחֲדָרֶיךָ. תָּא חֲזֵי, כַּמָּה קוּדְשָׁא בְּרִיךְ הוּא רָחִים לוֹן לְיִשְׂרָאֵל. וּבְגִין רְחִימוּתָא דִלְהוֹן דְּרָחִים לוֹן עַל כָּל עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, אַזְהַר לוֹן, וּבָעֵי לְנַטְרָא לוֹן בְּכָל מַה דְּאִינוּן עָבְדִין.","תָּא חֲזֵי, תְּלַת זִמְנִין אִית בְּיוֹמָא דְּדִינָא שַׁרְיָא בְּעַלְמָא, וְכַד אָתֵי הַהוּא זִמְנָא, מִבָּעֵי לֵיהּ לְבַר נָשׁ לְאִזְדַּהֲרָא וּלְאִסְתַּמְרָא דְּלָא יִפְגַע בֵּיהּ הַהוּא דִינָא, וְאִינוּן זִמְנִין יְדִיעָן וְהָא אוּקְמוּהָ.","בְּגִין דְּהָא כַּד סָלִיק צַפְרָא, אַבְרָהָם אִתְעַר בְּעַלְמָא, וְאָחִיד לֵיהּ לְדִינָא לְקָשְׁרָא לֵיהּ בַּהֲדֵיהּ. וּבְשֵׁירוּתָא דִּתְלַת שָׁעֵי קַמַּיְיתָא נָטִיל דִּינָא מֵאַתְרִיהּ לְאַתְעָרָא בֵּיהּ בְּיַעֲקֹב, עַד דְּאִתְעַר צְלוֹתָא דְמִנְחָה דְּאַהֲדַר דִּינָא לְאַתְרֵיהּ, וְאִתְעַר דִּינָא דִלְתַתָּא לְאִתְקַשְּׁרָא בְּדִינָא דִלְעֵילָא. דְּהָא כְּדֵין אִתְקַשַּׁר דִּינָא בְּדִינָא וּבָעֵי לְאִזְדַּהֲרָא.","(לעיל סח ב) תוּ כַּד דִּינָא אִתְעַר בְּעַלְמָא וּמוֹתָא אִשְׁתַּכַּח בְּמָתָא, לָא לִיבָּעֵי לֵיהּ לְבַר נָשׁ לְמֵיהַךְ יְחִידָאי בְּשׁוּקָא וְהָא אוֹקִימְנָא מִלֵּי. אֶלָּא בָּעֵי לְאַסְגָּרָא גַּרְמֵיהּ דְּלָא יִפּוּק לְבַר, כְּמָה דְאוּקְמוּהָ בְּנֹחַ דְּאַסְגַּר גַּרְמֵיהּ בְּתֵיבוּתָא דְּלָא יִשְׁתַּכַּח קַמֵי מְחַבְּלָא.","וְעַל דָּא לֵךְ עַמִּי בֹּא בַחֲדָרֶיךָ, אַסְגַּר גַּרְמָךְ. וּסְגוֹר דְּלָתְךָ בַּעֲדֶךָ, דְּלָא יִתְחֲזֵי קַמֵּיהּ דִּמְחַבְּלָא. חֲבִי כִּמְעַט רֶגַע עַד יַעֲבוֹר זַעַם, דְּבָתַר דְּאַעֲבַר דִּינָא לֵית לֵיהּ רְשׁוּ לִמְחַבְּלָא לְחַבָּלָא.","תָּא חֲזֵי, דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין רְחִימוּתָא דְּאִיהוּ רָחִים לוֹן לְיִשְׂרָאֵל וְקָרִיב לוֹן לְגַבֵּיהּ, כָּל שְׁאָר עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שָׂנְאִין לוֹן לְיִשְׂרָאֵל. בְּגִין דְּאִינוּן מִתְרַחֲקִין וְיִשְׂרָאֵל קְרֵיבִין.","וְתָּא חֲזֵי, בְּגִין רְחִימוּתָא דְּרָחִים יַעֲקֹב לְיוֹסֵף יַתִּיר מֵאֲחוֹי, אַף עַל גַּב דְּכֻלְּהוּ הֲווּ לֵיהּ אַחִין, מַה כְּתִיב וַיִּתְנַכְּלוּ אוֹתוֹ לַהֲמִיתוֹ, כָּל שֶׁכֵּן עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת לְיִשְׂרָאֵל.","תָּא חֲזֵי, כַּמָּה גָּרִים לֵיהּ הַהוּא רְחִימוּתָא דְּרָחִים לֵיהּ יַתִּיר, דְּגָרַם לֵיהּ דְּאִתְגְּלֵי מֵאֲבוֹי, וְאִתְגְּלִי אֲבוֹי בַּהֲדֵיהּ, וְגָרַם לְהוּ גָלוּתָא וְלִשְׁכִינְתָּא דְאִתְגַּלְּיָא בֵּינַיְיהוּ. וְאַף עַל גַּב דְּאִתְגְּזִירַת גְּזֵרָה, וְאוּקְמוּהָ דִּבְגִין כְּתֹנֶת פַּסִּים דְּעֲבַד לֵיהּ יַתִּיר, מַה כְּתִיב וַיִּרְאוּ אֶחָיו:"],[[0,"בגין דא בההוא וכו':","משום זה באותו זמן שאינו נמצא עמה דכר, אז, כל הנשמות היוצאות ממנה יש להם שינוי ממה שהיו בזמן שהשמש, שהוא ז\"א, נתחבר עם הלבנה, שהיא הנוקבא, כמו שלמדנו, כי כמו שזו\"ן נשתנו בזמן הגלות ממה שהיו, כן תולודותיהם שהם הנשמות משתנים אז ממה שהיו, ועל זה נאמר אלה תולדות יעקב יוסף וגו'. ולמדנו (לעיל אות כ\"א) שפירושו אחר שנתישב יוסף ביעקב והשמש נזדווג בלבנה, ע\"ש. וע\"כ גדלה אז מעלתם של הנשמות, ובגלות משתנות."],[1,"והוא נער:","משום שזווגם אינו נפרד לעולם, צדיק, שהוא יסוד, וצדק, שהוא הנוקבא, הם ביחד."],[1,"","פירוש. כי י\"ב השבטים הם סוד שייפי שכינתא, ח' מהם, שהם בני לאה ורחל ה\"ס הפנים של השכינה, וד' מהם, שהם בני השפחות, ה\"ס האחורים של השכינה. ומשמיענו הכתוב, והוא נער את בני בלהה וגו', שיוסף היה דבוק ומתקן גם את האחורים של השכינה. ומפרש הטעם, \u0003בגין דלא מתפרשין לעלמין, צדיק וצדק כחדא אינון,\u0004 כי הזווג של זו\"ן היה אז מבחינת או\"א, שזווגם אינו נפרד לעולם, וע\"כ יסוד ומלכות המה ביחד בכל חלקי הנוקבא, ואפילו באחורים שלה."],[1,"כמה דאיהי אתקריאת וכו':","כמו שהנוקבא נקראת בשם הזכר, דהיינו הוא חכם והיא חכמה, הוא גבור והיא גבורה, הוא מלך והיא מלכות. כן נקרא הזכר בשם הנוקבא, שכתוב והוא נער. כי הנוקבא נקראת \u0003נערה,\u0004 ונקרא היסוד על שמה בשם \u0003נער.\u0004"],[2,"את בני בלהה וגו':","בכולם, בכל י\"ב השבטים ואפילו בבני השפחות שהם אחורים של השכינה, הוא נמצא, לחדש אותם כראוי, ולשעשע אותם בשמחתו, שכל הענפים וכל העלים, של השכינה, כולם מתברכים בשמחתו. כלומר, אפילו חלקי האחורים של השכינה הנקראים עלים, בסו\"ה ועלהו לא יבול, מתתקנים עמו."],[3,"אלה תולדות יעקב יוסף וגו':","הוא כמו שלמדנו, שכל צורתו של יעקב היה ביוסף, וכל מה שקרה ליעקב קרה ליוסף, ושניהם הולכים ביחד וזהו סוד אות ו\"ו, אשר ו' ראשונה ה\"ס יעקב שה\"ס ת\"ת והמילוי ו' הנשמעת עמה במבטא, ה\"ס יוסף שה\"ס יסוד, שהולכים שניהם ביחד, כלומר שנשמעות כאחד בבטוי ו', משום שהם סוד אחד וצורה אחת."],[3,"","פירוש, כמו שיעקב ה\"ס קו אמצעי שמחזה ולמעלה, שה\"ס ת\"ת המכריע בין חסד וגבורה, כן יוסף ה\"ס קו אמצעי שמחזה ולמטה, שה\"ס יסוד המכריע בין נצח והוד, וע\"כ הם דומים זה לזה, והם בצורה אחת."],[4,"ויבא יוסף את דבתם וגו':","הרי בארוה שהיה אמר עליהם לאביו, שהיו אוכלים אבר מן החי בעוד שהוא חי. ויבא יוסף את דבתם רעה. ומקשה, והרי במנין י\"ב השבטים היו אלו בני השפחות וא\"כ איך היו בני לאה מזלזלים בהם, ואיך היו אוכלים אבר מן החי ועברו על מצות רבונם, שהרי עוד לבני נח צוה על מצוה זו, כמש\"א אך בשר בנפשו דמו לא תאכלו, ואיך אפשר שהם אכלו ועברו על מצות רבונם. ומשיב, אלא יוסף היה אומר כן מדעתו, וע\"כ נענש."],[5,"ר' יהודה אמר וכו':","רי\"א, את דבתם רעה הוא כמו שבארוה, שיוסף אמר שנתנו עיניהם בבנות הארץ. וזהו נבחן דבתם רעה, שיבואו לינק לכל אלו המדרגות שאינם קדושים הבאים מצד הטומאה."],[6,"וישראל אהב את יוסף וגו':","ר' אלעזר פתח, ואמר, לך עמי בא בחדריך וסגור דלתך בעדך חבי כמעט רגע עד יעבור זעם, \u0003לך עמי בא בחדריך,\u0004 בוא וראה, כמה אהב הקב\"ה את ישראל, ובשביל האהבה שאהב אותם מכל העמים עובדי ע\"ז, הזהירם ורצה לשמרם בכל מה שעושים."],[7,"תא חזי תלת וכו':","בוא וראה, ג' פעמים הם ביום, שהדין שורה בעולם, וכשמגיע זמן ההוא, צריך האדם להזהר ולהשמר שלא יפגע בו אותו הדין, והם בזמנים ידועים, וכבר בארוה."],[8,"בגין דהא כד וגו':","משום, כשהבוקר עולה, נתעורר אברהם בעולם, ונאחז בדין לקשר אותו עמו. ובתחילת שלש שעות הראשונות נוסע הדין ממקומו להתעורר ביעקב, עד שמגיע תפלת המנחה, שחוזר הדין למקומו, ונתעורר הדין של מטה להתקשר בדין של מעלה, כי אז נתקשר דין בדין וצריכים להזהר."],[8,"","ביאור הדברים \u0003יומא\u0004 הוא ז\"א הנקרא יום. \u0003תלת זמנין אית ביומא,\u0004 היינו ג' קוין שיש בז\"א, \u0003דדינא שריא בעלמא,\u0004 שיש בכל אחד ואחד מהם בחינת דין מיוחד."],[8,"","ואלו ג' בחינות דין שבג' קוין דז\"א, נמשכות מסוד ג' זריעות, חולם שורק וחירק, (כמ\"ש לעיל בראשית א' דף ט\"ו ד\"ה ההוא נקודה עש\"ה). שהן שורשיהם דג' קוין דז\"א. דין א) הוא, שבעת עלית המלכות לבינה נופלות ממנה אתוון אליה דאלקים ונשארה במ\"י דאלקים דהיינו ו\"ק בחוסר ג\"ר. והיא בחינת הדין שבנקודת החולם, ושבקו ימין דז\"א, הנקרא אברהם. דין ב) הוא, שבעת גדלות שהמלכות יוצאת מבינה וג' אתוון אל\"ה חוזרות לבינה, שאז חוזרת לראש א\"א, ומשגת ג\"ר, מבחינת חכמה בלי חסדים, שאז אפילו החכמה אינה מאירה, והיא נסתמה, וזהו בחינת הדין שבנקודת השורק, ושבקו שמאל דז\"א, הנקרא יצחק. ונקרא דין של מעלה. דין ג) הוא, עלית זו\"ן שמה בסוד המסך דחירק, ומכריע בין ב' הקוין, שמסך זה ה\"ס ו\"ק, ששורשו בא ממנעולא, ואח\"כ נתתקן בסוד מפתחא, (כמ\"ש לעיל לך דף י\"ג ד\"ה ולפיכך עש\"ה) ונעשה כמסך שבנקודת החולם. והיא בחינת הדין שבנקודת החירק, ושבקו אמצעי דז\"א הנקרא יעקב, ונקרא דין של מטה."],[8,"","וזה אמרו, \u0003בגין דהא כד סליק צפרא, אברהם אתער בעלמא,\u0004 כי כעלות הבוקר שולט קו ימין דז\"א הנקרא אברהם, \u0003ואחיד ליה לדינא,\u0004 ונאחז בדין של נקודת החולם, שהוא מסך דו\"ק חסר ראש מסבת התכללות המלכות בבינה, כנ\"ל, \u0003לקשריה ליה בהדיה,\u0004 כי בסבת גילוי הדין הזה דנקודת החולם, יוצאים כל המוחין דזו\"ן, (כנ\"ל בראשית א' דף ז' ד\"ה כבר) \u0003ובשירותא דתלת שעי קמייתא,\u0004 שאז זמן הזווג, ויעקב שה\"ס קו אמצעי עולה ומכריע בין ב' הקוין אברהם ויצחק, בסוד מסך דחירק שבו, \u0003נטיל דינא מאתריה לאתערא ביה ביעקב,\u0004 כי אחר שנכלל ב' הקוין ימין ושמאל זה בזה, יורד הדין מנקודת החולם שה\"ס אברהם, כי חזר והשיג הג\"ר ע\"י התכללותו בשמאל, והדין שהיה בו יורד ובא ביעקב, דהיינו בקו אמצעי בסוד המסך דחירק שבו, שהוא בחינת ו\"ק. \u0003עד דאתער צלותא דמנחה\u0004 שה\"ס שליטתו של יצחק דהיינו קו שמאל, \u0003דאהדר דינא לאתריה\u0004 כלומר, שבזווג של בוקר נתבטל הדין של יצחק, שה\"ס הסתימא שבנקודת השורק, בסבת הכרעתו של יעקב בכח המסך דחירק, ועתה שחזרה שליטתו של יצחק, ואינו נכלל באברהם, חזר ג\"כ הדין שבנקודת השורק למקומו, וז\"ש, \u0003דאהדר דינא לאתריה\u0004, שחזרו ונסתמו בו האורות מחמת חוסר החסדים. \u0003ואתער דינא דלתתא לאתקשרא בדינא דלעילא,\u0004 כי דין של מטה, שה\"ס בחינת ו\"ק חסר ראש שבמסך דחירק, בקו האמצעי, נתבטל עתה מפאת שנתקשר בדין של מעלה, שבנקודת השורק, וחזר הג\"ר גם לקו אמצעי מכח שליטת השמאל, וע\"כ נתבטלה הכרעתו, והדין שולט בעולם מסתימת האורות. \u0003ובעי לאזדהרא,\u0004 וע\"כ צריכים להזהר אז."],[9,"תו, כד דינא וכו':","ועוד, כשנתעורר הדין בעולם, והמות נמצא בעיר, אין אדם צריך ללכת יחידי בשוק, וכבר בארנו הדברים, (לעיל פרשת נח דף כ\"ט אות ע\"ט) אלא צריך להסגיר עצמו שלא יצא לחוץ, כמו שבארנו בנח (שם) שהסגיר את עצמו בתבה, שלא ימצא לפני המשחית."],[9,"","פירוש, ג' דינין הראשונים שהם בג' קוין דז\"א, צריכים רק להזהר שלא ימשיך הארת השמאל מלמעלה למטה, ואם הוא נזהר בזה, כבר הוא ניצל מהם. אבל בדין הזה הד', שיש מות בעיר, שה\"ס הדין של הנוקבא המתעורר בסוד, \u0003לא זכי הא רע,\u0004 שה\"ס הדינין שבמסך דצמצום א' שממנו המות, (כנ\"ל דף כ' ד\"ה ביאור). הנה כאן אינו מועיל זהירות ושמירה הנ\"ל, כי דין הזה אחר שנגלה, כבר שולט גם על בחינת ממטה למעלה. ואין לו עצה אלא להסגיר את עצמו, שלא יתראה לפני המשחית. שפירושו, שלא יגע בשום מוחין רק בבחינת ו\"ק שהוא אור החסדים שאין לס\"א שום אחיזה בהם, ונמצא שאינו נראה לפני המשחית, כי אין לו אחיזה בו, וזה נבחן, כמו מתחבא ומסגיר את עצמו בחדרו שלא יראו אותו. וז\"ש \u0003אלא בעי לאסגרא גרמיה וכו', כמה דאוקמוה בנח,\u0004 כי גם נח הסתיר את עצמו בבחינת הו\"ק שממטה למעלה דהיינו באור החסדים אשר שם, ואז ניצל, כי אין שום אחיזה לס\"א באור החסדים."],[10,"ועל דא, לך עמי בא בחדריך,","שפירושו, הסגר את עצמך בחדריך, \u0003וסגור דלתך בעדך,\u0004 היינו שלא יתראה בפני המשחית, דהיינו שלא ימשיך אלא אור ו\"ק דחסדים שאין למשחית אחיזה בו כנ\"ל בדבור הסמוך ע\"ש. \u0003חבי כמעט רגע עד יעבור זעם,\u0004 כי אחר שעבר הדין, אין עוד רשות למשחית להזיקו."],[11,"ת\"ח וגו',","בוא וראה, שהקב\"ה בשביל האהבה שאהב את ישראל, וקרבם אליו, גרמה שכל שאר העמים עכו\"ם שונאים את ישראל, משום שהם מתרחקים מקב\"ה, וישראל קרובים."],[12,"ותא חזי בגין וכו':","בוא וראה, בשביל האהבה שאהב יעקב את יוסף יותר מאחיו, אע\"פ שהיו כולם אחים מה כתוב, ויתנכלו אותו להמיתו. כל שכן העמים עובדי כו\"מ לישראל, שגם הם שונאים את ישראל בשביל האהבה שאהב הקב\"ה את ישראל יותר מכל העמים עכו\"ם."],[12,"","פירוש, האהבה שאהב יעקב את יוסף יותר מכל אחיו, גרמה לגילוי דין הד' הנ\"ל, שה\"ס המות, ומביא ראיה ממה שאומר הכתוב, ויתנכלו אותו להמיתו, והמות היא דין הד' הנ\"ל, ששום זהירות ושמירה אינו מועיל בו. כנ\"ל."],[13,"תא חזי כמה וכו':","בוא וראה כמה גרמה אהבה ההוא שאהב אותו יותר מכל אחיו, גרמה ליוסף שיגלה מאביו, ואביו הגלה עמו, וגרם גלות להם, אל השבטים וגרמה אל השכינה שהגלתה ביניהם. ואע\"פ שנגזרה גזירה בברית בין הבתרים, מ\"מ הסבה לזה היתה האהבה שאהבו מכל אחיו. ובארוה, שבשביל כתנת פסים שעשה לו יותר מלאחיו, נגרם כל הנ\"ל, מה כתוב, ויראו אחיו וגו' וישנאו אותו ולא יכלו דברו לשלום."]],[[0,"","מִשּׁוּם זֶה בְּאוֹתוֹ זְמַן שֶׁלֹּא נִמְצָא הַזָּכָר עִמָּהּ, וְאָז כָּל אוֹתָן נְשָׁמוֹת שֶׁיּוֹצְאוֹת, לְכֻלָּן הָיָה לָהֶן שִׁנּוּי מִכְּמוֹ שֶׁהָיוּ בִּזְמַן שֶׁהַשֶּׁמֶשׁ מִתְחַבֵּר בַּלְּבָנָה, כְּמוֹ שֶׁנִּתְבָּאֵר. וְלָכֵן אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף וְגוֹ', וְנִתְבָּאֵר."],[1,"","וְהוּא נַעַר, מִשּׁוּם שֶׁאֵין נִפְרָדִים לְעוֹלָמִים, צַדִּי\"ק וְצֶדֶ\"ק הֵם יַחַד. כְּמוֹ שֶׁהִיא נִקְרֵאת בַּשֵּׁם שֶׁל הַזָּכָר, גַּם כָּךְ הוּא נִקְרָא בַּשֵּׁם שֶׁלָּהּ, שֶׁכָּתוּב וְהוּא נַעַר."],[2,"","אֶת בְּנֵי בִלְהָה וְאֶת בְּנֵי זִלְפָּה. בְּכֻלָּם עוֹמֶדֶת לְחַדֵּשׁ אוֹתָם כָּרָאוּי וּלְהִשְׁתַּעֲשֵׁעַ לָהֶם בַּשִּׂמְחָה שֶׁלּוֹ. שֶׁכָּל הָעֲנָפִים וְכָל הֶעָלִים, כֻּלָּם מִתְבָּרְכִים בְּשִׂמְחָתוֹ."],[3,"","אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף, כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁכָּל דְּמוּתוֹ שֶׁל יַעֲקֹב הָיְתָה בְּיוֹסֵף, וְכָל מַה שֶּׁאֵרַע לָזֶה אֵרַע לָזֶה, וּשְׁנֵיהֶם הוֹלְכִים יַחַד. וְזֶהוּ הַסּוֹד שֶׁל הָאוֹת וָ\"ו, שֶׁשְּׁנֵיהֶם הוֹלְכִים יַחַד, מִשּׁוּם שֶׁהֵם סוֹד אֶחָד וּדְמוּת אַחַת."],[4,"","וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה, הֲרֵי פֵּרְשׁוּהָ שֶׁהָיָה אוֹמֵר לְאָבִיו עֲלֵיהֶם שֶׁהָיוּ אוֹכְלִים אֵיבָר מִבַּעֲלֵי חַיִּים כְּשֶׁהֵם חַיִּים. וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה, וְכִי זֶה בְּמִנְיָן הָיוּ אוֹתָם בְּנֵי הַשְּׁפָחוֹת, אֵיךְ הָיוּ מְזַלְזְלִים בָּהֶם בְּנֵי לֵאָה, וְאֵיךְ הָיוּ אוֹכְלִים אֵיבָר מִן הַחַי וְהָיוּ עוֹבְרִים עַל מִצְוַת רִבּוֹנָם, שֶׁהֲרֵי צִוָּה עַל בְּנֵי נֹחַ מִצְוָה זוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ט) אַךְ בָּשָׂר בְּנַפְשׁוֹ דָּמוֹ לֹא תֹאכֵלוּ, וְהֵם הָיוּ אוֹכְלִים אוֹתָם וְעוֹבְרִים עַל מִצְוַת רִבּוֹנָם? אֶלָּא יוֹסֵף הָיָה אוֹמֵר, וְעַל זֶה נֶעֱנַשׁ."],[5,"","רַבִּי יְהוּדָה אָמַר, אֶת דִּבָּתָם רָעָה - כְּמוֹ שֶׁבֵּאֲרוּהוּ שֶׁנָּתְנוּ עֵינֵיהֶם בִּבְנוֹת הָאָרֶץ, וְזֶהוּ דִּבָּתָם רָעָה, לְהֵינִיק אֶת כָּל אוֹתָן הַדְּרָגוֹת שֶׁאֵינָן קְדוֹשׁוֹת (ד\"א אף על גב) שֶׁבָּאוֹת מִצַּד הַטֻּמְאָה."],[6,"","וְיִשְׂרָאֵל אָהַב אֶת יוֹסֵף מִכָּל בָּנָיו כִּי בֶן זְקֻנִים הוּא לוֹ וְעָשָׂה לוֹ כְּתֹנֶת פַּסִּים. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (ישעיה כו) לֵךְ עַמִּי בֹּא בַחֲדָרֶיךְ וּסְגֹר דְּלָתְךְ בַּעֲדֶךְ חֲבִי כִמְעַט רֶגַע עַד יַעֲבָר זַעַם. לֵךְ עַמִּי בֹּא בַחֲדָרֶיךְ. בֹּא רְאֵה כַּמָּה אוֹהֵב הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל, וּבִשְׁבִיל אַהֲבָתָם שֶׁאוֹהֵב אוֹתָם עַל כָּל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, הִזְהִיר אוֹתָם וְרוֹצֶה לִשְׁמֹר אוֹתָם בְּכָל מַה שֶּׁהֵם עוֹשִׂים."],[7,"","בֹּא רְאֵה, שָׁלֹשׁ פְּעָמִים יֵשׁ בַּיּוֹם שֶׁהַדִּין שׁוֹרֶה בָּעוֹלָם, וּכְשֶׁבָּא אוֹתוֹ הַזְּמַן, צָרִיךְ הָאָדָם לְהִזָּהֵר וּלְהִשָּׁמֵר שֶׁלֹּא יִפְגַּע בּוֹ אוֹתוֹ הַדִּין, וְהֵם זְמַנִּים יְדוּעִים, וַהֲרֵי בֵּאֲרוּהָ."],[8,"","מִשּׁוּם שֶׁהֲרֵי כְּשֶׁעוֹלֶה הַבֹּקֶר, אַבְרָהָם מִתְעוֹרֵר בָּעוֹלָם וְאוֹחֵז אֶת הַדִּין לִקְשֹׁר אוֹתוֹ עִמּוֹ, וּבְרֵאשִׁית שְׁלֹשׁ הַשָּׁעוֹת הָרִאשׁוֹנוֹת נוֹסֵעַ הַדִּין מִמְּקוֹמוֹ לְהִתְעוֹרֵר בּוֹ בְּיַעֲקֹב, עַד שֶׁמִּתְעוֹרֶרֶת תְּפִלַּת הַמִּנְחָה שֶׁמַּחֲזִירָה אֶת הַדִּין לִמְקוֹמוֹ, וּמִתְעוֹרֵר הַדִּין שֶׁלְּמַטָּה לְהִתְקַשֵּׁר בַּדִּין שֶׁל מַעְלָה, שֶׁהֲרֵי אָז נִקְשָׁר דִּין עִם דִּין, וְצָרִיךְ לְהִזָּהֵר."],[9,"","עוֹד, כְּשֶׁהַדִּין מִתְעוֹרֵר בָּעוֹלָם וְהַמָּוֶת נִמְצָא בָּעִיר, לֹא צָרִיךְ הָאָדָם לָלֶכֶת יְחִידִי בַּשּׁוּק, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים, אֶלָּא צָרִיךְ לִסְגֹּר אֶת עַצְמוֹ שֶׁלֹּא יֵצֵא הַחוּצָה, כְּמוֹ שֶׁבֵּאֲרוּהוּ בְּנֹחַ שֶׁסָּגַר אֶת עַצְמוֹ בַּתֵּבָה שֶׁלֹּא יִמָּצֵא לִפְנֵי הַמַּשְׁחִית."],[10,"","וְעַל זֶה לֵךְ עַמִּי בַחֲדָרֶיךְ, סְגֹר אֶת עַצְמְךְ, וּסְגֹר דְּלָתְךְ בַּעֲדֶךְ, שֶׁלֹּא יִתְרָאֶה לִפְנֵי הַמַּשְׁחִית. חֲבִי כִמְעַט רֶגַע עַד יַעֲבָר זַעַם, שֶׁאַחַר שֶׁעוֹבֵר הַדִּין אֵין רְשׁוּת לַמַּשְׁחִית לְהַשְׁחִית."],[11,"","בֹּא רְאֵה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁבִיל הָאַהֲבָה שֶׁהוּא אוֹהֵב אֶת יִשְׂרָאֵל וְקֵרַב אוֹתָם אֵלָיו, כָּל שְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שׂוֹנְאִים אֶת יִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם מְרֻחָקִים וְיִשְׂרָאֵל קְרוֹבִים."],[12,"","וּבֹא רְאֵה, מִשּׁוּם הָאַהֲבָה שֶׁאָהַב יַעֲקֹב אֶת יוֹסֵף יוֹתֵר מֵאֶחָיו, אַף עַל גַּב שֶׁכֻּלָּם הָיוּ לוֹ אַחִים, מַה כָּתוּב? וַיִּתְנַכְּלוּ אֹתוֹ לַהֲמִיתוֹ. כָּל שֶׁכֵּן הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת לְיִשְׂרָאֵל."],[13,"","בֹּא רְאֵה כַּמָּה גָרְמָה לוֹ אוֹתָהּ אַהֲבָה שֶׁאָהַב אוֹתוֹ יוֹתֵר, שֶׁגָּרַם לוֹ שֶׁהָגְלָה מֵאָבִיו, וְגָלָה אָבִיו עִמּוֹ, וְגָרַם לָהֶם גָּלוּת וְלַשְּׁכִינָה שֶׁגָּלְתָה בֵּינֵיהֶם, וְאַף עַל פִּי שֶׁנִּגְזְרָה הַגְּזֵרָה, וּבֵאֲרוּהוּ שֶׁבִּשְׁבִיל כְּתֹנֶת הַפַּסִּים שֶׁעָשָׂה לוֹ יוֹתֵר, מַה כָּתוּב? וַיִּרְאוּ אֶחָיו."]]],[["וַיַּחֲלֹם יוֹסֵף חֲלוֹם וְגו', רִבִּי חִיָּיא פָּתַח וְאֲמַר, (במדבר י״ב:ו׳) וַיֹּאמֶר שִׁמְעוּ נָא דְּבָרָי אִם יִהְיֶה נְבִיאֲכֶם יְיָ בַּמַּרְאָה אֵלָיו אֶתְוַדָּע בַּחֲלוֹם אֲדַבֶּר בּוֹ. תָּא חֲזֵי, כַּמָּה דַרְגִּין לְדַרְגִין עֲבַד קוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ קָיְימֵי דָא עַל דָּא. דַּרְגָּא עַל דַּרְגָּא, דָּא לְעֵיל מִן דָּא, וְכֻלְּהוּ יָנְקִין אִלֵּין מִן אִלֵּין כְּדְקָא חָזֵי לוֹן, אִלֵּין מִימִינָא וְאִלֵּין מִשְּׂמָאלָא, וְכֻלְּהוּ אִתְמַנָּן אִלֵּין עַל אִלֵּין, כֹּלָּא כְּדְקָא יְאוּת.","תָּא חֲזֵי, כָּל נְבִיאֵי דְעַלְמָא כֻּלְּהוּ יָנְקֵי מִסִּטְרָא חָדָא, מִגּוֹ תְּרִין דַּרְגִּין יְדִיעָן, וְאִינוּן דַּרְגִּין הֲווּ אִתְחַזְּיָין בְּגוֹ אַסְפַּקְלַרְיָאה דְּלָא נָהֲרָא, דִּכְתִיב בַּמַּרְאָה אֵלָיו אֶתְוַדָּע, מַאי הוּא מַרְאָה, כְּמָה דְאִתְּמָר (ד\"א ל\"ג דמראה) חֵיזוּ דְּכָל גְּוָונִן אִתְחַזְּיָין בְּגַוָּוהּ, וְדָא הִיא אַסְפַּקְלַרְיָא דְּלָא נָהֲרָא. בַּחֲלוֹם אֲדַבֶּר בּוֹ, דָּא הוּא חַד מִשִּׁתִּין בִּנְבוּאָה כְּמָה דְאוּקְמוּהָ. וְאִיהוּ דַּרְגָּא שְׁתִיתָאָה מֵהַהוּא דַרְגָּא דִּנְבוּאָה וְאִיהוּ (קצו א) דַּרְגָּא דְגַבְרִיאֵל דִמְמַנָּא עַל חֶלְמָא וְהָא אִתְּמָר.","תָּא חֲזֵי, כָּל חֶלְמָא דְּאִיהוּ כְּדְקָא יְאוּת מֵהַאי דַרְגָּא קָא אַתְיָא, וְעַל דָּא לֵית לָךְ חֶלְמָא דְּלָא יִתְעָרְבוּן עִמֵּיהּ מִלִּין כְּדִיבִין, כְּמָה דְאוֹקִימְנָא, וּבְגִין כָּךְ מִנַּיְיהוּ קְשׁוֹט וּמִנַּיְיהוּ כְּדִיבָן, וְלֵית לָךְ חֶלְמָא דְּלָא אִית בֵּיהּ מֵהַאי גִיסָא וּמֵהַאי גִיסָא.","וּבְגִין דְּאִית בֵּיהּ בְּחֶלְמָא כֹּלָּא כִּדְאֲמָרָן, כָּל חֶלְמִין דְּעַלְמָא אָזְלִין בָּתַר פִּשְׁרָא דְפוּמָא, וְאוּקְמוּהָ. דִּכְתִיב, (בראשית מ״א:י״ג) וַיְהִי כַּאֲשֶׁר פָּתַר לָנוּ כֵּן הָיָה. מַאי טַעְמָא, בְּגִין דְּאִית בֵּיהּ בְּחֶלְמָא כְּדִיבוּ וּקְשׁוֹט, וּמִלָּה שָׁלְטָא עַל כֹּלָּא, וּבְגִין כָּךְ בָּעֵי חֶלְמָא פִּשְׁרָא טָבָא. רִבִּי יְהוּדָה אָמַר, בְּגִין דְּכָל חֶלְמָא מִדַּרְגָּא דִלְתַתָּא אִיהוּ, וְדִבּוּר שָׁלְטָא עֲלֵיהּ. וּבְגִין כָּךְ כָּל חֶלְמָא אָזְלָא בָּתַר פִּשְׁרָא.","פָּתַח וְאֲמַר, (איוב ל״ג:ט״ו-ט״ז) בַּחֲלוֹם חֶזְיוֹן לַיְלָה בִּנְפֹל תַּרְדֵּמָה עַל אֲנָשִׁים בִּתְנוּמוֹת עֲלֵי מִשְׁכָּב אָז יִגְלֶה אֹזֶן אֲנָשִׁים וּבְמֹסָרָם יַחְתֹּם. תָּא חֲזֵי, כַּד סָלִיק בַּר נָשׁ לְעַרְסֵיהּ, מִבָּעֵי לֵיהּ לְאַמְלָכָא עֲלֵיהּ מַלְכוּתָא דִשְׁמַיָא בְּקַדְמִיתָא, וּלְבָתַר יֵימָא חַד פְּסוּקָא דְרַחֲמֵי וְאוּקְמוּהָ חַבְרַיָיא. בְּגִין דְּהָא כַּד בַּר נָשׁ נָאִים עַל עַרְסֵיהּ, הָא נִשְׁמָתֵיהּ נַפְקָא מִנִּיהּ וְאָזְלָא וְשָׁטְיָא לְעֵילָא, כָּל חַד וְחַד כְּפוּם אָרְחֵיהּ וְהָכִי סְלִיקַת כְּמָה דְאִתְּמָר.","מַה כְּתִיב, בַּחֲלוֹם חֶזְיוֹן לַיְלָה. כַּד בְּנֵי נָשָׁא שָׁכְבֵי בְּעַרְסַיְיהוּ נָיְימִין וְנִשְׁמָתָא נָפְקַת מִנַּיְיהוּ. הֲדָא הוּא דִכְתִיב, בִּתְנוּמוֹת עֲלֵי מִשְׁכָּב אָז יִגְלֶה אֹזֶן אֲנָשִׁים. וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא אוֹדַע לָהּ לְנִשְׁמָתָא בְּהַהוּא דַרְגָּא דְּקָיְימָא עַל חֶלְמָא, אִינוּן מִלִּין דִּזְמִינִין לְמֵיתֵי עַל עַלְמָא אוֹ אִינוּן מִלִּין כְּפוּם אִינוּן הִרְהוּרִין דְּלִבֵּיהּ. בְּגִין דְּבַר נָשׁ נָטִיל אָרְחָא דְּתוֹכָחֵי דְעָלְמָא.","בְּגִין דְּהָא לָא מוֹדָעִין לֵיהּ לְבַר נָשׁ בְּעוֹד דְּאִיהוּ קָאִים בְּתוּקְפָא דְגוּפָא (נ\"א דרוחא) כִּדְקָאֲמָרָן, אֶלָּא מַלְאָכָא אוֹדַע לְנִשְׁמָתָא וְנִשְׁמָתָא לְבַר נָשׁ. וְהַהוּא חֶלְמָא אִיהוּ מִלְּעֵילָא, כַּד נִשְׁמָתִין נָפְקִין מִגּוּפֵי וְסָלְקִין כָּל חַד וְחַד כְּפוּם אָרְחֵיהּ.","וְכַמָּה דַּרְגִּין עַל דַּרְגִּין, בְּרָזָא דְחֶלְמָא כֻּלְּהוּ בְּרָזָא דְחָכְמְתָא. וְתָּא חֲזֵי, חֲלוֹם דַּרְגָּא חָדָא, מַרְאָה דַּרְגָּא חָדָא, נְבוּאָה דַּרְגָּא חָדָא, וְכֻלְּהוּ דַּרְגִּין לְדַרְגִּין אִלֵּין עַל אִלֵּין.","וַיַּחֲלֹם יוֹסֵף חֲלוֹם וַיַּגֵּד לְאֶחָיו וַיּוֹסִפוּ עוֹד שְׂנֹא אֹתוֹ עַל חֲלוֹמוֹתָיו. מֵהָכָא דְּלָא מִבָּעֵי לֵיהּ לְבַר נָשׁ לְמֵימַר חֶלְמֵיהּ בַּר לְהַהוּא בַּר נָשׁ דְּרָחִים לֵיהּ, וְאִי לָאו, אִיהוּ גָּרִים לֵיהּ. דְּאִי הַהוּא חֶלְמָא מִתְהַפֵּךְ לְגַוְונָא אָחֳרָא, אִיהוּ גָּרִים לְסַלְּקָא.","תָּא חֲזֵי, דְּיוֹסֵף אִיהוּ אָמַר חֶלְמָא לַאֲחוּהִי, וְעַל דָּא גָּרְמוּ לֵיהּ לְסַלָּקָא חֶלְמֵיהּ תְּרֵין וְעֶשְׂרִין שְׁנִין דְּאִתְעַכַּב. רִבִּי יוֹסֵי אָמַר, מְנָלָן, דִּכְתִיב וַיּוֹסִיפוּ עוֹד שְׂנֹא אוֹתוֹ. מַאי שְׂנֹא אוֹתוֹ, דְּגָרְמוּ לֵיהּ קִטְרוּגִין בְּדָא."],[[0,"ויחלום יוסף חלום וגו':","ר' חייא פתח ואמר, ויאמר שמעו נא דברי וגו' בוא וראה, כמה מדרגות למדרגות עשה הקב\"ה, וכולן עומדות זו על זו, מדרגה על מדרגה, זו למעלה מזו, וכולן יונקות אלו מאלו כראוי להם, אלו מימין ואלו משמאל, וכולן נתמנו אלו על אלו, הכל כראוי להיות."],[1,"ת\"ח כל נביאי וכו':","בוא וראה, כל נביאי העולם, כולם ינקו מבחינה אחת, מתוך ב' מדרגות ידועות, שהן נצח והוד, ואלו המדרגות היו נראים בתוך מראה שאינה מאירה, שהיא הנוקבא. שכתוב במראה אליו אתודע, מה היא מראה. הוא כמו שלמדנו, מראה שכל הצבעים נראים בתוכה, דהיינו ג' הצבעים לכן אדום ירוק, שהם ג' קוין דז\"א, וזה הוא, מראה שאינה מאירה."],[1,"בחלום אדבר בו וכו':","זה הוא אחד מששים שבנבואה כמו שבארוה, והוא מדרגה הששית למטה ממדרגת הנבואה, והיא מדרגת גבריאל הממונה על החלום. וכבר למדנו, הוא לעיל, ויצא אות מ\"ה, ע\"ש בסולם."],[2,"ת\"ח כל חלמא וכו':","בוא וראה, כל חלום שהוא כראוי בא ממדרגה ההיא, דהיינו ממלאך גבריאל, ומשום שבא ממלאך, על כן, אין לך חלום שלא יתערב עמו דברי שקר, כמו שבארוה, ומשום זה, יש מהם שהם אמת ויש מהם שהם שקר, ואין לך חלום שלא יש בו מצד זה ומצד זה."],[3,"ובגין דאית ביה וכו':","ומשום שיש בו, בחלום, הכל, הן אמת והן שקר, כמו שאמרנו, לכן כל חלומות שבעולם הולכים אחר פתרון הפה. ובארוה, שכתוב, ויהי כאשר פתר לנו כן היה, הרי שמתקיים לפי הפתרון, מהו הטעם, משום שיש בו, בחלום, שקר ואמת. לכן המלה של הפתרון שולטת על הכל שמכרעת אותו, אם לפי אמתיותו או לפי השקר שבו, ולפיכך צריך החלום לפתרון טוב."],[3,"רבי יהודה אמר וכו':","רי\"א, משום שכל חלום הוא ממדרגה שלמטה, דהיינו ממלאך גבריאל, ודבור, שה\"ס הנוקבא, שולטת עליו, על המלאך, ועל כן, כל חלום הולך אחר הפתרון, שהוא בחינת דבור, הבא מהנוקבא הנקראת דבור, השולטת על מלאך גבריאל."],[4,"פתח ואמר, בחלום חזיון וגו':","בוא וראה, כשאדם עולה למטתו, צריך להמליך על עצמו תחילה מלכות שמים, ואחר כך יאמר פסוק אחד של רחמים. ובארוה החברים, משום כי כשהאדם ישן על מטתו, הרי נשמתו יצאה ממנו, והולכת ומשוטטת למעלה, כל אחת ואחת לפי דרכה כן היא עולה. כמו שלמדנו."],[5,"מה כתיב בחלום חזיון וכו':","כשבני אדם שוכבים על מטתם ומנמנמים, והנשמה יצאה ממנו, זהו שכתוב, \u0003בתנומות עלי משכב אז יגלה אזן אנשים,\u0004 ואז הקב\"ה מודיע אל הנשמה, באותה המדרגה הממונה על החלום, דהיינו גבריאל, את הדברים העתידים לבא בעולם, או אלו הדברים שהם באים מהרהורי הלב, דהיינו אמת או שקר או שניהם יחד כנ\"ל. כדי שיקבל האדם דרך תוכחה מדברי העולם. כלומר, ע\"כ מגלים לו העתיד לבא בעולם."],[6,"בגין דהא לא מודעין וכו':","כי אין מודיעים לאדם בעוד שעומד בכחו של הגוף, כמו שאמרנו, אלא המלאך מודיע אל הנשמה והנשמה אל האדם, שהחלום בא אל הנשמות מלמעלה, כשהנשמות יוצאות מגופות, ועולות כל אחת ואחת כפי מעלתה."],[7,"וכמה דרגין וכו':","וכמה מדרגות על מדרגות הן בסוד החלום, כולם הן בסוד החכמה. ובוא וראה. חלום מדרגה אחת, מראה מדרגה אחת, נבואה מדרגה אחת וכולם הן מדרגות למדרגות אלו על אלו. כי מדרגת החלום מתחת מדרגת המראה, ומדרגת המראה הוא מתחת מדרגת הנבואה. ובאורם תמצא לעיל פרשת ויצא אות מ\"ה ואות נ' ע\"ש."],[8,"ויחלום יוסף חלום ויגד וגו':","מכאן, שאין לאדם לומר חלמו רק לאדם שאוהב אותו, ואם לא, אוהב אותו, הוא גורם לו רעה, שאם החלום מתהפך לדבר אחר, הוא שגרם להסתלק הוראת החלום האמיתית על ידי פתרונו."],[9,"תא חזי וכו':","בוא וראה. כי יוסף אמר את החלום לאחיו, שלא אהבו אותו, ועל כן גרמו לו, שיסתלק חלומו ויתעכב לשתים ועשרים שנה. ר' יוסי אמר, מאין לנו זה, שהשונא גורם להסתלקות החלום כנ\"ל, הוא ממה שכתוב ויוסיפו עוד שנא אותו. מה פירושו של שנא אותו, היינו שגרמו לו קטרוגים בזה, עד שנדחה החלום לעשרים ושתים שנים."]],[[0,"","וַיַּחֲלֹם יוֹסֵף חֲלוֹם וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (במדבר יב) וַיֹּאמֶר שִׁמְעוּ נָא דְּבָרָי אִם יִהְיֶה נְבִיאֲכֶם ה' בַּמַּרְאָה אֵלָיו אֶתְוַדָּע בַּחֲלוֹם אֲדַבֶּר בּוֹ. בֹּא רְאֵה כַּמָּה דְרָגוֹת לִדְרָגוֹת עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, כֻּלָּם עוֹמְדִים זֶה עַל זֶה, דַּרְגָּה עַל דַּרְגָּה, זוֹ לְמַעְלָה מִזּוֹ, וְכֻלָּן יוֹנְקוֹת אֵלּוּ מֵאֵלּוּ כָּרָאוּי לָהֶם, אֵלּוּ מִיָּמִין וְאֵלּוּ מִשְּׂמֹאל, וְכֻלָּם מְמֻנּוֹת אֵלּוּ עַל אֵלּוּ הַכֹּל כָּרָאוּי."],[1,"","בֹּא רְאֵה, כָּל נְבִיאֵי הָעוֹלָם, כֻּלָּם יוֹנְקִים מִצַּד אֶחָד מִתּוֹךְ שְׁתֵּי דְרָגוֹת יְדוּעוֹת, וְאוֹתָן הַדְּרָגוֹת הָיוּ נִרְאוֹת בְּתוֹךְ הָאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה, שֶׁכָּתוּב בַּמַּרְאָה אֵלָיו אֶתְוַדָּע. מַה הִיא הַמַּרְאָה? כְּמוֹ שֶׁנֶּאֱמַר (שמראה) הַמַּרְאֶה שֶׁכָּל הַגְּוָנִים נִרְאִים בְּתוֹכָהּ, וְזוֹהִי הָאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה. בַּחֲלוֹם אֲדַבֶּר בּוֹ, זֶהוּ אֶחָד מִשִּׁשִּׁים בִּנְבוּאָה, כְּמוֹ שֶׁבֵּאֲרוּהוּ, וְהִיא הַדַּרְגָּה הַשִּׁשִּׁית מֵאוֹתָהּ הַדַּרְגָּה שֶׁל נְבוּאָה, וְהִיא הַדַּרְגָּה שֶׁל גַּבְרִיאֵל שֶׁמְּמֻנֶּה עַל הַחֲלוֹם, וַהֲרֵי נִתְבָּאֵר."],[2,"","בֹּא רְאֵה, כָּל חֲלוֹם שֶׁהוּא כָּרָאוּי, בָּא מִן הַדַּרְגָּה הַזּוֹ, וְעַל כֵּן אֵין לְךְ חֲלוֹם שֶׁלֹּא יִתְעָרְבוּ בוֹ דְּבָרִים כּוֹזְבִים, כְּמוֹ שֶׁבֵּאַרְנוּ. וּמִשּׁוּם כָּךְ מֵהֶם אֱמֶת וּמֵהֶם כּוֹזְבִים, וְאֵין לְךְ חֲלוֹם שֶׁאֵין בּוֹ מִצַּד זֶה וּמִצַּד זֶה."],[3,"","וּמִשּׁוּם שֶׁיֵּשׁ בַּחֲלוֹם הַכֹּל כְּמוֹ שֶׁאָמַרְנוּ, כָּל הַחֲלוֹמוֹת שֶׁבָּעוֹלָם הוֹלְכִים אַחַר פִּתְרוֹן הַפֶּה, וּבֵאֲרוּהוּ שֶׁכָּתוּב (בראשית מא) וַיְהִי כַּאֲשֶׁר פָּתַר לָנוּ כֵּן הָיָה. מָה הַטַּעַם? מִשּׁוּם שֶׁיֵּשׁ בַּחֲלוֹם כָּזָב וֶאֱמֶת, וְהַדִּבּוּר שׁוֹלֵט עַל הַכֹּל, וּמִשּׁוּם כָּךְ צָרִיךְ הַחֲלוֹם פִּתְרוֹן טוֹב. רַבִּי יְהוּדָה אָמַר, מִשּׁוּם שֶׁכָּל חֲלוֹם הוּא מֵהַמַּדְרֵגָה שֶׁלְּמַטָּה, וְהַדִּבּוּר שׁוֹלֵט עָלָיו, וּמִשּׁוּם כָּךְ כָּל חֲלוֹם הוֹלֵךְ אַחַר הַפִּתְרוֹן."],[4,"","פָּתַח וְאָמַר, (איוב לג) בַּחֲלוֹם חֶזְיוֹן לַיְלָה בִּנְפֹל תַּרְדֵּמָה עַל אֲנָשִׁים בִּתְנוּמוֹת עֲלֵי מִשְׁכָּב אָז יִגְלֶה אֹזֶן אֲנָשִׁים וּבְמֹסָרָם יַחְתֹּם. בֹּא רְאֵה, כְּשֶׁעוֹלֶה אָדָם לְמִטָּתוֹ, הוּא צָרִיךְ לְהַמְלִיךְ עָלָיו מַלְכוּת שָׁמַיִם בָּרִאשׁוֹנָה, וְאַחַר כָּךְ יֹאמַר פָּסוּק אֶחָד שֶׁל רַחֲמִים, וּבֵאֲרוּהוּ הַחֲבֵרִים. מִשּׁוּם שֶׁהִנֵּה כַּאֲשֶׁר אָדָם יָשֵׁן עַל מִטָּתוֹ, הִנֵּה נִשְׁמָתוֹ יוֹצֵאת מִמֶּנּוּ וְהוֹלֶכֶת וּמְשׁוֹטֶטֶת לְמַעְלָה, כָּל אֶחָד וְאֶחָד כְּפִי דַרְכּוֹ, וְכָךְ עוֹלֶה, כְּמוֹ שֶׁנִּתְבָּאֵר."],[5,"","מַה כָּתוּב? בַּחֲלוֹם חֶזְיוֹן לַיְלָה, כְּשֶׁבְּנֵי אָדָם שׁוֹכְבִים בְּמִטָּתָם יְשֵׁנִים וְהַנְּשָׁמָה יוֹצֵאת מֵהֶם. זֶהוּ שֶׁכָּתוּב בִּתְנוּמוֹת עֲלֵי מִשְׁכָּב אָז יִגְלֶה אֹזֶן אֲנָשִׁים. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹדִיעַ לַנְּשָׁמָה, בְּאוֹתָהּ הַדַּרְגָּה שֶׁעוֹמֶדֶת עַל הַחֲלוֹם, אוֹתָם הַדְּבָרִים שֶׁעֲתִידִים לָבֹא עַל הָעוֹלָם, אוֹ אוֹתָם דְּבָרִים כְּפִי אוֹתָם הַהִרְהוּרִים שֶׁלּ לִבּוֹ, מִשּׁוּם שֶׁאָדָם נוֹטֵל דֶּרֶךְ שֶׁל תּוֹכְחוֹת הָעוֹלָם."],[6,"","מִשּׁוּם שֶׁהִנֵּה לֹא מוֹדִיעִים לָאָדָם בְּעוֹד שֶׁהוּא עוֹמֵד בְּכֹחַ הַגּוּף (נ\"א של הרוח) כְּמוֹ שֶׁאָמַרְנוּ, אֶלָּא מַלְאָךְ מוֹדִיעַ לַנְּשָׁמָה, וְהַנְּשָׁמָה לָאָדָם, וְאוֹתוֹ הַחֲלוֹם הוּא מִלְמַעְלָה, כְּשֶׁהַנְּשָׁמוֹת יוֹצְאוֹת מִן הַגּוּפִים וְעוֹלוֹת כָּל אַחַת וְאַחַת כְּפִי דַרְכָּהּ."],[7,"","וְכַמָּה דְּרָגוֹת עַל דְּרָגוֹת בְּסוֹד הַחֲלוֹם, כֻּלָּן בְּסוֹד הַחָכְמָה. וּבא וּרְאֵה, הַחֲלוֹם דַּרְגָּה אַחַת, הַמַּרְאֶה דַּרְגָּה אַחַת, הַנְּבוּאָה דַּרְגָּה אַחַת, וְכֻלָּם דְּרָגוֹת לִדְרָגוֹת אֵלֶּה עַל אֵלֶּה."],[8,"","וַיַּחֲלֹם יוֹסֵף חֲלוֹם וַיַּגֵּד לְאֶחָיו וַיּוֹסִפוּ עוֹד שְׂנֹא אֹתוֹ עַל חֲלוֹמוֹתָיו. מִכָּאן שֶׁלֹּא צָרִיךְ הָאָדָם לוֹמַר אֶת חֲלוֹמוֹ רַק לְאוֹתוֹ הָאָדָם שֶׁאוֹהֵב אוֹתוֹ, וְאִם לֹא - הוּא גוֹרֵם לוֹ. שֶׁאִם אוֹתוֹ הַחֲלוֹם מִתְהַפֵּךְ לְגָוֶן אַחֵר - הוּא גוֹרֵם לְסַלְּקוֹ"],[9,"","בֹּא רְאֵה שֶׁיּוֹסֵף אָמַר אֶת הַחֲלוֹם לְאֶחָיו, וְעַל כֵּן גָּרְמוּ לוֹ לְסַלֵּק אֶת חֲלוֹמוֹ עֶשְׂרִים וּשְׁתַּיִם שָׁנִים שֶׁהִתְעַכֵּב. רַבִּי יוֹסֵי אָמַר, מִנַּיִן לָנוּ? שֶׁכָּתוּב וַיּוֹסִפוּ עוֹד שְׂנֹא אֹתוֹ. מַה זֶה שְׂנֹא אֹתוֹ? שֶׁגָּרְמוּ לוֹ בָּזֶה קִטְרוּגִים."]]],[["מַה כְּתִיב, וַיֹּאמֶר אֲלֵיהֶם שִׁמְעוּ נָא הַחֲלוֹם הַזֶּה אֲשֶׁר חָלָמְתִּי, דְּבָעָא מִנַיְיהוּ דְּיִשְׁמְעוּן לֵיהּ. וְאִיהוּ אוֹדַע לְהוּ הַהוּא חֶלְמָא, דְּאִלְמָלֵא אִינוּן דְּאַהֲפָכוּ לֵיהּ לְגַוְונָא אָחֳרָא, הָכִי אִתְקְיַּים. וְאִינוּן אֲתִיבוּ וְאָמְרוּ הֲמָלֹךְ תִּמְלךְ עָלֵינוּ אִם מָשׁוֹל תִּמְשֹׁל בָּנוּ. מִיָּד אָמְרוּ לֵיהּ פִּשְׁרָא דְחָלְמָא וְגָזְרוּ גְּזֵרָה, וּבְגִין כָּךְ וַיּוֹסִיפוּ עוֹד שְׂנֹא אוֹתוֹ.","רִבִּי חִיָּיא וְרִבִּי יוֹסֵי הֲווּ שְׁכִיחֵי קַמֵיהּ דְּרִבִּי שִׁמְעוֹן, אָמַר רִבִּי חִיָּיא, הָא תָּנִינָן חֶלְמָא דְלָא אִתְפַּשַּׁר, כְּאִגַּרְתָּא דְלָא מִתְקַרְיָא. אִי בְּגִין דְּאִתְקְיַּים וְאִיהוּ לָא יָדַע, אוֹ דְּלָא אִתְקְיַּים כְּלָל. אָמַר לֵיהּ, אִתְקְיַּים וְלָא אִתְיְידַע, דְּהָא הַהוּא חֶלְמָא חֵילָא תַּלְיָא עֲלֵיהּ, וְאִיהוּ לָא אִתְיְדַע וְלָא יְדִיעַ, אִי אִתְקְיַּים אִי לָא אִתְקְיַּים.","וְלֵית לָךְ מִלָּה בְּעַלְמָא דְּעַד לָא יֵיתֵי לְעַלְמָא, דְּלָאו אִיהִי תַּלְיָיא בְּחֶלְמָא אוֹ עַל יְדָא דְּכָרוֹזָא. דְּהָא אִתְּמָר דְּכָל מִלָּה וּמִלָּה עַד לָא יֵיתֵי לְעַלְמָא, מַכְרְזֵי עֲלֵיהּ בָּרָקִיעַ. וּמִתַּמָּן אִתְפַּשַּׁט בְּעַלְמָא וְאִתְיְהִיב עַל יְדָא דְּכָרוֹזָא. וְכֹלָּא בְּגִין דִּכְתִיב, (עמוס ג׳:ז׳) כִּי לא יַעֲשֶׂה יְיָ אֱלהִים דָּבָר כִּי אִם גָּלָה סוֹדוֹ אֶל עֲבָדָיו הַנְּבִיאִים, בְּזִמְנָא דִנְבִיאִים אִשְׁתַּכָּחוּ בְּעַלְמָא. וְאִי לָאו, אַף עַל גַּב דִּנְבוּאָה לָא שַׁרְיָא, חַכִּימֵי עֲדִיפֵי מִנְּבִיאִים. וְאִי לָא, אִתְיְהִיב בְּחֶלְמָא. וְאִי לָאו, בְּצִפֳּרֵי שְׁמַיָא מִשְׁתַּכְּחֵי מִלָּה וְהָא אוּקְמוּהָ:","וַיֵּלְכוּ אֶחָיו לִרְעוֹת אֶת צֹאן אֲבִיהֶם בִּשְׁכֶם. רִבִּי שִׁמְעוֹן אָמַר, לִרְעוֹת צֹאן אֲבִיהֶם מִבָּעֵי לֵיהּ, מַאי אֶ\"ת נָקוּד מִלְּעֵילָא, לְאַסְגָּאָה עִמְהוֹן שְׁכִינְתָּא, דְּאִיהִי עִמְּהוֹן שַׁרְיָיא. בְּגִין דְּאִינוּן הֲווּ עֲשָׂרָה, דְּהָא יוֹסֵף לָא הֲוָה עִמְּהוֹן, וּבִנְיָמִין אִיהוּ זְעִיר בְּבֵיתָא. וּבְגִין כָּךְ אִינוּן הֲווּ עֲשָׂרָה. וְכַד אָזְלוּ הֲוַת שְׁכִינְתָּא בֵּינַיְיהוּ, וְעַל דָּא נָקוּד מִלְּעֵילָא.","וּבְגִין כָּךְ בְּזִמְנָא דְּזַבִּינוּ לֵיהּ לְיוֹסֵף אִשְׁתַּתָּפוּ כֻּלְּהוּ בַּהֲדֵי שְׁכִינְתָּא וְאַשְׁתִּיפוּ לָהּ בַּהֲדַיְיהוּ כַּד עֲבִידוּ אוֹמָאָה. וְעַד דְּאִתְגַּלְּיָיא מִלָּה דְיוֹסֵף, לָא שַׁרְיָא שְׁכִינְתָּא עֲלֵיהּ דְּיַעֲקֹב.","וְאִי תֵימָא דִּשְׁכִינְתָּא לָא אִשְׁתַּכְּחַת עִמְּהוֹן. תָּא חֲזֵי, דִּכְתִיב (תהילים קכ״ב:ד׳) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל לְהוֹדוֹת לְשֵׁם יְיָ. כֻּלְּהוּ צַדִּיקֵי וַחֲסִידֵי קִיּוּמָא דְכָל עַלְמָא, קִיּוּמָא אִינוּן לְעֵילָא וְתַתָּא.","פָּתַח וְאָמַר, (תהילים קכ״ב:א׳) שָׂמַחְתִּי בְּאוֹמְרִים לִי בֵּית יְיָ נִלֵךְ. הַאי קְרָא אוּקְמוּהָ, דְּדָוִד הֲוָה עִם לִבֵּיהּ לְמִבְנֵי בֵּיתָא. כְּמָה דְאַתְּ אָמֵר, (מלכים א ח׳:י״ז) וַיְהִי עִם לְבַב דָּוִד אָבִי לִבְנוֹת בַּיִת לְשֵׁם יְיָ וְגו'. וּלְבָתַר מַה כְּתִיב רַק אַתָּה לא תִבְנֶה הַבַּיִת כִּי אִם בִּנְךָ הַיּוֹצֵא מֵחֲלָצֶיךָ הוּא יִבְנֶה הַבַּיִת לִשְׁמִי. וְכָל יִשְׂרָאֵל הֲווּ יָדְעֵי דָא, וְהֲווּ אָמְרוּ אֵימָתַי יָמוּת דָּוִד וְיָקוּם שְׁלֹמֹה בְּרֵיהּ וְיִבְנֶה בֵּיתָא. וּכְדֵין עוֹמְדוֹת הָיוּ רַגְלֵינוּ בִּשְׁעָרַיִךְ יְרוּשָׁלַיִם, כְּדֵין נִיסַק וְנַקְרִיב תַּמָּן קָרְבָּנִין.","וְעִם כָּל דָּא, אַף עַל גַּב דְּהֲווּ אָמְרוּ אֵימָתַי יָמוּת סָבָא דָא, כְּדֵין שָׂמַחְתִּי. וְחֶדְוָה הֲוָה לִי בְּגִין בְּרִי, דְּהֲווּ אָמְרֵי דִבְרִי יָקוּם תְּחוֹתִי לְמִגְמַר פִּקוּדָא לְמִבְנִי בֵיתָא. כְּדֵין שָׁרֵי וְשַׁבַּח לָהּ וְאָמַר, יְרוּשָׁלַיִם הַבְּנוּיָה כְּעִיר שֶׁחֻבְּרָה לָהּ יַחְדָּו.","תְּנַן עֲבַד קוּדְשָׁא בְּרִיךְ הוּא יְרוּשָׁלַיִם לְתַתָּא כְּגַוְונָא דִלְעֵילָא, וְדָא מִתְתַּקְּנָא (דא) לָקֳבֵל דָּא דִּכְתִיב, (שמות ט״ו:י״ז) מָכוֹן לְשִׁבְתְּךָ פָּעַלְתָּ יְיָ. הַבְּנוּיָה, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְנַחֲתָא לָהּ יְרוּשָׁלַיִם דִּלְעֵילָא כְּדְקָא יָאוֹת, וּבְגִין כָּךְ הַבְּנוּיָה. שֶׁחֻבְּרָה לָהּ יַחְדָּו, וְהָא אוּקְמוּהָ שֶׁחֻבְּרָה שֶׁחִבְּרוּ מִבָּעֵי לֵיהּ. אֶלָּא דְּאִתְחַבָּרַת אִמָּא בִּבְרַתָּא וְהֲווּ כְּחֲדָא וְאוּקְמוּהָ.","וְאִתְּמָר. שֶׁשָּׁם עָלוּ שְׁבָטִים אִלֵּין אִינוּן קִיּוּמָא דְעַלְמָא וְתִקּוּנָא דְעַלְמָא תַּתָּאָה, וְלָא תֵימָא דְּעַלְמָא תַּתָּאָה בִּלְחוֹדוֹי, אֶלָּא אֲפִילּוּ דְּעַלְמָא עִלָּאָה. דִּכְתִיב שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל, לְיִשְׂרָאֵל דַּיְיקָא. בְּגִין דְּאִינוּן קִיּוּמָא לְתַתָּא, סַהֲדוּתָא אִינוּן לְעֵילָא. וְכֹלָּא לְהוֹדוֹת לְשֵׁם יְיָ, לְאוֹדָאָה שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא לְכָל סִטְרִין, דִּכְתִיב לְהוֹדוֹת לְשֵׁם יְיָ:"],[[0,"מה כתיב, ויאמר אליהם וגו':","שבקש מהם שישמעו לו, והוא הודיע להם את החלום. ואלמלא הם, שהפכו את החלום לדבר אחר, היה החלום מתקיים, אבל הם השיבו ואמרו, המלוך תמלוך עלינו אם משול תמשול בנו, מיד אמרו לו בזה את פתרון החלום, כלומר שהוציאו אותו ממשמעות המלוכה והממשלה ודחו אותו לדבר אחר, וגזרו גזירה, שלא ימלוך עליהם ומשום זה אומר הכתוב ויוסיפו עוד שנא אותו, דהיינו שגרמו לו קטרוגים כנ\"ל."],[1,"ר' חייא ורבי יוסי וכו':","ר\"ח ור\"י היו מצוים לפני ר' שמעון, אמר ר' חייא הרי למדנו, חלום שלא נפתר דומה לאגרת שלא נקראה, הוא שואל, אם פירושו שהחלום מתקיים והוא אינו יודע, או שאינו מתקיים כלל."],[1,"אמר ליה אתקיים וכו':","אמר לו, שהפירוש הוא שמתקיים והוא אינו יודע. כי החלום כח תלוי עליו, ומוכרח שיתקיים, אלא שלא נודע לו ואינו יודע אם נתקיים החלום או לא נתקיים. דהיינו הדמיון לאגרת שלא נקראה."],[2,"ולית לך מלה וכו':","ואיך לך דבר בעולם, שאינו תלוי בחלום או בידי כרוז עוד מטרם שבא לעולם. כי למדנו, כל דבר ודבר מטרם שבא לעולם, מכריזים עליו ברקיע, ומשם מתפשט בעולם. והוא ניתן על ידי כרוז. והכל משום שכתוב, כי לא יעשה ה' אלקים דבר וגו', והיינו בזמן שהנביאים נמצאו בעולם. ואם לא, אע\"פ שנבואה אינה שורה, הרי חכמים חשובים מנביאים. ואם לא יש חכמים, ניתן הדבר בחלום. ואם לא ניתן בחלום נמצא הדבר בצפרי השמים, וכבר בארוה."],[3,"וילכו אחיו לרעות את וגו':","ר' שמעון אמר, לרעות צאן אביהם היה צריך לומר, למה אומר \u0003את\u0004 צאן אביהם. ומשיב, המלה \u0003את\u0004 מנוקדת מלמעלה, והוא לרבות עמהם השכינה כי השכינה נקראת \u0003את\u0004 (כנ\"ל בראשית ב' אות רמ\"ו) שהיתה שורה עמהם. משום שהיו עשרה, ובכל מקום שיש עשרה שורה בהם השכינה, כי יוסף לא היה עמהם, ובנימין הקטן הוא בבית, ומשום זה היו עשרה, וכשהלכו היתה השכינה ביניהם, ועל כן מנוקד מלמעלה על המלה \u0003את.\u0004"],[4,"ובג\"כ בזמנא וכו':","ומשום זה, בשעה שמכרו את יוסף נשתתפו כולם עם השכינה, ושתפו אותה עמהם בעת שעשו את השבועה והחרם שלא לגלות המעשה ממכירת יוסף, וע\"כ עד שנתגלה הדבר דמכירת יוסף, לא שרתה השכינה על יעקב."],[5,"ואי תימא דשכינתא וכו':","ואם תאמר, שהשכינה לא היתה עמהם, עם השבטים, בוא וראה, שכתוב, ששם עלו שבטים וגו', הרי שכולם היו צדיקים וחסידים, וקיומם של כל בני העולם, שהעולם כולו היה מתקיים בזכותם, קיום של מעלה ומטה. דהיינו של עולמות העליונים ועולם התחתון."],[6,"פתח ואמר, שמחתי וגו':","מקרא זה בארוהו, שדוד היה עם לבבו לבנות הבית, כמש\"א, ויהי עם לבב דוד וגו' ואחר כך מה כתוב, רק אתה לא תבנה הבית וגו', וכל ישראל היו יודעים את זה, והיו אומרים, מתי ימות דוד, ויקום שלמה בנו, ויבנה הבית, ואז, עומדות היו רגלינו בשעריך ירושלים, כי אז נעלה ונקריב קרבנות."],[7,"ועם כל דא וכו':","ועם כל זה, אע\"פ שהיו אומרים, מתי ימות זקן הזה, אז, \u0003שמחתי,\u0004 וחדוה היתה לי, משום בני, שהיו אומרים שבני יקום תחתי לגמור המצוה ולבנות הבית, אז התחיל ושבח אותה, את השכינה, ואמר ירושלים הבנויה כעיר שחברה לה יחדיו."],[8,"תנן, עבד וכו':","למדנו, עשה הקב\"ה את ירושלים של מטה, שהיא הנוקבא, כעין ירושלים של מעלה, שהיא בינה, וזו מתתקנת לנגד זו. שהנוקבא מתתקנת בכל התקונים שבבינה, שכתוב, מכן לשבתך פעלת ה'. \u0003הבנויה,\u0004 פירושו, שעתיד הקב\"ה להוריד את ירושלים מלמעלה בנויה כראוי, ומשום זה אומר \u0003הבנויה\u0004. \u0003שחברה לה יחדיו:\u0004 וכבר בארוה. ושואל, כתוב שחברה, שחברו היה צריך לכתוב, בלשון רבים, ומשיב, אלא שנתחברה אמא שהיא בינה, בבתה, שהיא נוקבא, והיו כאחת, ע\"כ כתוב שחברה בלשון, יחיד. ובארוהו."],[9,"ואתמר, ששם עלו שבטים:","אלו הם קיומו של העולם והתקון של עולם התחתון, ולא תאמר תקון עולם התחתון בלבד, אלא אפילו של עולם העליון, שכתוב, שבטי יה עדות לישראל, \u0003לישראל\u0004 בדיוק. משום שהם קיומו של העולם למטה, הם עדות למעלה בעולם העליון. והכל הוא להודות לשם ה', דהיינו להודות לשמו של הקב\"ה בכל הבחינות, שכתוב להודות לשם ה'."]],[[0,"","מַה כָּתוּב? וַיֹּאמֶר אֲלֵיהֶם שִׁמְעוּ נָא הַחֲלוֹם הַזֶּה אֲשֶׁר חָלָמְתִּי. שֶׁרָצָה מֵהֶם שֶׁיִּשְׁמְעוּ לוֹ, וְהוּא הוֹדִיעַ לָהֶם אוֹתוֹ הַחֲלוֹם, שֶׁאִלְמָלֵא הֵם שֶׁהָפְכוּ אוֹתוֹ לְגָוֶן אַחֵר - כָּךְ הִתְקַיֵּם, וְהֵם הֵשִׁיבוּ וְאָמְרוּ, הֲמָלֹךְ תִּמְלֹךְ עָלֵינוּ אִם מָשׁוֹל תִּמְשֹׁל בָּנוּ!? מִיָּד אָמְרוּ לוֹ אֶת פֵּשֶׁר הַחֲלוֹם וְגָזְרוּ גְזֵרָה, וּמִשּׁוּם כָּךְ וַיּוֹסִפוּ עוֹד שְׂנֹא אֹתוֹ."],[1,"","רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ מְצוּיִים לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר רַבִּי חִיָּיא, הִנֵּה שָׁנִינוּ, חֲלוֹם שֶׁלֹּא נִפְתָּר כְּמוֹ אִגֶּרֶת שֶׁלֹּא נִקְרְאָה, אִם מִשּׁוּם שֶׁהִתְקַיֵּם וְהוּא לֹא יָדַע, אוֹ שֶׁלֹּא הִתְקַיֵּם כְּלָל. אָמַר לוֹ, הִתְקַיֵּם וְלֹא נוֹדַע, שֶׁהֲרֵי אוֹתוֹ הַחֲלוֹם תָּלוּי עָלָיו כֹּחַ, וְהוּא לֹא נוֹדַע וְלֹא יָדוּעַ אִם הִתְקַיֵּם וְאִם לֹא הִתְקַיֵּם."],[2,"","וְאֵין לְךְ דָּבָר בָּעוֹלָם שֶׁטֶּרֶם יָבֹא לָעוֹלָם שֶׁאֵינוֹ תָלוּי בַּחֲלוֹם אוֹ עַל יְדֵי כָרוֹז, שֶׁהֲרֵי נֶאֱמַר שֶׁכָּל דָּבָר וְדָבָר בְּטֶרֶם יָבֹא לָעוֹלָם מַכְרִיזִים עָלָיו בָּרָקִיעַ, וּמִשָּׁם מִתְפַּשֵּׁט בָּעוֹלָם וְנִתָּן עַל יְדֵי הַכָּרוֹז, וְהַכֹּל מִשּׁוּם שֶׁכָּתוּב (עמוס ג) כִּי לֹא יַעֲשֶׂה ה' אֱלֹהִים דָּבָר כִּי אִם גָּלָה סוֹדוֹ אֶל עֲבָדָיו הַנְּבִיאִים, בִּזְמַן שֶׁנְּבִיאִים נִמְצָאִים בָּעוֹלָם, וְאִם לֹא - אַף עַל גַּב שֶׁנְּבוּאָה לֹא שׁוֹרָה, חֲכָמִים עֲדִיפִים מִנְּבִיאִים, וְאִם לֹא - נִתָּן בַּחֲלוֹם, וְאִם לֹא - הַדָּבָר נִמְצָא בְּצִפֳּרֵי הַשָּׁמַיִם, וַהֲרֵי בֵּאֲרוּהָ."],[3,"","וַיֵּלְכוּ אֶחָיו לִרְעוֹת אֶת צֹאן אֲבִיהֶם בִּשְׁכֶם. רַבִּי שִׁמְעוֹן אָמַר, לִרְעוֹת צֹאן אֲבִיהֶם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אֶ\"ת נָקוּד מֵעָלָיו? לְרַבּוֹת שְׁכִינָה עִמָּהֶם, שֶׁהִיא שְׁרוּיָה עִמָּהֶם, מִשּׁוּם שֶׁהֵם הָיוּ עֲשָׂרָה, שֶׁהֲרֵי יוֹסֵף לֹא הָיָה עִמָּהֶם, וּבִנְיָמִין הוּא קָטָן בַּבַּיִת, וּמִשּׁוּם כָּךְ הֵם הָיוּ עֲשָׂרָה, וּכְשֶׁהָלְכוּ, הַשְּׁכִינָה הָיְתָה בֵינֵיהֶם, וְעַל כֵּן נָקוּד מִלְמַעְלָה."],[4,"","וּמִשּׁוּם כָּךְ, בִּזְמַן שֶׁמָּכְרוּ אֶת יוֹסֵף, הִשְׁתַּתְּפוּ כֻלָּם עִם הַשְּׁכִינָה, וְשִׁתְּפוּ אוֹתָהּ עִמָּהֶם כְּשֶׁעָשׂוּ שְׁבוּעָה, וְעַד שֶׁהִתְגַּלָּה דְּבַר יוֹסֵף, לֹא שָׁרְתָה שְׁכִינָה עַל יַעֲקֹב."],[5,"","וְאִם תֹּאמַר שֶׁהַשְּׁכִינָה לֹא נִמְצְאָה עִמָּהֶם - בֹּא רְאֵה, שֶׁכָּתוּב (תהלים קכב) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל לְהוֹדוֹת לְשֵׁם ה'. כֻּלָּם צַדִּיקִים וַחֲסִידִים, הַקִּיּוּם שֶׁל כָּל הָעוֹלָם, הֵם קִיּוּם לְמַעְלָה וּלְמַטָּה."],[6,"","פָּתַח וְאָמַר, (שם) שָׂמַחְתִּי בְּאֹמְרִים לִי בֵּית ה' נֵלֵךְ. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, שֶׁדָּוִד הָיָה עִם לִבּוֹ לִבְנוֹת הַבַּיִת, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ח) וַיְהִי עִם לְבַב דָּוִד אָבִי לִבְנוֹת בַּיִת לְשֵׁם ה' וְגוֹ'. וְאַחַר כָּךְ מַה כָּתוּב? רַק אַתָּה לֹא תִבְנֶה הַבָּיִת כִּי אִם בִּנְךְ הַיֹּצֵא מֵחֲלָצֶיךְ הוּא יִבְנֶה הַבַּיִת לִשְׁמִי. וְכָל יִשְׂרָאֵל הָיוּ יוֹדְעִים אֶת זֶה, וְהָיוּ אוֹמְרִים מָתַי יָמוּת דָּוִד וְיָקוּם שְׁלֹמֹה בְּנוֹ וְיִבְנֶה אֶת הַבַּיִת, וְאָז עֹמְדוֹת הָיוּ רַגְלֵינוּ בִּשְׁעָרַיִךְ יְרוּשָׁ לם, אָז נַעֲלֶה וְנַקְרִיב שָׁם קָרְבָּנוֹת."],[7,"","וְעִם כָּל זֶה, אַף עַל גַּב שֶׁהָיוּ אוֹמְרִים מָתַי יָמוּת הַזָּקֵן הַזֶּה, אֲזַי שָׂמַחְתִּי וְשִׂמְחָה הָיְתָה לִי בִּשְׁבִיל בְּנִי, שֶׁהָיוּ אוֹמְרִים שֶׁבְּנִי יָקוּם תַּחְתַּי לִגְמֹר אֶת הַמִּצְוָה לִבְנוֹת אֶת הַבַּיִת. אָז הִתְחִיל לְשַׁבֵּחַ אוֹתָהּ וְאָמַר, יְרוּשָׁלַיִם הַבְּנוּיָה כְּעִיר שֶׁחֻבְּרָה לָּהּ יַחְדָּו."],[8,"","שָׁנִינוּ, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא יְרוּשָׁלַיִם לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, וְזוֹ מְתֻקֶּנֶת (זו) כְּנֶגֶד זוֹ, שֶׁכָּתוּב (שמות טו) מָכוֹן לְשִׁבְתְּךְ פָּעַלְתָּ ה'. הַבְּנוּיָה, שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹרִיד אֶת יְרוּשָׁלַיִם שֶׁלְּמַעְלָה כָּרָאוּי, וּמִשּׁוּם כָּךְ הַבְּנוּיָה. שֶׁחֻבְּרָהּ לָּהּ יַחְדָּו, וַהֲרֵי בֵּאֲרוּהָ, שֶׁחֻבְּרָה? הָיָה צָרִיךְ לִהְיוֹת שֶׁחִבְּרוּ! אֶלָּא שֶׁהִתְחַבְּרָה הָאֵם עִם הַבַּת וְנִהְיוּ יַחַד, וּבֵאֲרוּהוּ."],[9,"","וְנֶאֱמַר שֶׁשָּׁם עָלוּ שְׁבָטִים, אֵלּוּ הֵם קִיּוּם שֶׁל הָעוֹלָם וְהַתִּקּוּן שֶׁל הָעוֹלָם הַתַּחְתּוֹן. וְאַל תֹּאמַר שֶׁהָעוֹלָם הַתַּחְתּוֹן לְבַדּוֹ, אֶלָּא אֲפִלּוּ שֶׁל הָעוֹלָם הָעֶלְיוֹן, שֶׁכָּתוּב שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל, דַּוְקָא לְיִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם הַקִּיּוּם לְמַטָּה, עֵדוּת הֵם לְמַעְלָה, וְהַכֹּל - לְהוֹדוֹת לְשֵׁם ה', לְהוֹדוֹת לְשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא לְכָל הַצְּדָדִים, שֶׁכָּתוּב לְהוֹדוֹת לְשֵׁם ה'."]]],[["וַיִּמְצָאֵהוּ אִישׁ וְהִנֵּה תֹעֶה בַּשָּׂדֶה וַיִּשְׁאָלֵהוּ הָאִישׁ לֵאמֹר מַה תְּבַקֵּשׁ. מַה כְּתִיב לְעֵילָא, וַיֹּאמֶר יִשְׂרָאֵל אֶל יוֹסֵף הֲלוֹא אַחֶיךָ רֹעִים בִּשְׁכֶם לְכָה וְאֶשְׁלָחֲךָ אֲלֵיהֶם. וְכִי יַעֲקֹב שְׁלֵימָא דְּהֲוָה רָחִים לֵיהּ לְיוֹסֵף מִכָּל בְּנוֹי, וְהֲוָה יָדַע דְּכָל אֲחוּי הֲווּ סָנְאִין לֵיהּ, אַמַּאי שַׁדַּר לֵיהּ לְגַבַּיְיהוּ. אֶלָּא אִיהוּ לָא חָשִׁיד עֲלַיְיהוּ, דְּהֲוָה יָדַע דְּכֻלְּהוּ הֲווּ זַכָּאִין, וְלָא חָשִׁיד לוֹן. אֶלָּא גָּרִים קוּדְשָׁא בְּרִיךְ הוּא כָּל דָּא, בְּגִין לְקַיְימָא גְּזֵרָה דְּגָזַר בֵּין הַבְּתָרִים.","אַשְׁכַּחְנָא בְּסִפְרֵי קַדְמָאי, דְּבָעְיָין אִלֵּין בְּנֵי יַעֲקֹב לְשַׁלְּטָאָה עֲלוֹי עַד לָא יֵחוֹת לְמִצְרַיִם. דְּאִילּוּ הוּא יֵחוֹת לְמִצְרַיִם, וְאִינוּן לָא שָׁלְטוּ בֵּיהּ בְּקַדְמִיתָא. יָכְלֵי מִצְרָאִי לְשַׁלְּטָאָה לְעָלְמִין עֲלַיְיהוּ דְּיִשְׂרָאֵל, וְאִתְקַיְימָא בֵּיהּ בְּיוֹסֵף דְּאִזְדַּבַּן לְעַבְדָא וְאִינוּן שָׁלְטוּ עֲלוֹי. וְאַף עַל גַּב דְּיוֹסֵף הֲוָה מַלְכָּא לְבָתַר, וּמִצְרָאֵי הֲווּ עָבְדִין לֵיהּ, אִשְׁתַּכָּחוּ יִשְׂרָאֵל דְּשָׁלְטוּ עַל כֻּלְּהוּ.","תָּא חֲזֵי, דְּיוֹסֵף דְּאִיהוּ בְּרִית עִלָאָה, כָּל זִמְנָא דְּאִתְקְיַּים בְּרִית, שְׁכִינְתָּא אִתְקְיַּים בַּהֲדַיְיהוּ דְיִשְׂרָאֵל בִּשְׁלָם כְּדְקָא יְאוּת, כֵּיוָן דְּאִסְתַּלַּק יוֹסֵף בְּרִית עִלָּאָה מֵעַלְמָא, כְּדֵין בְּרִית שְׁכִינְתָּא וְיִשְׂרָאֵל כֻּלְּהוּ בְּגָלוּתָא נָפְקוּ, וְהָא אוֹקִימְנָא דִּכְתִיב (שמות א׳:ח׳) וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרַיִם אֲשֶׁר לא יָדַע אֶת יוֹסֵף. וְכֹלָּא הֲוָה מֵעִם קוּדְשָׁא בְּרִיךְ הוּא כְּדְקָא יְאוּת.","תָּא חֲזֵי, וַיִּמְצָאֵהוּ אִישׁ דָּא גַּבְרִיאֵ\"ל, וְאוּקְמוּהָ. כְּתִיב הָכָא וַיִּמְצָאֵהוּ אִישׁ, וּכְתִיב הָתָם (דניאל ט׳:כ״א) וְהָאִישׁ גַּבְרִיאֵל אֲשֶׁר רָאִיתִי בֶחָזוֹן בַּתְּחִלָּה. וְהִנֵּה תוֹעֶה, בְּכֹלָּא תּוֹעֶה, דְּאַבְטַח עַל אֲחוּי דְּהֲוָה מִתְבַּע אַחְוָה דִלְהוֹן וְלָא אַשְׁכַּח, וְתָבַע לְהוּ וְלָא אַשְׁכַּח. וְעַל דָּא תוֹעֶה בְּכֹלָּא, וְעַל דָּא וַיִּשְׁאָלֵהוּ הָאִישׁ לֵאמֹר מַה תְּבַקֵּשׁ:","וַיֹּאמֶר אֶת אַחַי אָנֹכִי מְבַקֵּשׁ וְגו'. וַיֹּאמֶר הָאִישׁ נָסְעוּ מִזֶּה וְגו', רִבִּי יְהוּדָה פָּתַח, (שיר השירים ח׳:א׳) מִי יִתֶּנְךָ כְּאָח לִי יוֹנֵק שְׁדֵי אִמִּי אֶמְצָאֲךָ בַחוּץ אֶשָׁקְךָ גַּם לֹא יָבוֹזוּ לִי. הַאי קְרָא אוּקְמוּהָ חַבְרַיָיא, אֲבָל הַאי קְרָא כְּנֶסֶת יִשְׂרָאֵל אֲמָרוֹ לְמַלְכָּא דִּשְׁלָמָא דִילֵיהּ. מִי יִתֶּנְךָ כְּאָח לִי, כְּיוֹסֵף עַל אֲחוּי, דְּאָמַר, (בראשית נ׳:כ״א) וְעַתָּה אַל תִּירָאוּ אָנֹכִי אֲכַלְכֵּל אֶתְכֶם וְאֶת טַפְּכֶם. יָהַב לוֹן מְזוֹנָא וְזָן לְהוּ בְּכַפְנָא. בְּגִין כָּךְ מִי יִתֶּנְךָ כְּאָח לִי.","דָּבָר אַחֵר מִי יִתֶּנְךָ כְּאָח לִי, דָּא יוֹסֵף, לְגַבָּהּ דִּשְׁכִינְתָּא דְּאִתְאַחַד עִמָּהּ וְאִתְדָּבַּק בַּהֲדָהּ. יוֹנֵק שְׁדֵי אִמִּי, דְּהָא כְּדֵין אַחְוָה וּשְׁלִימוּ בַּהֲדַיְיהוּ. אֶמְצָאֲךָ בַּחוּץ, גּוֹ גָּלוּתָא, דְּאִיהוּ בְּאַרְעָא אָחֳרָא. אֶשָׁקְךָ, בְּגִין לְאִתְדַּבְּקָא רוּחָא בְּרוּחָא. גַּם לא יָבוֹזוּ לִי, אַף עַל גַּב דְּאֲנָא בְּאַרְעָא אָחֳרָא.","תָּא חֲזֵי, דְּיוֹסֵף אַף עַל גַּב דְּאֲחוֹי לָא הֲווּ לֵיהּ כְּאַחִין כַּד נָפַל בִּידַיְיהוּ. אִיהוּ הֲוָה לוֹן כְּאַחָא כַּד נָפְלוּ בִּידֵיהּ, וְהָא אוּקְמוּהָ. דִּכְתִיב, (בראשית נ׳:כ״א) וַיְנַחֵם אוֹתָם וַיְדַבֵּר עַל לִבָּם, בְּכֹלָּא דִּבֶּר עַל לִבַּיְיהוּ.","וְתָא חֲזֵי, מַה כְּתִיב וַיֹּאמְרוּ אִישׁ אֶל אָחִיו, דָּא שִׁמְעוֹן וְלֵוִי דְּאִינוּן הֲווּ אַחִין וַדַּאי בְּכֹלָּא, בְּגִין דְּקָא אָתוּ מִסִּטְרָא דְדִינָא קַשְׁיָא. וּבְגִין כָּךְ רוּגְזָא דִלְהוֹן, אִיהוּ רוּגְזָא דִּקְטָלָא בְּעַלְמָא. כְּמָה דְאַתְּ אָמֵר (בראשית מ״ט:ז׳) אָרוּר אַפָּם כִּי עָז וְעֶבְרָתָם כִּי קָשָׁתָה.","תָּא חֲזֵי, רָזָא דְמִלָּה, אִית רוּגְזָא וְאִית רוּגְזָא. אִית רוּגְזָא דְּאִיהוּ מְבָרְכָא מֵעֵילָא וּמִתַּתָּא, וְאִקְרֵי בָּרוּךְ, כְּמָה דְאִתְּמָר דִּכְתִיב (בראשית י״ד:י״ט) בָּרוּךְ אַבְרָם לְאֵל עֶלְיוֹן קוֹנִה שָׁמַיִם וָאָרֶץ וְהָא אוּקְמוּהָ. וְאִית רוּגְזָא דְּאִיהִי אִתְלַטְיָא לְעֵילָא וְתַתָּא, כְּמָה דְאִתְּמָר דְּאִקְרֵי אָרוּר. דִּכְתִיב, (בראשית ג׳:י״ד) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וּמִכָּל חַיַּת הַשָּׂדֶה. אָרוּר אַפָּם כִּי עָז.","וְעַל רָזָא דָא אִית תְּרֵין טוּרִין דִּכְתִיב, (דברים י״א:כ״ט) וְנָתַתָּ אֶת הַבְּרָכָה עַל הַר גְּרִיזִים וְאֶת הַקְּלָלָה עַל הַר עֵיבָל, לָקֳבֵיל אִלֵּין תְּרֵין דַּרְגִּין. וְעַל דָּא, דָּא אִקְרֵי אָרוּר, וְדָא אִקְרֵי בָּרוּךְ. וְשִׁמְעוֹן וְלֵוִי אִינוּן מִסִּטְרָא דְדִינָא קַשְׁיָא, וּמִן סִטְרָא דְדִינָא קַשְׁיָא תַּקִּיפָא, נָפְקַת רוּגְזָא דְאִתְלַטְיָא."],[[0,"וימצאהו איש וגו':","מה כתוב למעלה, ויאמר ישראל וגו' לכה ואשלחך אליהם. ושואל, וכי יעקב השלם, שאהב את יוסף מכל בניו, והיה יודע שכל אחיו שונאים אותו, למה שלח אותו אליהם. ומשיב, אלא, הוא לא חשד אותם, שהיה יודע שכולם הם צדיקים ולא חשד אותם, אלא הקב\"ה סבב כל זה, כדי לקיים הגזירה שגזר לאברהם אבינו בין הבתרים."],[1,"אשכחנא בספרי וכו':","מצאתי בספרי הראשונים, שצריכים היו בני יעקב למשול על יוסף טרם שירד למצרים, שאלו ירד למצרים והם לא היו שולטים עליו מתחילה, יכלו המצרים לשלוט לעולם על ישראל, ולא יכלו לצאת משם. ע\"כ, נתקיים ביוסף, שנמכר להיות עבד על ידי אחיו, והם שלטו עליו למכרו לעבד, לכן, אע\"פ שיוסף היה אחר כך מלך, שהמצרים המליכוהו, נמצאים ישראל שכבר שלטו על כולם. כי מאחר שכבר שלטו על מלכם יוסף למכרו לעבד, מכל שכן ששלטו אז על המצרים עצמם, ובזה נחלש כחם של המצרים, ויכלו להשתחרר מהם."],[2,"ת\"ח דיוסף וכו':","בוא וראה, יוסף שהיה ברית עליון, דהיינו יסוד דז\"א, כל זמן שהברית שהוא יוסף היה קיים, השכינה נתקיימת בישראל בשלום כראוי, כיון שנסתלק יוסף ברית העליון, מן העולם, כי נמכר לעבד, אז הברית והשכינה וישראל יצאו כולם בגלות. וכן בארוה, שכתוב, ויקם מלך חדש על מצרים אשר לא ידע את יוסף, שזה יורה שנתבטל מעלתו ויצא לגלות, והכל היה מן הקב\"ה כמו שהיה ראוי להיות."],[3,"ת\"ח, וימצאהו איש:","זהו גבריאל. ובארוה, כתוב כאן וימצאהו \u0003איש,\u0004 וכתוב שם, \u0003והאיש\u0004 גבריאל וגו', ולמדים גזירה שוה, שאף \u0003איש\u0004 הנאמר כאן הוא גבריאל. \u0003והנה תועה\u0004, בכל היה תועה: שבטח על אחיו והיה מבקש האחוה מהם ולא מצא. גם בקש אותם עצמם ולא מצא. וע\"כ בכל היה תועה. וע\"כ וישאלהו האיש לאמר מה תבקש."],[4,"ויאמר את אחי וגו' נסעו מזה וגו':","ר' יהודה פתח, מי יתנך כאח לי וגו'. מקרא זה בארוהו החברים. אבל מקרא זה, כנסת ישראל, שהיא הנוקבא, אמרה אותו אל המלך שהשלום שלו, שהוא ז\"א. \u0003מי יתנך כאח לי,\u0004 היינו כמו יוסף על אחיו, שאמר, ועתה אל תיראו וגו' שנתן להם מזונות וזן אותם בימי רעב. משום זה, אמרה כנסת ישראל לז\"א, מי יתנך כאח לי, דהיינו כמו יוסף לאחיו."],[5,"ד\"א, מי יתנך כאח לי:","זה אמר יוסף שהוא יסוד, אל השכינה, שנתאחד עמה ונתדבק בה. \u0003יונק שדי אמי,\u0004 כי אז, כשמקבלת מוחין דאמא, יש אחוה ושלימות ביניהם. \u0003אמצאך בחוץ,\u0004 בתוך הגלות, שהיא בארץ אחרת, \u0003אשקך\u0004, כדי להתדבק רוח שלה ברוח שלו. \u0003גם לא יבוזו לי,\u0004 אף על פי שאני בארץ אחרת."],[6,"תא חזי דיוסף וכו':","בוא וראה, שיוסף, אע\"פ, שאחיו לא היו לו כאחים כשנפל בידיהם, הוא היה להם כאח כשנפלו בידו, ובארוה, שכתוב, וינחם אותם וידבר על לבם, בכל הצדדים דבר על לבם, עד שהאמינו לו."],[7,"ותא חזי מה וכו':","ובוא וראה מה כתוב, \u0003ויאמרו איש אל אחיו\u0004, זהו שמעון ולוי, שהם היו אחים ודאי בכל דבר, משום שבאו מצד הדין הקשה, ומשום זה הכעס שלהם הוא כעס של רציחה בעולם, כמש\"א, ארור אפם כי עז ועברתם כי קשתה."],[8,"ת\"ח רזא דמלה וכו':","בוא וראה סוד הדבר, יש כעס ויש כעס: יש כעס שהוא מבורך מלמעלה ומלמטה, ונקרא ברוך, כמו שלמדנו, שכתוב, ברוך אברם לאל עליון קונה שמים וארץ וכבר בארוה, כי אע\"פ שאברהם עשה מלחמה והרג אנשים, מכל מקום נאמר עליו במעשה זו ברוך אברם וגו', משום שקדש שם שמים בזה. ויש כעס שהוא מקולל למעלה ולמטה, כמו שלמדנו שנקרא \u0003ארור,\u0004 שכתוב, ארור אתה מכל הבהמה וגו'. ארור אפם כי עז וגו'."],[9,"ועל רזא דא אית וכו':","ועל סוד הזה יש ב' הרים, שכתוב, ונתת את הברכה על הר גריזים ואת הקללה על הר עיבל, שהם כנגד אלו ב' המדרגות שאחת נק' ברוך, ואחת נקראת ארור כנ\"ל, ועל כן גם ב' ההרים זה נקרא ארור, וזה נקרא ברוך. ושמעון ולוי הם מצד דין הקשה, ומן צד דין הקשה והחזק יוצא הכעס שנתקלל, הנקרא ארור כנ\"ל."]],[[0,"","וַיִּמְצָאֵהוּ אִישׁ וְהִנֵּה תֹעֶה בַּשָּׂדֶה וַיִּשְׁאָלֵהוּ הָאִישׁ לֵאמֹר מַה תְּבַקֵּשׁ. מַה כָּתוּב לְמַעְלָה? וַיֹּאמֶר יִשְׂרָאֵל אֶל יוֹסֵף הֲלוֹא אַחֶיךְ רֹעִים בִּשְׁכֶם לְכָה וְאֶשְׁלָחֲךְ אֲלֵיהֶם. וְכִי יַעֲקֹב הַשָּׁלֵם, שֶׁהָיָה אוֹהֵב אֶת יוֹסֵף מִכָּל בָּנָיו וְהָיָה יוֹדֵעַ שֶׁכָּל אֶחָיו הָיוּ שׂוֹנְאִים אוֹתוֹ, לָמָּה שָׁלַח אוֹתוֹ אֲלֵיהֶם? אֶלָּא הוּא לֹא חָשַׁד עֲלֵיהֶם, שֶׁהָיָה יוֹדֵעַ שֶׁכֻּלָּם הָיוּ צַדִּיקִים וְלֹא חָשַׁד אוֹתָם, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא גָּרַם אֶת כָּל זֶה כְּדֵי לְקַיֵּם אֶת הַגְּזֵרָה שֶׁגָּזַר בֵּין הַבְּתָרִים."],[1,"","מָצָאנוּ בְּסִפְרֵי הַקַּדְמוֹנִים, שֶׁצְּרִיכִים בְּנֵי יַעֲקֹב הַלָּלוּ לִשְׁלֹט עָלָיו בְּטֶרֶם יֵרֵד לְמִצְרַיִם, שֶׁאִלּוּ הוּה יָרַד לְמִצְרַיִם וְהֵם לֹא הָיוּ שׁוֹלְטִים בּוֹ בָּרִאשׁוֹנָה, יָכְלוּ הַמִּצְרִים לִשְׁלֹט עַל יִשְׂרָאֵל לְעוֹלָמִים, וְהִתְקַיֵּם בְּיוֹסֵף שֶׁנִּמְכַּר לְעֶבֶד, וְהֵם שָׁלְטוּ עָלָיו, וְאַף עַל גַּב שֶׁיּוֹסֵף הָיָה אַחַר כָּךְ מֶלֶךְ וְהַמִּצְרִים הָיוּ עֲבָדִים שֶׁלּוֹ, נִמְצְאוּ יִשְׂרָאֵל שֶׁשָּׁלְטוּ עַל כֻּלָּם."],[2,"","בֹּא רְאֵה שֶׁיּוֹסֵף הוּא הַבְּרִית הָעֶלְיוֹנָה, כָּל זְמַן שֶׁמִּתְקַיֵּם הַבְּרִית, הַשְּׁכִינָה מִתְקַיֶּמֶת עִם יִשְׂרָאֵל בְּשָׁלוֹם כָּרָאוּי. כֵּיוָן שֶׁהִסְתַּלֵּק יוֹסֵף, הַבְּרִית הָעֶלְיוֹנָה, מִן הָעוֹלָם, אָז הַבְּרִית וְהַשְּׁכִינָה וְיִשְׂרָאֵל יָצְאוּ כֻלָּם לַגָּלוּת, וְהִנֵּה בֵּאַרְנוּ שֶׁכָּתוּב (שמות א) וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרַיִם אֲשֶׁר לֹא יָדַע אֶת יוֹסֵף, וְהַכֹּל הָיָה מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא כָּרָאוּי."],[3,"","בֹּא רְאֵה, וַיִּמְצָאֵהוּ אִישׁ - זֶה גַבְרִיאֵל. וּפֵרְשׁוּהוּ, כָּתוּב כָּאן וַיִּמְצָאֵהוּ אִישׁ, וְכָתוּב שָׁם (דניאל ט) וְהָאִישׁ גַּבְרִיאֵל אֲשֶׁר רָאִיתִי בֶחָזוֹן בַּתְּחִלָּה. וְהִנֵּה תֹעֶה - תּוֹעֶה בַּכֹּל, שֶׁבָּטַח עַל אֶחָיו שֶׁהָיָה מְבַקֵּשׁ אֶת הָאַחֲוָה שֶׁלָּהֶם וְלֹא מָצָא, וּבִקֵּשׁ אוֹתָם וְלֹא מָצָא, וְעַל כֵּן תּוֹעֶה בַּכֹּל. וְעַל זֶה, וַיִּשְׁאָלֵהוּ הָאִישׁ לֵאמֹר מַה תְּבַקֵּשׁ."],[4,"","וַיֹּאמֶר אֶת אַחַי אָנֹכִי מְבַקֵּשׁ וְגוֹ'. וַיֹּאמֶר הָאִישׁ נָסְעוּ מִזֶּה וְגוֹ'. רַבִּי יְהוּדָה פָּתַח (שיר ח) מִי יִתֶּנְךְ כְּאָח לִי יוֹנֵק שְׁדֵי אִמִּי אֶמְצָאֲךְ בַחוּץ אֶשָּׁקְךְ גַּם לֹא יָבֻזוּ לִי. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּ הַחֲבֵרִים, אֲבָל אֶת הַפָּסוּק הַזֶּה אָמְרָה כְּנֶסֶת יִשְׂרָאֵל לַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ, מִי יִתֶּנְךְ כְּאָח לִי, כְּיוֹסֵף עַל אֶחָיו, שֶׁאָמַר וְעַתָּה אַל תִּירָאוּ אָנֹכִי אֲכַלְכֵּל אֶתְכֶם וְאֶת טַפְּכֶם. נָתַן לָהֶם מָזוֹן וְזָן אוֹתָם בָּרָעָב. מִשּׁוּם כָּךְ, מִי יִתֶּנְךְ כְּאָח לִי."],[5,"","דָּבָר אַחֵר מִי יִתֶּנְךְ כְּאָח לִי - זֶה יוֹסֵף, אֶל הַשְּׁכִינָה, שֶׁנֶּאֱחַז עִמָּהּ וְנִדְבַּק עִמָּהּ. יוֹנֵק שְׁדֵי אִמִּי - שֶׁהֲרֵי אָז אַחֲוָה וּשְׁלֵמָה עִמָּהֶם. אֶמְצָאֲךְ בַחוּץ - בְּתוֹךְ הַגָּלוּת, שֶׁהִיא בְּאֶרֶץ אַחֶרֶת. אֶשָּׁקְךְ - כְּדֵי לְהַדְבִּיק רוּחַ עִם רוּחַ. גַּם לֹא יָבֻזוּ לִי - אַף עַל גַּב שֶׁאֲנִי נִמְצֵאת בְּאֶרֶץ אַחֶרֶת"],[6,"","בֹּא רְאֵה שֶׁיּוֹסֵף, אַף עַל גַּב שֶׁאֶחָיו לֹא הָיוּ לוֹ כְּמוֹ אַחִים כְּשֶׁנָּפַל בִּידֵיהֶם, הוּא הָיָה לָהֶם כְּמוֹ אָח כְּשֶׁנָּפְלוּ בְיָדוֹ, וַהֲרֵי פֵּרְשׁוּהָ שֶׁכָּתוּב (בראשית נ) וַיְנַחֵם אוֹתָם וַיְדַבֵּר עַל לִבָּם, בַּכֹּל הוּא דִּבֵּר, עַל לִבָּם."],[7,"","וּבֹא וּרְאֵה מַה כָּתוּב, וַיֹּאמְרוּ אִישׁ אֶל אָחִיו. זֶה שִׁמְעוֹן וְלֵוִי שֶׁהֵם הָיוּ וַדַּאי אַחִים בַּכֹּל, מִשּׁוּם שֶׁבָּאוּ מִצַּד הַדִּין הַקָּשֶׁה, וּמִשּׁוּם כָּךְ רָגְזָם הוּא רֹגֶז שֶׁל הֶרֶג בָּעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (שם מט) אָרוּר אַפָּם כִּי עָז וְעֶבְרָתָם כִּי קָשָׁתָה"],[8,"","בֹּא רְאֵה אֶת סוֹד הַדָּבָר, יֵשׁ רֹגֶז וְיֵשׁ רֹגֶז. יֵשׁ רֹגֶז שֶׁהוּא מְבֹרָךְ מִמַּעְלָה וּמִמַּטָּה, וְנִקְרָא בָּרוּךְ, כְּמוֹ שֶׁנִּתְבָּאֵר שֶׁכָּתוּב (שם יד) בָּרוּךְ אַבְרָם לְאֵל עֶלְיוֹן קֹנֵה שָׁמַיִם וָאָרֶץ, וַהֲרֵי פֵּרְשׁוּהָ. וְיֵשׁ רֹגֶז מְקֻלָּל לְמַעְלָה וּמַטָּה, כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁנִּקְרָא אָרוּר, שֶׁכָּתוּב (שם ג) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וּמִכֹּל חַיַּת הַשָּׂדֶה. אָרוּר אַפָּם כִּי עָז."],[9,"","וְעַל הַסּוֹד הַזֶּה יֵשׁ שְׁנֵי הָרִים, שֶׁכָּתוּב (דברים יא) וְנָתַתָּה אֶת הַבְּרָכָה עַל הַר גְּרִזִּים וְאֶת הַקְּלָלָה עַל הַר עֵיבָל, כְּנֶגֶד שְׁתֵּי הַדְּרָגוֹת הַלָּלוּ. וְעַל כֵּן זֶה נִקְרָא אָרוּר וְזֶה נִקְרָא בָּרוּךְ. וְשִׁמְעוֹן וְלֵוִי הֵם מִצַּד הַדִּין הַקָּשֶׁה, וּמִצַּד הַדִּין הַקָּשֶׁה הֶחָזָק יוֹצֵא רֹגֶז שֶׁמְּקֵלָּל."]]],[["וְתָּא חֲזֵי, מִסִּטְרָא דְדִינָא קַשְׁיָא נָפְקֵי רוּגְזָא לִתְרֵי סִטְרִין, חַד דְּאִתְבָּרַךְ, וְחַד דְּאִתְלַטְיָא. חַד בָּרוּךְ וְחַד אָרוּר. כְּגַוְונָא דָא מִסִּטְרָא דְיִצְחָק נָפְקוּ תְּרֵין בְּנִין, חַד מְבוֹרָךְ, וְחַד דְּאִתְלַטְיָא לְעֵילָא וְתַתָּא. דָּא אִתְפָּרַשׁ לְסִטְרֵיהּ, וְדָא אִתְפָּרַשׁ לְסִטְרֵיהּ. דָּא דִּיּוּרֵיהּ בְּאַרְעָא קַדִּישָׁא, וְדָא דִּיּוּרֵיהּ בְּטוּרָא דְשֵׂעִיר. דִּכְתִיב, (בראשית כ״ה:כ״ז) אִישׁ יוֹדֵעַ צַיִד אִישׁ שָׂדֶה. דָּא אַתְרֵיהּ בְּאֲתַר דְּמִדְבָּרָא וְחָרְבָא וּשְׁמָמָה, וְדָא יוֹשֵׁב אֹהָלִים. וְכֹלָּא כְּגַוְונָא דְאִצְטְרִיךְ.","וּבְגִין כָּךְ תְּרֵין דַּרְגִּין אִינוּן, בָּרוּךְ וְאָרוּר, דָּא לְסִטְרֵיהּ וְדָא לְסִטְרֵיהּ. מֵהַאי נָפְקִין כָּל בִּרְכָאן דְּעָלְמִין לְעֵילָא וְתַתָּא וְכָל טִיבוּ וְכָל נְהִירוּ וְכָל פּוּרְקָן וְכָל שֵׁזָבוּתָא. וּמֵהַאי נָפְקִין כָּל לְוָוטִין וְכָל חַרְבָּא וְכָל דָּמָא וְכָל שְׁמָמָא וְכָל בִּישִׁין וְכָל מְסָאֲבוּ דְעָלְמָא.","רִבִּי שִׁמְעוֹן פָּתַח וְאֲמַר, (תהילים כ״ו:ו׳) אֶרְחַץ בְּנִקָּיוֹן כַּפָּי וַאֲסוֹבְבָה אֶת מִזְבַּחֲךָ יְיָ, הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי, רָזָא דְמִלָּה הָכָא, דְּהָא לֵית לָךְ בַּר נָשׁ בְּעַלְמָא דְּלָא טָעִים טַעְמָא דְמוֹתָא בְּלֵילְיָא, וְרוּחַ מְסָאֲבָא שַׁרְיָא עַל הַהוּא גוּפָא. מַאי טַעְמָא, בְּגִין דְּנִשְׁמָתָא קַדִּישָׁא אִסְתַּלְּקַת מִנֵּיהּ דְּבַר נָשׁ, וְנָפְקַת מִנֵּיהּ. וְעַל דְּנִשְׁמָתָא קַדִּישָׁא נָפְקַת וְאִסְתַּלְּקַת מִנִּיהּ, שַׁרְיָא רוּחָא מְסָאֲבָא עַל הַהוּא גוּפָא וְאִסְתָּאַב.","וְכַד נִשְׁמָתָא אִתְהַדְּרַת לְגוּפָא, אִתְעֲבַר הַהוּא זוּהֲמָא. וְהָא אִתְּמָר דִּידוֹי דְּבַר נָשׁ זוּהֲמָא דִמְסָאֲבוּ אִשְׁתָּאַר בְּהוּ. וְעַל דָּא לָא יַעֲבָר יְדוֹי עַל עֵינוֹי, בְּגִין דְּהַהוּא רוּחַ מְסָאֲבָא שַׁרְיא עֲלוֹי, עַד דְּנָטִיל לוֹן. וְכַד נָטִיל יְדוֹי כְּדְקָא חָזֵי, כְּדֵין אִתְק3ַדּשׁ וְאִקְרֵי קָדוֹשׁ.","וְהֵיךָ בָּעֵי לְאִתְקַדְּשָׁא. בָּעֵי חַד כְּלִי לְתַתָּא וְחַד כְּלִי מִלְּעֵילָא, בְּגִין דְּיִתְקַדַּשׁ מֵהַהוּא דִלְעֵילָא. וְהַהוּא דִלְתַתָּא דְּיָתִיב בְּזוּהֲמָא דִּמְסָאֲבוּ בֵּיהּ. וְדָא כְּלִי לְקַבְּלָא מְסָאֲבוּ, וְדָא לְאִתְקַדְּשָׁא מִנֵּיהּ, דָּא בָּרוּךְ וְדָא אָרוּר. וְלָא בָּעְיָין אִינוּן מַיִין דְּזוּהֲמָא לְאוֹשְׁדָא לוֹן בְּבֵיתָא, דְּלָא יִקְרַב בְּהוּ בַּר נָשׁ. דְּהָא בְּהוּ מִתְכַּנְּשֵׁי סִטְרָא דִלְהוֹן, יָכִיל לְקַבְּלָא נִזְקָא מֵאִינוּן מַיִין מְסָאֲבִין.","וְעַד דְּיִתְעֲבַר זוּהֲמָא מִן יְדוֹי לָא יְבָרֵךְ, וְאוֹקִימְנָא. וּבְגִין כָּךְ, בַּר נָשׁ עַד לָא יְקַדֵּשׁ יְדוֹי בְּצַפְרָא, אִקְרֵי טָמֵא. כֵּיוָן דְּאִתְקַדַּשׁ אִקְרֵי טָהוֹר. וּבְגִין כָּךְ לָא יִטּוֹל אֶלָּא מִן יְדָא דְּאִדְכֵּי בְּקַדְמִיתָא. דִּכְתִיב, (במדבר י״ט:י״ט) וְהִזָּה הַטָּהוֹר עַל הַטָּמֵא. דָּא אִקְרֵי טָהוֹר, וְדָא אִקְרֵי טָמֵא.","בְּגִין כָּךְ חַד כְּלִי לְעֵילָא וְחַד כְּלִי לְתַתָּא, דָּא קַדִּישָׁא וְדָא מְסָאֲבָא. וּמֵאִינוּן מַיִין אָסִיר לְמֶעְבַּד בְּהוּ מִידִי, אֶלָּא בָּעֵי לְאוֹשְׁדָא לוֹן בְּאֲתַר דִּבְנֵי נָשָׁא לָא עָבְרִין עֲלַיְיהוּ, וְלָא יָבִית לוֹן בְּבֵיתָא. דְּהָא כֵּיוָן דְּאִתּוֹשְׁדָן בְּאַרְעָא, רוּחָא מְסָאֲבָא אִשְׁתַּכַּח תַּמָּן וְיָכִיל לְנַזְקָא. וְאִי חָפַר לוֹן מִדְרוֹן תְּחוֹת אַרְעָא דְּלָא יִתְחֲזוּן שַׁפִּיר.","וְלָא יָהִיב לוֹן לִנְשֵׁי חֳרָשַׁיָא דְּיִכְלוּן לְאַבְאָשָׁא בְּהוּ לִבְנִי נָשָׁא. בְּגִין דְּאִינוּן מַיִין דְּאִתְלַטְיָין, וְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְדַכָּאָה לוֹן לְיִשְׂרָאֵל וּלְמֶהֱוֵי קַדִּישִׁין. דִּכְתִיב, (יחזקאל ל״ו:כ״ה) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם מִכֹּל טֻמְאוֹתֵיכֶם וּמִכָּל גִּלּוּלֵיכֶם אֲטַהֵר אֶתְכֶם:","וַיִּקָּחֻהוּ וַיַּשְׁלִכוּ אֹתוֹ הַבֹּרָה וְהַבּוֹר רֵק אֵין בּוֹ מָיִם. רִבִּי יְהוּדָה פָּתַח וְאֲמַר, (תהילים י״ט:ח׳) תּוֹרַת יְיָ תְּמִימָה מְשִׁיבַת נָפֶשׁ (מאן דבטיל מילי דאורייתא כאילו חריב עלמא שלים). כַּמָּה אִית לוֹן לִבְנֵי נָשָׁא לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא לֶהוֵי לֵיהּ חַיִּים בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי, וְזָכֵי בִּתְרֵין עָלְמִין. וְאֲפִילּוּ מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא וְלָא יִשְׁתַּדַּל בָּהּ לִשְׁמָהּ כְּדְקָא יָאוֹת, זָכֵי לְאֲגַר טַב בְּעַלְמָא דֵין, וְלָא דָיְינִין לֵיהּ בְּהַהוּא עַלְמָא.","וְתָּא חֲזֵי, כְּתִיב, (משלי ג׳:ט״ז) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ עשֶׁר וְכָבוֹד. אֹרֶךְ יָמִים בְּהַהוּא דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא לִשְׁמָהּ, דְּאִית לֵיהּ אֹרֶךְ יָמִים בְּהַהוּא עַלְמָא דְּבֵיהּ אוֹרְכָא דְיוֹמִין. וְאִינוּן יוֹמִין אִינוּן יוֹמִין וַדַּאי, תַּמָּן אִיהוּ רָחֲצָנוּ דִקְדוּשָׁא דִלְעֵילָא דְּאִתְרְחִיץ בַּר נָשׁ בְּהַאי עַלְמָא לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, לְאִתְתַּקְּפָא בְּהַהוּא עַלְמָא בִּשְׂמֹאלָהּ עוֹשֶׁר וְכָבוֹד, אֲגַר טַב וְשַׁלְוָה אִית לֵיהּ בְּהַאי עַלְמָא."],[[0,"ותא חזי מסטרא וכו':","ובוא וראה, מצד דין הקשה יוצא הכעס לשני צדדים, אחד שנתברך ואחד שנתקלל, אחד ברוך ואחד ארור, כעין זה מצד יצחק יצאו שני בנים, אחד מבורך, ואחד שנתקלל למעלה ולמטה, זה נפרד לצד שלו, וזה נפרד לצד שלו, זה דירתו בארץ הקודש, וזה דירתו בהר שעיר. שכתוב, איש יודע ציד איש שדה, זה מקומו במקום מדבר וחורבן ושממה, וזה יושב אהלים. והכל כמו שצריך להיות."],[1,"ובג\"כ, תרין דרגין וכו':","ומשום זה, שתי מדרגות הן, ברוך וארור, זו אל הצד שלה וזו אל הצד שלה, מזו יוצאות כל הברכות שבעולם שלמעלה ושלמטה, וכל טוב, וכל הארה, וכל גאולה, וכל הצלה. ומזו יוצאות כל הקללות, וכל הרבה, וכל דם, וכל שממה, וכל רע, וכל הטומאות שבעולם."],[2,"ר\"ש פתח ואמר ארחץ בנקיון וגו':","מקרא זה בארוהו, אבל בוא וראה, סוד הדבר כאן, הוא, כי אין לך אדם בעולם שלא יטעם בלילה טעם מות, ורוח הטומאה שורה על גוף ההוא. מה הטעם, הוא משום שהנשמה הקדושה נסתלקה מן האדם ויצאה ממנו ומשום שהנשמה הקדושה נסתלקה ויצאה מן האדם, שורה רוח הטומאה על גוף ההוא, והוא נטמא."],[3,"וכד נשמתא אתהדרת וכו':","וכשהנשמה חוזרת אל הגוף, מסתלקת זוהמא ההוא, ולמדנו, שידיו של האדם, זוהמת הטומאה נשאר עליהם, וע\"כ לא יעביר ידיו על עיניו, כי רוח הטומאה שורה עליהם עד שרוחץ אותם, וכשנוטל ידיו כראוי, אז נתקדש ונקרא קדוש."],[4,"והיך בעי לאתקדשא וכו':","שואל, ואיך צריכים להתקדש בנטילת ידים. ואומר, צריכים שיהיה כלי אחד מלמטה, וכלי אחד מלמעלה, כדי שיתקדש מהכלי שלמעלה, והכלי שלמטה יושבת בזוהמא שטומאה בו, וזהו כלי לקבל הטומאה, דהיינו מי הרחיצה, וזהו שלמעלה, הוא כלי להתקדש ממנו, שממנו שופכים המים על הידים. זהו שלמעלה \u0003ברוך\u0004 וזהו שלמטה \u0003ארור.\u0004 ולא צריכים לשפוך אלו המים של זוהמא, בבית, כדי שלא יקרב אליהם אדם, כי בהם מתאספים הצד שלהם, שהם הרוחות המזיקים, והאדם יכול לקבל נזק מאלו מים הטמאים."],[5,"ועד דיתעבר וכו':","ועד שיעביר הזוהמא מידיו, לא יברך. ובארוה, ועל כן האדם, טרם שקדש ידיו בבוקר, נקרא טמא. כיון שקידש ידיו נקרא טהור, ומשום זה, לא יטול ידיו אלא מן יד שנטהר מקודם, שכתוב, והזה הטהור על הטמא, זה שכבר נטל ידיו נקרא טהור, וזה שעוד לא נטל ידיו נקרא טמא."],[6,"בגין כך חד כלי וכו':","משום זה כלי אחד למעלה וכלי אחד למטה, זה קדוש, וזה טמא. ומאלו המים אסור לעשות בהם דבר, אלא צריכים לשפוך אותם במקום שבני אדם לא יעברו עליהם. ולא ילין אותם בבית, כי כיון שנשפכו על הארץ, רוח הטומאה נמצא שמה, ויכול להזיק. ואם חפר להם מורד למתחת הארץ שלא יתראו, טוב הוא."],[7,"ולא יהיב לון וכו':","ולא יתן אותם לנשים מכשפות, שיכולות להזיק עמהם בני אדם, משום שהם מים המאררים, והקב\"ה רצה לטהר את ישראל, ושיהיו קדושים, שכתוב, וזרקתי עליכם מים טהורים וגו'."],[7,"","ביאור המאמר. כי יש ב' בחינות דין, א) הנעשה מכח עלית המלכות לבינה, שאז נופלים ממנה אתוון אל\"ה דאלקים, ונשארת משום זה בו\"ק בלי ראש. ב) הם הדינים הנמשכים מקו שמאל כל עוד שלא נכלל בקו ימין, שה\"ס הדינים של נקודת השורק, (כנ\"ל דף כ\"ה ד\"ה ואלו)."],[7,"","וזה אמרו (באות ק\"י) \u0003אית רוגזא דאיהו מברכא מעילא ומתתא,\u0004 רוגזא היינו דין, וה\"ס הדינים דבחינה א' הנ\"ל, הבאים מכח עלית המלכות לבינה, ודינים הללו הם מבורכים למעלה בבינה ולמטה בזו\"ן, כי לולא הדינים הללו לא היו מוחין לזו\"ן ולתחתונים, (כנ\"ל בראשית א' דף ז' ד\"ה וכבר, ע\"ש) \u0003ואקרי ברוך,\u0004 כי הוא מקור כל הברכות שבעולם דהיינו המוחין וכל מיני הארות כנ\"ל, והיינו בבינה עצמה, אבל כשהדינים ההם נמשכים לזו\"ן אינם נקראים \u0003ברוך\u0004 אלא \u0003מבורך\u0004 כמ\"ש להלן. \u0003דכתיב ברוך אברם\u0004 וכו'. כי ב' הקוין ימין ושמאל הם מבינה, וע\"כ הם נק' \u0003ברוך,\u0004 אצל אברהם, שהוא קו ימין. שבדינים הללו הכה המלכים. \u0003ואית רוגזא דאיהי אתלטיא לעילא ותתא,\u0004 שה\"ס הדינים הנ\"ל שבבחינה ב', הנמשכים משליטת קו השמאל שאינו נכלל בימין, והיא נתקללה, במיתה הנמשך מנחש הקדמוני, בסוד \u0003לא זכי הא רע,\u0004 שאם אינו זוכה, דהיינו שממשיך מקו שמאל ממעלה למטה, שזה היה החטא דעצה\"ד, אז מתגלה הנקודה דמנעולא, שה\"ס המלכות דצמצום א' במסך דבחי\"ד, שאינה ראויה לקבל אורות החיים וע\"כ האדם מת עם התגלותה, שז\"ס \u0003ביום אכלך ממנו\u0004 דהיינו שתמשיך הארת השמאל ממעלה למטה, \u0003מות תמות.\u0004 כי תתגלה נקודת המלכות דמדת הדין שבצמצום א', וכל אורות החיים יסתלקו, הרי שרוגזא זה, שהוא הדינים דהארת השמאל נתקללו בקללת נחש הקדמוני שנאמר עליו ארור אתה מכל הבהמה וגו' שסופו מיתה. ועל בחינה זו, שהיתה ג\"כ בשמעון ולוי, נאמר, ארור אפם כי עז, וע\"כ יש ברוגזא שלהם רציחה, דהיינו הריגת אנשי שכם, כי הוא \u0003רוגזא דאתלטיא,\u0004 המביא מיתה."],[7,"","וז\"ש \u0003מסטרא דדינא קשיא וכו', מסטרא דיצחק, נפקו תרין בנין, חד מבורך, וחד דאתלטיא וכו'.\u0004 יצחק ה\"ס קו שמאל דז\"א, ששליטתו בפני עצמו בלי ימין הוא דינא קשיא, וממנו יצאו שני בנים, שהם ב' בחינות רוגזא הנ\"ל, יעקב היא בחינה א', אבל מתוך שאינו בחינת בינה, כמו אברהם, אינו נקרא \u0003ברוך\u0004 אלא \u0003מבורך,\u0004 כנ\"ל. כי ה\"ס קו אמצעי דז\"א. ועשו ה\"ס הדינים דבחינה ב' הנ\"ל דאתלטיא."],[7,"","והנה בלילה, כשהאדם ישן, יש בו ג\"כ הדין דבחי\"ב הנ\"ל שהיא רוגזא דאתלטיא. כי הלילה ה\"ס שליטת קו שמאל, שע\"כ מסתלקים אז האורות, וע\"כ מסתלקת נשמתו של אדם. אמנם הסתלקות האורות הללו אינם מיתה ממש, כמו בגילוי נקודת המלכות דצמצום א' הנ\"ל, אלא נבחן לשינה, ועכ\"ז יש בו בחי' התכללות ממיתה ג\"כ, והוא מכח הקללה דעצה\"ד, אשר שליטת השמאל תגלה אותה נקודה הממיתה לאדם. וע\"כ יש בה ג\"כ אחד מששים ממיתה."],[7,"","וזה אמרו (באות קי\"ד) \u0003ועל דנשמתא קדישא נפקת ואסתלקת מניה,\u0004 דהיינו מכח שליטת השמאל בלי ימין, \u0003שריא רוחא מסאבא על ההוא גופא,\u0004 דהיינו טומאת נחש הקדמוני שסופו מיתה, \u0003וכד נשמתא אתהדרת לגופא, אתעבר ההוא זוהמא, והא אתמר דידוי דבר נש וכו',\u0004 פירוש. כי ידים של אדם ה\"ס הכלים של הג\"ר, שה\"ס חג\"ת הנעשים בעת גדלות לחב\"ד. ועם ביאת הנשמה בבקר, מקובלת רק בחינת ו\"ק אל הגוף, ולא ג\"ר, וע\"כ נבחן שהידים עוד לא נטהרו מזוהמתן שקבלו בלילה. \u0003וכד נטיל ידוי כדקא חזי,\u0004 דהיינו שהמשיך הג\"ר, \u0003אתקדש ואקרי קדוש,\u0004 כי מוחין דג\"ר נמשכים מאו\"א, הנקראים קדושים, וע\"כ נקרא גם האדם קדוש. שז\"ס שאו ידיכם קודש וגו'. \u0003טהרה,\u0004 נופל על שלמות הכלים, שמקודם לכן כשהיה המלכות כלולה בבינה, היה כח הצמצום שבמלכות מעורב בכל הכלים של הבינה, ולא היתה ראויה משום זה לג\"ר, ואח\"כ, שע\"י הארה עליונה שלמה, מורידה הבינה את כח הצמצום הזה למקומו, וג' אתוון אל\"ה חוזרים אליה, נבחן שהכלים שלה נטהרו מכח הצמצום וראוים לג\"ר. \u0003קדושה,\u0004 נופל על המוחין שמקבלת מאו\"א עלאין שהם נק' קודש."],[7,"","והורדת המלכות מן הבינה למקומה באה ע\"י הארה עליונה מן ע\"ב ס\"ג דא\"ק שאין צמצום ב' נוהג שם, וע\"כ הארתו בכל מקום שבאה מורידה משם כח המלכות והצמצום מן הבינה למקומה דהיינו למלכות. כמ\"ש לעיל (בהקדמת ספר הזהר דף כ\"ב ד\"ה ואגליף) כן אחר שנשלמו ונטהרו הכלים דבינה, הנה השפע שלה שלם ובכל מקום שהשפע שלה באה מורידה כח הצמצום מהכלים דבינה אשר שם, והם נעשים ג\"ר."],[7,"","וזה אמרו, \u0003והיך בעי לאתקדשא, בעי חד כלי\u0004 וכו', כי \u0003כלי העליון\u0004 ה\"ס בינה, אשר הכלים שלה כבר נטהרו מכח הצמצום של המלכות שנתערבה בה, \u0003המים\u0004 ה\"ס השפע השלם שבבינה זו הטהורה. \u0003והידים\u0004 של האדם, ה\"ס הכלים דחג\"ת שצריכים להטהר מכח הצמצום וזוהמת הנחש שקבלו בלילה בעת שינה. וכלי התחתון, ה\"ס המלכות הבלתי נמתקת בבינה, שהיא שבויה בקליפות דבי\"ע."],[7,"","ועל ידי המים מכלי העליון, שהם שפע מכלים הטהורים דבינה, הנשפכים על הידים, שהם כלים דחג\"ת, יורד משם כח הצמצום של המלכות שנתערב בהם, למקומו, דהיינו אל המלכות הבלתי נמתקת, שהיא כלי התחתון. ונמצא כל כח הצמצום והדינים יורדים לכלי התחתון והכלים דחג\"ת של האדם שהם הידים מטוהרים עתה מכל כח צמצום ודין וטומאה, ומקבלים מוחין שלמים דג\"ר הנקראים קדושה. והכלים דחג\"ת נעשים לחב\"ד, וז\"ש, \u0003ודא כלי לקבלא מסאבו ודא לאתקדשא מניה.\u0004 כי כח הורדת המלכות מבינה בא מכלי עליון, שעי\"ז מקבלים החג\"ת מוחין הנקראים קדושה. ומקום ירידת המלכות וכחות הצמצום והדין והטומאה היא כלי התחתון. וזהו שמסיים בסוד הכתוב, \u0003וזרקתי עליכם מים טהורים,\u0004 דהיינו שפע השלם הבא מכלים טהורים שכח הצמצום כבר הורד מהם, שבכל מקום בואו מוריד כח הצמצום מכלים דבינה אשר שם והם נטהרים, והיינו \u0003וטהרתם מכל טומאותיכם\u0004 וגו', כנ\"ל."],[8,"ויקחהו וגו' רק אין בו מים:","ר' יהודה פתח ואמר, תורת ה' תמימה משיבת נפש. כמה יש להם לבני אדם, להשתדל בתורה, כי כל מי שמשתדל בתורה יהיה לו חיים בעולם הזה ובעולם הבא, והוא זוכה בשני עולמות. ואפילו מי שמשתדל בתורה ואינו משתדל בה כראוי, הוא זוכה, לשכר טוב בעולם הזה, ואין דנים אותו בעולם האמת."],[9,"ותא חזי כתיב וכו':","ובוא וראה כתוב אורך ימים בימינה וגו'. \u0003ארך ימים\u0004 הוא לאותו המשתדל בתורה לשמה, שיש לו אורך ימים באותו העולם שבו אריכת ימים, דהיינו בעולם הנצחי. ואלו הימים שבו המה ימים בודאי, כלומר, שהמה טובים וכדאים לשמם, שם הוא בטחון הקדושה של מעלה, כלומר שכר המקווה. שהאדם בוטח בו בעולם הזה להשתדל בתורה כדי להיות מאושר בעולם ההוא הנצחי. \u0003בשמאלה עושר וכבוד:\u0004 שיש לו שכר טוב ושלוה בעולם הזה."]],[[0,"","וּבֹא וּרְאֵה, מִצַּד הַדִּין הַקָּשֶׁה יוֹצֵא רֹגֶז לִשְׁנֵי צְדָדִים - אֶחָד שֶׁהִתְבָּרֵךְ וְאֶחָד שֶׁהִתְקַלֵּל, אֶחָד בָּרוּךְ וְאֶחָד אָרוּר. כְּמוֹ כֵן מֵהַצַּד שֶׁל יִצְחָק יָצְאוּ שְׁנֵי בָנִים - אֶחָד מְבֹרָךְ, וְאֶחָד שֶׁהִתְקַלֵּל לְמַעְלָה וּלְמַטָּה. זֶה נִפְרַד לְצִדּוֹ וְזֶה נִפְרַד לְצִדּוֹ. זֶה דִּיּוּרוֹ בָּאָרֶץ הַקְּדוֹשָׁה, וְזֶה דִּיּוּרוֹ בְּהַר שֵׂעִיר, שֶׁכָּתוּב (בראשית כד) אִישׁ יֹדֵעַ צַיִד אִישׁ שָׂדֶה. זֶה מְקוֹמוֹ בְּמָקוֹם שֶׁל מִדְבָּר, חָרְבָּה וּשְׁמָמָה, וְזֶה יֹשֵׁב אֹהָלִים, וְהַכֹּל כְּמוֹ שֶׁצָּרִיךְ."],[1,"","וּמִשּׁוּם כָּךְ שְׁתֵּי דְרָגוֹת הֵן - בָּרוּךְ וְאָרוּר, זֶה לְצִדּוֹ וְזֶה לְצִדּוֹ. מִזֶּה יוֹצְאוֹת כָּל הַבְּרָכוֹת שֶׁל הָעוֹלָמוֹת לְמַעְלָה וּלְמַטָּה וְכָל הַטּוֹב וְכָל הָאוֹר וְכָל גְּאֻלָּה וְכָל הַצָּלָה, וּמִזֶּה יוֹצְאוֹת כָּל הַקְּלָלוֹת וְכָל חֶרֶב וְכָל דָּם וְכָל שְׁמָמָה וְכָל הָרָעוֹת וְכָל הַטֻּמְאָה שֶׁל הָעוֹלָם."],[2,"","רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (תהלים כו) אֶרְחַץ בְּנִקָּיוֹן כַּפָּי וַאֲסוֹבְבָה אֶת מִזְבַּחֲךְ ה'. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ. אֲבָל בֹּא רְאֵה כָּאן אֶת סוֹד הַדָּבָר, שֶׁהֲרֵי אֵין לְךְ אָדָם בָּעוֹלָם שֶׁאֵינוֹ טוֹעֵם אֶת טַעַם הַמָּוֶת בַּלַּיְלָה, וְרוּחַ הַטֻּמְאָה שׁוֹרָה עַל אוֹתוֹ הַגּוּף, מָה הַטַּעַם? מִשּׁוּם שֶׁהַנְּשָׁמָה הַקְּדוֹשָׁה מִסְתַּלֶּקֶת מִן הָאָדָם וְיוֹצֵאת מִמֶּנּוּ, וְעַל שֶׁהַנְּשָׁמָה הַקְּדוֹשָׁה יוֹצֵאת וּמִסְתַּלֶּקֶת מִמֶּנּוּ, שׁוֹרָה רוּחַ שֶׁל טֻמְאָה עַל אוֹתוֹ הַגּוּף וְנִטְמָא."],[3,"","כְּשֶׁהַנְּשָׁמָה חוֹזֶרֶת לַגּוּף, עוֹבֶרֶת אוֹתָהּ הַזֻּהֲמָה, וַהֲרֵי נִתְבָּאֵר שֶׁבִּידֵי הָאָדָם נִשְׁאֶרֶת זֻהֲמַת הַטֻּמְאָה, וְעַל כֵּן אַל יַעֲבִיר יָדוֹ עַל עֵינוֹ, מִשּׁוּם שֶׁאוֹתָהּ רוּחַ הַטֻּמְאָה שׁוֹרָה עָלָיו עַד שֶׁנּוֹטֵל אוֹתָם, וּכְשֶׁנּוֹטֵל יָדוֹ כָּרָאוּי, אָז מִתְקַדֵּשׁ וְנִקְרָא קָדוֹשׁ."],[4,"","וְאֵיךְ צָרִיךְ לְהִתְקַדֵּשׁ? צָרִיךְ כְּלִי אֶחָד לְמַטָּה וּכְלִי אֶחָד מִלְמַעְלָה, כְּדֵי שֶׁיִּתְקַדֵּשׁ מֵאוֹתוֹ שֶׁלְּמַעְלָה, וְאוֹתוֹ שֶׁלְּמַטָּה שֶׁיּוֹשֵׁב בַּזֻּהֲמָה שֶׁטֻּמְאָה בּוֹ. וְזֶה הַכְּלִי לְקַבֵּל טֻמְאָה, וְזֶה לְהִתְקַדֵּשׁ מִמֶּנּוּ. זֶה בָּרוּךְ וְזֶה אָרוּר. וְלֹא צָרִיךְ לִשְׁפֹּךְ בַּבַּית אֶת אוֹתָם מַיִם שֶׁל הַזֻּהֲמָה, שֶׁלֹּא יִקְרַב אֲלֵיהֶם אִישׁ, שֶׁהֲרֵי בָּהֶם מִתְכַּנְּסִים הַצַּד שֶׁלָּהֶם, וְיָכוֹל לְקַבֵּל נֵזֶק מֵאוֹתָם הַמַּיִם הַטְּמֵאִים."],[5,"","וְעַד שֶׁיַּעֲבֹר הַזֻּהֲמָה מִיָּדוֹ לֹא יְבָרֵךְ, וּבֵאַרְנוּ. וּמִשּׁוּם כָּךְ, בְּטֶרֶם יְקַדֵּשׁ הָאָדָם אֶת יָדָיו בַּבֹּקֶר, נִקְרָא טָמֵא. כֵּיוָן שֶׁהִתְקַדֵּשׁ, נִקְרָא טָהוֹר. וּמִשּׁוּם כָּךְ אַל יִטֹּל אֶלָּא מִיָּד שֶׁנִּטְהֲרָה בָּרִאשׁוֹנָה, שֶׁכָּתוּב (במדבר יט) וְהִזָּה הַטָּהוֹר עַל הַטָּמֵא. זֶה נִקְרָא טָהוֹר, וְזֶה נִקְרָא טָמֵא."],[6,"","מִשּׁוּם כָּךְ כְּלִי אֶחָד לְמַעְלָה וּכְלִי אֶחָד לְמַטָּה, זֶה קָדוֹשׁ וְזֶה טָמֵא. וְאָסוּר לַעֲשׂוֹת דָּבָר עִם אוֹתָם הַמַּיִם, אֶלָּא צָרִיךְ לִשְׁפֹּךְ אוֹתָם בְּמָקוֹם שֶׁאֲנָשִׁים לֹא עוֹבְרִים עֲלֵיהֶם וְלֹא יָלִין אוֹתָם בַּבַּיִת, שֶׁהֲרֵי כֵּיוָן שֶׁנִּשְׁפְּכוּ בָּאָרֶץ, רוּחַ הַטֻּמְאָה נִמְצֵאת שָׁם וִיכוֹלָה לְהַזִּיק. וְאִם חָפַר לָהֶם מִדְרוֹן תַּחַת הָאָרֶץ שֶׁלֹּא יֵרָאוּ - יָפֶה."],[7,"","וְלֹא יִתֵּן אוֹתָם לְנָשִׁים מְכַשְּׁפוֹת שֶׁיּוּכְלוּ לְהָרַע בָּהֶם לִבְנֵי אָדָם, מִשּׁוּם שֶׁאוֹתָם הַמַּיִם שֶׁהִתְקַלְּלוּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְטַהֵר אֶת יִשְׂרָאֵל שֶׁיִּהְיוּ קְדוֹשִׁים, שֶׁכָּתוּב (יחזקאל לו) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים מִכֹּל טֻמְאוֹתֵיכֶם וּמִכָּל גִּלּוּלֵיכֶם אֲטַהֵר אֶתְכֶם."],[8,"","וַיִּקָּחֻהוּ וַיַּשְׁלִכוּ אֹתוֹ הַבֹּרָה וְהַבּוֹר רֵק אֵין בּוֹ מָיִם. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים יט) תּוֹרַת ה' תְּמִימָה מְשִׁיבַת נָפֶשׁ. (מי שמבטל דברי תורה כאלו החריב עולם שלם) כַּמָּה יֵשׁ לִבְנֵי אָדָם לְהִשְׁתַּדֵּל בַּתּוֹרָה, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, יִהְיוּ לוֹ חַיִּים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא וְזוֹכֶה בִּשְׁנֵי עוֹלָמוֹת. וַאֲפִלּוּ מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וְלֹא מִשְׁתַּדֵּל בָּהּ לִשְׁמָהּ כָּרָאוּי, זוֹכֶה לְשָׂכָר טוֹב בָּעוֹלָם הַזֶּה, וְאֵין דָּנִים אוֹתוֹ בָּעוֹלָם הַהוּא."],[9,"","וּבֹא וּרְאֵה, כָּתוּב (משלי ג) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ עֹשֶׁר וְכָבוֹד. אֹרֶךְ יָמִים בְּאוֹתוֹ שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה לִשְׁמָהּ, שֶׁיֵּשׁ לוֹ אֹרֶךְ יָמִים בָּעוֹלָם הַהוּא שֶׁבּוֹ אֹרֶךְ הַיָּמִים, וְאוֹתָם הַיָּמִים הֵם וַדַּאי יָמִים, שָׁם הוּא בִּטְחוֹן הַקְּדֻשָּׁה שֶׁלְּמַעְלָה שֶׁבּוֹטֵחַ אָדָם בָּעוֹלָם הַזֶּה לְהִשְׁתַּדֵּל בַּתּוֹרָה, לְהִתְחַזֵּק בָּעוֹלָם הַהוּא, בִּשְׂמֹאלָהּ עֹשֶׁר וְכָבוֹד, יֵשׁ לוֹ שָׂכָר טוֹב וְשַׁלְוָה בָּעוֹלָם הַזֶּה."]]],[["וְכָל מַאן דְּיִשְׁתַּדַּל בְּאוֹרַיְיתָא לִשְׁמָהּ, כַּד נָפִיק מֵהַאי עַלְמָא, אוֹרַיְיתָא אָזְלָא קַמֵּיהּ וְאַכְרָזַת קַמֵּיהּ וְאֲגִינַת עֲלֵיהּ, דְּלָא יִקְרְבוּן בַּהֲדֵיהּ מָארֵיהוֹן דְּדִינָא. כַּד שָׁכִיב גּוּפָא בְּקִבְרָא, הִיא נָטְרַת לֵיהּ. כַּד נִשְׁמָתָא אָזְלָא לְאִסְתַּלְּקָא לְמֵיתַב לְאַתְרָהּ, אִיהִי אָזְלָא קַמָּהּ דְּהַהִיא נִשְׁמָתָא. וְכַמָּה תַּרְעִין אִתָּבְרוּ מִקַּמָּהּ דְּאוֹרַיְיתָא עַד דְּעָאלַת לְדוּכְתָּהּ. וְקָיְימָא עֲלֵיהּ דְּבַר נָשׁ עַד דְּיִתְעַר בְּזִמְנָא דִּיקוּמוּן מֵתַיָיא דְעַלְמָא, וְאִיהִי מַלְפָא סַנֵּיגוֹרָא עֲלֵיהּ.","הֲדָא הוּא דִכְתִיב, (משלי ו׳:כ״ב) בְּהִתְהַלֶּכְךָ תַּנְחֶה אֹתָךְ בְּשָׁכְבְּךָ תִּשְׁמֹר עָלֶיךָ וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךָ. בְּהִתְהַלֶּכְךָ תַּנְחֶה אֹתָךְ, כְּמָה דְאִתְּמָר. בְּשָׁכְבְּךָ תִּשְׁמֹר עָלֶיךָ, בְּשַׁעְתָּא דְּשָׁכִיב גּוּפָא בְּקִבְרָא, דְּהָא כְּדֵין בְּהַהוּא זִמְנָא אִתְדָּן גּוּפָא בְּקִבְרָא וּכְדֵין אוֹרַיְיתָא אֲגִינַת עֲלֵיהּ. וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךָ כְּמָא דְאִתְּמָר בְּזִמְנָא דְּיִתְעָרוּן מֵתֵי עַלְמָא מִן עַפְרָא. הִיא תְשִׂיחֶךָ לְמֶהֱוֵי סַנֵּיגוֹרְיָא עֲלָךְ.","רִבִּי אֶלְעָזָר אָמַר, הִיא תְשִׂיחֶךָ. מַאי הִיא תְשִׂיחֶךָ. בְּגִין דְּאַף עַל גַּב דְּהַשְׁתָּא יְקוּמוּן מֵעַפְרָא, אוֹרַיְיתָא לָא יִתְנְשֵׁי מִנְּהוֹן. דְּהָא כְּדֵין יִנְדְּעוּן כָּל הַהִיא אוֹרַיְיתָא דְּשָׁבְקוּ כַּד אִסְתַּלְקוּ מֵהַאי עַלְמָא, הַהִיא אוֹרַיְיתָא נְטִירָא מֵהַהוּא זִמְנָא וְתִיעוּל בְּמֵעַיְיהוּ כְּמִלְּקַדְּמִין וְאִיהִי תְּמַלֵּל בְּמֵעַיְיהוּ.","וְכָל מִלִּין מִתְתַּקְּנָן יַתִּיר מִכְּמָה דְּהֲווּ בְּקַדְמִיתָא, דְּהָא כָּל אִינוּן מִלִּין דְּאִיהוּ לָא יָכִיל לְאַדְבָּקָא לוֹ כְּדְקָא יָאוֹת וְאִיהוּ אִשְׁתַּדַּל בְּהוּ וְלָא אִתְדָּבַּק בְּהוּ. כֻּלְּהוּ עָאלִין בְּמֵעוֹי מִתְתַּקְנָן, וְאוֹרַיְיתָא תְּמַלֵּל בֵּיהּ. הֲדָא הוּא דִכְתִיב וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךָ. רִבִּי יְהוּדָה אָמַר, כְּגַוְונָא דָא כָּל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא בְּהַאי עַלְמָא, זָכֵי לְאִשְׁתַּדְּלָא בָּהּ לְעַלְמָא דְאָתֵי וְהָא אִתְּמָר.","תָּא חֲזֵי, הַהוּא בַר נָשׁ דְּלָא זָכֵי לְאִשְׁתַּדְּלָא בְּהַאי עַלְמָא בְּאוֹרַיְיתָא, וְאִיהוּ אָזִיל בְּחֲשׁוֹכָא, כַּד נָפִיק מֵהַאי עַלְמָא, נָטְלִין לֵיהּ וְעָאלִין לֵיהּ לַגֵּיהִנֹּם, אֲתַר תַּתָּאָה דְּלָא יְהֵא מְרַחֵם עֲלֵיהּ, דְּאִקְרֵי בּוֹר שָׁאוֹן טִיט הַיָּוֵן. כְּמָה דְאַתְּ אָמֵר, (תהילים מ׳:ג׳) וַיַּעֲלֵנִי מִבּוֹר שָׁאוֹן מִטִּיט הַיָּוֵן וַיָּקֶם עַל סֶלַע רַגְלָי כּוֹנֵן אֲשׁוּרָי.","וּבְּגִין כָּךְ הַהוּא דְּלָא אִשְׁתַּדַּל בְּאוֹרַיְיתָא בְּהַאי עַלְמָא וְאִתְטַנַּף בְּטִנּוּפֵי עַלְמָא, מַה כְּתִיב וַיִּקָּחֻהוּ וַיַּשְׁלִיכוּ אֹתוֹ הַבּוֹרָה. דָּא הוּא גֵּיהִנֹּם, אֲתַר דְּדַיְינִין לְהוּ לְאִינוּן דְּלָא אִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא. וְהַבּוֹר רֵק, כְּמָה דְאִיהוּ הֲוָה רֵק. מַאי טַעְמָא בְּגִין דְּלָא הֲוָה בֵּיהּ מַיִם.","וְתָא חֲזֵי, כַּמָּה הוּא עוֹנְשָׁא דְּאוֹרַיְיתָא, דְּהָא לָא אִתְגָּלוּ יִשְׂרָאֵל מֵאַרְעָא קַדִּישָׁא, אֶלָּא בְּגִין דְּאִסְתַּלָּקוּ מֵאוֹרַיְיתָא, וְאִשְׁתְּבָקוּ מִינָהּ. הֲדָא הוּא דִכְתִיב, (ירמיהו ט׳:י״א) מִי הָאִישׁ הֶחָכָם וְיָבֵן אֶת זֹאת וְגו' עַל מַה אָבְדָה הָאָרֶץ וְגו'. וַיֹּאמֶר יְיָ עַל עָזְבָם אֶת תּוֹרָתִי וְגו'. רִבִּי יוֹסֵי אָמַר, מֵהָכָא, (ישעיהו ה׳:י״ג) לָכֵן גָּלָה עַמִּי מִבְּלִי דָעַת.","בְּגִין כָּךְ כֹּלָּא קָיְימָא עַל קִיּוּמָא דְאוֹרַיְיתָא, וְעַלְמָא לָא אִתְקְיַּים בְּקִיּוּמֵיהּ אֶלָּא בְּאוֹרַיְיתָא, דְּאִיהוּ קִיּוּמָא דְעָלְמִין עֵילָא וְתַתָּא דִּכְתִיב, (ירמיהו ל״ג:כ״ה) אִם לא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לא שָׂמְתִּי:","וַיִּקָּחֻהוּ וַיַּשְׁלִיכוּ אוֹתוֹ הַבּוֹרָה, רָמַז עַל דְּאַרְמִיאוּ לֵיהּ לְגוֹ מִצְרָאֵי אֲתַר דְּלָא אִשְׁתַּכַּח רָזָא דִמְהֵימְנוּתָא כְּלָל. רִבִּי יִצְחָק אָמַר, אִי נְחָשִׁין וְעַקְרַבִּין הֲווּ בֵּיהּ, אַמַּאי כְּתִיב בִּרְאוּבֵן לְמַעַן הַצִּיל אוֹתוֹ מִיָּדָם לַהֲשִׁיבוֹ אֶל אָבִיו. וְכִי לָא חַיִּישׁ רְאוּבֵן לְהַאי. דְּהָא אִינוּן נְחָשִׁין וְעַקְרַבִּין יְנַזְקוּן לֵיהּ, וְאֵיךְ אָמַר לַהֲשִׁיבוֹ אֶל אָבִיו, וּכְתִיב לְמַעַן הַצִּיל אוֹתוֹ.","אֶלָּא חָמָא רְאוּבֵן דְּנִזְקָא אִשְׁתַּכַּח בִּידַיְיהוּ דְּאֲחוֹי, בְּגִין דְּיָדַע כַּמָּה שָׂנְאִין לֵיהּ וּרְעוּתָא דִלְהוֹן לְקָטְלָא לֵיהּ. אָמַר רְאוּבֵן, טַב לְמִנְפַּל לֵיהּ לְגוֹ גּוֹבָא דִּנְחָשִׁין וְעַקְרַבִּין, וְלָא יִתְמְסַר בִּידָא דְּשַׂנְאוֹי דְּלָא מְרַחֲמֵי עֲלֵיהּ. מִכָּאן אָמְרוּ יַפִּיל בַר נָשׁ גַּרְמֵיהּ לְאֶשָׁא אוֹ לְגוּבָא דִּנְחָשִׁין וְעַקְרַבִּין, וְלָא יִתְמַסַּר בִּידָא דְּשַׂנְאוֹי (דזעירין אינון דיכלי לאשתזבא. ובגין כך אמר למען הציל אותו מידם)."],[[0,"וכל מאן דישתדל וכו':","וכל מי שעוסק בתורה לשמה, בעת שנפטר מעולם הזה, התורה הולכת לפניו, ומכרזת לפניו, ומגנת עליו שלא יקרבו אליו בעלי הדין. כשהגוף שוכב בקבר, היא משמרתו. כשהנשמה הולכת להסתלק ולשוב למקומה, היא הולכת לפני הנשמה, והרבה שערים סתומים, נשברים מלפני התורה, עד שמביאה את הנשמה למקומה. והתורה עומדת על האדם בשעה שיתעורר לתחית המתים בזמן שיקומו המתים של העולם. והיא מלמדת זכות עליו."],[1,"הה\"ד בהתהלכך וגו':","בהתהלכך תנחה אותך, הוא כמו שאמרנו, לעיל, שהתורה הולכת לפניו בעת הפטירה, \u0003בשכבך תשמור עליך\u0004, הוא בשעה שהגוף שוכב בקבר, כי אז בזמן ההוא נדון הגוף בקבר, והתורה מגנת עליו. \u0003והקיצות היא תשיחך,\u0004 הוא כמו שאמרנו לעיל, שהוא בזמן שיקיצו מתי העולם לתחיה מן העפר. \u0003היא תשיחך,\u0004 ללמד זכות עליך."],[2,"רבי אלעזר וכו':","ר\"א אמר, \u0003היא תשיחך,\u0004 מהו היא תשיחך. ומשיב, הוא משום, שאע\"פ שעתה קמו מעפר, התורה שלמדו מטרם שמתו, לא נשכחה מהם, כי ידעו אז כל התורה שהניחו בעת שנסתלקו מעולם הזה, תורה זו שמורה להם מאותו הזמן, ונכנסת במעיהם כמקודם לכן, והיא תדבר במעיהם. כלומר שלא תחזור להם לאט לאט כטבע הבא במחשבה, אלא תבוא כולה בבת אחת בדרך התלבשות, כטבע הבא במעים."],[3,"וכל מלין מתתקנן וכו':","וכל הדברים ברורים יותר ממה שהיה בתחילה, מטרם שמת, כי כל אלו הדברים שהוא לא יכול להשיג אותם כראוי, והשתדל בהם אז ולא השיגם, כולם באים עתה במעיו ברורים, והתורה תדבר בו, וז\"ש, והקיצות היא תשיחך. ר' יהודה אומר, כעין זה, כל מי שהשתדל בתורה בעולם הזה זוכה לעסוק בה לעולם הבא, וכבר בארוה."],[4,"ת\"ח ההוא ב\"נ וכו':","בוא וראה, האדם שלא זכה לעסוק בתורה בעולם הזה, והוא הולך בחשך, כשהוא נפטר מעולם הזה, לוקחים אותו ומכניסים אותו לגיהנם, במקום תחתון שלא יהיה מרחם עליו, שנקרא, בור שאון טיט היון, כמו שאתה אומר, ויעלני מבור שאון מטיט היון וגו'."],[5,"ובגין כך ההוא וכו':","ומשום זה, אותו שאינו משתדל בתורה בעולם הזה, ונטנף בטנופי עולם הזה, מה כתוב עליו, \u0003ויקחהו וישליכו אותו הבורה,\u0004 זהו גיהנם, המקום שדנים שם לאותם שאינם עוסקים בתורה. \u0003והבור רק,\u0004 כמו שהוא היה רק, מה הטעם, משום שלא היה שם מים, דהיינו תורה שנקראת מים."],[6,"ותא חזי כמה וכו':","ובוא וראה כמה היא העונש של ביטול תורה, כי לא גלו ישראל מארץ הקדושה, אלא משום שנסתלקו מתורה ונעזבו ממנה, וז\"ש, \u0003מי האיש וגו'. על עזבם את תורתי.\u0004 רבי יוסי אומר, מכאן, \u0003לכן גלה עמי מבלי דעת\u0004 דהיינו בלי תורה."],[7,"בגין כך כלא וכו'",": משום זה הכל עומד על קיום התורה, והעולם אינו עומד על קיומו, אלא בתורה, שהיא קיום העולמות למעלה ולמטה, שכתוב, אם לא בריתי וגו'."],[8,"ויקחהו וישליכו אותו הבורה:","זה רמז על שהשליכו אותו אח\"כ לתוך מצרים, שלא נמצא בהם כלל סוד האמונה. פירוש. מים ה\"ס אמונה, וכשאומר והבור רק וגו', היינו, שאין שם סוד האמונה."],[8,"ר' יצחק אמר וכו':","רי\"א, אם היה בו בבור נחשים ועקרבים, דהיינו כמו שדרשו חז\"ל (שבת כ\"ב.) מים אין בו אבל נחשים ועקרבים יש בו. למה כתוב בראובן \u0003למען הציל אותו מידם\u0004 וגו', וכי לא פחד ראובן לזה, אשר הנחשים והעקרבים יזיקו אותו, ואיך אמר \u0003להשיבו אל אביו,\u0004 וכתוב, \u0003למען הציל אותו.\u0004"],[9,"אלא חמא ראובן וכו':","ומשיב, אלא ראובן ראה, שהנזק הוא ודאי, כשהוא בידיהם של אחיו, כי ידע כמה הם שונאים אותו, ורצונם הוא להרוג אותו. אמר ראובן, מוטב להפילו לתוך הבור שיש בו נחשים ועקרבים, ולא יהיה נמסר ביד שונאיו שאינם מרחמים עליו, מכאן אמרו, יפיל אדם את עצמו לאש או לבור של נחשים ועקרבים, ולא ימסור את עצמו ביד שונאיו."]],[[0,"","וְכָל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה לִשְׁמָהּ, כְּשֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה, הַתּוֹרָה הוֹלֶכֶת לְפָנָיו וּמַכְרִיזָה לְפָנָיו וּמְגִנָּה עָלָיו שֶׁלֹּא יִקְרְבוּ אֵלָיו בַּעֲלֵי הַדִּין. כְּשֶׁשּׁוֹכֵב הַגּוּף בַּקֶּבֶר, הִיא שׁוֹמֶרֶת אוֹתוֹ. כְּשֶׁהַנְּשָׁמָה הוֹלֶכֶת לְהִסְתַּלֵּק לָשׁוּב לִמְקוֹמָהּ, הִיא הוֹלֶכֶת לִפְנֵי הַנְּשָׁמָה הַהִיא. וְכַמָּה שְׁעָרִים נִשְׁבָּרִים מִלִּפְנֵי הַתּוֹרָה עַד שֶׁנִּכְנֶסֶת לִמְקוֹמָהּ, וְעוֹמֶדֶת עַל הָאָדָם עַד שֶׁיִּתְעוֹרֵר בַּזְּמַן שֶׁיָּקוּמוּ הַמֵּתִים שֶׁל הָעוֹלָם, וְהִיא מְלַמֶּדֶת עָלָיו סָנֵגוֹרְיָה."],[1,"","זֶהוּ שֶׁכָּתוּב (משלי ו) בְּהִתְהַלֶּכְךְ תַּנְחֶה אֹתָךְ בְּשָׁכְבְּךְ תִּשְׁמֹר עָלֶיךְ וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךְ. בְּהִתְהַלֶּכְךְ תַּנְחֶה אֹתָךְ - כְּמוֹ שֶׁנִּתְבָּאֵר. בְּשָׁכְבְּךְ תִּשְׁמֹר עָלֶיךְ - בְּשָׁעָה שֶׁשּׁוֹכֵב הַגּוּף בַּקֶּבֶר, שֶׁהֲרֵי אָז בַּזְּמַן הַהוּא נִדּוֹן הַגּוּף בַּקֶּבֶר, וְאָז הַתּוֹרָה מְגִנָּה עָלָיו. וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךְ - כְּמוֹ שֶׁנִּתְבָּאֵר, בִּזְמַן שֶׁיִּתְעוֹרְרוּ הַמֵּתִים שֶׁל הָעוֹלָם מִן הֶעָפָר, הִיא תְשִׂיחֶךְ לִהְיוֹת עָלֶיךְ סָנֵגוֹר."],[2,"","רַבִּי אֶלְעָזָר אָמַר, הִיא תְשִׂיחֶךְ, מַה זֶּה הִיא תְשִׂיחֶךְ? מִשּׁוּם שֶׁאַף עַל גַּב שֶׁעַכְשָׁו יָקוּמוּ מֵהֶעָפָר, הַתּוֹרָה לֹא תִשְׁתַּכַּח מֵהֶם, שֶׁהֲרֵי אָז יֵדְעוּ אֶת כָּל אוֹתָהּ הַתּוֹרָה שֶׁעָזְבוּ כְּשֶׁהִסְתַּלְּקוּ מִן הָעוֹלָם הַזֶּה. אוֹתָהּ הַתּוֹרָה שְׁמוּרָה מֵאוֹתוֹ זְמַן, וְתִכָּנֵס לִמְעֵיהֶם כְּמוֹ מִקֹּדֶם, וְהִיא תְדַבֵּר בִּמְעֵיהֶם."],[3,"","וְכָל הַדְּבָרִים מְתֻקָּנִים יוֹתֵר מִכְּמוֹ שֶׁהָיוּ בָּרִאשׁוֹנָה, שֶׁהֲרֵי כָּל אוֹתָם הַדְּבָרִים שֶׁהוּא לֹא יָכֹל לְהַשִּׂיג אוֹתָם כָּרָאוּי וְהוּא הִשְׁתַּדֵּל בָּהֶם וְלֹא נִדְבַּק בָּהֶם - כֻּלָּם נִכְנָסִים לְמֵעָיו מְתֻקָּנִים וְהַתּוֹרָה תְּדַבֵּר בּוֹ. זֶהוּ שֶׁכָּתוּב וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךְ. רַבִּי יְהוּדָה אָמַר, כְּמוֹ זֶה כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה בָּעוֹלָם הַזֶּה, זוֹכֶה לְהִשְׁתַּדֵּל בָּהּ לָעוֹלָם הַבָּא, וְהִנֵּה נִתְבָּאֵר."],[4,"","בֹּא רְאֵה, אוֹתוֹ הָאִישׁ שֶׁלֹּא זוֹכֶה לְהִשְׁתַּדֵּל בָּעוֹלָם הַזֶּה בַּתּוֹרָה וְהוּא הוֹלֵךְ בַּחֲשֵׁכָה, כְּשֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה, נוֹטְלִים אוֹתוֹ וּמַכְנִיסִים אוֹתוֹ לַגֵּיהִנֹּם לַמָּקוֹם הַתַּחְתּוֹן, שֶׁלֹּא יִהְיֶה מְרַחֵם עָלָיו, שֶׁנִּקְרָא בּוֹר שָׁאוֹן טִיט הַיָּוֵן, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מ) וַיַּעֲלֵנִי מִבּוֹר שָׁאוֹן מִטִּיט הַיָּוֵן וַיָּקֶם עַל סֶלַע רַגְלָי כּוֹנֵן אֲשׁוּרָי."],[5,"","וּמִשּׁוּם כָּךְ, אוֹתוֹ שֶׁלֹּא מִשְׁתַּדֵּל בַּתּוֹרָה בָּעוֹלָם הַזֶּה וּמִתְטַנֵּף בַּטִּנּוֹפוֹת שֶׁל הָעוֹלָם, מַה כָּתוּב? וַיִּקָּחֻהוּ וַיַּשְׁלִכוּ אֹתוֹ הַבֹּרָה - זֶה הוּא הַגֵּיהִנֹּם, הַמָּקוֹם שֶׁדָּנִים אֶת אוֹתָם שֶׁלֹּא הִשְׁתַּדְּלוּ בַּתּוֹרָה. וְהַבּוֹר רֵק - כְּמוֹ שֶׁהוּא הָיָה רֵיק, מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא הָיָה בּוֹ מַיִם."],[6,"","וּבֹא וּרְאֵה כַּמָּה הוּא הָעֹנֶשׁ שֶׁל הַתּוֹרָה, שֶׁהֲרֵי לֹא גָלוּ יִשְׂרָאֵל מֵהָאָרֶץ הַקְּדוֹשָׁה אֶלָּא מִשּׁוּם שֶׁהִסְתַּלְּקוּ מִן הַתּוֹרָה וְנֶעֶזְבוּ מִמֶּנָּה, זֶהוּ שֶׁכָּתוּב (ירמיה ט) מִי הָאִישׁ הֶחָכָם וְיָבֵן אֶת זאת וְגוֹ' עַל מָה אָבְדָה הָאָרֶץ וְגוֹ'. וַיּאמֶר ה' עַל עָזְבָם אֶת תּוֹרָתִי וְגוֹ'. רַבִּי יוֹסֵי אָמַר, מִכָּאן (ישעיה ה) לָכֵן גָּלָה עַמִּי מִבְּלִי דָעַת."],[7,"","מִשּׁוּם כָּךְ הַכֹּל עוֹמֵד עַל קִיּוּם הַתּוֹרָה, וְהָעוֹלָם לֹא מִתְקַיֵּם בְּקִיּוּמוֹ אֶלָּא בַּתּוֹרָה, שֶׁהִיא קִיּוּם הָעוֹלָמוֹת, מַעְלָה וּמַטָּה, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי."],[8,"","וַיִקָּחֻהוּ וַיַּשְׁלִכוּ אֹתוֹ הַבֹּרָה, רֶמֶז עַל שֶׁזָּרְקוּ אוֹתוֹ לְתוֹךְ הַמִּצְרִים, הַמָּקוֹם שֶׁלֹּא נִמְצָא בּוֹ סוֹד הָאֱמוּנָה כְּלָל. רַבִּי יִצְחָק אָמַר, אִם נְחָשִׁים וְעַקְרַבִּים הָיוּ בוֹ, לָמָּה כָּתוּב בִּרְאוּבֵן לְמַעַן הַצִּיל אֹתוֹ מִיָּדָם לַהֲשִׁיבוֹ אֶל אָבִיו, וְכִי לֹא חָשַׁשׁ רְאוּבֵן לָזֶה שֶׁהִנֵּה אוֹתָם נְחָשִׁים וְעַקְרַבִּים יַזִּיקוּ אוֹתוֹ, וְאֵיךְ אָמַר לַהֲשִׁיבוֹ אֶל אָבִיו, וְכָתוּב לְמַעַן הַצִּיל אוֹתוֹ?"],[9,"","אֶלָּא שֶׁרָאָה רְאוּבֵן שֶׁהַנֵּזֶק נִמְצָא בִּידֵי אֶחָיו, מִשּׁוּם שֶׁיָּדַע כַּמָּה הֵם שׂוֹנְאִים אוֹתוֹ וּרְצוֹנָם לַהֲרֹג אוֹתוֹ. אָמַר רְאוּבֵן, טוֹב לְהַפִּיל אוֹתוֹ לְתוֹךְ בּוֹר הַנְּחָשִׁים וְהָעַקְרַבִּים וְלֹא יִמָּסֵר בִּידֵי שׂוֹנְאָיו שֶׁלֹּא מְרַחֲמִים עָלָיו. מִכָּאן אָמְרוּ, יַפִּיל אָדָם עַצְמוֹ לָאֵשׁ אוֹ לְבוֹר שֶׁל נְחָשִׁים וְעַקְרַבִּים וְלֹא יִמָּסֵר בִּידֵי שׂוֹנְאָיו (שמעטים הם שיכולים להנצל, ומשום כך אמר למען הציל אתו מידם)."]]],[["בְּגִין דְּהָכָא אֲתַר דִּנְחָשִׁים וְעַקְרַבִּים. אִי אִיהוּ צַדִּיקָא, קוּדְשָׁא בְּרִיךְ הוּא יַרְחִישׁ לֵיהּ נִיסָא. וּלְזִמְנִין דִּזְכוּ דְּאֲבָהָן מְסַיְיעִין לֵיהּ לְבַר נָשׁ וְיִשְׁתְּזִיב מִנַּיְיהוּ. אֲבָל כֵּיוָן דְּיִתְמַסַּר בִּידָא דְּשַׂנְאוֹי, זְעִירִין אִינוּן דְּיָכְלִין לְאִשְׁתְּזָבָא.","וּבְגִין כָּךְ אָמַר, לְמַעַן הַצִּיל אוֹתוֹ מִיָּדָם. מִיָּדָם דַּיְיקָא, וְלָא כְּתִיב לְמַעַן הַצִּיל אוֹתוֹ וְתוּ לָא. אֶלָּא אָמַר רְאוּבֵן, יִשְׁתְּזִיב מִן יְדַיְיהוּ, וְאִי יְמוּת בְּגוּבָא יְמוּת. וּבְגִין כָּךְ כְּתִיב וַיִּשְׁמַע רְאוּבֵן וַיַּצִּילֵהוּ מִיָּדָם.","תָּא חֲזֵי, כַּמָּה חֲסִידוּתֵיהּ דִּרְאוּבֵן, דִּבְגִין דְּיָדַע דְּשִׁמְעוֹן וְלֵוִי שׁוּתְּפוּתָא וַחֲכִימוּתָא וְחַבְרוּתָא דִּלְהוֹן, קַשְׁיָא אִינוּן. דְּכַד אִתְחַבָּרוּ בִּשְׁכֶם, קָטְלוּ כָּל דְּכוּרָא (ס\"א ל\"ג והא דקטלו כל דכורא) לָא דַי לוֹן. אֶלָּא דְּנָטְלִין נָשִׁין וָטַף וְכַסְפָּא וְדַהֲבָא וְכָל בְּעִירֵי וְכָל מָאנֵי דִיקָר וְכָל מַאן דְּאִשְׁתַּכַּח בְּקַרְתָּא. וְלָא דַי כָּל דָא, אֶלָּא דְּאָפִילּוּ כָּל מַה דִּבְחַקְלָא נָטְלוּ. דִּכְתִיב, (בראשית לה) וְאֶת אֲשֶׁר בָּעִיר וְאֶת אֲשֶׁר בַּשָּׂדֶה לָקָחוּ.","אָמַר, וּמַה קַּרְתָּא רַבָּתָא כִּי הַאי לָא אִשְׁתְּזִיב מִנְּהוֹן, אִלְמָלֵא רַבְיָא דָא יִפּוֹל בִּידַיְיהוּ, לָא יַשְׁאֲרוּן מִנֵּיהּ אוּמְצָא בְּעַלְמָא. וְעַל דָּא אָמַר, טַב לְאִשְׁתְּזָבָא מִנַּיְיהוּ דְּלָא יַשְׁאֲרוּן מִנֵּיהּ אִשְׁתָּאֲרוּתָא בְּעַלְמָא, וְלָא יֶחמֵי אַבָּא מִנֵּיהּ כְּלוּם לְעָלְמִין.","וְהָכָא אִי יְמוּת, לָא יָכְלִין לֵיהּ וְיִשְׁתָּאַר כָּל גּוּפֵיהּ שְׁלִים, וַאֲתִיב לֵיהּ לְאַבָּא שְׁלִים. וְעַל דָּא לְמַעַן הַצִּיל אוֹתוֹ מִיָּדָם לַהֲשִׁיבוֹ אֶל אָבִיו, אַף עַל גַּב דִּימוּת הָתָם. וּבְגִין כָּךְ אָמַר הַיֶּלֶד אֵינֶנּוּ. וְלָא אָמַר אֵינְנּוּ חַי, אֶלָּא אָמַר אֵינֶנּוּ, אֲפִילּוּ מֵת.","תָּא חֲזֵי, מַאי דְּעֲבַד, דְּאִיהוּ בְּחָכְמְתָא הֲוָה שַׁתִּיף גַּרְמֵיהּ בַּהֲדַיְיהוּ, דִּכְתִיב לא נַכֶּנּוּ נָפֶשׁ, וְלָא כְּתִיב לָא תַכּוּהוּ. וְאִיהוּ לָא הֲוָה תַּמָּן כַּד אִזְדַּבַּן יוֹסֵף, דְּהָא כֻּלְּהוּ מְשַׁמְּשֵׁי לַאֲבוּהוֹן כָּל חַד וְחַד יוֹמָא חַד. וְהַהוּא יוֹמָא דִרְאוּבֵן הֲוָה. וְעַל דָּא בָּעָא דִּבְהַהוּא יוֹמָא דְּהֲוָה שִׁמּוּשָׁא דִילֵיהּ לָא יִתְאֲבִיד יוֹסֵף. וּבְגִין כָּךְ כְּתִיב וַיָּשָׁב רְאוּבֵן אֶל הַבּוֹר וְהִנֵּה אֵין יוֹסֵף בַּבּוֹר וַיִּקְרַע אֶת בְּגָדָיו. וְהִנֵה אֵין יוֹסֵף דַּיְיקָא. אֲפִילּוּ (חי או) מִית, מִיָּד וַיָּשָׁב אֶל אֶחָיו וַיֹּאמֶר הַיֶּלֶד אֵינֶנּוּ.","וְאֲפִילּוּ רְאוּבֵן לָא יָדַע מֵהַהוּא זְבִינָא דְיוֹסֵף, וְהָא אוּקְמוּהָ דְּאִשְׁתַּתִּיף בְּהוּ שְׁכִינְתָּא, וְעַל דָּא לָא יָדַע רְאוּבֵן מֵהַהוּא זְבִינָא דְיוֹסֵף וְלָא אִתְגַלְיָיא לֵיהּ עַד הַהוּא זִמְנָא דְּאִתְגְּלֵי יוֹסֵף לַאֲחוֹהִי.","תָּא חֲזֵי, כַּמָּה גָּרִים לֵיהּ לִרְאוּבֵן בְּגִין דְּאִיהוּ אִשְׁתַּדַּל לְאַחֲיָיא לֵיהּ לְיוֹסֵף, מַה כְּתִיב, (דברים ל״ג:ו׳) יְחִי רְאוּבֵן וְאַל יָמוֹת וְגו'. דְּהָא בְּגִין דָּא, אַף עַל גַּב דְּיָדַע דְּאִשְׁתְּקִיל בְּכֵירוּתֵיהּ מִנֵּיהּ וְאִתְיְהִיב לְיוֹסֵף, אִשְׁתַּדַּל לְאֲחַיָיא לֵיהּ, וְצַלֵּי משֶׁה וְאֲמַר יְחִי רְאוּבֵן וְאַל יָמוֹת, וְאִתְקְיַּים בְּעַלְמָא דֵין וְאִתְקְיַּים בְּעַלְמָא דְאָתֵי. מַאי טַעְמָא, בְּגִין דָּא, וּבְגִין דְּעֲבַד תְּשׁוּבָה מֵהַהוּא עוֹבָדָא. דְּכָל מַאן דְּעָבִיד תְּשׁוּבָה, קוּדְשָׁא בְּרִיךְ הוּא קַיַּים לֵיהּ בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי.","תָּא חֲזֵי מַה כְּתִיב, וַיִּקְחוּ אֶת כְּתֹנֶת יוֹסֵף וְגו', הָא אוּקְמוּהָ דִּבְגִין דְּדָמָא דְּשָׂעִיר דַּמְיָא לְדָמָא דְבַר נָשׁ. אֲבָל תָּא חֲזֵי, אַף עַל גַּב דְּמִלָּה אַתְיָא כְּדְקָא חָזֵי, קוּדְשָׁא בְּרִיךְ הוּא מְדַקְדֵּק בְּהוּ בְּצַדִּיקַיָיא אֲפִילּוּ כְּחוּט הַשַּׂעֲרָה.","יַעֲקֹב עָבַד עוֹבָדָא כְּדְקָא יָאוֹת. בְּמַאי, בְּגִין דְּאַקְרִיב לְגַבּוֹי אֲבוֹי שָׂעִיר, דְּאִיהוּ סִטְרָא דְּדִינָא קַשְׁיָא. וְעִם כָּל דָּא, בְּגִין דְּאִיהוּ אַקְרִיב שָׂעִיר וְאַכְּחִישׁ לֵיהּ לְאֲבוֹי דְּאִיהוּ סִטְרָא דִילֵיהּ, אִתְעֲנַשׁ בְּהַאי שָׂעִיר אָחֳרָא, דְּאַקְרִיבוּ לֵיהּ בְּנוֹי דָמָא דִילֵיהּ.","בְּאִיהוּ כְּתִיב, (בראשית כ״ז:ט״ז) וְאֵת עוֹרוֹת גְּדָיֵי הָעִזִּים הִלְבִּישָׁה עַל יָדָיו וְעַל חֶלְקַת צַוָּארָיו, בְּגִין כָּךְ וַיִּטְבְּלוּ אֶת הַכֻּתֹּנֶת בַּדָּם, אַקְרִיבוּ לֵיהּ כֻּתּוֹנְתָּא לְאַכְּחָשָׁא לֵיהּ, וְכֹלָּא דָּא לָקֳבֵל דָּא, אִיהוּ גָּרִים דִּכְתִיב וַיֶּחרַד יִצְחָק חֲרָדָה גְדוֹלָה עַד מְאֹד, בְּגִין כָּךְ גָּרְמוּ לֵיהּ דְּחָרַד חֲרָדָה בְּהַהוּא זִמְנָא דִּכְתִיב הַכֶּר נָא הַכְּתֹנֶת בִּנְךָ הִיא אִם לֹא."],[[0,"בגין דהכא אתר וכו':","מפני שכאן במקום נחשים ועקרבים, אם הוא צדיק, הקב\"ה עושה לו נס, ולפעמים זכות אבותיו עומדת לאדם, וינצל מהם, אבל כיון שנמסר ביד שונאיו, מועטים הם היכולים להנצל."],[1,"ובגין כך אמר וכו':","ומשום זה אמר, למען הציל אותו מידם, \u0003מידם\u0004 הוא בדיוק, שלא כתוב למען הציל אותו, ולא יותר אלא שכתוב מידם, אלא אמר ראובן, ינצל מהם, ואם ימות מוטב שימות בבור, כמ\"ש לפנינו, ומשום זה כתוב וישמע ראובן ויצילהו \u0003מידם,\u0004 דהיינו שהצילו שלא ימות תחת \u0003ידם\u0004, אלא אם ימות יהיה זה בבור."],[2,"ת\"ח כמה וכו':","בוא וראה כמה הוא חסידותו של ראובן, כי משום שידע ששמעון ולוי, שותפותם וערמתם, והתחברותם, הוא קשה, כי כשנתחברו בשכם, הרגו כל זכר, ולא היה זה די להם, אלא שלקחו נשים וטף, וכסף וזהב, וכל בהמה, וכל כלי יקר, וכל מה שנמצא בעיר. ולא די להם כל זה, אלא שאפילו כל מה שבשדה לקחו, שכתוב ואת אשר בעיר ואת אשר בשדה לקחו."],[3,"אמר ומה קרתא וכו':","אמר, ומה עיר גדולה כזו לא נצלה מהם, אם ילד הזה יפול בידיהם, לא ישאירו ממנו חתיכת בשר בעולם. ועל כן אמר טוב להצילו מהם, כי לא ישאירו ממנו שום שיור בעולם, ואבי לא יראה ממנו כלום בעולם."],[4,"והכא אי ימות וכו':","וכאן, בבור, אם ימות לא יוכלו לו אחיו, וישאר כל גופו שלם, והשיבותי אותו שלם לאבי, וע\"כ, אוה\"כ, \u0003למען הציל אותו מידם להשיבו אל אביו,\u0004 אף על פי שימות שמה, אוכל להשיבו לאביו, ומשום זה אמר \u0003הילד איננו,\u0004 ולא אמר איננו חי, אלא אמר, איננו, אפילו מת."],[5,"ת\"ח מאי דעבד וכו':","בוא וראה מה שעשה. כי בחכמה היה משתף עצמו עמהם, שכתוב לא נכנו נפש, ולא כתוב לא תכוהו נפש, והוא לא היה שם בעת שנמכר יוסף, כי כולם היו משמשים לאביהם כל אחד ואחד מהם יום אחד, ואותו יום של ראובן היה וע\"כ רצה, שביום השמוש שלו לא יאבד יוסף וע\"כ כתוב וישב ראובן אל הבור וגו', \u0003והנה אין יוסף\u0004 הוא בדיוק דהיינו שאינו אפילו מת, מיד וישב אל אחיו וגו'."],[6,"ואפילו ראובן וכו':","ואפילו ראובן לא היה יודע ממכירה זו של יוסף, ובארוה, שנשתתפה עמהם השכינה, בהחרם שעשו שלא לגלות מכירת יוסף, וע\"כ לא ידע ראובן ממכירה זו של יוסף, ולא נתגלה לו עד אותו זמן שנתגלה יוסף לאחיו."],[7,"ת\"ח כמה גרים וכו':","בוא וראה, כמה גרם לראובן, מה שהשתדל להציל חיי יוסף. מה כתוב, יחי ראובן ואל ימות, כי משום זה, אע\"פ שידע שנטלה הבכורה ממנו ונתנה ליוסף מכל מקום השתדל להציל את חייו, וע\"כ התפלל משה, ואמר יחי ראובן ואל ימות, ונתקיים בעולם הזה ובעולם הבא. מהו הטעם. הוא משום זה, שהציל חייו של יוסף. ומשום שעשה תשובה על אותו מעשה של חלול יצועי אביו. שכל מי שעושה תשובה, הקב\"ה מחיה אותו בעולם הזה ובעולם הבא."],[8,"ת\"ח מה כתיב וכו':","בוא וראה מה כתוב, ויקחו את כתונת יוסף וגו'. ובארוה, שהוא משום שדם שעיר דומה לדם אדם. אבל בוא וראה. אע\"פ שהדבר בא כראוי, דהיינו שאין בו עבירה, הקב\"ה מדקדק עם הצדיקים, אפילו כחוט השערה."],[9,"יעקב עבד עובדא וכו':","יעקב עשה מעשה כראוי במה שהקריב לאביו שעיר, שהוא צד דין הקשה, ועם כל זה, משום שהקריב שעיר, והחליש את אביו כדין קשה שלו, משום שהוא הצד שלו, כי גם יצחק הוא בחינת דין קשה, וע\"כ נאחז בו הדין שבשעיר, ע\"כ נענש יעקב בשעיר אחר שבניו הקריבו אליו הדם שלו."],[10,"באיהו כתיב וכו'",": בו ביעקב כתוב, ואת עורות גדיי העזים וגו'. משום זה כתוב בבניו, ויטבלו את הכתונת בדם, הקריבו לו הכתונת להחליש אותו. והכל היה זה כנגד זה, הוא גרם שכתוב, ויחרד יצחק חרדה גדולה עד מאד, משום זה גרמו לו בניו, שחרד חרדה, באותו הזמן שכתוב, הכר נא הכתנת בנך הוא אם לא."]],[[0,"","מִשּׁוּם שֶׁכָּאן בִּמְקוֹם הַנְּחָשִׁים וְהָעַקְרַבִּים - אִם הוּא צַדִּיק, הַקָּדוֹשׁ בָּרוּךְ הוּא יַרְחִישׁ לוֹ נֵס, וְלִפְעָמִים שֶׁזְּכוּת אָבוֹת מְסַיְּעִים לָאָדָם וְיִנָּצֵל מֵהֶם. אֲבָל כֵּיוָן שֶׁנִּמְסָר בִּידֵי שׂוֹנְאָיו, מְעַטִּים הֵם שֶׁיְּכוֹלִים לְהִנָּצֵל."],[1,"","וּמִשּׁוּם כָּךְ אָמַר לְמַעַן הַצִּיל אֹתוֹ מִיָּדָם, מִיָּדָם דַּוְקָא, וְלֹא כָתוּב לְמַעַן הַצִּיל אוֹתוֹ וְיוֹתֵר לֹא. אֶלָּא אָמַר רְאוּבֵן, יִנָּצֵל מִיָּדָם, וְאִם יָמוּת בַּבּוֹר - יָמוּת. וּמִשּׁוּם כָּךְ כָּתוּב וַיִּשְׁמַע רְאוּבֵן וַיַּצִּלֵהוּ מִיָּדָם"],[2,"","בֹּא רְאֵה כַּמָּה הִיא חֲסִידוּתוֹ שֶׁל רְאוּבֵן, שֶׁמִּשּׁוּם שֶׁיָּדַע שֶׁשִּׁמְעוֹן וְלֵוִי, הַשֻּׁתָּפוּת וְהַחָכְמָה וְהַחֲבֵרוּת שֶׁלָּהֶם הֵם קָשִׁים, שֶׁכַּאֲשֶׁר הִתְחַבְּרוּ בִּשְׁכֶם הָרְגוּ כָּל זָכָר (ס\"א וזה שהרגו כל זכר), לֹא דַי לָהֶם, אֶלָּא שֶׁנּוֹטְלִים נָשִׁים וָטַף וְכֶסֶף וְזָהָב וְכָל הַבְּהֵמוֹת וְכָל כְּלֵי יְקָר וְכָל מִי שֶׁנִּמְצָא בַּקִּרְיָה, וְלֹא דַי, אֶלָּא שֶׁאֲפִלּוּ כָּל מַה שֶּׁבַּשָּׂדֶה נָטְלוּ, שֶׁכָּתוּב (בראשית לד) וְאֶת אֲשֶׁר בָּעִיר וְאֶת אֲשֶׁר בַּשָּׂדֶה לָקָחוּ."],[3,"","אָמַר, וּמָה הַקִּרְיָה הַגְּדוֹלָה כָּזוֹ לֹא נִצַּל מֵהֶם - אִלְמָלֵא הָעֶלֶם הַזֶּה יִפֹּל בִּידֵיהֶם, לֹא יַשְׁאִירוּ מִמֶּנּוּ חֲתִיכַת בָּשָׂר בָּעוֹלָם, וְעַל כֵּן אָמַר טוֹב לְהִנָּצֵל מֵהֶם, שֶׁלֹּא יַשְׁאִירוּ מִמֶּנּוּ שְׁאֵרִית בָּעוֹלָם וְלֹא יִרְאֶה מִמֶּנּוּ אַבָּא כְּלוּם לְעוֹלָמִים."],[4,"","וְכָאן אִם יָמוּת, לֹא יְכוֹלִים לוֹ, וְיִשָּׁאֵר כָּל גּוּפוֹ שָׁלֵם וְאָשִׁיב אוֹתוֹ לְאַבָּא שָׁלֵם, וְעַל כֵּן לְמַעַן הַצִּיל אֹתוֹ מִיָּדָם לַהֲשִׁיבוֹ אֶל אָבִיו, אַף עַל גַּב שֶׁיָּמוּת שָׁם. וּמִשּׁוּם כָּךְ אָמַר הַיֶּלֶד אֵינֶנּוּ, וְלֹא אָמַר אֵינֶנּוּ חַי, אֶלָּא אָמַר אֵינֶנּוּ - אֲפִלּוּ מֵת."],[5,"","בֹּא רְאֵה מַה שֶּׁעָשָׂה, שֶׁהוּא בְחָכְמָה הָיָה מְשַׁתֵּף עַצְמוֹ עִמָּהֶם, שֶׁכָּתוּב לֹא נַכֶּנּוּ נָפֶשׁ, וְלֹא כָתוּב לֹא תַכּוּהוּ, וְהוּא לֹא הָיָה שָׁם כְּשֶׁנִּמְכַּר יוֹסֵף, שֶׁהֲרֵי כֻּלָּם שִׁמְּשׁוּ אֶת אֲבִיהֶם, כָּל אֶחָד וְאֶחָד יוֹם אֶחָד, וְאוֹתוֹ הַיּוֹם הָיָה שֶׁל רְאוּבֵן, וְעַל כֵּן רָצָה שֶׁבְּאוֹתוֹ הַיּוֹם שֶׁהָיָה הַשִּׁמּוּשׁ שֶׁלּוֹ לֹא יֵאָבֵד יוֹסֵף, וּמִשּׁוּם כָּךְ כָּתוּב וַיָּשָׁב רְאוּבֵן אֶל הַבּוֹר וְהִנֵּה אֵין יוֹסֵף בַּבּוֹר וַיִּקְרַע אֶת בְּגָדָיו. וְהִנֵּה אֵין יוֹסֵף דַּוְקָא, אֲפִלּוּ (חי או) מֵת, מִיָּד וַיָּשָׁב אֶל אֶחָיו וַיֹּאמֶר הַיֶּלֶד אֵינֶנּוּ."],[6,"","וַאֲפִלּוּ רְאוּבֵן לֹא יָדַע מֵאוֹתָהּ הַמְּכִירָה שֶׁל יוֹסֵף. וַהֲרֵי בֵּאֲרוּהוּ שֶׁהַשְּׁכִינָה הִשְׁתַּתְּפָה עִמָּהֶם, וְעַל כֵּן לֹא יָדַע רְאוּבֵן מֵהַמְּכִירָה הַהִיא שֶׁל יוֹסֵף, וְלֹא הִתְגַּלְּתָה לוֹ עַד אוֹתוֹ הַזְּמַן שֶׁיּוֹסֵף הִתְגַּלָּה לְאֶחָיו."],[7,"","בֹּא רְאֵה כַּמָּה גָרַם לִרְאוּבֵן מִשּׁוּם שֶׁהוּא הִשְׁתַּדֵּל לְהַחֲיוֹת אֶת יוֹסֵף. מַה כָּתוּב? (דברים לג) יְחִי רְאוּבֵן וְאַל יָמֹת וְגוֹ'. שֶׁהֲרֵי מִשּׁוּם זֶה, אַף עַל גַּב שֶׁיָּדַע שֶׁנִּלְקְחָה בְכוֹרָתוֹ מִמֶּנּוּ וְנִתְּנָה לְיוֹסֵף, הִשְׁתַּדֵּל לְהַחֲיוֹת אוֹתוֹ, וְהִתְפַּלֵּל מֹשֶׁה וְאָמַר יְחִי רְאוּבֵן וְאַל יָמֹת, וְהִתְקַיֵּם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. מָה הַטַּעַם? מִשּׁוּם זֶה, וּמִשּׁוּם שֶׁעָשָׂה תְשׁוּבָה מֵהַמַּעֲשֶׂה הַהוּא. שֶׁכָּל מִי שֶׁעוֹשֶׂה תְשׁוּבָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַיֵּם אוֹתוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[8,"","בֹּא רְאֵה מַה כָּתוּב? וַיִּקְחוּ אֶת כְּתֹנֶת יוֹסֵף וְגוֹ'. הֲרֵי בֵּאֲרוּהוּ, שֶׁמִּשּׁוּם שֶׁדַּם הַשָּׂעִיר דּוֹמֶה לְדָם שֶׁל אָדָם. אֲבָל בּא רְאֵה, אַף עַל גַּב שֶׁהַדָּבָר בָּא כָּרָאוּי, הַקָּדוֹשׁ בָּרוּךְ הוּא מְדַקְדֵּק עִם הַצַּדִּיקִים אֲפִלּוּ כְּחוּט הַשַּׂעֲרָה."],[9,"","יַעָקֹב עָשָׂה מַעֲשֶׂה כָּרָאוּי, בַּמֶּה? מִשּׁוּם שֶׁהִקְרִיב לְאָבִיו שָׂעִיר, שֶׁהוּא צַד הַדִּין הַקָּשֶׁה, וְעִם כָּל זֶה, מִשּׁוּם שֶׁהוּא הִקְרִיב שָׂעִיר וְהִכְחִישׁ אֶת אָבִיו שֶׁהוּא הַצַּד שֶׁלּוֹ, נֶעֱנַשׁ בַּשָּׂעִיר הָאַחֵר הַזֶּה שֶׁהִקְרִיבוּ לוֹ בָּנָיו אֶת הַדָּם שֶׁלּוֹ."],[10,"","בּוֹ כָּתוּב (בראשית כז) וְאֵת עֹרֹת גְּדָיֵי הָעִזִּים הִלְבִּישָׁה עַל יָדָיו וְעַל חֶלְקַת צַוָּארָיו, מִשּׁוּם כָּךְ - וַיִּטְבְּלוּ אֶת הַכֻּתֹּנֶת בַּדָּם, הִקְרִיבוּ לוֹ כֻּתֹּנֶת לְהַכְחִישׁ אוֹתוֹ. וְהַכֹּל זֶה כְּנֶגֶד זֶה. הוּא גָּרַם שֶׁכָּתוּב וַיֶּחֱרַד יִצְחָק חֲרָדָה גְּדֹלָה עַד מְאֹד, מִשּׁוּם כָּךְ גָּרְמוּ לוֹ שֶׁחָרַד חֲרָדָה בַּזְּמַן הַהוּא, שֶׁכָּתוּב הַכֶּר נָא הַכְּתֹנֶת בִּנְךְ הִיא אִם לֹא."]]],[["רִבִּי חִיָּיא אָמַר, בֵּיהּ כְּתִיב, (בראשית כ״ז:כ״א) הַאַתָּה זֶה בְּנִי עֵשָׂו אִם לֹא. לֵיהּ כְּתִיב, הַכְּתֹנֶת בִּנְךָ הִיא אִם לא. וּבְּגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא מְדַקְדֵּק בְּהוּ בְּצַדִּיקַיָא בְּכָל מַה דְּאִינוּן עָבְדִין.","רִבִּי אַבָּא אָמַר, (נ\"א אמרז רבי אבא) כֵּיוָן דְּחָמוּ כֻּלְּהוּ שִׁבְטִין הַהוּא צַעֲרָא דְּאֲבוּהוֹן, אִתְנֶחָמוּ וַודַּאי, וִיהִיבוּ גַּרְמַיְיהוּ עֲלֵיהּ דְּיוֹסֵף, דְּיִפְדוּן לֵיהּ אִלְמָלֵא יִשְׁכְּחוּן לֵיהּ. כֵּיוָן דְּחָמוּ דְּלָא יָכִילוּ, אַהֲדָרוּ לְגַבֵּיהּ דִּיהוּדָה וְאַעֲבָרוּ לֵיהּ מֵעֲלַיְיהוּ, בְּגִין דְּאִיהוּ הֲוָה מַלְכָּא עֲלַיְיהוּ. (וכדין ס\"א וכיון ד) אַעֲבָרוּהוּ מֵעֲלַיְיהוּ, מַה כְּתִיב, וַיְהִי בָּעֵת הַהִיא וַיֵּרֶד יְהוּדָה וְגו'.","רִבִּי יְהוּדָה פָּתַח וְאֲמַר, (תהילים י״ח:י״ד) וַיַּרְעֵם בַּשָּׁמַיִם יְיָ וְעֶלְיוֹן יִתֵּן קוֹלוֹ בָּרָד וְגַחֲלֵי אֵשׁ. תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, אַתְקִין לֵיהּ שִׁבְעָה סְמָכִין עַל מַה דְּקָיְימָא, וְכֻלְּהוּ סְמָכִין קָיְימֵי בְּחַד סָמְכָא יְחִידָאי, וְהָא אוּקְמוּהָ. דִּכְתִיב, (משלי ט׳:א׳) חַכְמוֹת נָשִׁים בָּנְתָה בֵיתָהּ חָצְבָה עַמּוּדֶיהָ שִׁבְעָה. וְאִלֵּין כֻּלְּהוּ אִינוּן קָיְימֵי בְּחַד דַּרְגָּא מִנַּיְיהוּ דְּאִקְרֵי (משלי י׳:כ״ה) צַדִּיק יְסוֹד עוֹלָם.","וְעַלְמָא כַּד אִתְבְּרֵי, מֵהַהוּא אֲתַר אִתְבְּרֵי. דְּאִיהוּ שִׁכְלוּלָא דְּעַלְמָא, וְתִקּוּנוֹי. דְּאִיהוּ חַד נְקוּדָה דְעַלְמָא, וְאֶמְצָעִיתָא דְכֹלָּא. וּמַאן אִיהוּ, צִיּוֹן. דִּכְתִיב, (תהילים נ׳:א׳) מִזְמוֹר לְאָסָף אֵל אֱלֹהִים יְיָ דִּבֶּר וַיִּקְרָא אֶרֶץ מִמִּזְרַח שֶׁמֶשׁ עַד מְבוֹאוֹ. וּמֵאָן אֲתַר, מִצִּיּוֹן, דִּכְתִיב מִצִּיּוֹן מִכְלַל יוֹפִי אֱלֹהִים הוֹפִיעַ. מֵהַהוּא אֲתַר דְּאִיהוּ סִטְרָא דְּשִׁכְלוּלָא דִּמְהֵימְנוּתָא שְׁלֵימָתָא כְּדְקָא יְאוּת (והשתא (עי' קמא א כי שם מקומו) ישראל אתתקפו ביה ברזי דפקודי דאורייתא בגין דכל יומא ויומא אתתקף בר נש בציצית דאתעטף ביה). וְצִיּוֹן תַּקִּיפוּ וּנְקוּדָה דְּכָל עַלְמָא, וּמֵהַהוּא אֲתַר אִשְׁתַּכְלַל כָּל עַלְמָא וְאִתְעֲבִיד, וּמִגַּוֵּיהּ כָּל עַלְמָא אִתְּזָן.","וְתָּא חֲזֵי, וַיַּרְעֵם בַּשָּׁמַיִם יְיָ וְעֶלְיוֹן יִתֵּן קוֹלוֹ וְגו', כֵּיוָן דְּאָמַר וַיַּרְעֵם בַּשָּׁמַיִם יְיָ, אַמַּאי כְּתִיב וְעֶלְיוֹן יִתֵּן קוֹלוֹ. הָא (ס\"א אלא) הָכָא רָזָא דִּמְהֵימְנוּתָא, (ועל מה ס\"א עלמא) דְּאֲמִינָא דְּצִיּוֹן אִיהוּ שִׁכְלוּלָא וְשַׁפִּירוּ דְּעַלְמָא, וְעַלְמָא מִנֵּיהּ אִתְּזָן. בְּגִין דִּתְרֵין דַּרְגִּין אִינוּן וְאִינוּן חַד, אִינוּן צִיּוֹן וִיְרוּשָׁלַם. דָּא דִינָא וְדָא רַחֲמֵי, וְתַרְוַיְיהוּ חַד, מֵהָכָא דִּינָא וּמֵהָכָא רַחֲמֵי.","מֵעֵילָא לְעֵילָא נָפְקָא קוֹל דְּאִשְׁתְּמַע, לְבָתַר דְּהַהוּא קוֹל נָפְקָא וְאִשְׁתְּמַע נָפְקֵי דִינִין וְאָרְחֵי דְּדִינָא, וְרַחֲמֵי נָפְקִין וּמִתְפָּרְשָׁן מִתַּמָּן. וַיַּרְעֵם בַּשָּׁמַיִם יְיָ, דָּא בֵּי דִינָא בְּרַחֲמֵי. וְעֶלְיוֹן, אַף עַל גַּב דְּלָא אִשְׁתַּכַּח וְלָא אִתְיְידַע, כֵּיוָן דְּהַהוּא קוֹל נָפִיק כְּדֵין אִשְׁתַּכַּח כֹּלָּא, דִּינָא וְרַחֲמֵי. הֲדָא הוּא דִכְתִיב וְעֶלְיוֹן יִתֵּן קוֹלוֹ, כֵּיוָן דְּיִתֵּן קוֹלוֹ, כְּדֵין בָּרָד וְגַחֲלֵי אֵשׁ, מַיָא וְאֶשָׁא.","תָּא חֲזֵי, בְּשַׁעְתָּא דְּאִתְיְלִיד יְהוּדָה מַה כְּתִיב, (בראשית כט) וַתַּעֲמֹד מִלֶּדֶת, בְּגִין דְּדָא הוּא יְסוֹדָא רְבִיעָאָה מֵאִינוּן אַרְבַּע דְּאִינוּן רְתִיכָא עִלָּאָה, סַמְכָא חַד מֵאִינוּן אַרְבַּע סַמְכִין. מַה כְּתִיב בֵּיהּ, וַיְהִי בָּעֵת הַהִיא וַיֵּרֶד יְהוּדָה מֵאֵת אֶחָיו, דְּהֲוָה מַלְכָּא עֲלַיְיהוּ. מַאי טַעְמָא, בְּגִין דְּיוֹסֵף נָחֲתוּ לֵיהּ לְמִצְרַיִם כִּדְקָאֲמָרָן:","וַיַּרְא שָׁם יְהוּדָה בַּת אִישׁ כְּנַעֲנִי. וְכִי כְּנַעֲנִי הֲוָה, אֶלָּא הָא אוּקְמוּהָ חַבְרַיָּיא. וַתַּהַר וַתֵּלֶד בֵּן וַיִּקְרָא אֶת שְׁמוֹ עֵר, תְּלַת בְּנִין הֲווּ לֵיהּ לִיהוּדָה, וְלָא אִשְׁתָּאֲרוּ מִנַּיְיהוּ בַּר חַד, וְדָא הוּא שֵׁלָה.","רִבִּי אֶלְעָזָר וְרִבִּי יוֹסֵי וְרִבִּי חִיָּיא הֲווּ אָזְלֵי בְּאָרְחָא. אָמַר רִבִּי יוֹסֵי לְרִבִּי אֶלְעָזָר, אַמַּאי כְּתִיב בִּבְנוֹי דִּיהוּדָה, בְּקַדְמָאָה וַיִּקְרָא אֶת שְׁמוֹ עֵר, וּבִתְרֵין אָחֳרָנִין כְּתִיב וַתִּקְרָא אֶת שְׁמוֹ אוֹנָן, וַתִּקְרָא אֶת שְׁמוֹ שֵׁלָה.","אָמַר לֵיהּ תָּא חֲזֵי, הַאי פָּרְשָׁתָא רָזָא עִלָּאָה אִיהוּ, וְכֹלָּא אִיהוּ כְּדְקָא חָזֵי. וַיֵּרֶד יְהוּדָה מֵאֵת אֶחָיו, דְּהָא אִתְכַּסְיָא סִיהֲרָא, וְנָחֲתַת מִדַּרְגָּא דְּתִקֻּנָּא לְגוֹ דַּרְגָּא אוֹחֲרָא, דְּאִתְחַבַּר בֵּיהּ חִוְּיָא, כְּמָה דְאַתְּ אָמֵר וַיֵּט עַד אִישׁ עֲדֻלָּמִי וּשְׁמוֹ חִירָה.","וַתַּהַר וַתֵּלֶד בֵּן וַיִּקְרָא אֶת שְׁמוֹ עֵר, וְאִיהוּ רַע, וְכֹלָּא חַד, דְּאַתְיָא מִסִּטְרָא דְיֵצֶר הָרָע. וּבְגִין כָּךְ כְּתִיב וַיִּקְרָא אֶת שְׁמוֹ, וְלָא כְּתִיב וַיִּקְרָא שְׁמוֹ. בְּיַעֲקֹב כְּתִיב וַיִּקְרָא שְׁמוֹ, דְּקוּדְשָׁא בְּרִיךְ הוּא קָרָא לֵיהּ יַעֲקֹב. וְהָכָא אֶת לְאַסְגָּאָה דַּרְגָּא אָחֳרָא דְּזוּהֲמָא דִּמְסָאֲבָא אִתְיְלִיד, וְדָא הוּא עֵר רַע, וְכֹלָּא חַד."],[[0,"ר' חייא אמר וכו':","רח\"א, בו כתוב, האתה זה בני עשו אם לא, ואליו כתוב, שאמרו לו, הכתנת בנך הוא אם לא, והוא משום שהקב\"ה מדקדק עם הצדיקים בכל מה שהם עושים."],[1,"רבי אבא אמר וכו':","רא\"א, כיון שראו כל השבטים אותו הצער של אביהם, התחרטו ודאי על מכירת יוסף, ונתנו נפשם על יוסף לפדותו, אם ימצאו אותו, כיון שראו שאינם יכולים לפדותו, חזרו אל יהודה, שנתן להם עצה למכרו, והעבירו אותו מעליהם, כי הוא היה מלך עליהם, וכיון שהעבירוהו מעליהם, מה כתוב, ויהי בעת ההוא וירד יהודה וגו'."],[2,"ר' יהודה וכו':","ר\"י פתח ואמר, וירעם בשמים ה' וגו'. בוא וראה, כשברא הקב\"ה את העולם,דהיינו כשהאציל את הנוקבא הנקראת \u0003עולם,\u0004 התקין לו שבעה עמודים, שהאיר לה מז' ספירות חג\"ת נהי\"מ דז\"א, וכל העמודים עומדים על עמוד אחד יחידי דהיינו יסוד דז\"א. וביארוה במה שכתוב, חכמות בנתה ביתה חצבה עמודיה שבעה, ואלו כולם עומדים על מדרגה אחת מהם, שנקראת צדיק יסוד עולם. שהוא יסוד דז\"א."],[3,"ועלמא כד אתברי וכו':","והעולם כשנברא, נברא מאותו מקום, שהוא שכלול העולם ותקוניו, שהוא נקודה אחת של העולם ושהיא אמצעית הכל, ומי היא. הוא \u0003ציון,\u0004 שהיא יסוד הפנימי דנוקבא, שכתוב \u0003מזמור לאסף אל אלהים הוי\"ה דבר ויקרא ארץ ממזרח שמש עד מבואו.\u0004 ומאיזה מקום דבר, מציון, שכתוב, \u0003מציון מכלל יופי אלקים הופיע,\u0004 מאותו מקום, שהיא בחינת השכלול של אמונה השלמה כראוי. וציון היא חזקתו, שה\"ס הארת החכמה, ונקודתו, שה\"ס הארת החסדים, של כל העולם, ומאותו מקום נשתכלל ונעשה כל העולם, דהיינו בחכמה שבה, ומתוכה כל העולם ניזון, דהיינו בחסדים שבה."],[4,"ות\"ח וירעם בשמים ה' וגו':","ושואל, כיון שאמר וירעם בשמים ה', למה כתוב ועליון יתן קולו, שהוא מיותר, ומשיב, אלא כאן סוד האמונה שאמרתי, שציון, הוא השכלול והיופי של העולם, והעולם ממנו ניזון. דהיינו שיש בה ב' בחינות, חכמה וחסדים, כנ\"ל, הוא. משום ששתי מדרגות הן, והן אחד, שהן ציון וירושלים, זו דין וזו רחמים, ושתיהם הן אחת, מכאן דין ומכאן רחמים."],[4,"","פירוש. ציון וירושלים שתיהן הן בחינת יסוד הנוקבא, אלא ציון ה\"ס פנימיות היסוד, וה\"ס מלכותא דדוד, שנמשכת ממנה החכמה, (עי' לעיל ב\"א דף ק\"י ד\"ה מלכותא) והיא בחינת רחמים כלפי ירושלים. וירושלים ה\"ס חצוניות היסוד דנוקבא, ששם המסך וע\"כ הוא דין. וז\"ש \u0003ותרוייהו חד\u0004, ששניהם הם בחינת יסוד דנוקבא, \u0003מהכא דינא\u0004, היינו מירושלים, \u0003ומהכא רחמי\u0004 היינו מציון. ולפיכך, \u0003ציון איהו שכלולא ושפירו דעלמא,\u0004 היינו רק אחר שהחכמה שבה מתלבשת בחסדים של ירושלים, ונמצא שמ\"ש, \u0003דעלמא מניה אתזן\u0004, היינו מירושלים שבה החסדים, היוצאים על המסך."],[5,"מעילא לעילא נפקא וכו':","ממעלה ולמעלה דהיינו מבינה, יוצא קול הנשמע, שהוא עמוד האמצעי המכריע בבינה, ואחר שקול ההוא יוצא ונשמע, שמכריע גם בנוקבא, והאורות דימין ושמאל נשמעים, דהיינו שמאירים, כמ\"ש לעיל, (פרשת לך דף ד' ד\"ה בשעתא עש\"ה.) יוצאים הדינים מן נוקבא, ודרכי דין ורחמים יוצאים ומפורשים משם. פירוש, הדינים מסתלקים בסבת הכרעת קו אמצעי, והמוחין מאירים בדרכים של דין ורחמים שביסוד דנוקבא, שבדרכי הרחמים \u0003שבציון\u0004 מאירה החכמה, ובדרכי הדין \u0003שבירושלים\u0004 מאירים החסדים."],[5,"וירעם בשמים ה' וגו':","זהו בית דין ברחמים, דהיינו בחינת הדינין שבציון שהם דינין דשמאל, שכלפי דינין שבירושלים הוא רחמים, \u0003ועליון,\u0004 דהיינו בינה, אע\"פ שאינו נמצא ואינו נודע מטרם ביאת קו אמצעי, מחמת הדינין שבשמאל, כיון שאותו הקול יוצא ומכריע בין ימין ושמאל, אז נמצא הכל בדין ורחמים. דהיינו שמקיים הארת ב' הקוין ימין ושמאל. וזהו שכתוב, \u0003ועליון יתן קולו, כיון דיתן קולו\u0004 כיון שהעליון שהיא בינה נותן קולו אל הנוקבא, ומכריע בב' קוין שלה, אז \u0003ברד וגחלי אש,\u0004 שהם מים ואש."],[5,"","פירוש, עם ביאת הקול, שהוא קו אמצעי, מבינה אל הנוקבא, מסתלקים הדינים ומתגלים המוחין על דרכי הדין ורחמים שבה, כנ\"ל, שדרכי הרחמים שהם \u0003בציון\u0004 מכונים \u0003ברד,\u0004 ושם מתגלה החכמה. ודרכי הדין שהם \u0003בירושלים,\u0004 מכונים גחלי אש. ששם מתגלים החסדים."],[6,"ת\"ח בשעתא וכו':","בוא וראה בשעה שנולד יהודה מה כתוב, \u0003ותעמוד מלדת,\u0004 משום שזה, הוא יסוד הרביעי מארבע יסודות, הנקראים חסד וגבורה ות\"ת ומלכות, שהם מרכבה עליונה, אל הבינה, והוא רגל אחד מאלו ארבע רגלים של הכסא, שהוא המלכות. כמ\"ש לעיל (וירא דף ה' ד\"ה ואע\"ג ע\"ש) ועל כן כתוב בו \u0003ותעמוד מלדת,\u0004 להיותו ספירה אחרונה מלכות. מה כתוב בו, ויהי בעת ההוא וירד יהודה מאת אחיו, כי היה מלך עליהם להיותו ספירת המלכות, ואחר מכירת יוסף ירד מגדולתו. מה הטעם, הוא משום שהורידו את יוסף למצרים כמו שאמרנו."],[6,"","פירוש, כי יוסף ה\"ס קו אמצעי המאיר אל המלכות שה\"ס יהודה, וכשהוא מאיר בה מסתלקים הדינים מיסוד שלה הנקרא ציון וירושלים, והמוחין מאירים על דרכי הדין ורחמים שלה שבציון מאירה החכמה ובירושלים החסדים כנ\"ל, אבל כשנמכר יוסף למצרים, ואינו מאיר לה או חזרה המלכות לבחינת שמאל, והדינין שבציון המכונים \u0003ברד\u0004 שולטים בה, וע\"כ כתוב \u0003וירד\u0004 יהודה, כי \u0003ירד\u0004 מגדולתו ונפל לבחינת הדינין \u0003דברד.\u0004"],[7,"וירא שם יהודה בת איש כנעני:","שואל, וכי כנעני היה, הלא האבות לא היו מתחתנים בכנענים. ואומר, אלא ככר בארוה החברים. אשר כנעני פירושו סוחר. (עי' פסחים נ.) \u0003ותהר ותלד בן ויקרא וגו':\u0004 ג' בנים היו לו ליהודה, ולא נשאר מהם רק אחד, וזהו שלה. כלומר, שהוא בכלל הכתוב וירד יהודה, כי הוליד בנים וקברם שהוא ירידה גדולה ועונש."],[8,"ר' אלעזר וכו':","ר\"א ור' יוסי ור' חייא היו מהלכים בדרך. אמר ר' יוסי לר' אלעזר, למה כתוב בראשון מבניו של יהודה, ויקרא את שמו ער, בלשון זכר, ובשני בנים האחרים כתוב, ותקרא את שמו אונן, ותקרא את שמו שלה, בלשון נקבה."],[9,"א\"ל תא חזי וכו':","אמר לו בוא וראה, פרשה זו היא סוד עליון והכל הוא כמו שראוי להיות. \u0003וירד יהודה מאת אחיו,\u0004 כי הלבנה, שהיא הנוקבא, נתכסה וירדה ממדרגה הישרה, לתוך מדרגה אחרת שהנחש נתחבר בה. כמו שאתה אומר, ויט עד איש עדלמי ושמו חירה, פירוש, שפירש עצמו מאחיו בית ישראל שהם הקדושה, ונתחבר באיש נכרי שלא מבית ישראל הוא, שהנחש דבוק בו, שלא פסקה הזוהמא שלו מן הנכרים."],[10,"ותהר ותלד בן ויקרא את שמו ער:","והוא רע, והכל אחד, כלומר, אשר \u0003ער ורע\u0004 אותיותיהם שוות. כי בא מצד היצר הרע. ומשום זה כתוב ויקרא \u0003את\u0004 שמו, ולא כתוב ויקרא שמו. ביעקב כתוב ויקרא שמו, כי הקב\"ה קרא אותו יעקב. וכאן כתוב \u0003את\u0004 שמו והוא לרבות מדרגה אחרת של זוהמת הטומאה שנולד, וזהו \u0003ער רע\u0004 שהכל אחד כלומר, שאותיותיהן שוות."]],[[0,"","רַבִּי חִיָּיא אָמַר, כָּתוּב בּוֹ (שם) הַאַתָּה זֶה בְּנִי עֵשָׂו אִם לֹא - לוֹ כָּתוּב, הַכְּתֹנֶת בִּנְךְ הִיא אִם לֹא. וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְדַקְדֵּק עִם הַצַּדִּיקִים בְּכָל מַה שֶּׁהֵם עוֹשִׂים."],[1,"","רַבִּי אַבָּא אָמַר (נ\"א: אמר רבי אבא), כֵּיוָן שֶׁכָּל הַשְּׁבָטִים רָאוּ אוֹתוֹ הַצַּעַר שֶׁל אֲבִיהֶם, וַדַּאי הִתְנַחֲמוּ וְנָתְנוּ עַצְמָם עַל יוֹסֵף שֶׁיִּפְדּוּ אוֹתוֹ אִלְמָלֵא יִמְצְאוּ אוֹתוֹ. כֵּיוָן שֶׁרָאוּ שֶׁלֹּא יְכוֹלִים, חָזְרוּ אֶל יְהוּדָה וְהֶעֱבִירוּ אוֹתוֹ מֵעֲלֵיהֶם, מִשּׁוּם שֶׁהוּא הָיָה מֶלֶךְ עֲלֵיהֶם, (ואז ס\"א וכיון ש) הֶעֱבִירוּהוּ מֵעֲלֵיהֶם, מַה כָּתוּב? וַיְהִי בָּעֵת הַהִיא וַיֵּרֶד יְהוּדָה וְגוֹ'."],[2,"","רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים יח) וַיַּרְעֵם בַּשָּׁמַיִם ה' וְעֶלְיוֹן יִתֵּן קוֹלוֹ בָּרָד וְגַחֲלֵי אֵשׁ. בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הִתְקִין לוֹ שִׁבְעָה עַמּוּדִים עַל מַה שֶּׁעוֹמֵד, וְכָל הָעַמּוּדִים עוֹמְדִים בְּעַמּוּד אֶחָד יְחִידִי, וַהֲרֵי פֵּרְשׁוּהָ שֶׁכָּתוּב (משלי ט) חָכְמוֹת בָּנְתָה בֵיתָהּ חָצְבָה עַמּוּדֶיהָ שִׁבְעָה, וְכָל אֵלֶּה הֵם עוֹמְדִים בְּדַרְגָּה אַחַת מֵהֶם שֶׁנִּקְרֵאת (שם י) צַדִּיק יְסוֹד עוֹלָם."],[3,"","וּכְשֶׁנִּבְרָא הָעוֹלָם, נִבְרָא מֵאוֹתוֹ הַמָּקוֹם שֶׁהוּא הַשְּׁלֵמוּת שֶׁל הָעוֹלָם וְתִקּוּנוֹ, שֶׁהוּא נְקֻדָּה אַחַת שֶׁל הָעוֹלָם וְהָאֶמְצַע שֶׁל הַכֹּל, וּמִי הוּא? צִיּוֹן, שֶׁכָּתוּב (תהלים נ) מִזְמוֹר לְאָסָף אֶל אֱלֹהִים ה' דִּבֶּר וַיִּקְרָא אָרֶץ מִמִּזְרַח שֶׁמֶשׁ עַד מְבֹאוֹ. וּמֵאֵיזֶה מָקוֹם? מִצִּיּוֹן, שֶׁכָּתוּב מִצִּיּוֹן מִכְלַל יֹפִי אֱלֹהִים הוֹפִיעַ. מֵאוֹתוֹ הַמָּקוֹם שֶׁהוּא צַד הַשְּׁלֵמוּת שֶׁל הָאֱמוּנָה הַשְּׁלֵמָה כָּרָאוּי (וכעת ישראל החזיקו בו בסודות המצוות של התורה, משום שכל יום ויום מחזיק אדם בציצית שמתעטף בה), וְצִיּוֹן הַחֹזֶק וְהַנְּקֻדָּה שֶׁל כָּל הָעוֹלָם, וּמֵהַמָּקוֹם הַהוּא נִתְקַן כָּל הָעוֹלָם וְנַעֲשָׂה, וּמִתּוֹכוֹ נִזּוֹן כָּל הָעוֹלָם."],[4,"","וּבֹא וּרְאֵה, וַיַּרְעֵם בַּשָּׁמַיִם ה' וְעֶלְיוֹן יִתֵּן קוֹלוֹ וְגוֹ'. כֵּיוָן שֶׁאָמַר וַיַּרְעֵם בַּשָּׁמַיִם ה', לָמָּה כָּתוּב וְעֶלְיוֹן יִתֵּן קוֹלוֹ? הִנֵּה (ס\"א אלא) כָּאן סוֹד הָאֱמוּנָה (על מה עולם) שֶׁאָמַרְנוּ שֶׁצִּיּוֹן הִיא הַשְּׁלֵמוּת וְהַיֹּפִי שֶׁל הָעוֹלָם, וְהָעוֹלָם נִזּוֹן מִמֶּנּוּ, מִשּׁוּם שֶׁשְּׁתֵּי דְרָגוֹת הֵן, וְהֵן אַחַת, הֵם צִיּוֹן וִירוּשָׁלַיִם, זֶה דִּין וְזֶה רַחֲמִים, וּשְׁנֵיהֶם אֶחָד, מִכָּאן דִּין וּמִכָּאן רַחֲמִים."],[5,"","מִמַּעִִלָה לְמַעְלָה יוֹצֵא קוֹל שֶׁנִּשְׁמָע. לְאַחַר שֶׁאוֹתוֹ הַקּוֹל יוֹצֵא וְנִשְׁמָע, אָז יוֹצְאִים הַדִּינִים וְדַרְכֵי הַדִּין, וְהָרַחֲמִים יוֹצְאִים וְנִפְרָדִים מִשָּׁם. וַיַּרְעֵם בַּשָּׁמַיִם ה', זֶה בֵּית הַדִּין בְּרַחֲמִים. וְעֶלְיוֹן, אַף עַל גַּב שֶׁאֵינוֹ נִמְצָא וְאֵינוֹ נוֹדָע, כֵּיוָן שֶׁהַקּוֹל הַהוּא יוֹצֵא, אָז נִמְצָא הַכֹּל, דִּין וְרַחֲמִים. זֶהוּ שֶׁכָּתוּב וְעֶלְיוֹן יִתֵּן קוֹלוֹ. כֵּיוָן שֶׁיִּתֵּן קוֹלוֹ, אָז בָּרָד וְגַחֲלֵי אֵשׁ, מַיִם וְאֵשׁ."],[6,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁנּוֹלַד יְהוּדָה, מַה כָּתוּב? (בראשית כט) וַתַּעֲמֹד מִלֶּדֶת, מִשּׁוּם שֶׁזֶּה הוּא הַיְסוֹד הָרְבִיעִי מֵאוֹתָם הָאַרְבָּעָה שֶׁהֵם הַמֶּרְכָּבָה הָעֶלְיוֹנָה, עַמּוּד אֶחָד מֵאוֹתָם אַרְבָּעָה הָעַמּוּדִים, מַה כָּתוּב בּוֹ? וַיְהִי בָּעֵת הַהִיא וַיֵּרֶד יְהוּדָה מֵאֵת אֶחָיו, שֶׁהָיָה מֶלֶךְ עֲלֵיהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁהוֹרִידוּ אֶת יוֹסֵף לְמִצְרַיִם, כְּמוֹ שֶׁאָמַ רְנוּ."],[7,"","וַיַּרְא שָׁם יְהוּדָה בַּת אִישׁ כְּנַעֲנִי, וְכִי כְּנַעֲנִי הָיָה? אֶלָּא הִנֵּה פֵּרְשׁוּהוּ הַחֲבֵרִים. וַתַּהַר וַתֵּלֶד בֵּן וַיִּקְרָא אֶת שְׁמוֹ עֵר. שְׁלֹשָׁה בָנִים הָיוּ לִיהוּדָה, וְלֹא נִשְׁאַר מֵהֶם רַק אֶחָד, וְזֶה הוּא שֵׁלָה."],[8,"","רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבִּי אֶלְעָזָר, לָמָּה כָּתוּב בִּבְנֵי יְהוּדָה, בָּרִאשׁוֹן - וַיִּקְרָא אֶת שְׁמוֹ עֵר, וּבִשְׁנֵי הָאֲחֵרִים כָּתוּב, וַתִּקְרָא אֶת שְׁמוֹ אוֹנָן, וַתִּקְרָא אֶת שְׁמוֹ שֵׁלָה?"],[9,"","אָמַר לוֹ, בּא רְאֵה, הַפָּרָשָׁה הַזּוֹ הִיא סוֹד עֶלְיוֹן, וְהַכֹּל הוּא כָּרָאוּי. וַיֵּרֶד יְהוּדָה מֵאֵת אֶחָיו, שֶׁהִנֵּה נִכְסְתָה הַלְּבָנָה וְיָרְדָה מֵהַדַּרְגָּה שֶׁל תִּקּוּן לְתוֹךְ דַּרְגָּה אַחֶרֶת, שֶׁהִתְחַבֵּר בָּהּ הַנָּחָשׁ, כְּמוֹ שֶׁנֶּאֱמַר וַיֵּט עַד אִישׁ עֲדֻלָּמִי וּשְׁמוֹ חִירָה."],[10,"","וַתַּהַר וַתֵּלֶד בֵּן וַיִּקְרָא אֶת שְׁמוֹ עֵר, וְהוּא רַע, וְהַכֹּל אֶחָד, שֶׁבָּא מִצַּד הַיֵּצֶר הָרָע, וּמִשּׁוּם כָּךְ כָּתוּב וַיִּקְרָא אֶת שְׁמוֹ וְלֹא כָתוּב וַיִּקְרָא שְׁמוֹ. בְּיַעֲקֹב כָּתוּב וַיִּקְרָא שְׁמוֹ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לוֹ יַעֲקֹב, וְכָאן אֶת - לְרַבּוֹת דַּרְגָּה אַחֶרֶת שֶׁזֻּהֲמַת הַטֻּמְאָה נוֹלַד, וְזֶה הוּא עֵר רַע, וְהַכֹּל אֶחָד."]]],[["לְבָתַר לָא אִתְבַּסַּם אַתְרָא, עַד דְאֲתָא שֵׁלָה דְּהֲוָה עִקָּרָא דְּכֻלְּהוּ. מַה כְּתִיב וַיְהִי עֵר בְּכֹר יְהוּדָה רַע בְּעֵינִי יְיָ, כְּתִיב הָכָא רַע, וּכְתִיב הָתָם (בראשיתח) כִּי יֵצֶר לֵב הָאָדָם רַע מִנְעוּרָיו, רַע דְּאוֹשִׁיד דָּמִין, אוֹשִׁיד זַרְעָא עַל אַרְעָא. וּבְגִין כָּךְ וַיְמִיתֵהוּ יְיָ. מַה כְּתִיב בַּתְרֵיהּ, וַיֹּאמֶר יְהוּדָה לְאוֹנָן בֹּא אֶל אֵשֶׁת אָחִיךָ וְגו':","וַיֹּאמֶר יְהוּדָה לְאוֹנָן בֹּא אֶל אֵשֶׁת אָחִיךָ וְגו'. רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ישעיהו מ״א:כ״ה) הַעִירוֹתִי מִצָּפוֹן וַיַּאֲת מִמִּזְרַח שֶׁמֶשׁ יִקְרָא בִשְׁמִי וְיָבֹא סְגָנִים כְּמוֹ חֹמֶר וּכְמוֹ יוֹצֵר יִרְמָס טִיט. תָּא חֲזֵי, כַּמָּה אִינוּן בְּנִי נָשָׁא טִפְּשִׁין דְּלָא יָדְעִין וְלָא מִסְתַּכְּלִין לְמִנְדַע אָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא. דְּהָא כֻּלְּהוּ נַיְימִין, דְּלָא מִתְעָרֵי שֵׁינְתָא בְּחוֹרֵיהוֹן.","תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא עֲבַד לֵיהּ לְבַר נָשׁ, כְּגַוְונָא דִלְעֵילָא. כֹּלָּא אִיהוּ בְּחָכְמְתָא. דְּלֵית לָךְ שַׁיְיפָא וְשַׁיְיפָא בְּבַר נָשׁ דְּלָא קָיְימָא בְּחָכְמְתָא עִלָּאָה. דְּהָא כֵּיוָן דְּאִתְתַּקַּן כָּל גּוּפָא בְּשַׁיְיפוֹי כְּדְקָא יְאוּת, קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתַּתַּף (נ\"א אתתקף) בַּהֲדֵיהּ, וְאָעִיל בֵּיהּ נִשְׁמָתָא קַדִּישָׁא. בְּגִין לְאוֹלָפָא לֵיהּ לְבַר נָשׁ לְמֵהַךְ בְּאָרְחוֹי דְּאוֹרַיְיתָא וּלְמִיטַר פִּקּוּדוֹי, בְּגִין דְּיִתְתַּקַּן בַּר נָשׁ כְּדְקָא יְאוּת.","(ס\"א ובגין דא בעוד) (ובגין ס\"א ובעוד) דְּאִית בֵּיהּ נִשְׁמָתָא קַדִּישָׁא מִבָּעֵי לֵיהּ לְבַר נָשׁ לְאַסְגָּאָה דִּיוּקְנָא דְמַלְכָּא עִלָּאָה בְּעַלְמָא. וְרָזָא דָא, דְּהָא הַהוּא נָהָר דְּנָגִיד וְנָפִיק לָא פָּסְקָן מֵימוֹי לְעָלְמִין. וְעַל דָּא מִבָּעֵי לֵיהּ לְבַר נָשׁ דְּלָא יַפְסִיק נַהֲרָא וּמְקוֹרָא דִּילֵיהּ בְּהַאי עָלְמָא (גליון נה\"ר רמז לקיימא קדישא דחתים בבשריה, דאיהו דוגמא דההוא נה\"ר רזא דצדיק דאתחבר בצד\"ק כחדא לעילא, בגין כך בעי בר נש לתתא לאתחברא באתתיה בקדושה בגין דאתתקף ביה בההוא עלמא). וְכָל זִמְנָא דְּבַר נָשׁ לָא יַצְלַח בְּהַאי עַלְמָא (ס\"א ועל דא מבעי ליה לבר נש דלא יפסיק נהרא ומקורא דיליה בהאי עלמא, ואי לא) קוּדְשָׁא בְּרִיךְ הוּא עָקַר לֵיהּ וְנָטַע לֵיהּ בְּכַמָּה זִמְנִין כְּמִלְּקַדְּמִין.","תָּא חֲזֵי, מַה כְּתִיב, הַעִירוֹתִי מִצָּפוֹן וַיַּאת. הַעִירוֹתִי, דָּא אִתְעֲרוּתָא דְּזִוּוּגָא דְּבַר נָשׁ בְּהַאי עַלְמָא, דְּאִיהוּ אִתְעֲרוּתָא מִסִּטְרָא דְצָפוֹן. וַיַאת, דָּא הִיא נִשְׁמָתָא קַדִּישָׁא דְּאַתְיָא מִלְּעֵילָא, וְקוּדְשָׁא בְּרִיךְ הוּא מְשַׁדֵּר לָהּ מִלְּעֵילָא. אַתְיָא בְּהַאי עַלְמָא וְעָאלַת בְּגוֹ בְּנֵי נָשָׁא כִּדְקָאֲמָרָן.","מִמִּזְרַח שֶׁמֶשׁ, דָּא אֲתַר דְּהַהוּא נָהָר דְּנָגִיד וְנָפִיק דְּמִתַּמָּן נָפְקַת נִשְׁמָתָא וְאִתְנְהִירַת. וְיָבֹא סְגָנִים (כמו חמר) אִלֵּין אִינוּן חֵילִין דְּעָלְמָא דְּאַתְיָין בְּגִין (ס\"א בגו) הַהוּא אִתְעֲרוּתָא דְּנִשְׁמָתִין. כְּמוֹ חוֹמֶר, כְּגַוְונָא דְּאִתְעַר בַּר נָשׁ בְּגוּפָא.","דְּהָא בְּגִין דָּא, קוּדְשָׁא בְּרִיךְ הוּא עָבִיד זִווּגִין וְאַטִּיל נִשְׁמָתִין בְּעַלְמָא, וְחַבְרוּתָא אִשְׁתַּכַּח לְעֵילָא וְתַתָּא וּמְקוֹרָא דְּכֹלָּא הוּא (ס\"א יהא) בָּרוּךְ. וּבְּגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא עֲבַד לֵיהּ לְבַר נָשׁ בְּגִין לְאִשְׁתַּדָּלָא בְּאָרְחוֹי, וְלָא יַפְסִיק מְקוֹרֵיהּ וּמַבּוּעָא דִילֵיהּ לְעָלְמִין.","וְכָל מַאן דְּפָסִיק מְקוֹרֵיהּ, (מתתא ומיבש ליה כביכול כאלו גרים ליה לאתפסקא לעילא, כדין (איוב י״ד:י״א) אזלו מים מני ים ונהר יחרב ויבש, הואיל ובר נש אתקם לתתא כדוגמא דלעילא, מאן דמקוריה ימיש מלמעבד פירין, כגון דין דלא בעא למיתב איתתא, או נסיב לה דאשתדל ולא יכיל, אלו דתרין הפכין אינון דא מדא, (או ס\"א ההוא) דימיש מלמעבד פירין, לית ליה תקנה לעולם. (קהלת א׳:ט״ו) מעוות לא יכול לתקון, בגין דלא בעא למיסב איתתא ולאשתדלא בפריה ורביה, וההוא דאשתדל ונסב איתתא ולא יכיל, דא מתתקן בפריקיה דקריב ליה דהוא אחוי, וההוא דמית בלא בנין) כַּד נָפִיק מֵהַאי עַלְמָא הַהוּא בַּר נָשׁ לָא עָאל בְּפַרְגּוֹדָא וְלָא נָטִיל חוּלַק בְּהַהוּא עַלְמָא (ונשמתיה לא אתכלילת באתר דכל נשמתין אתכלילו, ואתגזר דיוקניה מתמן. הדא הוא דכתיב, (ויקרא כ״ב:ג׳) ונכרתה הנפש ההיא מלפני, הואיל וכדין הוא, ברא ליה קודשא בריך הוא פריק דיפרוק ליה מידא דמחבלין, ודא אחוי דקריב ליה שנאמר (דברים כ״ה:ה׳) כי ישבו אחים יחדיו וגו'. וכתיב בא אל אשת אחיך ויבם אותה וגו'. בגין דנשמתיה לא עאלת קמיה קודשא בריך הוא, אלא היא קימא לבר. בגין דלא זכה לאנהרא בהאי עלמא בההוא גופא. מאן דלא זכה בהאי אתר, יהך לאתר אחרא ויזכי ביה. כגוונא דא אעא דדליק ונהורא לא סליק יבטשון ליה ויסלק נהורא ביה וינהיר. אעא הוא אדם דכתיב (שם כ) כי האדם עץ השדה. רצונו לומר בר נש כד איהו בהאי עלמא ואזל ותאיב ואכיל ושתי ואזדווג באיתתא ולא זכי לבנין. דא הוא אעא דדליק ונהורא לא סליק, כלומר נשמתיה לא זכאת בההוא גופא לאתנהרא אלא איהי בחשוכא). תָּא חֲזֵי, כְּתִיב, (ישעיהו מ״ה:י״ח) לֹא תֹהוּ בְּרָאָהּ לְשֶׁבֶת יְצָרָהּ, דְּקוּדְשָׁא בְּרִיךְ הוּא בְּגִין דָּא עֲבַד לֵיהּ לְבַר נָשׁ כְּדְקָא יְאוּת כְּדְאֲמָרָן. וְקוּדְשָׁא בְּרִיךְ הוּא עֲבַד טִיבוּ עִם עַלְמָא. תָּא חֲזֵי, מַה כְּתִיב, (בראשית כ״ה:א׳) וַיּוֹסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה, רָזָא דְּנִשְׁמָתָא אָתַת לְאִתְתַּקָּנָא כְּמִלְקַדְּמִין."],[[0,"לבתר לא אתבסם וכו':","ואחר כך גם בבן השני, לא נמתק המקום לחזור לקדושה, עד שבא שלה, שהיה עיקר כולם. מה כתוב, ויהי ער בכר יהודה רע בעיני ה' כתוב כאן \u0003רע,\u0004 וכתוב שם, כי יצר לב האדם \u0003רע\u0004 מנעוריו, מה שם פירושו, השחתת זרע אף כאן, פירושו ששפך דמים, ששפך זרע על הארץ, ומשום זה וימיתהו ה'. מה כתוב אחריו, ויאמר יהודה לאונן וגו'."],[1,"ויאמר יהודה לאונן וגו':","ר' שמעון פתח ואמר, העירותי מצפון ויאת וגו' בוא וראה, כמה הם כסילים בני אדם, שאינם יודעים ואינם מסתכלים לדעת דרכיו של הקב\"ה, כי כולם ישנים שלא תמוש שינה מחורי עיניהם."],[2,"ת\"ח קב\"ה וכו':","בוא וראה, הקב\"ה עשה את האדם כעין של מעלה, הכל בחכמה. כי אין לך אבר ואבר בבן אדם, שאינו עומד בחכמה העליונה, שכל אבר רומז על מדרגה מיוחדת, כי אחר שנתקן כל הגוף באבריו כראוי, הקב\"ה משתתף עמו, ומכניס בו נשמה קדושה, כדי ללמד האדם ללכת בדרכי התורה, ולשמור מצותיו, כדי שיתוקן האדם כראוי. דהיינו ע\"ד הכתוב, נשמת האדם תלמדנו."],[3,"ובגין דאית ביה וכו':","ומשום שיש בו נשמה קדושה הוא ראוי להוליד בנים בצלמו ודמותו ית', וע\"כ צריך האדם להרבות הדמות של מלך העליון בעולם. וזה סוד, כי להיות אותו הנהר הנמשך ויוצא, שהוא יסוד העליון, מימיו אינם נפסקים לעולם, ע\"כ צריך גם האדם, שלא יפסיק הנהר והמקור שלו, בעולם הזה, אלא שיוליד בנים."],[3,"וכל זמנא וכו':","ותמיד בזמן שהאדם אינו מצליח בעולם הזה. להוליד בנים, הקב\"ה עוקר אותו מעולם הזה, ונוטע אותו שנית כבתחילה הרבה פעמים. דהיינו שמת ומתגלגל שנית לבא בעולם הרבה פעמים, עד שמצליח להוליד בנים."],[4,"ת\"ח מה כתיב וכו':","בוא וראה, מה כתוב, העירותי מצפון ויאת. \u0003העירותי,\u0004 זהו התעוררות הזווג של האדם בעולם הזה, שהוא התעוררות מצד צפון, דהיינו משמאל, כי התעוררות הזווג משמאל בא. \u0003ויאת,\u0004 זו היא נשמה הקדושה הבאה מלמעלה, שהקב\"ה שולח אותה מלמעלה ובאה בעולם הזה, ונכנסת בבני אדם. כמו שאמרנו"],[5,"ממזרח שמש:","זה הוא מקומו של אותו הנהר הנמשך ויוצא, דהיינו ת\"ת שהוא מקומו של היסוד, שמשם יוצאת ונולדת הנשמה ומאירה. כי הנשמות מזווג תו\"מ באות. \u0003ויבא סגנים\u0004 אלו הם צבאות העולם, שהוא הנוקבא, הנק' עולם, וצבאותיה הם המלאכים, הבאים עם התעוררות הנשמות כלומר הנולדים עמהם יחד. (כנ\"ל בהקדמת ספר הזהר אות ר\"כ ע\"ש). \u0003כמו חומר,\u0004 היינו כמו שנתעורר האדם בגוף שלו, המכונה חומר."],[6,"דהא בגין דא וכו':","כי משום זה, עושה הקב\"ה זווגים ומטיל נשמות בעולם, והזווג נמצא למעלה ולמטה, ומקור הכל הוא ברוך. ועל כן עשה הקב\"ה את האדם כדי שישתדל בדרכיו, ולא יפסיק מקורו ומעיינו לעולם, אלא שיוליד בנים."],[7,"וכל מאן דפסיק וכו':","וכל מי שפסק מקורו, שלא הוליד בנים, כשנפטר מעולם הזה, לא יכנס אדם ההוא במחיצתו של הקב\"ה, ואינו נוטל חלק באותו העולם. בוא וראה, כתוב, לא תהו בראה לשבת יצרה, משום זה עשה את האדם כעין של מעלה וכו' כראוי כמו שאמרנו (לעיל אות קנ\"ו) כי הקב\"ה עושה חסר עם העולם."],[7,"ת\"ח מה כתיב וכו':","בוא וראה, כתוב, ויוסף אברהם ויקח אשה ושמה קטורה, הוא סוד, שהנשמה באה כבתחילה בגוף כדי להתתקן."],[7,"","פירוש. \u0003אברהם\u0004 ה\"ס הנשמה \u0003אשה\u0004 ה\"ס גוף, ואמרו ויוסף אברהם ויקח אשה, פירושו, שאחר שהנשמה יצאה מגוף הוסיפה לבא בגוף. והוא כדי להתתקן, מה שלא נתתקנה בהיותה בגוף הא'."]],[[0,"","אַחַר כָּךְ לֹא הִתְבַּסֵּם הַמָּקוֹם עַד שֶׁבָּא שֵׁלָה שֶׁהָיָה הָעִקָּר שֶׁל כֻּלָּם. מַה כָּתוּב? וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה'. כָּתוּב כָּאן רַע, וְכָתוּב שָׁם (בראשית ח) כִּי יֵצֶר לֵב הָאָדָם רַע מִנְּעֻרָיו. רַע שֶׁשּׁוֹפֵךְ דָּמִים, שׁוֹפֵךְ זֶרַע עַל הָאָרֶץ, וּמִשּׁוּם כָּךְ וַיְמִתֵהוּ ה'. מַה כָּתוּב אַחֲרָיו? וַיֹּאמֶר יְהוּדָה לְאוֹנָן בֹּא אֶל אֵשֶׁת אָחִיךְ וְגוֹ'."],[1,"","וַיֹּאמֶר יְהוּדָה לְאוֹנָן בּא אֶל אֵשֶׁת אָחִיךְ וְגוֹ'. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ישעיה מא) הֲעִירוֹתִי מִצָּפוֹן וַיַּאת מִמִּזְרַח שֶׁמֶשׁ יִקְרָא בִשְׁמִי וְיָבֹא סְגָנִים כְּמוֹ חֹמֶר וּכְמוֹ יוֹצֵר יִרְמָס טִיט. בּא רְאֵה כַּמָּה בְּנֵי אָדָם הֵם טִפְּשִׁים שֶׁאֵין יוֹדְעִים וְאֵין מִסְתַּכְּלִים לָדַעַת דִּבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִנֵּה כֻּלָּם יְשֵׁנִים, שֶׁאֵין מִתְעוֹרְרִים, וְשֵׁנָה בְּנִקְבֵי עֵינֵיהֶם."],[2,"","בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת הָאָדָם כְּמוֹ שֶׁלְּמַעְלָה, הַכֹּל הוּא בְּחָכְמָה, וְאֵין לְךְ אֵיבָר וְאֵיבָר בָּאָדָם שֶׁאֵינוֹ עוֹמֵד בְּחָכְמָה עֶלְיוֹנָה. שֶׁהֲרֵי כֵּיוָן שֶׁנִּתְקַן כָּל הַגּוּף בְּאֵיבָרָיו כָּרָאוּי, הַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁתַּתֵּף (התחזק) עִמּוֹ וְהִכְנִיס בּוֹ נְשָׁמָה קְדוֹשָׁה כְּדֵי לְלַמֵּד אֶת הָאָדָם לָלֶכֶת בְּדַרְכֵי הַתּוֹרָה וְלִשְׁמֹר מִצְווֹתָיו, כְּדֵי שֶׁאָדָם יִתְתַּקֵּן כָּרָאוּי."],[3,"","(ומשום זה) (ובעוד) שֶׁיֵּשׁ בּוֹ נְשָׁמָה קְדוֹשָׁה, צָרִיךְ לָאָדָם לְהַגְדִּיל אֶת דְּמוּת הַמֶּלֶךְ הָעֶלְיוֹן בָּעוֹלָם. וְסוֹד זֶה, שֶׁהֲרֵי אוֹתוֹ הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא לֹא פוֹסְקִים מֵימָיו לְעוֹלָמִים, וְעַל זֶה צָרִיךְ לָאָדָם שֶׁלֹּא יַפְסִיק אֶת הַנָּהָר וְהַמָּקוֹר שֶׁלּוֹ בָּעוֹלָם הַזֶּה. (נה\"ר רמז לברית הקדש שחתום בבשרו, שהוא דגמא של אותו הנה\"ר הסוד של צדיק שמתחבר עם צד\"ק יחד למעלה, משום כך צריך אדם למטה להתחבר עם אשתו בקדשה כדי שיתחזק באותו העולם,) וְכָל זְמַן שֶׁאָדָם לֹא יַצְלִיחַ בָּעוֹלָם הַזֶּה (ס\"א ועל כן צריך לאדם שלא יפסיק את הנהר והמקור שלו בעולם הזה, ואם לא) הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹקֵר אוֹתוֹ וְנוֹטֵעַ אוֹתוֹ בְּכַמָּה פְעָמִים כְּמוֹ מִקֹּדֶם."],[4,"","בֹּא רְאֵה מַה כָּתוּב, הַעִירוֹתִי מִצָּפוֹן וַיַּאת. הַעִירוֹתִי - זוֹ הַהִתְעוֹרְרוּת שֶׁל הַזִּוּוּג שֶׁל הָאָדָם בָּעוֹלָם הַזֶּה, שֶׁהִיא הִתְעוֹרְרוּת מִצַּד הַצָּפוֹן. וַיַּאת - זוֹ הִיא הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁבָּאָה מִלְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵחַ אוֹתָהּ מִלְמַעְלָה, בָּאָה לָעוֹלָם הַזֶּה וְנִכְנֶסֶת לְתוֹךְ בְּנֵי אָדָם, כְּמוֹ שֶׁאָמַרְנוּ."],[5,"","מִמִּזְרַח שֶׁמֶשׁ - זֶה הַמָּקוֹם שֶׁל אוֹתוֹ הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, שֶׁמִּשָּׁם יוֹצֵאת הַנְּשָׁמָה וּמְאִירָה. וְיָבֹא סְגָנִים (כמו חמר) - אֵלּוּ הֵם חֵילוֹת הָעוֹלָם שֶׁבָּאִים מִשּׁוּם (בתוך) אוֹתָהּ הַהִתְעוֹרְרוּת שֶׁל הַנְּשָׁמוֹת. כְּמוֹ חֹמֶר - כְּמוֹ שֶׁמִּתְעוֹרֵר אָדָם בַּגּוּף."],[6,"","שֶׁהֲרֵי מִשּׁוּם זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה זִוּוּגִים וּמַטִּיל נְשָׁמוֹת בָּעוֹלָם, וְנִמְצֵאת חֲבֵרוּת לְמַעְלָה וּלְמַטָּה, וְהַמָּקוֹר שֶׁל הַכֹּל הוּא (ס\"א יהיה) בָּרוּךְ. וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת הָאָדָם, כְּדֵי לְהִשְׁתַּדֵּל בִּדְרָכָיו, וְלֹא יַפְסִיק אֶת מְקוֹרוֹ וּמַעְיָנוֹ לְעוֹלָמִים. וְכָל מִי שֶׁמַּפְסִיק מְקוֹרוֹ (מלמטה ומיבש אותו, כביכול גורם להפסק למעלה, אז (איוב יד) אזלו מים מני ים ונהר יחרב ויבש, והואיל ובן אדם הוקם למטה כדגמא שלמעלה מי שמקורו ימיש מעשות פרות, כמו זה שלא רצה לשא אשה, או שנשא אותה והשתדל ולא יכל, אלו ששני הפכים הם זה מזה, (או אותו) שימיש מעשות פרות, אין לו תקנה לעולם, (קהלת א) מעות לא יוכל לתקן, משום שלא רצה לשא אשה ולהשתדל בפריה ורביה, ואותו שהשתדל ונשא אשה ולא יכל, זה מתקן בגואלו שקרוב לו, שהוא אחיו של אותו מת בלי בנים). כְּשֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה, אוֹתוֹ הָאִישׁ לֹא נִכְנָס לַפַּרְגּוֹד וְלֹא נוֹטֵל חֵלֶק בָּעוֹלָם הַהוּא (ונשמתו לא נכללת במקום שכל הנשמות נכללו, ונגזרת דמותו משם, זהו שכתוב ונכרתה הנפש ההיא מלפני, הואיל וכך הוא, בורא לו הקדוש ברוך הוא גואל שיגאלנו מיד המשחיתים, וזה אחיו שקרוב אליו, שנאמר (דברים כה) כי ישבו אחים יחדו וגו', וכתוב בא אל אשת אחיך ויבם אתה וגו', משום שנשמתו לא נכנסת לפני הקדוש ברוך הוא, אלא היא עומדת בחוץ, משום שלא זכה להאיר בעולם הזה בגוף ההוא, מי שלא זוכה במקום הזה, ילך למקום אחר ויזכה בו, כמו כן עץ שדולק ואורו לא עולה, יכו אותו ויעלה בו אור ויאיר, עץ הוא אדם, שכתוב (שם כ) כי האדם עץ השדה, רוצה לומר, שהאדם כשהוא בעולם הזה והולך ותאב ואוכל ושותה ומזדוג עם אשה ולא זוכה לבנים, זהו עץ שדולק ואורו לא עולה, כלומר, נשמתו לא זוכה באותו הגוף להיות מוארת, אלא היא בחשכה),"],[7,"","בֹּא רְאֵה, כָּתוּב (ישעיה מה) לֹא תֹהוּ בְּרָאָהּ לָשֶׁבֶת יְצָרָהּ, שֶׁמִּשּׁוּם כָּךְ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם כָּרָאוּי, כְּמוֹ שֶׁאָמַרְנוּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה חֶסֶד עִם הָעוֹלָם בּא רְאֵה מַה כָּתוּב, (בראשית כה) וַיֹּסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה. סוֹד הַנְּשָׁמָה שֶׁבָּאָה לְהִתְתַּקֵּן כְּמוֹ מִקֹּדֶם."]]],[["תָּא חֲזֵי, הַהוּא גוּפָא מַה כְּתִיב, (ישעיהו נ״ג:י׳) וַיְיָ חָפֵץ דַּכְּאוֹ הֶחלִי אִם תָּשִׂים אָשָׁם נַפְשׁוֹ יִרְאֶה זֶרַע יַאֲרִיךְ יָמִים וְחֵפֶץ יְיָ בְּיָדוֹ יִצְלָח. וַיְיָ חָפַץ דַּכְּאוֹ, הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ, אַמַּאי חָפֵץ בְּגִין דְּיִתְדַּכֵּי. אִם תָּשִׂים אָשָׁם, אִם יָשִׂים אָשָׁם מִבָּעֵי לֵיהּ, מַאי אִם תָּשִׂים. אֶלָּא לְנִשְׁמָתָא אַהֲדַר מִלָּה. אִי הַהִיא נִשְׁמָתָא בַּעְיָא לְאִתְתַּקָּנָא כְּדְקָא יָאוֹת, יִרְאֶה זֶרַע. בְּגִין דְּהַהִיא נִשְׁמָתָא אָזְלַת וְשָׁאטַת וְאִיהִי זְמִינָא לְאָעֳלָא בְּהַהוּא זֶרַע דְּאִתְעַסַּק בָּהּ בַּר נָשׁ בִּפְרִיָּה וּרְבִיָּה, וּכְדֵין יַאֲרִיךְ יָמִים. וְחֵפֶץ יְיָ דָּא אוֹרַיְיתָא בִּידֵיהּ אַצְלַח.","תָּא חֲזֵי, אַף עַל גַּב דְּבַר נָשׁ אִשְׁתַּדַּל בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא, וּמְקוֹרֵיהּ וּמַבּוּעֵיהּ קָיְימָא בֵּיהּ לְמַגָּנָא, לֵית לֵיהּ אֲתַר לְאֲעָלָא לְפַרְגּוֹדָא. וְהָא אִתְּמָר דְּבֵירָא דְמַיָא אִי הַהוּא מְקוֹרָא וּמַבּוּעָא לָא עָאל בֵּיהּ, לָאו אִיהוּ בְּאֵר, דְּבֵירָא וּמְקוֹרָא, כְּחֲדָא אִינוּן, וְרָזָא חָדָא אִיהוּ, וְאוֹקִימְנָא.","כְּתִיב, (תהילים קכ״ז:ב׳) שָׁוְא לָכֶם מַשְׁכִּימֵי קוּם מֵאַחֲרֵי שֶׁבֶת אוֹכְלֵי לֶחֶם הָעֲצָבִים כֵּן יִתֵּן לִידִידוֹ שֵׁנָה. תָּא חֲזֵי, כַּמָּה חֲבִיבִין אִינוּן מִלֵּי דְאוֹרַיְיתָא. דְּכָל מִלָּה וּמִלָּה דְאוֹרַיְיתָא אִית בֵּיהּ רָזִין עִלָּאִין קַדִּישִׁין. וְהָא אִתְּמָר דְּכַד יָהַב קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא לְיִשְׂרָאֵל, כָּל גְּנִיזִין עִלָּאִין קַדִּישִׁין כֻּלְּהוּ יָהַב לְהוּ (וכלהו) בְּאוֹרַיְיתָא, וְכֻלְּהוּ אִתְיְהִיבוּ לְהוּ לְיִשְׂרָאֵל בְּשַׁעְתָּא דְּקַבִּילוּ אוֹרַיְיתָא בְּסִינַי.","תָּא חֲזֵי, שָׁוְא לָכֶם מַשְׁכִּימֵי קוּם, אִלֵין אִינוּן יְחִידִים דְּאִשְׁתַּכָּחוּ, דְּלָאו אִינוּן דְּכַר וְנוּקְבָא כְּדְקָא יְאוּת, וְאַקְדְּמָן בְּצַפְרָא לַעֲבִידְתַּיְהוּ. כְּמָה דְאַתְּ אָמֵר, (קהלת ד׳:ח׳) יֵשׁ אֶחָד וְאֵין שֵׁנִי וְגו' וְאֵין קֵץ לְכָל עֲמָלוֹ. מֵאַחֲרֵי שֶׁבֶת. מְאַחֲרִין נַיְיחָא, כְּמָה דְאַתְּ אָמֵר, כִּי בוֹ שָׁבַת. בְּגִין דְּאִתְּתָא לְגַבֵּי בַּר נָשׁ אִיהִי נַיְיחָא לְגַבֵּיהּ וַדַּאי.","אוֹכְלֵי לֶחֶם הָעֲצָבִים, מַאי לֶחֶם הָעֲצָבִים. דְּכַד בַּר נָשׁ אִית לֵיהּ בְּנִין, הַהוּא נַהֲמָא דְּאָכִיל, אָכִיל לֵיהּ בְּחֶדְוָה וּבִרְעוּתָא דְלִבָּא. וְהַהוּא דְּלֵית לֵיהּ בְּנִין, הַהוּא נַהֲמָא דְּאָכִיל אִיהוּ נַהֲמָא דַּעֲצִיבוּ. וְאִלֵּין אִינוּן אוֹכְלֵי לֶחֶם הָעֲצָבִים וַדַּאי.","כֵּן יִתֵּן לִידִידוֹ שֵׁנָה, מַאי יִתֵּן לִידִידוֹ, דָּא הוּא דִּמְקוֹרֵיהּ מְבָרַךְ, דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לֵיהּ שֵׁינָה בְּהַהוּא עַלְמָא כְּמָה דְאַתְּ אָמֵר, (משלי ג׳:כ״ד) וְשָׁכַבְתָּ וְעָרְבָה שְׁנָתֶךָ. בְּגִין דְּאִית לֵיהּ חוּלָקָא בְּעַלְמָא דְאָתֵי. בְּגִין דְּהַהוּא בַּר נָשׁ שָׁכִיב וְיִתְהַנֵּי בְּהַהוּא עַלְמָא דְאָתֵי כְּדְקָא יְאוּת.","יֵשׁ אֶחָד וְאֵין שֵׁנִי וְגו'. יֵשׁ אֶחָד, דָּא הוּא בַּר נָשׁ דְּאִיהוּ יְחִידָאי בְּעַלְמָא, לָא יְחִידָאי כְּדְקָא יְאוּת, אֶלָּא דְּאִיהוּ בְּלָא זִוּוּגָא. וְאֵין שֵׁנִי, דְּלֵית עִמֵּיהּ סֶמֶךְ. גַּם בֵּן, דְּיוֹקִים שְׁמֵיהּ בְּיִשְׂרָאֵל לָא שָׁבַק. וְאָח (אין לו) לְאַיְיתָאָה לֵיהּ לְתִקּוּנָא."],[[0,"ת\"ח האי גופא וכו':","בוא וראה, גוף ההוא מה כתוב בו, וה' חפץ דכאו החלי אם תשים וגו'. \u0003וה' חפץ דכאו,\u0004 מקרא זה יש להסתכל בו, למה חפץ ה' כך. ומשיב, כדי שיטהר. \u0003אם תשים אשם,\u0004 שואל, אם \u0003ישים\u0004 אשם, היה צריך לומר, בלשון זכר. למה אומר אם תשים, בלשון נקבה. ומשיב, אלא המלה סובבת על הנשמה, ופירושו, אם הנשמה רוצה להתתקן כראוי, \u0003יראה זרע,\u0004 משום שהנשמה הולכת ומשוטטת, שאין לה מקום מנוחה, והיא עתידה להכנס באותו זרע שהאדם עסק בה במצות פריה ורביה, ואז \u0003יאריך ימים. וחפץ ה',\u0004 זה התורה. \u0003בידו יצלח,\u0004 אבל אם לא זכה לבנים, אין התורה מסייעתו. כמ\"ש לפנינו."],[1,"ת\"ח אע\"ג וכו':","בוא וראה, אע\"פ שאדם עסק בתורה יום ולילה, ומקורו ומעינו עומד בו בחנם, דהיינו שאינו מוליד בנים, אין לו מקום להכנס למחיצתו של הקב\"ה, והרי למדנו, שבאר המים, אם המקור והמעיין לא נכנס בו, אינה באר, כי הבאר והמקור אחד הוא, וסוד אחד הוא. ובארנוהו ומי שאין לו בנים דומה שהמקור שבו לא נכנס בו, כלומר, שאינו פועל בו."],[2,"כתיב, שוא לכם משכימי קום וגו':","בוא וראה כמה חביבים הם דברי תורה, שכל מלה ומלה שבתורה, יש בה סודות עליונים הקדושים. ולמדנו, כאשר נתן הקב\"ה את התורה לישראל, כל סודות עליונים הקדושים כולם נתן להם בתורה, וכולם ניתנו לישראל בשעה שקבלו התורה בסיני."],[3,"ת\"ח, שוא לכם משכימי קום וגו':","אלו הם יחידים שאין להם אשה, שנמצאים שאין הם זכר ונקבה כמו שצריכים, והם משכימים בבקר למלאכתם. כמו שאתה אומר, יש אחד ואין שני וגו' ואין קץ לכל עמלו. \u0003מאחרי שבת,\u0004 מאחרים המנוחה, דהיינו שמאחרים לשאת אשה, כי \u0003שבת\u0004 פירושו מניחה, כמו שאתה אומר כי בו \u0003שבת\u0004, כי האשה אל האיש נחשבת ודאי אליו למנוחה."],[4,"אוכלי לחם העצבים וגו':","שואל, מהו לחם העצבים. ומשיב, כי כאשר יש לאדם בנים, הלחם שאוכל אוכל אותו בשמחה בחפץ לב. ואותו שאין לו בנים, הלחם שאוכל הוא לחם העצבים, ואלו הם אוכלי לחם העצבים ודאי."],[5,"כן יתן לידידו שנה:","שואל, מהו \u0003יתן לידידו,\u0004 ומשיב, זהו שמקורו מבורך, דהיינו שיש לו בנים, שהקב\"ה נותן לו שינה בעולם הזה, כמש\"א. ושכבת וערבה שנתך. והוא משום שיש לו חלק בעולם הבא, לכן אותו האדם שוכב בקבר, ונהנה בעולם הבא כראוי."],[6,"יש אחד ואין שני וגו': יש אחד,","זהו אדם, שהוא יחיד בעולם, ולא שהוא יחיד כראוי, דהיינו יחיד בחכמה, אלא שהוא בלי אשה. \u0003ואין שני,\u0004 שאין עמו עזר, דהיינו אשה. \u0003גם בן,\u0004 שיקיים שמו בישראל לא הניח. \u0003ואח\u0004, שיביאו לתיקון, דהיינו ביבום, \u0003אין לו.\u0004"]],[[0,"","בֹּא רְאֵה בְּאוֹתוֹ הַגּוּף מַה כָּתוּב, (ישעיה נג) וַה' חָפֵץ דַּכְּאוֹ הֶחֱלִי אִם תָּשִׂים אָשָׁם נַפְשׁוֹ יִרְאֶה זֶרַע יַאֲרִיךְ יָמִים וְחֵפֶץ ה' בְּיָדוֹ יִצְלָח. וַה' חָפֵץ דַּכְּאוֹ, בַּפָּסוּק הַזֶּה יֵשׁ לְהִסְתַּכֵּל, לָמָּה חָפֵץ? כְּדֵי שֶׁיִּטְהַר. אִם תָּשִׂים אָשָׁם - הָיָה צָרִיךְ לִהְיוֹת אִם יָשִׂים אָשָׁם! מַה זֶּה אִם תָּשִׂים? אֶלָּא עַל הַנְּשָׁמָה חוֹזֵר הַדָּבָר. אִם הַנְּשָׁמָה הַהִיא רוֹצָה לְהִתְתַּקֵּן כָּרָאוּי - יִרְאֶה זֶרַע, מִשּׁוּם שֶׁאוֹתָהּ הַנְּשָׁמָה הוֹלֶכֶת וּמְשׁוֹטֶטֶת וּמְזֻמֶּנֶת לְהִכָּנֵס לְאוֹתוֹ הַזֶּרַע שֶׁהִתְעַסֵּק בָּהּ הָאָדָם בִּפְרִיָּה וּרְבִיָּה, וְאָז יַאֲרִיךְ יָמִים, וְחֵפֶץ ה' - זוֹ הַתּוֹרָה - בְּיָדוֹ יִצְלָח."],[1,"","בֹּא רְאֵה, אַף עַל גַּב שֶׁאָדָם מִשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה וּמְקוֹרוֹ וּמַעְיָנוֹ עוֹמֵד בּוֹ לְחִנָּם, אֵין לוֹ מָקוֹם לְהִכָּנֵס לַפַּרְגּוֹד. וַהֲרֵי נֶאֱמַר שֶׁבְּאֵר הַמַּיִם, אִם לֹא נִכְנָס בָּהּ אוֹתוֹ הַמָּקוֹר וְהַמַּעְיָן, אֵינָהּ בְּאֵר, שֶׁהַבְּאֵר וְהַמָּקוֹר הֵם יַחַד וְהֵם סוֹד אֶחָד, וּבֵאַרְנוּ."],[2,"","כָּתוּב (תהלים קכז) שָׁוְא לָכֶם מַשְׁכִּימֵי קוּם מְאַחֲרֵי שֶׁבֶת אֹכְלֵי לֶחֶם הָעֲצָבִים כֵּן יִתֵּן לִידִידוֹ שֵׁנָא. בֹּא רְאֵה כַּמָּה הֵם חֲבִיבִים דִּבְרֵי הַתּוֹרָה, שֶׁבְּכָל דָּבָר וְדָבָר בַּתּוֹרָה יֵשׁ בּוֹ סוֹדוֹת עֶלְיוֹנִים קְדוֹשִׁים, וַהֲרֵי נֶאֱמַר שֶׁכַּאֲשֶׁר נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא הַתּוֹרָה לְיִשְׂרָאֵל, אֶת כָּל הַגְּנָזִים הָעֶלְיוֹנִים הַקְּדוֹשִׁים כֻּלָּם נָתַן לָהֶם (וכלם) בַּתּוֹרָה, וְכֻלָּם נִתְּנוּ לְיִשְׂרָאֵל בְּשָׁעָה שֶׁקִּבְּלוּ הַתּוֹרָה בְּסִינַי."],[3,"","בֹּא רְאֵה, שָׁוְא לָכֶם מַשְׁכִּימֵי קוּם - אֵלּוּ הֵם הַיְחִידִים שֶׁנִּמְצָאִים, שֶׁאֵינָם זָכָר וּנְקֵבָה כָּרָאוּי, וּמַקְדִּימִים בַּבֹּקֶר לַעֲבוֹדָתָם, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ד) יֵשׁ אֶחָד וְאֵין שֵׁנִי וְגוֹ', וְאֵין קֵץ לְכָל עֲמָלוֹ. מְאַחֲרֵי שֶׁבֶת - מְאַחֲרִים הַמְּנוּחָה, כְּמוֹ שֶׁנֶּאֱמַר כִּי בוֹ שָׁבַת, מִשּׁוּם שֶׁהָאִשָּׁה אֶל הָאָדָם הִיא נַחַת וַדַּאי אֶצְלוֹ."],[4,"","אֹכְלֵי לֶחֶם הָעֲצָבִים, מַה זֶּה לֶחֶם הָעֲצָבִים? שֶׁכַּאֲשֶׁר לָאָדָם יֵשׁ בָּנִים, אוֹתוֹ הַלֶּחֶם שֶׁאוֹכֵל, אוֹכֵל אוֹתוֹ בְּשִׂמְחָה וּבִרְצוֹן הַלֵּב. וְזֶה שֶׁאֵין לוֹ בָּנִים, אוֹתוֹ לֶחֶם שֶׁאוֹכֵל הוּא לֶחֶם שֶׁל עֶצֶב, וְאֵלּוּ הֵם אֹכְלֵי לֶחֶם הָעֲצָבִים וַדַּאי."],[5,"","כֵּן יִתֵּן לִידִידוֹ שֵׁנָא, מַה זֶּה יִתֵּן לִידִידוֹ? זֶהוּ שֶׁמְּקוֹרוֹ מְבֹרָךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לוֹ שֵׁנָה בָּעוֹלָם הַהוּא, כְּמוֹ שֶׁנֶּאֱמַר (משלי ג) וְשָׁכַבְתָּ וְעָרְבָה שְׁנָתֶךְ, מִשּׁוּם שֶׁיֵּשׁ לוֹ חֵלֶק בָּעוֹלָם הַבָּא, כְּדֵי שֶׁאוֹתוֹ הָאִישׁ יִשְׁכַּב וְיֵהָנֶה בָּעוֹלָם הַבָּא הַהוּא כָּרָאוּי."],[6,"","יִשִׁ אֶחָד וְאֵין שֵׁנִי וְגוֹ', יֵשׁ אֶחָד - זֶהוּ אָדָם שֶׁהוּא יְחִידִי בָּעוֹלָם, לֹא יְחִידִי כָּרָאוּי, אֶלָּא שֶׁהוּא בְּלִי זִוּוּג. וְאֵין שֵׁנִי - שֶׁאֵין עִמּוֹ סֶמֶךְ. גַּם בֵּן - שֶׁיָּקִים שְׁמוֹ בְּיִשְׂרָאֵל לֹא הִשְׁאִיר. וָאָח אֵין לוֹ - שֶׁיָּבִיא אוֹתוֹ לְתִקּוּן."]]],[["וְאֵין קֵץ לְכָל עֲמָלוֹ, דְּאִיהוּ עָמֵל תָּדִיר דְּאַקְדִּים יְמָמָא וְלֵילְיָא. גַּם עֵינוֹ לא תִשְׂבַּע עשֶׁר, וְלֵית לֵיהּ לִבָּא לְאַשְׁגָּחָא וּלְמֵימַר לְמִי אֲנִי עָמֵל וּמְחַסֵּר אֶת נַפְשִׁי מִטּוֹבָה. וְאִי תֵימָא דִּבְגִין דְּיֵיכוּל וְיִשְׁתֵּי יַתִּיר וְיַעֲבֵד מִשְׁתַּיָא בְּכָל יוֹמָא תָּדִיר, לָאו הָכִי. דְּהָא נַפְשָׁא לָא אִתְהַנִּי מִנֵּיהּ, אֶלָּא וַדַּאי אִיהוּ מְחַסֵּר לְנַפְשֵׁיהּ מִטִּיבוּ דִּנְהוֹרָא דְעַלְמָא דְאָתֵי. בְּגִין דְּדָא הִיא נַפְשָׁא חַסְרָא, דְּלָא אִשְׁתַּלִּימַת כְּדְקָא יְאוּת. תָּא חֲזֵי, כַּמָּה חָס קוּדְשָׁא בְּרִיךְ הוּא עַל עוֹבָדוֹי, בְּגִין דְּקָא בָּעֵי דְּיִתְתַּקַּן, וְלָא יִתְאֲבִיד מֵהַהוּא עַלְמָא דְאָתֵי כִּדְקָאֲמָרָן.","רִבִּי חִיָּיא בָּעָא, הַאי דְאִיהוּ זַכָּאָה שְׁלֵימָא וְאִשְׁתְּדָּל בְּאוֹרַיְיתָא יוֹמֵי וְלֵילֵי וְכָל עוֹבָדוֹי לִשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְלָא זָכָה לִבְנִין בְּהַאי עַלְמָא כְּגוֹן דְּאִשְׁתַּדַּל בְּהוּ וְלָא זָכָה, אוֹ דְּהֲווּ לֵיהּ וּמִיתוּ. מַה אִינוּן לְעַלְמָא דְאָתֵי. אָמַר לֵיהּ רִבִּי יוֹסֵי, עוֹבָדוֹי וְהַהִיא אוֹרַיְיתָא, קָא מָגִינָן עֲלֵיהּ לְהַהוּא עַלְמָא.","אָמַר רִבִּי יִצְחָק, עֲלַיְיהוּ וְעַל אִינוּן זַכָּאֵי קְשׁוֹט, (כגון רבי יוחנן דהוו ליה בנין ומיתו, וכגון רבי חזקיה דאיהו עקר) עֲלַיְיהוּ כְּתִיב, (ישעיהו נ״ו:ד׳) כֹּה אָמַר יְיָ לַסָּרִיסִים אֲשֶׁר יִשְׁמְרוּ אֶת שַׁבְּתוֹתַי וּבָחֲרוּ בַּאֲשֶׁר חָפָצְתִּי וּמַחֲזִיקִים בִּבְרִיתִי. מַה כְּתִיב בַּתְרֵיהּ, וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמוֹתַי יָד וָשֵׁם טוֹב מִבָּנִים וּמִבָּנוֹת שֵׁם עוֹלָם אֶתֵּן לוֹ אֲשֶׁר לֹא יִכָּרֵת. בְּגִין דְּאִלֵּין אִית לוֹן חוּלָקָא לְעַלְמָא דְאָתֵי. אָמַר לֵיהּ רִבִּי יוֹסֵי, יָאוֹת הוּא וְשַׁפִּיר.","תָּא חֲזֵי, זַכָּאָה שְׁלִים דְּהֲווּ כָּל אִלֵּין בֵּיהּ, וְאִשְׁתְּלִים כְּדְקָא יְאוּת, וּמִית בְּלָא בְּנִין, וְהָא קָא יָרִית דּוּכְתֵּיהּ בְּהַהוּא עַלְמָא, אִתְּתֵיהּ בָּעְיָא לִיבוּמֵי אוֹ לָא. אִי תֵימָא דְּלִבָּעֵי לִיבוּמֵי, הָא בְּרֵיקַנְיָא אִיהוּ, דְּהָא אַתְרֵיהּ קָא יָרִית בְּהַהוּא עַלְמָא.","אֶלָּא וַדַּאי בָּעְיָא לִיבוּמֵי, בְּגִין דְּלָא יַדְעִינָן אִי הֲוָה שְׁלִים בְּעוֹבָדוֹי אִי לָאו. וְהִיא אִי אִתְיַיבְּמַת לָא הֲוָה בְּרֵיקַנְיָא. בְּגִין דְּאֲתַר אִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא דְּהָא (ל) בַּר נָשׁ (ד) הֲוָה בְּעַלְמָא וּמִית בְּלָא בְּנִין וּפוּרָקָא לָא הֲוֵי לֵיהּ בְּעַלְמָא, כֵּיוָן דְּמִית הַאי זַכָּאָה שְׁלִים וְאִתְּתֵיה אִתְיַיבְּמַת, וְאִיהוּ אַתְרֵיהּ יָרִית. אֲתָא הַהוּא בַּר נָשׁ וְאִשְׁתַּלִּים הָכָא, וּבֵין כָּךְ וּבֵין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא, אֲתַר זַמִּין לֵיהּ (לעלמא) (בעלמא) עַד דְּיֵימוּת הַאי זַכָּאָה שְׁלִים, וְיִשְׁתְּלִים אִיהוּ בְּעַלְמָא. הֲדָא הוּא דִכְתִיב (במדבר ל״ה:כ״ח) כִּי בְעִיר מִקְלָטוֹ יֵשֵׁב עַד מוֹת הַכֹּהֵן הַגָּדוֹל וְגו'.","וְדָא הוּא דְּתָנִינָן, בְּנִין זְמִינִין אִינוּן לְצַדִּיקַיָא בְּמִיתַתְהוֹן, בְּחַיֵּיהוֹן לָא זָכוּ וּבְמִיתַתְהוֹן זָכוּ. וּבְגִין כָּךְ כָּל עוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא כֻּלְּהוּ קְשׁוֹט וּזְכוּ, (ס\"א וחייס) וְחַיִּים עַל כֹּלָּא.","(קהלת ד׳:ט׳) טוֹבִים הַשְּׁנַיִם מִן הָאֶחָד אֲשֶׁר יֵשׁ לָהֶם שָׂכָר טוֹב בַּעֲמָלָם, אִלֵּין אִינוּן דְּמִתְעַסְּקִין בְּהַאי עַלְמָא לְאוֹלָדָא בְּנִין. דְּאִינוּן בְּנִין דְּשָׁבְקוּ, בְּגִינֵיהוֹן אִית לוֹן אֲגַר טַב בְּהַהוּא עַלְמָא, וּבְגִינֵיהוּ יַרְתִין אֲבָהָן דִּלְהוֹן חוּלָקָא בְּהַהוּא עַלְמָא וְאוּקְמוּהָ.","תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא נָטַע אִילָנִין בְּהַאי עַלְמָא אִי אַצְלָחוּ יָאוֹת, לָא אַצְלָחוּ אַעֲקַר לוֹן וְשָׁתַל לוֹן אֲפִילּוּ כַּמָּה זִמְנִין. וּבְּגִין כָּךְ כָּל אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא כֻּלְּהוּ לְטַב וּלְאַתְקָנָא עָלְמָא:","בֹּא אֶל אֵשֶׁת אָחִיךָ וְיַבֵּם אוֹתָהּ, דְּהָא יְהוּדָה וְכֻלְּהוּ שִׁבְטִין הֲווּ יָדְעֵי דָּא. וְעִקְּרָא דְמִלְּתָא, וְהָקֵם זֶרַע. בְּגִין דְּהַהוּא זֶרַע אִצְטְרִיךְ לְאִתְתַּקָּנָא מִלָּה וּלְמִגְלַם גּוֹלָמָא לְתִקּוּנָא דְּלָא יִתְפְּרַשׁ גִּזְעָא מִשָּׁרְשֵׁיהּ כְּדְקָא יְאוּת, הֲדָא הוּא דִכְתִיב (איוב לה) וְאָדָם עַל עָפָר יָשׁוּב.","וְכַד מִתְתַּקַּן לְבָתַר כְּדְקָא יָאוֹת, אִלֵּין מִשְׁתַּבְּחִין בְּהַהוּא עַלְמָא בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ. וּבְגִין כָּךְ כְּתִיב, (קהלת ד׳:ב׳) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, דַּיְיקָא. מִן הַחַיִּים אֲשֶׁר הֵמָּה חַיִּים עֲדֶנָּה. מַאי עֲדֶנָּה, כְּמָה דְאַתְּ אָמֵר (בראשית י״ח:י״ב) אַחֲרֵי בְלוֹתִי הָיְתָה לִי עֶדְנָה. וּכְתִיב (איוב ל״ג:כ״ה) יָשׁוּב לִימֵי עֲלוּמָיו.","וְטוֹב מִשְּׁנִיהֶם אֵת אֲשֶׁר עֲדֶן לא הָיָה (דלא שב לימי עלומיו) אֲשֶׁר לֹא רָאָה אֶת הַמַּעֲשֶׂה הָרַע אֲשֶׁר נַעֲשָׂה תַּחַת הַשֶּׁמֶשׁ. וְטוֹב מִשְּׁנִיהֶם אֶת אֲשֶׁר עֲדֶן לֹא הָיָה, דְּלָא שָׁב לִימֵי עֲלוּמָיו וְלָא אִצְטְרִיךְ לְאִתְתַּקָּנָא, וְלָא סָבִיל חוֹבִין קַדְמָאֵי, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לֵיהּ אֲתַר מְתַקְנָא בְּהַהוּא עַלְמָא כְּדְקָא יָאוֹת."],[[0,"ואין קץ לכל עמלו","שהוא עומל תמיד, שמקדים עצמו ביום ובלילה, \u0003גם עינו לא תשבע עשר,\u0004 ואין לו לב להסתכל ולומר \u0003למי אני עמל ומחסר את נפשי מטובה.\u0004 ואם תאמר, שהוא עמל בכדי שיאכל וישתה ביותר, ויעשה משתה בכל יום תמיד, אינו כן, שהרי הנפש אינה נהנית מזה. אלא ודאי, שהוא \u0003מחסר את נפשו מטובה\u0004 של אור העולם הבא. משום שהיא נפש בעלת חסרון, שלא נשלמה כראוי. בוא וראה, כמה מרחם הקב\"ה על מעשיו, דהיינו שמביאו לגלגול להתתקן, משום שרוצה שיתתקן ולא יאבד מאותו עולם הבא, כמו שאמרנו."],[1,"ר' חייא בעא וכו':","ר' חייא שאל, מי שהוא צדיק גמור, ועסק בתורה ימים ולילות, וכל מעשיו לשמו של הקב\"ה, ולא זכה לבנים בעולם הזה, או שהשתדל ולא זכה, או שהיה לו בנים ומתו, מה הם לעולם הבא. אמר לו ר' יוסי מעשיו, והתורה, מגינים עליו שיזכה לעולם הבא."],[2,"אמר רבי יצחק וכו':","אר\"י עליהם ועל אלו צדיקי אמת, עליהם כתוב, כה אמר ה' לסריסים וגו'. מה כתוב אחריו, ונתתי להם בביתי ובחומותי וגו'. כי אלו יש להם חלק לעולם הבא. א\"ל ר' יוסי טוב הוא ויפה. כלומר שהסכים עמו."],[3,"ת\"ח זכאה וכו':","בוא וראה, צדיק גמור שכל אלו המעלות הנ\"ל היו בו, ונשלם כראוי, ומת בלי בנים, והרי הוא יורש מקומו בעולם הבא, כנ\"ל, שואל אשתו צריכה יבום או לא. ואם תאמר שצריכה יבום, הרי לריק הוא, כי אינו צריך שאחיו ישלים אותו, כי כבר ירש מקומו בעולם הבא."],[4,"אלא ודאי בעיא וכו':","ומשיב, אלא ודאי שצריך ליבם את אשתו, משום שאין אנו יודעים אם היה שלם במעשיו אם לא. ואשתו אם נתיבמה, אינה לריק, אפילו אם היה שלם, משום שיש מקום אל הקב\"ה בשביל אותם שמתו בלי בנים וגם אח ליבם אשתו אין להם, כי אדם שהיה בעולם ומת בלי בנים, וגואל אין לו בעולם, כיון שמת צדיק גמור הזה, ואשתו נתיבמת והוא כבר ירש מקומו, ואינו צריך לתקון היבום, בא אותו האדם שלא הניח גואל, ונשלם ביבום הזה של אשת הצדיק, ובינתים הקב\"ה מכין מקום, להאיש שאין לו גואל, שיהיה שם, עד שימות צדיק גמור הזה וישתלם הוא בעולם. וז\"ש, כי בעיר מקלטו ישב עד מות הכהן הגדול וכו', נראה לי של\"ג כאן פתח ואמר, והוא שייך להלן (אות קע\"ה) לפני הכתוב, טובים השנים מן האחד."],[4,"","פירוש. כי מי שאין לו בנים, הוא ממעט הדמות, ודומה להורג אנשים בשוגג. והמקום שהקב\"ה מכין לאותו שאין לו בנים ואין לו אח, ה\"ס עיר מקלט. שיושב שם עד שמת אותו צדיק גמור, שה\"ס כהן גדול. ואז יורד ונתתקן ע\"י אשתו."],[5,"ודא הוא דתנינן וכו':","וזה הוא שלמדנו, עתידים להיות לצדיקים בנים במיתתם, דהיינו הבנים של היבום, המתקנים אותו שמת בלי בנים ואין לו אח כנ\"ל, בחייהם לא זכו ובמיתתם זכו. ועל כן כל מעשיו של הקב\"ה כולם אמת וצדק, ומרחם על כל. דהיינו גם על מי שאין לו אח."],[5,"","ואין לשאול, מה קמשמע לנו, הרי כל המתים בלי בנים כן, שיש להם בנים לאחר מיתתם ע\"י היבום. אמנם עיקר הרבותא היא כאן, במה שאומר \u0003לצדיקים,\u0004 כי המתים בלי בנים המה בעלי חסרון ולא צדיקים, (כנ\"ל באות קס\"ט) ולפיכך הוצרך לתירוץ הנ\"ל."],[6,"פתח ואמר, טובים השנים מן האחד וגו':","אלו הם המשתדלים בעולם הזה להוליד בנים. כי אלו הבנים שהניחו, בשבילם יש להם שכר טוב בעולם הזה, ובשבילם יורשים אבותיהם חלק לעולם הבא."],[7,"ת\"ח קב\"ה וכו':","בוא וראה הקב\"ה נוטע אילנות בעולם הזה, אם מצליחים, טוב, אם לא הצליחו, עוקר אותם ושותל אותם במקום אחר, אפילו הרבה פעמים, וע\"כ כל דרכיו של הקב\"ה כולם הם לטוב ולתקן העולם."],[7,"","פירוש. אם האדם אינו זוכה להשתלם בפעם הראשון בחייו, אז הוא בא בגלגול בעולם הזה פעם שנית, וכן הרבה פעמים עד שמשתלם."],[8,"בא אל אשת אחיך וגו':","לא היה צריך לומר לו את זה, כי יהודה וכל השבטים היו יודעים את זה, אלא עיקר הדבר שאמר לו, הוא \u0003והקם זרע\u0004 משום שזרע ההוא, נצרך, כדי שהדבר יתתקן, ולהכין גולם שיקבל תקון כראוי, שלא יפרד הגזע משורשו. וז\"ש ואדם על עפר ישוב."],[8,"","פירוש. אע\"פ שנגזר מיתה על האדם, המפרידה אותו משורש הנצחי ית', מ\"מ לא נפרד לגמרי, כי על ידי הבנים שכל אחד מוליד, נשאר כל אחד דבוק בשורשו הנצחי, ית', כי כל בן הוא חלק מגוף האב, ובזה נמצא כל אדם כמו טבעת אחת בשרשרת החיים, המתחילה מאדם הראשון ונמשכת עד לתחה\"מ, לנצחיות, בלי הפסק. וכל עוד שלא נפסק לאדם שלשלת החיים, כי מניח אחריו בן, אין המיתה פועלת עליו שום פירוד מהנצחיות. וכעודו חי דומה."],[8,"","וזה אמרו, \u0003דלא יתפרש גזעא משרשיה\u0004 כי המת בלי בנים צריך תקון שלא יפרד משורשו הנצחי מחמת המיתה, כי נפסק לו שלשלת החיים כנ\"ל. ועל זה צריכים ב' תקונים א) \u0003אצטריך לאתתקנא מלה,\u0004 דהיינו לתקן דבר הפירוד השורה עליו מחמת המיתה בלי בנים. ב) \u0003ולמגלם גולמא לתקונא,\u0004 שצריך לעשות גולם, דהיינו גוף שיתלבש בו נפש המת ויחזור ויתחבר בשלשלת החיים."],[9,"וכד מתתקן לבתר וכו':","וכשנתתקן לאחר כך כראוי על ידי הגלגול הנזכר, הם משובחים בעולם הבא, כי הקב\"ה חפץ בהם ועל כן כתוב, \u0003ושבח אני את המתים שכבר מתו,\u0004 בדיוק, \u0003מן החיים אשר המה חיים עדנה,\u0004 בדיוק על ידי מה שמתגלגלים בחיים וחזרו לימי עידון, מהו עדנה, הוא כמש\"א אחרי בלותי היתה לי עדנה, וכתוב, ישוב לימי עלומיו, דהיינו ימי עידון ונעורים, שחזר להם בסבת הגלגול."],[10,"וטוב משניהם וגו':","וטוב משניהם את אשר עדן לא היה, דהיינו שלא שב לימי עלומיו, שלא נתגלגל, כי הוא צדיק גמור, שאינו צריך להתתקן בגלגול, ואינו סובל מעונות הראשונים, כי המתגלגל סובל מעונות שעשה בגלגול הקודם. כי הקב\"ה נתן לו מקום מתוקן בעולם הבא כראוי."]],[[0,"","וְאֵין קֵץ לְכָל עֲמָלוֹ - שֶׁהוּא עָמֵל תָּמִיד, שֶׁמַּקְדִּים יוֹם וָלַיְלָה. גַּם עֵינוֹ לֹא תִשְׂבַּע עֹשֶׁר - וְאֵין לוֹ לֵב לְהַשְׁגִּיחַ וְלוֹמַר, לְמִי אֲנִי עָמֵל וּמְחַסֵּר אֶת נַפְשִׁי מִטּוֹבָה. וְאִם תֹּאמַר שֶׁכְּדֵי שֶׁיּאכַל וְיִשְׁתֶּה יוֹתֵר וְיַעֲשֶׂה מִשְׁתֶּה בְּכָל יוֹם תָּמִיד - לֹא כָּךְ, שֶׁהֲרֵי הַנֶּפֶשׁ אֵינָהּ נֶהֱנֵית מִמֶּנּוּ. אֶלָּא וַדַּאי הוּא מְחַסֵּר אֶת נַפְשׁוֹ מִטּוֹב שֶׁל הָאוֹר שֶׁל הָעוֹלָם הַבָּא מִשּׁוּם שֶׁזּוֹהִי נֶפֶשׁ חֲסֵרָה, שֶׁלֹּא הֻשְׁלְמָה כָּרָאוּי. בֹּא רְאֵה כַּמָּה חָס הַקָּדוֹשׁ בָּרוּךְ הוּא עַל מַעֲשָׂיו, מִשּׁוּם שֶׁרוֹצֶה שֶׁיֶּתֻקַּן וְלֹא יֹאבַד מֵאוֹתוֹ הָעוֹלָם הַבָּא, כְּמוֹ שֶׁאָמַרְנוּ."],[1,"","רַבִּי חִיָּיא שָׁאַל, זֶה שֶׁהוּא צַדִּיק שָׁלֵם וּמִשְׁתַּדֵּל בַּתּוֹרָה יָמִים וְלֵילוֹת וְכָל מַעֲשָׂיו לִשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא זָכָה לְבָנִים בָּעוֹלָם הַזֶּה, כְּמוֹ שֶׁהִשְׁתַּדֵּל בָּהֶם וְלֹא זָכָה, אוֹ שֶׁהָיוּ לוֹ וּמֵתוּ - מַה הֵם לָעוֹלָם הַבָּא? אָמַר לוֹ רַבִּי יוֹסֵי, מַעֲשָׂיו וְהַתּוֹרָה הַהִיא מְגִנִּים עָלָיו לָעוֹלָם הַהוּא."],[2,"","אָמַר רַבִּי יִצְחָק, עֲלֵיהֶם וְעַל אוֹתָם צַדִּיקֵי הָאֱמֶת, (כמו רבי יוחנן שהיו לו בנים ומתו, וכמו רבי חזקיה שהוא עקר) עֲלֵיהֶם כָּתוּב (ישעיה נו) כֹּה אָמַר ה' לַסָּרִיסִים אֲשֶׁר יִשְׁמְרוּ אֶת שַׁבְּתוֹתַי וּבָחֲרוּ בַּאֲשֶׁר חָפַצְתִּי וּמַחֲזִיקִים בִּבְרִיתִי. מַה כָּתוּב אַחֲרָיו? וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמֹתַי יָד וָשֵׁם טוֹב מִבָּנִים וּמִבָּנוֹת שֵׁם עוֹלָם אֶתֶּן לוֹ אֲשֶׁר לֹא יִכָּרֵת, מִשּׁוּם שֶׁלְּאֵלֶּה יֵשׁ חֵלֶק לָעוֹלָם הַבָּא. אָמַר לוֹ רַבִּי יוֹסֵי, נָאֶה הוּא וְיָפֶה."],[3,"","בֹּא רְאֵה, צַדִּיק שָׁלֵם שֶׁהָיוּ בוֹ כָּל אֵלֶּה וְהֻשְׁלַם כָּרָאוּי וּמֵת בְּלִי בָנִים, וְהִנֵּה יוֹרֵשׁ מְקוֹמוֹ בָּעוֹלָם הַהוּא - הַאִם אִשְׁתּוֹ צְרִיכָה יִבּוּם אוֹ לֹא? אִם תֹּאמַר שֶׁצְּרִיכָה לְהִתְיַבֵּם, הֲרֵי זֶה לְרֵיקָנוּת, שֶׁהֲרֵי אֶת מְקוֹמוֹ יָרַשׁ בָּעוֹלָם הַהוּא."],[4,"","אֶלָּא וַדַּאי צְרִיכָה לְיִבּוּם, מִשּׁוּם שֶׁאֵינֶנּוּ יוֹדְעִים אִם הָיָה שָׁלֵם בְּמַעֲשָׂיו וְאִם לֹא. וְאִם הִיא מִתְיַבֶּמֶת, זֶה לֹא הָיָה בְּרֵיקָנוּת, מִשּׁוּם שֶׁיֵּשׁ מָקוֹם לַקָּדוֹשׁ-בָּרוּךְ- הוּא לָאִישׁ הַזֶּה שֶׁהָיָה בָּעוֹלָם וּמֵת בְּלִי בָנִים וְגוֹאֵל לֹא הָיָה לוֹ בָּעוֹלָם. כֵּיוָן שֶׁהַצַּדִּיק הַשָּׁלֵם הַזֶּה מֵת וְאִשְׁתּוֹ מִתְיַבֶּמֶת, וְהוּא יָרַשׁ אֶת מְקוֹמוֹ, בָּא הָאִישׁ הַהוּא וּמִשְׁתַּלֵּם כָּאן, וּבֵין כָּךְ וּבֵין כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מַזְמִין לוֹ מָקוֹם לָעוֹלָם עַד שֶׁיָּמוּת הַצַּדִּיק הַשָּׁלֵם הַזֶּה וְהוּא יִשְׁתַּלֵּם בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב (במדבר לב) כִּי בְעִיר מִקְלָטוֹ יֵשֵׁב עַד מוֹת הַכֹּהֵן הַגָּדוֹל וְגוֹ'."],[5,"","וְזְהִוּ שֶׁשָּׁנִינוּ, בָּנִים מְזֻמָּנִים לַצַּדִּיקִים בְּמִיתָתָם. בְּחַיֵּיהֶם לֹא זָכוּ, וּבְמִיתָתָם זָכוּ. וּמִשּׁוּם כָּךְ כָּל מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כֻּלָּם אֱמֶת וּזְכוּת, (וחס) וְחַיִּים עַל הַכֹּל."],[6,"","(קהלת ד) טוֹבִים הַשְּׁנַיִם מִן הָאֶחָד אֲשֶׁר יֵשׁ לָהֶם שָׂכָר טוֹב בַּעֲמָלָם - אֵלּוּ הֵם שֶׁמִּתְעַסְּקִים בָּעוֹלָם הַזֶּה לְהוֹלִיד בָּנִים, שֶׁאוֹתָם בָּנִים שֶׁהִשְׁאִירוּ, בִּגְלָלָם יֵשׁ לָהֶם שָׂכָר טוֹב בָּעוֹלָם הַזֶּה וּבִגְלָלָם יוֹרְשִׁים אֲבוֹתֵיהֶם חֵלֶק בָּעוֹלָם הַהוּא, וּבֵאֲרוּהוּ."],[7,"","בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹטֵעַ אִילָנוֹת בָּעוֹלָם הַזֶּה. אִם הִצְלִיחוּ - יָפֶה. לֹא הִצְלִיחוּ - עוֹקֵר אוֹתָם וְשׁוֹתֵל אוֹתָם אֲפִלּוּ כַּמָּה פְעָמִים, וּמִשּׁוּם כָּךְ כָּל דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הֵן לְטוֹב וּלְתַקֵּן אֶת הָעוֹלָם."],[8,"","בֹּא אֶל אֵשֶׁת אָחִיךְ וְיַבֵּם אֹתָהּ. שֶׁהֲרֵי יְהוּדָה וְכָל הַשְּׁבָטִים הָיוּ יוֹדְעִים אֶת זֶה וְעִקַּר הַדָּבָר וְהָקֵם זֶרַע, מִשּׁוּם שֶׁאוֹתוֹ הַזֶּרַע צָרִיךְ לְהִתְתַּקֵּן הַדָּבָר וְלִגְלֹם גֹּלֶם לְתִקּוּן שֶׁלֹּא יִפָּרֵד הַזֶּרַע מִשָּׁרְשׁוֹ כָּרָאוּי, זֶהוּ שֶׁכָּתוּב (איוב לד) וְאָדָם עַל עָפָר יָשׁוּב."],[9,"","וּכְשֶׁנִּתְקָן אַחַר כָּךְ כָּרָאוּי, אֵלּוּ מִשְׁתַּבְּחִים בָּעוֹלָם הַהוּא, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בָהֶם, וּמִשּׁוּם כָּךְ כָּתוּב (קהלת ד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, דַּוְקָא, מִן הַחַיִּים אֲשֶׁר הֵם חַיִּים עֲדֶנָה. מַה זֶּה עֲדֶנָה? כְּמוֹ שֶׁנֶּאֱמַר (בראשית יח) אַחֲרֵי בְלֹתִי הָיְתָה לִּי עֶדְנָה, וְכָתוּב (איוב לג) יָשׁוּב לִימֵי עֲלוּמָיו."],[10,"","וְטוֹב מִשְּׁנֵיהֶם אֵת אֲשֶׁר עֲדֶן לֹא הָיָה (שלא שב לימי עלומיו) אֲשֶׁר לֹא רָאָה אֶת הַמַּעֲשֶׂה הָרָע אֲשֶׁר נַעֲשָׂה תַּחַת הַשָּׁמֶשׁ. וְטוֹב מִשְּׁנֵיהֶם אֵת אֲשֶׁר עֲדֶן לֹא הָיָה, שֶׁלֹּא שָׁב לִימֵי עֲלוּמָיו וְלֹא צָרִיךְ לְהִתְתַּקֵּן וְלֹא סוֹבֵל חֲטָאִים רִאשׁוֹנִים, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ מָקוֹם מְתֻקָּן בָּעוֹלָם הַהוּא כָּרָאוּי."]]],[["תָּא חֲזֵי, מַה כְּתִיב, (קהלת ח׳:י׳) וּבְכֵן רָאִיתִי רְשָׁעִים קְבוּרִים וְגו', כְּמָה דְּאִתְּמָר. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד טִיבוּ וְלָא בָעָא לְשֵׁצָאָה עַלְמָא אֶלָּא כְּמָה דְאִתְּמָר, וְכָל אָרְחוֹי כֻּלְּהוּ קְשׁוֹט וּזְכוּ לְאוֹטָבָא לְהוּ בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי. זַכָּאָה חוּלְקֵהוֹן דְּצַדִּיקַיָיא דְּאִינוּן אָזְלֵי בְּאֹרַח קְשׁוֹט, עֲלַיְיהוּ כְּתִיב, (תהילים ל״ז:כ״ט) צַדִּיקִים יִרְשׁוּ אָרֶץ:","וַיֵּרַע בְּעֵינֵי יְיָ אֲשֶׁר עָשָׂה וַיָּמֶת גַּם אֹתוֹ. רִבִּי חִיָּיא פָּתַח, (קהלת י״א:ו׳) בַּבֹּקֶר זְרַע אֶת זַרְעֲךָ וְלָעֶרֶב אַל תַּנַּח יָדְךָ וְגו'. תָּא חֲזֵי, כַּמָּה אִתְחֲזֵי לֵיהּ לְבַר נָשׁ לְאִזְדַּהֲרָא מֵחוֹבוֹי, וּלְאִזְדַּהֲרָא בְּעוֹבָדוֹי קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. בְּגִין דְּכַמָּה שְׁלִיחָן וְכַמָּה מְמַנָּן אִינוּן בְּעַלְמָא, דְּאִינוּן אָזְלִין וְשָׁיְיטָן, וְחָמָאן עוֹבָדֵיהוֹן דִּבְנֵי נָשָׁא, וְסָהֲדִין עֲלוֹי (ז\"ח עלייהו) וְכֹלָּא בְּסִפְרָא כְתִיבִין.","וְתָּא חֲזֵי, בְּכָל אִינוּן חוֹבִין דְּאִסְתָּאַב בְּהוּ בַר נָשׁ בְּהַאי עַלְמָא, דָּא אִיהוּ חוֹבָא דְּאִסְתָּאַב בֵּיהּ בַר נָשׁ יַתִּיר בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי. מַאן דְּאוֹשִׁיד זַרְעֵיהּ בְּרֵיקַנְיָא, וְאַפִּיק זַרְעָא לְמַגָּנָא בִּידָא אוֹ בְּרַגְלָא וְאִסְתָּאַב בֵּיהּ. כְּמָה דְאַתְּ אָמֵר, (תהילים ה׳:ה׳) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לא יְגוּרְךָ רָע.","בְּגִין דָא לָא עָאל לְפַרְגּוֹדָא, וְלָא חָמֵי סְבָר אַפֵּי עַתִּיק יוֹמִין, כְּמָה דְּתָנִינָן כְּתִיב הָכָא לא יְגוּרְךָ רָע, וּכְתִיב וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי יְיָ. וּבְגִין כָּךְ כְּתִיב, (ישעיהו א׳:ט״ו-ט״ז) יְדֵיכֶם דָּמִים מָלֵאוּ. זַכָּאָה חוּלָקֵיהּ דְּבַר נָשׁ דְּדָחִיל לְמָארֵיהּ וִיהֵא נְטִיר מֵאוֹרַח בִּישָׁא, וְיַדְכֵּי גַרְמֵיהּ לְאִשְׁתַּדָּלָא בִּדְחִילוּ דְמָארֵיהּ.","תָּא חֲזֵי, בַּבֹּקֶר זְרַע אֶת זַרְעֶךָ, הַאי קְרָא אוּקְמוּהָ. בַּבֹּקֶר, דָּא הוּא בְּזִמְנָא דְּבַר נָשׁ אִתְקַיֵּים בְּחֵילֵיהּ וִיהֵא בְּעוּלֵימוֹ, כְּדֵין אִשְׁתַּדַּל לְאוֹלָדָא בְּנִין בְּאִיתְּתָא דְּחַזְיָא לֵיהּ, דִּכְתִיב בַּבֹּקֶר זְרַע אֶת זַרְעֶךָ.","דְּהָא כְּדֵין זִמְנָא אִיהוּ כְּמָה דְאַתְּ אָמֵר, (תהילים קכ״ז:ד׳) כְּחִצִּים בְּיַד גִּבּוֹר כֵּן בְּנִי הַנְּעוּרִים. בְּגִין דְּיָכִיל לְמֵילַף לְהוּ אָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, וִיהֵא לֵיהּ אַגְרָא טָבָא לְעַלְמָא דְאָתֵי. דִּכְתִיב אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ מֵהֶם לא יֵבשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר. לא יֵבוֹשׁוּ בְּהַהוּא עַלְמָא, בְּזִמְנָא דְמָארֵיהוֹן דְּדִינָא יֵיתוּן לְקַטְרְגָא עֲלוֹי. דְּלֵית לָךְ אַגְרָא טָבָא בְּהַהוּא עַלְמָא, כְּהַהוּא דְאוֹלִיף לֵיהּ לִבְרֵיהּ דְּחִילוּ דְמָרֵיהּ בְּאָרְחוֹי דְאוֹרַיְיתָא.","תָּא חֲזֵי מַה אָמַר בְּאַבְרָהָם, דִּכְתִיב, (בראשית י״ח:י״ט) כִּי יְדַעְתִּיו לְמַעַן אֲשֶׁר יְצַוֶּה אֶת בָּנָיו וְאֶת בֵּיתוֹ אַחֲרָיו וְשָׁמְרוּ דֶּרֶךְ יְיָ לַעֲשׂוֹת צְדָקָה וּמִשְׁפָּט. וְעַל דָּא הַהוּא זְכוּ קָיְימָא לֵיהּ בְּהַהוּא עַלְמָא לְגַבֵּי כָּל מָארֵיהוֹן דְּדִינָא.","וּבְגִין כָּךְ בַּבֹּקֶר זְרַע אֶת זַרְעֶךָ, וְלָעֶרֶב אַל תַּנַּח יָדֶךָ, אֲפִילּוּ בְּיוֹמֵי דְזִקְנָה, דְּאִיהוּ זִמְנָא דְסִיב בַר נָשׁ (לא יימא כבר אשתדלית ודי לי או כבר אשתדלית ולא יכילנא והשתא דאנא סיב לית אנא בעי ועם כל דא) מַה כְּתִיב אַל תַּנַּח יָדֶךָ לָא יִשְׁבּוֹק מִלְּאוֹלָדָא בְּהַאי עַלְמָא. מַאי טַעְמָא, בְּגִין דְּלָא תֵדַע אֵיזֶה יִכְשַׁר הַזֶּה אוֹ זֶה לִפְנֵי הָאֱלהִים. בְּגִין דִּיקוּמוּן בְּגִינֵיהּ בְּהַהוּא עַלְמָא.","וְעַל דָּא כְּתִיב (תהילים קכ״ז:ג׳) הִנֵּה נַחֲלַת יְיָ בָּנִים, דָּא צְרוֹרָא דְנִשְׁמָתָא סִטְרָא דְעַלְמָא דְאָתֵי, וּלְהַאי נַחֲלָה מַאן זָכֵי לֵיהּ לְבַר נָשׁ לְאַעָלָא בְּהַהוּא נַחֲלַת יְיָ, בָּנִים. אִינוּן בְּנִין זָכָאן לֵיהּ לְנַחֲלַת יְיָ, וְעַל דָּא זַכָּאָה הַהוּא בַּר נָשׁ דְּזָכֵי לוֹן דְּיוֹלִיף לוֹן אָרְחוֹי דְאוֹרַיְיתָא כְּמָה דְּאִתְּמָר:","וַתָּסַר בִּגְדֵי אַלְמְנוּתָהּ מֵעָלֶיהָ וְגו', תָּא חֲזֵי, תָּמָר בַּת כֹּהֵן הֲוַת, וְכִי סַלְקָא דַעְתָּךְ דְּאִיהִי אָזְלָא בְּגִין לְאַזְנָאָה עִם חָמוּהָ, דְּהָא אִיהִי צְנִיעוּתָא אִשְׁתַּכְּחַת בָּהּ תָּדִיר. אֶלָּא אִיהִי צַדֶּקֶת הֲוַת וּבְחָכְמָה עָבְדַת הַאי, דְּהָא אִיהִי לָא אַפְקָרַת גַּרְמָהּ לְגַבֵּיהּ, אֶלָּא בְּגִין דִּידִיעָה יָדְעַת וְחָכְמְתָא אִסְתַּכָּלַת. וְעַל דָּא אִיהִי אָתַת לְגַבֵּיהּ לְמֶעְבַּד (עמיה) טִיבוּ וּקְשׁוֹט, וְעַל דָּא אָתַת (להדיה) וְאִשְׁתַּדְּלַת בְּעִסְקָא דָא.","תָּא חֲזֵי, בְּגִין דְּאִיהִי יָדְעַת יְדִיעָה וְאִשְׁתַּדְּלַת בְּעִסְקָא דָא. קוּדְשָׁא בְּרִיךְ הוּא עֲבַד סִיּוּעָא תַּמָּן בְּהַהוּא עוֹבָדָא וְאִתְעֲבְּרַת מִיָּד. וְכֹלָּא הֲוָה מִנֵּיהּ. וְאִי תֵימָא אַמַּאי לָא אַיְיתֵי קוּדְשָׁא בְּרִיךְ הוּא אִינוּן בְּנִין מֵאִתְּתָא אוֹחֲרָא, אַמַּאי מִן דָּא. אֶלָּא וַדַּאי אִיהִי אִצְטְרִיכָא לְעוֹבָדָא דָא וְלָא אִתְּתָא אָחֳרָא."],[[0,"ת\"ח מה כתיב וכו':","בוא וראה, מה כתוב, ובכן ראיתי רשעים קבורים ובאו וגו' שהוא כמו שאמרנו, שבאו בגלגול להתתקן. משום שהקב\"ה עושה חסד ואינו רוצה לכלות העולם, אלא כמו שאמרנו, שהרשעים מתתקנים על ידי גלגול, וכל דרכיו אמת וחסד להטיב להם בעולם הזה ובעולם הבא, אשרי חלקם של הצדיקים ההולכים בדרך האמת, עליהם כתוב, צדיקים ירשו ארץ."],[1,"וירע בעיני ה' וגו':","רבי חייא פתח, בבקר זרע את זרעך ולערב אל תנח ידך וגו'. בוא וראה, כמה צריך האדם להזהר מחטאיו ולהזהר במעשיו לפני הקב\"ה, משום שכמה שליחים וכמה ממונים הם בעולם, ההולכים ומשוטטים ורואים מעשי בני אדם, ומעידים עליו. והכל כתוב בספר."],[2,"ות\"ח בכל אינון וכו':","ובוא וראה, בכל החטאים שאדם נטמא בהם בעוה\"ז, חטא זה הוא החטא שאדם נטמא בו ביותר בעולם הזה ובעולם הבא: מי ששופך זרעו לבטלה, ומוציא זרעו בחנם ביד או ברגל, ונטמא בו. כמש\"א, כי לא אל חפץ רשע אתה לא יגורך רע."],[3,"בג\"ד לא עאל וכו':","משום זה, אינו נכנס למחיצתו של הקב\"ה, ואינו רואה פני עתיק יומין. כמו שלמדנו, כתוב כאן, לא יגורך \u0003רע,\u0004 וכתוב, ויהי ער בכר יהודה \u0003רע בעיני ה',\u0004 שפירושו שאינו רואה פני ה', אף כאן אינו רואה פני ה'. וע\"כ כתוב ידיכם דמים מלאו, שפירושו, על המוציא זרעו לבטלה ביד, שהוא כשופך דמים. אשרי חלקו של אדם הירא את ה' והוא נשמר מדרך הרע, ומטהר עצמו לעסוק ביראת רבונו."],[4,"ת\"ח בבוקר זרע את זרעך:","מקרא זה בארוהו, \u0003בבקר,\u0004 זהו בזמן שאדם עומד בכחו והוא בימי עלומיו, ישתדל אז להוליד בנים באשה הראויה לו, שכתוב, בבקר זרע את זרעך."],[5,"דהא כדין זמנא וכו':","כי אז הזמן, להוליד בנים, כמו שאתה אומר, כחצים ביד גבור כן בני הנעורים, משום שיכול אז ללמד אותם דרכי הקב\"ה, ויהיה לו שכר טוב לעולם הבא. שכתוב, אשרי הגבר וגו' לא יבושו כי ידברו את אויבים בשער. \u0003לא יבושו,\u0004 בעולם האמת, בזמן שבעלי הדין יבואו לקטרג עליו. כי אין לך שכר טוב בעולם ההוא, כשכרו של המלמד לבנו יראת ה' בדרכי התורה."],[6,"ת\"ח מה אמר וכו':","בוא וראה מה אמר באברהם. שכתוב, כי ידעתיו למען וגו', וע\"כ זכות ההיא עמדה לו בעולם ההוא כנגד כל בעלי הדין."],[7,"ובג\"כ בבקר וגו':","וע\"כ כתוב, בבקר זרע את זרעך ולערב אל תנח ידך, אפילו בימי הזקנה, המכונים ערב, שהאדם זקן, מה כתוב, \u0003אל תנח ידך,\u0004 לא ינוח מלהוליד בעולם הזה, מה הטעם. הוא משום, \u0003כי אינך יודע איזה יכשר, הזה או זה,\u0004 לפני האלקים, דהיינו שיגינו עליו בעולם האמת."],[8,"ועל דא כתיב וכו':","וע\"כ כתוב, \u0003הנה נחלת ה' בנים,\u0004 זהו צרור החיים של הנשמה, בסו\"ה והיתה נפש אדני צרורה בצרור החיים, שהיא בחינת עולם הבא, ולזה קורא הכתוב נחלה. מי מזכה להביא את האדם בנחלת ה' הזו, \u0003בנים,\u0004 הבנים מזכים אותו לנחלת ה'. ועל כן, אשרי האדם שזכה לבנים, שילמד אותם דרכי התורה, כמו שלמדנו."],[9,"ותסר בגדי אלמנותה וגו':","בוא וראה, תמר, בת כהן היתה, וכי יעלה על דעתך שהלכה לזנות עם חמיה, הרי צניעות היתה בה תמיד. ומשיב, אלא היא צדקת היתה, ובחכמה עשתה זאת. כי לא היתה מפקרת עצמה אליו, אלא משום שידעה ידיעה והסתכלה בחכמה וראתה מה שעתיד לצאת מזה, ועל כן באה אצלו לעשות חסד ואמת, וע\"כ באה והשתדלה בעסק הזה."],[10,"ת\"ח בגין דאיהי וכו':","בוא וראה, משום שהיא ידעה ידיעה, מה שעתיד לצאת מזה, והשתדלה בעסק הזה, הקב\"ה נתן עזרה שם בפעולה ההוא, ונתעברה מיד, והכל היה ממנו. מן הקב\"ה."],[10,"ואי תימא אמאי וכו':","ואם תאמר, למה לא הביא הקב\"ה בנים האלו מאשה אחרת, למה הביאם מן זו, מתמר. ומשיב, אלא ודאי, היא נצרכה למעשה הזו, ולא אשה אחרת."]],[[0,"","בֹּא רְאֵה מַה כָּתוּב? (קהלת ח) וּבְכֵן רָאִיתִי רְשָׁעִים קְבֻרִים וְגוֹ', כְּמוֹ שֶׁנֶּאֱמַר מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה חֶסֶד וְלֹא רוֹצֶה לְכַלּוֹת אֶת הָעוֹלָם, אֶלָּא כְּמוֹ שֶׁנִּתְבָּאֵר, וְכָל דְּרָכָיו כֻּלָּם אֱמֶת וּזְכוּת לְהֵיטִיב לָהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהֵם הוֹלְכִים בְּדֶרֶךְ הָאֱמֶת, עֲלֵיהֶם כָּתוּב (תהלים לז) צַדִּיקִים יִירְשׁוּ אָרֶץ."],[1,"","וַיֵּרַע בְּעֵינֵי ה' אֲשֶׁר עָשָׂה וַיָּמֶת גַּם אֹתוֹ. רַבִּי חִיָּיא פָּתַח, (קהלת יא) בַּבֹּקֶר זְרַע אֶת זַרְעֶךְ וְלָעֶרֶב אַל תַּנַּח יָדֶךְ וְגוֹ'. בֹּא רְאֵה כַּמָּה רָאוּי לָאָדָם לְהִזָּהֵר מֵחֲטָאָיו וּלְהִזָּהֵר בְּמַעֲשָׂיו לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁכַּמָּה שְׁלוּחִים וְכַמָּה מְמֻנִּים הֵם בָּעוֹלָם שֶׁהֵם הוֹלְכִים וּמְשׁוֹטְטִים וְרוֹאִים אֶת מַעֲשֵׂי בְּנֵי הָאָדָם וּמְעִידִים עָלָיו (ז\"ח עליהם), וְהַכֹּל כְּתוּבִים בַּסֵּפֶר."],[2,"","וּבֹא וּרְאֵה, בְּכָל אוֹתָם הַחֲטָאִים שֶׁנִּטְמָא בָהֶם הָאָדָם יוֹתֵר בָּעוֹלָם הַזֶּה, זֶהוּ חֵטְא שֶׁנִּטְמָא בוֹ אָדָם יוֹתֵר בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא - מִי שֶׁשּׁוֹפֵךְ זַרְעוֹ לָרִיק וּמוֹצִיא זֶרַע לְחִנָּם בַּיָּד אוֹ בָרֶגֶל וְנִטְמָא בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ה) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע."],[3,"","בִּגְלַל זֶה לֹא נִכְנָס לַמְּחִצָּה וְלֹא רוֹאֶה תֹּאַר פָּנָיו שֶׁל עַתִּיק יוֹמִין, כְּמוֹ שֶׁלָּמַדְנוּ, כָּתוּב כָּאן לֹא יְגֻרְךְ רָע, וְכָתוּב וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה', וּמִשּׁוּם כָּךְ כָּתוּב (ישעיה א) יְדֵיכֶם דָּמִים מָלֵאוּ. אַשְׁרֵי חֶלְקוֹ שֶׁל הָאִישׁ שֶׁיָּרֵא מֵרִבּוֹנוֹ וְיִהְיֶה שָׁמוּר מִדֶּרֶךְ רָעָה, וִיטַהֵר עַצְמוֹ לְהִשְׁתַּדֵּל בְּיִרְאַת רִבּוֹנוֹ."],[4,"","בֹּא רְאֵה, בַּבּקֶר זְרַע (את) זַרְעֶךְ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, בַּבֹּקֶר - זֶהוּ בִּזְמַן שֶׁאָדָם עוֹמֵד בְּכֹחוֹ וְיִהְיֶה בַּעֲלוּמָיו, אָז יִשְׁתַּדֵּל לְהוֹלִיד בָּנִים עִם אִשָּׁה שֶׁרְאוּיָה לוֹ, שֶׁכָּתוּב בַּבֹּקֶר זְרַע אֶת זַרְעֶךְ."],[5,"","שֶׁהֲרֵי אָז הוּא הַזְּמַן, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קכז) כְּחִצִּים בְּיַד גִּבּוֹר כֵּן בְּנֵי הַנְּעוּרִים, מִשּׁוּם שֶׁיָּכוֹל לְלַמֵּד אוֹתָם דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְיִהְיֶה לוֹ שָׂכָר טוֹב לָעוֹלָם הַבָּא, שֶׁכָּתוּב אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ מֵהֶם לֹא יֵבוֹשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשַּׁעַר. לֹא יֵבוֹשׁוּ - בָּעוֹלָם הַהוּא, בִּזְמַן שֶׁבַּעֲלֵי הַדִּין יָבוֹאוּ לְקַטְרֵג עָלָיו, שֶׁאֵין לְךְ שָׂכָר טוֹב בָּעוֹלָם הַהוּא כְּמוֹ הַהוּא שֶׁמְּלַמֵּד אֶת בְּנוֹ יִרְאַת רִבּוֹנוֹ בְּדַרְכֵי הַתּוֹרָה."],[6,"","בֹּא רְאֵה מָה אָמַר בְּאַבְרָהָם, שֶׁכָּתוּב (בראשית יח) כִּי יְדַעְתִּיו לְמַעַן אֲשֶׁר יְצַוֶּה אֶת בָּנָיו וְאֶת בֵּיתוֹ אַחֲרָיו וְשָׁמְרוּ דֶּרֶךְ ה' לַעֲשׂוֹת צְדָקָה וּמִשְׁפָּט, וְעַל כֵּן אוֹתָהּ הַזְּכוּת קַיֶּמֶת לוֹ בָּעוֹלָם הַהוּא אֵצֶל כָּל בַּעֲלֵי הַדִּין."],[7,"","וּמִשּׁוּם כָּךְ בַּבֹּקֶר זְרַע אֶת זַרְעֶךְ, וְלָעֶרֶב אַל תַּנַּח יָדֶךְ - אֲפִלּוּ בִּימֵי הַזִּקְנָה, שֶׁהוּא הַזְּמַן שֶׁאָדָם זָקֵן, (לא יאמר כבר השתדלתי ודי לי, או כבר השתדלתי ואיני יכול, וכעת שאני זקן איני רוצה, ועם כל זה) מַה כָּתוּב? אַל תַּנַּח יָדֶךְ. לֹא יַנִּיחַ מִלְּהוֹלִיד בָּעוֹלָם הַזֶּה. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא תֵדַע אֵיזֶה יִכְשַׁר הֲזֶה אוֹ זֶה. לִפְנֵי הָאֱלֹהִים - כְּדֵי שֶׁיַּעַמְדוּ בִּשְׁבִילוֹ בָּעוֹלָם הַהוּא."],[8,"","וְעַל כֵּן כָּתוּב (תהלים קכז) הִנֵּה נַחֲלַת ה' בָּנִים. זֶהוּ צְרוֹר הַנְּשָׁמוֹת, הַצַּד שֶׁל הָעוֹלָם הַבָּא. וְלַנַּחֲלָה הַזּוֹ, מִי מְזַכֶּה אֶת הָאָדָם לְהִכָּנֵס לְאוֹתָהּ נַחֲלַת ה'? הַבָּנִים. אוֹתָם הַבָּנִים מְזַכִּים אוֹתוֹ לְנַחֲלַת ה', וְעַל כֵּן אַשְׁרֵי אוֹתוֹ הָאִישׁ שֶׁמְּזַכֶּה אוֹתָם לְלַמֵּד אוֹתָם דַּרְכֵי הַתּוֹרָה כְּמוֹ שֶׁנִּתְבָּאֵר."],[9,"","וַתָּסַר בִּגְדֵי אַלְמְנוּתָהּ מֵעָלֶיהָ וְגוֹ'. בֹּא רְאֵה, תָּמָר הָיְתָה בַּת כֹּהֵן, וְכִי תַעֲלֶה עַל דַּעְתְּךְ שֶׁהִיא הָלְכָה כְּדֵי לִזְנוֹת עִם חָמִיהָ? שֶׁהֲרֵי הִיא, צְנִיעוּת נִמְצְאָה בָּהּ תָּמִיד. אֶלָּא הִיא הָיְתָה צַדֶּקֶת, וּבְחָכְמָה עָשְׂתָה אֶת זֶה, שֶׁהֲרֵי הִיא לֹא הִפְקִירָה אֶת עַצְמָהּ אֵלָיו, אֶלָּא מִשּׁוּם שֶׁיָּדְעָה יְדִיעָה וּבְחָכְמָה הִתְבּוֹנְנָה, וְעַל כֵּן הִיא בָּאָה אֵלָיו לַעֲשׂוֹת (עמו) חֶסֶד וֶאֱמֶת, וְעַל זֶה בָּאָה (בפרהסיא) וְהִשְׁתַּדְּלָה בָּעֵסֶק הַזֶּה."],[10,"","בֹּא רְאֵה, מִשּׁוּם שֶׁהִיא יָדְעָה יְדִיעָה וְהִשְׁתַּדְּלָה בְּעֵסֶק זֶה, הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה שָׁם סִיּוּעַ בַּמַּעֲשֶׂה הַהוּא וּמִיָּד הִתְעַבְּרָה, וְהַכֹּל הָיָה מִמֶּנּוּ. וְאִם תֹּאמַר, לָמָּה לֹא הֵבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָם בָּנִים מֵאִשָּׁה אַחֶרֶת? לָמָּה מִזּוֹ? אֶלָּא וַדַּאי שֶׁהִיא הֻצְרְכָה לַמַּעֲשֶׂה הַזֶּה וְלֹא אִשָּׁה אַחֶרֶת."]]],[["תְּרֵין נְשִׁין הֲווּ דְּמִנַּיְיהוּ אִתְבְּנֵי זַרְעָא דִיהוּדָה, וְאֲתוּ מִנַּיְיהוּ דָּוִד מַלְכָּא וּשְׁלֹמֹה מַלְכָּא וּמַלְכָּא מְשִׁיחָא. וְאִלֵּין תְּרֵין נְשִׁין דָּא כְּגַוְונָא דְּדָא, תָּמָר וְרוּת דְּמִיתוּ בַּעֲלַיְיהוּ בְּקַדְמִיתָא, וְאִינוּן אִשְׁתַּדְּלוּ לְעוֹבָדָא דָא.","תָּמָר אִשְׁתַּדְּלַת לְגַבֵּי חָמוּהָ דְּאִיהוּ קָרִיב יַתִּיר לִבְנוֹי דְמִיתוּ. מַאי טַעְמָא אִיהִי אִשְׁתַּדְּלַת לְגַבֵּיהּ, דִּכְתִיב כִּי רָאֲתָה כִּי גָדַל שֵׁלָה וְהִיא לֹא נִתְּנָה לוֹ לְאִשָּׁה. וּבְגִין דָּא אִשְׁתַּדְּלַת בְּעוֹבָדָא דָא לְגַבֵּי חָמוּהָ.","רוּת מִית בַּעֲלָהּ וּלְבָתַר אִשְׁתַּדְּלַת בְּעוֹבָדָא דָא לְגַבֵּיהּ דְּבֹעַז דִּכְתִיב, (רות ג׳:ז׳) וַתְּגַל מַרְגְּלוֹתָיו וַתִּשְׁכָּב. וְאִשְׁתַּדְּלַת בַּהֲדֵיהּ וּלְבָתַר אוֹלִידַת לֵיהּ לְעוֹבֵד. וְאִי תֵימָא אַמַּאי לָא נָפִיק עוֹבֵד מֵאִתְּתָא אָחֳרָא, אֶלָּא וַדַּאי הִיא אִצְטְרִיכַת וְלָא אִתְּתָא אָחֳרָא. וּמִתְּרֵין אִלֵּין אִתְבְּנִי וְאִשְׁתַּכְלִיל זַרְעָא דִיהוּדָה, וְתַרְוַוְיְיהוּ בְּכַשְׁרוּת עָבְדוּ לְמֶעְבַּד טִיבוּ עִם אִינוּן מֵיתַיָיא לְאִתְתַּקְּנָא עַלְמָא לְבָתַר.","וְדָא הוּא כְּמָה דְאִתְּמָר (קהלת ד׳:ב׳) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, דְּהָא כַּד הֲווּ חַיִּין בְּקַדְמִיתָא לָא הֲוָה בְּהוּ שְׁבָחָא (ז\"ח ולבתר הוה בהו שבחא), וְתַרְוַויְיהוּ אִשְׁתַּדְּלוּ לְמֶעְבַּד טִיבוּ וּקְשׁוֹט עִם אִנּוּן מֵיתַיָיא, וְקוּדְשָׁא בְּרִיךְ הוּא סִיֵּיעַ בְּהַהוּא עוֹבָדָא וְכֹלָּא הֲוָה כְּדְקָא יָאוֹת. זַכָּאָה אִיהוּ מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא. כְּמָה דְאַתְּ אָמֵר, (יהושע א׳:ח׳) וְהָגִיתָ בוֹ יוֹמָם וָלַיְלָה לְמַעַן תִּשְׁמֹר לַעֲשׂוֹת כְּכָל הַכָּתוּב בּוֹ כִּי אָז תַּצְלִיחַ אֶת דְּרָכֶיךָ וְגו':","וְיוֹסֵף הוּרַד מִצְרַיְמָה וַיִּקְנֵהוּ פּוֹטִיפַר וְגו'. (מה כתיב לעיל ויכר יהודה ויאמר, איהו אמר לגבי אבוי הכר נא וגו', ועל דא ויכר יהודה. וכתיב והנה תאומים בבטנה. תאומין הוו מקדמת דנא אחין הוו. רבי חזקיה אמר, לא אשתמע הכי. אלא בנין אחרנין אתילידו. אמר רבי אבא, בגין כך אשתדלת לאשכחא אובדא דאתאביד. תא חזי מה כתיב, ויהי כמשיב ידו והנה יצא אחיו ותאמר מה פרצת עליך פרץ. רמז הכא פריצותא קדמאה דפריץ ההוא דמית עליה משמע דכתיב פרצת עליך פריצותא בגין דאצטריכת לאטרחא למרך ובגין כך פריצותא תעביד בשאר עמין עובדי עבודת כוכבים ומזלות. ועל דא ויקרא את שמו פרץ. ולבתר דכל עובדא דיהודה אתמר דיהודה זבין ליה ליוסף. ואיהו גרים ליה לכל האי. דאי יהודה הוה אמר נהדר ליה לאבונא הוו עבדין ליה אחוי הס ועל דא נחתו ליה אחוי משלטנותא דעליהו. לבתר דאתגלי מאחוי ואתא עליה כל דא אהדר ואמר ויוסף הורד מצרימה) מַאי הוּרַד. דְּאִסְתַּכַּם קוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא עוֹבָדָא לְקַיְימָא גְזֵרָה דִילֵיהּ דִּגְזַר בֵּין הַבְּתָרִים דִּכְתִיב, (בראשית ט״ו:י״ג) יָדוֹעַ תֵּדַע כִּי גֵר יִהְיֶה זַרְעֲךָ וְגו'. וַיִּקְנֵהוּ פּוֹטִיפַר לִסְטַר חֲטָאָה קָנָה לֵיהּ.","פָּתַח וְאָמַר, (איוב ט׳:ז׳) הָאֹמֵר לַחֶרֶס וְלֹא יִזְרָח וּבְעַד כּוֹכָבִים יַחְתֹּם. תָּא חֲזֵי, שִׁבְעָה כֹּכְבַיָא עֲבַד קוּדְשָׁא בְּרִיךְ הוּא בִּרְקִיעָא, וְכָל רְקִיעָא וּרְקִיעָא אִית בֵּיהּ כַּמָּה שַׁמָּשִׁין מְמַנִּין לְשַׁמָּשָׁא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא.","בְּגִין דְּלֵית לָךְ שַׁמָּשָׁא אוֹ מְמַנָּא דְּלֵית לֵיהּ פּוּלְחָנָא וְשִׁמּוּשָׁא לְמָארֵיהּ, וְקָיְימֵי כָּל חַד וְחַד עַל הַהוּא שִׁמּוּשָׁא דְּאִתְפַּקְדָא בֵּיהּ, וְכָל חַד יָדַע עֲבִידְתֵּיהּ לְשַׁמָּשָׁא.","מִנְּהוֹן מְשַׁמְּשֵׁי בִּשְׁלִיחוּתָא דְמָרֵיהוֹן וְאִתְפַּקְּדָן בְּעַלְמָא עַל כָּל עוֹבָדֵיהוֹן דִּבְנֵי נָשָׁא, וּמִנְּהוֹן דְּקָא מְשַׁבְּחִין לֵיהּ וְאִינוּן (הא) אִתְפַּקְּדָן עַל שִׁירָתָא. וְאַף עַל גַּב דְּאִינוּן אִתְפַּקְּדָן בְּהַאי, לֵית לָךְ כָּל חֵילָא בִּשְׁמַיָיא וְכֹכָבִין וּמַזָּלֵי דְּכֻלְּהוּ לָא מְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא.","דְּהָא בְּשַׁעְתָּא דְּעָאל לֵילְיָא כְּדֵין אִתְפַּרְשָׁן תְּלַת סִטְרִין מַשִּׁרְיָין לִתְלַת סִטְרֵי עַלְמָא, וּבְכָל סִטְרָא וְסִטְרָא אֶלֶף אַלְפִין וְרִבּוֹא רִבְבָן וְכֻלְּהוּ מְמַנָּן עַל שִׁירָתָא."],[[0,"תרין נשין הוו וכו':","שתי נשים היו, שמהן נבנה זרע יהודה, ומהן באו דוד המלך ושלמה המלך ומלך המשיח. ואלו שתי נשים היו זו כמו זו, כלומר שהיו שוות זו לזו. והן תמר ורות, שבעליהן מתו מתחילה, והן השתדלו למעשה זה."],[1,"תמר אשתדלת וכו':","תמר השתדלה בחמיה שהוא הקרוב ביותר לבניו שמתו, הראוי ליבם אותה, מה הטעם השתדלה בו. כתוב, כי ראתה כי גדל שלה והיא לא נתנה לו לאשה, ועל כן השתדלה במעשה הזה אצל חמיה."],[2,"רות מית בעלה וכו':","רות, מת בעלה, כמו תמר, ואח\"כ השתדלה במעשה הזה אצל בועז. שכתוב ותגל מרגלותיו ותשכב, והשתדלה בו, ואח\"כ הולידה את עובד, ואם תאמר, למה לא יצא עובד מאשה אחרת. ולא באופן כזה. ומשיב, אלא ודאי, היא נצרכה והולידו, ולא אשה אחרת, ומשתי אלה נבנה ונשתכלל זרע יהודה. ושתיהן עשו בכשרות, כדי לעשות טובה עם המתים, להתתקן אח\"כ בעולם."],[3,"ודא הוא כמה דאתמר וכו':","וזהו כמו שנאמר, ושבח אני את המתים שכבר מתו, כי כשהיו חיים בתחילה, בעליהן של תמר ורות, לא היה בהם שבח, ולאחר כך שמתו, ונתיבמו נשיהם נתגלגל מהם מלכות דוד ושלמה ומלך המשיח. ושתיהן, תמר ורות, השתדלו לעשות חסד ואמת עם המתים, והקב\"ה עזר להם באותו מעשה, והכל היה כראוי להיות. אשרי מי שמשתדל בתורה יום ולילה, כמש\"א, והגית בו יומם ולילה למען וגו'."],[4,"ויוסף הורד וגו':","שואל, מהו הורד, היה לו לומר ירד מצרימה, ומשיב, שהסכים הקב\"ה באותו מעשה של מכירת יוסף למצרים, כדי לקיים הגזירה שלו שגזר בין הבתרים, שכתוב, ידוע תדע כי גר יהיה זרעך וגו'. וע\"כ כתוב \u0003הורד,\u0004 כלומר הורד מן השמים, \u0003ויקנהו פוטיפר.\u0004 כדי לחטא עמו קנה אותו, דהיינו למשכב זכור."],[5,"פתח ואמר האומר לחרס וגו'",": בוא וראה שבעה כוכבים עשה הקב\"ה ברקיע, כנגד ז' ספירות חג\"ת נהי\"ם, וכל רקיע ורקיע יש בו כמה משמשים ממונים לשמש את הקב\"ה."],[6,"בגין דלית לך וכו':","כי אין לך משמש או ממונה שאין לו עבודה ושמוש מיוחד לרבונו, וכל אחד עומד על השמוש שלו שנתמנה עליו, וכל אחד יודע את עבודתו לשמש."],[7,"מנהון משמשי בשליחותא וכו':","מהם משמשים בשליחות רבונם. ונתמנים בעולם על כל מעשי בני אדם. ומהם שמשבחים לו שירות ותשבחות, והם שנתמנו על השירה. ואע\"פ שהם נתמנו על השירה, אין לך כל כח בשמים, והכוכבים והמזלות, שלא ישבחו כולם אל הקב\"ה."],[8,"דהא בשעתא וכו':","כי בשעה שבא לילה, מתחלקים אז ג' בחינות מחנות, לג' צדדי העולם, ובכל צד וצד אלף אלפים ורבי רבבות מלאכים, וכולם ממונים על השירה."]],[[0,"","שְׁתֵּי נָשִׁים הָיוּ שֶׁמֵּהֶן נִבְנָה הַזֶּרַע שֶׁל יְהוּדָה, וּבָאוּ מֵהֶן דָּוִד הַמֶּלֶךְ וּשְׁלֹמֹה הַמֶּלֶךְ וּמֶלֶךְ הַמָּשִׁיחַ, וּשְׁתֵּי הַנָּשִׁים הַלָּלוּ זוֹ כְּמוֹ זוֹ, תָּמָר וְרוּת שֶׁמֵּתוּ בַּעְלֵיהֶן בָּרִאשׁוֹנָה, וְהֵן הִשְׁתַּדְּלוּ לַמַּעֲשֶׂה הַזֶּה."],[1,"","תָּמָר הִשְׁתַּדְּלָה אֵצֶל חָמִיהָ, שֶׁהוּא יוֹתֵר קָרוֹב לְבָנָיו שֶׁמֵּתוּ. מָה הַטַּעַם הִיא הִשְׁתַּדְּלָה אֶצְלוֹ? שֶׁכָּתוּב כִּי רָאֲתָה כִּי גָדַל שֵׁלָה וְהִיא לֹא נִתְּנָה לוֹ לְאִשָּׁה, וּמִשּׁוּם זֶה הִשְׁתַּדְּלָה בַּמַּעֲשֶׂה הַזֶּה אֵצֶל חָמִיהָ."],[2,"","רוּת מֵת בַּעְלָהּ, וְאַחַר כָּךְ הִשְׁתַּדְּלָה בַּמַּעֲשֶׂה הַזֶּה אֵצֶל בֹּעַז, שֶׁכָּתוּב (רות ג) וַתְּגַל מַרְגְּלֹתָיו וַתִּשְׁכָּב, וְהִשְׁתַּדְּלָה עִמּוֹ, וְאַחַר כָּךְ הוֹלִידָה אֶת עוֹבֵד. וְאִם תֹּאמַר, לָמָּה לֹא יָצָא עוֹבֵד מֵאִשָּׁה אַחֶרֶת? אֶלָּא וַדַּאי הִיא הֻצְרְכָה וְלֹא אִשָּׁה אַחֶרֶת. וּמִשְּׁתֵּי אֵלּוּ נִבְנָה וְנִתְקַן זַרְעוֹ שֶׁל יְהוּדָה, וּשְׁתֵּיהֶן עָשׂוּ בְּכַשְׁרוּת, לַעֲשׂוֹת חֶסֶד עִם אוֹתָם הַמֵּתִים לְתַקֵּן אֶת הָעוֹלָם לְאַחַר מִכֵּן."],[3,"","וְזְהִוּ כְּמוֹ שֶׁנֶּאֱמַר (קהלת ד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, שֶׁהֲרֵי כְּשֶׁהָיוּ חַיִּים בַּהַתְחָלָה, לֹא הָיָה בָּהֶם שֶׁבַח (ז\"ח ואחר כך היה בהם שבח), וּשְׁתֵּיהֶן הִשְׁתַּדְּלוּ לַעֲשׂוֹת חֶסֶד וֶאֱמֶת עִם אוֹתָם הַמֵּתִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא סִיַּע בְּאוֹתוֹ הַמַּעֲשֶׂה וְהַכֹּל הָיָה כָּרָאוּי. אַשְׁרֵי הוּא מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה, כְּמוֹ שֶׁנֶּאֱמַר (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלָיְלָה לְמַעַן תִּשְׁמֹר לַעֲשׂוֹת כְּכָל הַכָּתוּב בּוֹ כִּי אָז תַּצְלִיחַ אֶת דְּרָכֶךְ וְגוֹ'."],[4,"","וְיוֹסֵף הוּרַד מִצְרָיְמָה וַיִּקְנֵהוּ פּוֹטִיפַר וְגוֹ'. (מה כתוב למעלה? ויכר יהודה ויאמר, הוא אמר לאביו הכר נא וגו', ועל כן ויכר יהודה, וכתוב והנה תאומים בבטנה, תאומים היו מקדם לכן אחים היו, רבי חזקיה אמר, לא כך נשמע, אלא בנים אחרים נולדו, אמר רבי אבא, משום כך השתדלה למצא האבדה שנאבדה בא ראה מה כתוב, ויהי כמשיב ידו והנה יצא אחיו ותאמר מהפרצת עליך פרץ, רמז כאן התפרצות ראשונה שפרץ זה שמת עליו, ממשמע שכתוב פרצת עליך, התפרצות בגלל שהצטרכת להטריח לאדונך, ומשום כך התפרצות תעשה בשאר אמות עובדי עבודת כוכבים ומזלות, ועל זה ויקרא שמו פרץ, ולאחר שכל מעשה של יהודה נאמר שיהודה מכר לו ליוסף, והוא גרם לו לכל זה, שאם יהודה היה אומר נחזיר אותו לאבינו, היו עושים לו אחיו כך, ועל זה הורידו אותו אחיו משלטונו שעליהם, ולבסוף שגלה מאחיו ובא עליו כל זה, חזר ואמר ויוסף הורד מצרימה) מַה זֶּה הוּרַד? שֶׁהִסְכִּים הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ הַמַּעֲשֶׂה לְקַיֵּם אֶת הַגְּזֵרָה שֶׁלּוֹ שֶׁגָּזַר בֵּין הַבְּתָרִים, שֶׁכָּתוּב (בראשית טו) יָדוֹעַ תֵּדַע כִּי גֵר יִהְיֶה זַרְעֲךְ וְגוֹ'. וַיִּקְנֵהוּ פּוֹטִיפַר, לְצַד הַחֵטְא קָנָה אוֹתוֹ."],[5,"","פָּתַח וְאָמַר, (איוב ט) הָאֹמֵר לַחֶרֶס וְלֹא יִזְרָח וּבְעַד כּוֹכָבִים יַחְתֹּם. בֹּא רְאֵה, שִׁבְעָה כּוֹכָבִים עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָקִיעַ, וּבְכָל רָקִיעַ וְרָקִיעַ יֵשׁ כַּמָּה שַׁמָּשִׁים מְמֻנִּים לְשִׁמּוּשׁוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[6,"","מִשּׁוּם שֶׁאֵין לְךְ שַׁמָּשׁ אוֹ מְמֻנֶּה שֶׁאֵין לוֹ עֲבוֹדָה וְשִׁמּוּשׁ לַאֲדוֹנוֹ, וְעוֹמְדִים כָּל אֶחָד וְאֶחָד עַל אוֹתוֹ הַשִּׁמּוּשׁ שֶׁנִּתְמַנָּה בוֹ, וְכָל אֶחָד יוֹדֵעַ עֲבוֹדָתוֹ לְשַׁמֵּשׁ."],[7,"","מֵהֶם שֶׁמְּשַׁמְּשִׁים בִּשְׁלִיחוּת רִבּוֹנָם וּמֻפְקָדִים בָּעוֹלָם עַל כָּל מַעֲשֵׂי בְּנֵי הָאָדָם, וּמֵהֶם שֶׁמְּשַׁבְּחִים אוֹתוֹ, וְהֵם (הרי) מֻפְקָדִים עַל הַשִּׁירָה. וְאַף עַל גַּב שֶׁהֵם מֻפְקָדִים עַל זֶה, אֵין לְךְ כָּל חַיִל בַּשָּׁמַיִם וְכוֹכָבִים וּמַזָּלוֹת שֶׁכֻּלָּם לֹא מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא."],[8,"","שֶׁהֲרֵי בְּשָׁעָה שֶׁנִּכְנָס הַלַּיְלָה, אָז נִפְרָדִים שְׁלֹשָׁה צְדָדִים מַחֲנוֹת לִשְׁלֹשֶׁת צִדְדֵי הָעוֹלָם, וּבְכָל צַד וְצַד אֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת, וְכֻלָּם מְמֻנִּים עַל הַשִּׁירָה."]]],[["תְּלַת מַשִּׁרְיָין אִינוּן, וְחַד חֵיוָתָא קַדִּישָׁא מְמַנָּא עֲלַיְיהוּ וְקָיְימָא עֲלַיְיהוּ, וְכֻלְּהוּ קָא מְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא עַד דְּאָתֵי צַפְרָא, כַּד אָתֵי צַפְרָא, כָּל אִינוּן דְּבִסְטַר דָּרוֹם וְכָל כֹּכְבַיָא דְּנָהֲרֵי, כֻּלְּהוּ מְשַׁבְּחָן וְאָמְרֵי שִׁירָתָא לְקוּדְשָׁא בְּרִיךְ הוּא כְּמָה דְאַתְּ אָמֵר, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. בְּרָן יַחַד כֹּכְבֵי בֹקֶר, אִלֵּין כֹּכְבַיָא דְּבִסְטַר דָּרוֹם כְּמָה דְאַתְּ אָמֵר, (בראשית י״ט:כ״ז) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. וַיָּרִיעוּ כָּל בְּנֵי אֱלהִים, אִלֵּין אִינוּן דְּבִסְטַר שְׂמָאלָא דְּאִתְכְּלִילוּ בִּימִינָא.","וּכְדֵין צַפְרָא נָהִיר, וְיִשְׂרָאֵל נָטְלֵי שִׁירָתָא וּמְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בִּימָמָא, תְּלַת זִמְנִין בִּימָמָא, לָקֳבֵל תְּלַת זִמְנִין דְּלֵילְיָא. וְקָיְימִין אִלֵּין לָקֳבֵיל אִלֵּין, עַד דְּיִסְתַּלַּק יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא בִּימָמָא וּבְלֵילְיָא כְּדְקָא יְאוּת, וְקוּדְשָׁא בְּרִיךְ הוּא אִסְתַּלַּק בְּהוּ בְּשִׁית אִלֵּין.","הַהוּא חֵיוָתָא קַדִּישָׁא דְּקָיְימָא עֲלַיְיהוּ לְעֵילָא קָיְימָא עַל יִשְׂרָאֵל לְתַתָּא בְּגִין לְאַתְקָנָא כֹּלָּא כְּדְקָא יְאוּת. מַה כְּתִיב בָּהּ (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. וַתִּתֵּן טֶרֶף לְבֵיתָהּ אִלֵּין אִינוּן מַשִּׁירְיָין דִּלְעֵילָא, וְחֹק לְנַעֲרוֹתֶיהָ אִלֵּין מַשִּׁרְיָין דְּיִשְׂרָאֵל לְתַתָּא, וּבְגִין כָּךְ יְקָרָא דְקוּדְשָׁא בְּרִיךְ הוּא אִסְתַּלַּק מִכָּל סִטְרִין מֵעֵילָא וּמִתַּתָּא. וְעַל דָּא כֹּלָּא הֲוָה (ס\"א הוא) בִּרְשׁוּתֵיהּ קַיְימָא, וְכֹלָּא אִיהוּ בִּרְעוּתֵיהּ.","(איוב ט׳:ז׳) הָאוֹמֵר לַחֶרֶס וְלא יִזְרָח. רִבִּי שִׁמְעוֹן אָמַר, דָּא יוֹסֵף. וּבְעַד כּוֹכָבִים יַחְתּוֹם, אִלֵּין אִינוּן אֲחוֹי דִּכְתִיב בְּהוּ וַאֲחַד עָשָׂר כּוֹכָבִים מִשְׁתַּחֲוִים לִי. דָּבָר אַחֵר הָאוֹמֵר לַחֶרֶס, דָּא יַעֲקֹב, בְּשַׁעְתָּא דְּאָמְרוּ לוֹ הַכֶּר נָא. וְלא יִזְרָח, בְּשַׁעְתָּא דְּאִסְתַּלְקַת שְׁכִינְתָּא מִנֵּיהּ. וּבְעַד כֹּכָבִים יַחְתּוֹם, בְּגִין בְּנוֹי אִתְחַתַּם וְאַסְתִּים נְהוֹרָא דִּילֵיהּ, שִׁמְשָׁא אִתְחַשַׁךְ וְכֹכְבַיָא לָא נְהִירוּ בְּגִין דְּיוֹסֵף אִתְפָּרַשׁ מֵאֲבוֹי. וְתָּא חֲזֵי, מֵהַהוּא יוֹמָא דְהַהוּא עוֹבָדָא דְיוֹסֵף, אִתְפְּרַשׁ יַעֲקֹב מִשִּׁמּוּשָׁא דְּעַרְסָא וְאִשְׁתָּאַר אֲבֵלָא עַד הַהוּא יוֹמָא דְּאִתְבַּשַּׂר בְּשׂוֹרָה דְיוֹסֵף:","וַיְהִי יְיָ אֶת יוֹסֵף וַיְהִי אִישׁ מַצְלִיחַ וַיְהִי בְּבֵית אֲדוֹנָיו וְגו'. רִבִּי יוֹסֵי פָּתַח, (תהילים ל״ז:כ״ח) כִּי ה' אוֹהֵב מִשְׁפָּט וְלֹא יַעֲזֹב אֶת חֲסִידָיו לְעוֹלָם נִשְׁמָרוּ. הַאי קְרָא אוּקְמוּהָ בְּאַבְרָהָם, אֶת חֲסִידָיו, חֲסִידוֹ כְּתִיב, וְהָא אִתְּמָר.","תָּא חֲזֵי, בְּכָל אֲתַר דְּצַדִּיקַיָא אָזְלֵי, קוּדְשָׁא בְּרִיךְ הוּא נָטִיר לוֹן וְלָא שָׁבִיק לוֹן. דָּוִד אָמַר, (תהילים כ״ג:ד׳) גַּם כִּי אֵלֵךְ בְּגֵיא צַלְמָוֶת לֹא אִירָא רָע כִּי אַתָּה עִמָּדִי שִׁבְטְךָ וּמִשְׁעַנְתְּךָ וְגו'. בְּכָל אֲתַר דְּצַדִּיקַיָא אָזְלֵי, שְׁכִינְתָּא אָזְלָא עִמְּהוֹן וְלָא שָׁבִיק לוֹן.","יוֹסֵף אָזַל בְּגֵיא צַלְמָוֶת וְנָחֲתוּ לֵיהּ לְמִצְרַיִם, שְׁכִינְתָא הֲוַת עִמֵּיהּ. הֲדָא הוּא דִּכְתִיב, וַיְהִי יְיָ אֶת יוֹסֵף. וּבְגִין דְּהֲוַת עִמֵּיהּ שְׁכִינְתָּא בְּכָל מַה דְּהֲוָה עָבִיד הֲוָה מַצְלַח בִּידֵיהּ. דְּאָפִילּוּ מַאי דְהֲוָה בִּידֵיהּ וְהֲוָה תָּבַע לֵיהּ מָארֵיהּ בְּגַוְונָא אָחֳרָא, הֲוָה מִתְהַפֵּךְ בִּידֵיהּ לְהַהוּא גַוְונָא דִּרְעוּתָא דְמָארֵיהּ הֲוָה רָעֵי בֵּיהּ. כְּמָה דְאַתְּ אָמֵר, וַיַּרְא אֲדוֹנָיו כִּי יְיָ אִתּוֹ וְכָל אֲשֶׁר הוּא עוֹשֶׂה יְיָ מַצְלִיחַ בְּיָדוֹ, מַצְלִיחַ בְּיָדוֹ וַדַּאי, כִּי יְיָ אִתּוֹ.","תָּא חֲזֵי, וַיֵּדַע אֲדֹנָיו כִּי יְיָ אִתּוֹ לָא כְּתִיב, אֶלָּא וַיַּרְא אֲדֹנָיו, דְּהָא בְּעֵינוֹי הֲוָה חָמֵי עוֹבָדָא דְנִסִּין בְּכָל יוֹמָא דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד בִּידֵיהּ, וְעַל דָּא וַיְבָרֶךְ יְיָ אֶת בֵּית הַמִּצְרִי בִּגְלַל יוֹסֵף. קוּדְשָׁא בְּרִיךְ הוּא נָטִיר לוֹן לְצַדִּיקַיָא וּבְגִינֵהוֹן נָטַר לוֹן לְרַשִּׁיעַיָא, דְּהָא רַשִּׁיעַיָא מִתְבָּרְכִין בְּגִינֵהוֹן דְּצַדִּיקַיָא. כְּגַוְונָא דָא כְּתִיב, (שמואל ב ו׳:י״ב) וַיְבָרֶךְ יְיָ אֶת בֵּית עוֹבֵד אֱדוֹם הַגִּתֵּי בַּעֲבוּר אֲרוֹן הָאֱלהִים.","צַדִּיקַיָא, אָחֳרָנִין מִתְבָּרְכִין בְּגִינַייהוּ, וְאִינוּן לָא יָכְלוּ לְאִתְּזְנָא (ס\"א לאשתזבא) בִּזְכוּתַיְיהוּ, וְהָא אוּקְמוּהָ. יוֹסֵף אִתְבָּרֵךְ מָארֵיהּ בְּגִינֵיהּ, וְאִיהוּ לָא יָכִיל לְאִשְׁתְּזָבָא בִּזְכוּתֵיהּ מִנֵּיהּ וּלְנָפְקָא לְחֵירוּ.","וּלְבָתַר אָעִיל לֵיהּ בְּבֵית הַסֹּהַר כְּמָה דְאַתְּ אָמֵר (תהילים ק״ה:י״ח-י״ט) עִנּוּ בַכֶּבֶל רַגְלוֹ בַּרְזֶל בָּאָה נַפְשׁוֹ, עַד דִּלְבָתַר קוּדְשָׁא בְּרִיךְ הוּא אַפִּיק לֵיהּ לְחֵירוּ וְשַׁלְטֵיהּ עַל כָּל אַרְעָא דְמִצְרָיִם. וּבְגִין כָּךְ כְּתִיב וְלא יַעֲזֹב אֶת חֲסִידָיו לְעוֹלָם נִשְׁמָרוּ, חֲסִידוֹ כְּתִיב וְאִתְּמָר. וְקוּדְשָׁא בְּרִיךְ הוּא אָגִין עֲלַיְיהוּ דְּצַדִּיקַיָא, בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי. דִּכְתִיב, (תהילים ה׳:י״ב) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנִּנוּ וְתָסֵךְ עָלֵימוּ וְיַעְלְצוּ בְךָ אוֹהֲבֵי שְׁמֶךָ:"],[[0,"תלת משריין אנון וכו':","ג' מחנות מלאכים הם כנ\"ל, וחיה אחת, שהיא הנוקבא, ממונה עליהם ועומדת עליהם, וכולם משבחים אל הקב\"ה עד שבא הבוקר. כשבא הבוקר, כל אלו שבצד דרום, וכל הכוכבים, דהיינו המלאכים, המאירים, כולם משבחים ואומרים שירה להקב\"ה, כמש\"א, ברן יחד ככבי בקר ויריעו כל בני אלקים. \u0003ברן יחד ככבי בקר,\u0004 הם הככבים שבצד דרום, דהיינו צד ימין חסד, כמש\"א וישכם אברהם בבוקר. \u0003ויריעו כל בני אלקים,\u0004 אלו הם הככבים שבצד שמאל שנכללו בימין."],[1,"וכדין צפרא נהיר וכו':","ואז הבוקר מאיר, וישראל לוקחים השירה, ומשבחים אל הקב\"ה ג' פעמים ביום, כנגד ג' פעמים, שהם ג' משמורות שבלילה. ועומדים אלו מול אלו עד שמתעלה כבוד הקב\"ה ביום ובלילה כראוי. והקב\"ה מתעלה בששה אלו. דהיינו ג' של יום וג' של לילה, האמורים."],[2,"ההוא חיותא קדישא וכו':","אותה החיה העומדת עליהם למעלה (כנ\"ל אות ר') שהיא הנוקבא, עומדת גם על ישראל למטה, כדי לתקן הכל כראוי. מה כתוב בה, ותקם בעוד לילה ותתן טרף וגו'. \u0003ותתן טרף לביתה,\u0004 אלו הם המחנות של מעלה, שהם תלת משריין הנ\"ל. \u0003וחק לנערותיה,\u0004 אלו מחנות ישראל שלמטה. ועל כן כבוד הקב\"ה מתעלה מכל הצדדים, מלמעלה ומלמטה, וע\"כ הכל ברשותו עומד והכל הוא ברצונו."],[3,"האומר לחרס ולא יזרח:","ר\"ש אמר, זהו יוסף. בשעה שמכרוהו למצרים. \u0003ובעד ככבים יחתום,\u0004 אלו הם אחיו, שכתוב בהם ואחד עשר ככבים משתחוים לי. פירוש אחר. האומר \u0003לחרם,\u0004 זהו יעקב, בשעה שאמרו לו הכר נא הכתונת בנך היא אם לא. \u0003ולא יזרח,\u0004 בשעה שנסתלקה ממנו השכינה. \u0003ובעד ככבים יחתום,\u0004 בעד בניו נחתם ונסתם ממנו האור שלו. השמש נחשך, והככבים לא האירו, משום שיוסף נפרד מאביו. ובוא וראה, מיום שהיה אותו מעשה של יוסף. נפרש יעקב מתשמיש המטה, ונשאר אבל, עד היום שנתבשר בבשורת יוסף."],[4,"ויהי ה' את יוסף וגו':","רבי יוסי פתח, כי ה' אוהב משפט ולא יעזוב \u0003את חסידיו\u0004 לעולם נשמרו, מקרא זה בארוהו באברהם, ועל כן, \u0003את חסידיו,\u0004 כתוב \u0003חסידו,\u0004 בלשון יחיד, וכבר נתבאר."],[5,"ת\"ח בכל אתר וכו':","בוא וראה בכל מקום שצדיקים הולכים, שומר אותם הקב\"ה ואינו עוזב אותם. דוד אמר, גם כי אלך בגיא וגו'. כי בכל מקום שצדיקים הולכים, השכינה הולכת עמהם ואינה עוזבת אותם."],[6,"יוסף אזל וכו'",": יוסף הלך בגיא צלמות והורידוהו למצרים, השכינה היתה עמו, וזהו שכתוב, ויהי ה' את יוסף, ומשום שהיתה עמו השכינה, כל מה שהיה עושה היה מצליח \u0003בידו,\u0004 ואפילו אם כבר היה \u0003בידו\u0004, ורבונו דרש ממנו באופן אחר ממה שהיה, היה הדבר מתהפך \u0003בידו,\u0004 לאותו אופן שרבונו היה רוצה בו. כמש\"א, וירא אדניו וגו' ה' מצליח \u0003בידו,\u0004 מצליח \u0003בידו\u0004 ודאי, כי ה' אתו."],[7,"ת\"ח וידע וגו':","בוא וראה, וידע אדניו כי ה' אתו לא כתוב, אלא \u0003וירא\u0004 אדניו, ללמד, שהיה רואה בעיניו בכל יום, מעשה נסים שהקב\"ה עשה בידו. וע\"כ ויברך ה' את בית המצרי בגלל יוסף. הקב\"ה שומר את הצדיקים, ובשבילם שומר גם את הרשעים, כי הרשעים מתברכים בזכותם של הצדיקים. כעין זה כתוב, ויברך ה' את בית עובד אדום וגו'."],[8,"צדיקיא אחרנין וכו':","הצדיקים, אחרים מתברכים בשבילם, והם עצמם אינם יכולם להנצל בזכותם. ובארוה. יוסף, נתברך רבונו בשבילו, והוא עצמו לא יכול להנצל ממנו בזכותו, ולצאת לחירות."],[9,"ולבתר אעיל ליה וכו':","ואחר כך הכניסו לבית הסוהר, כמש\"א, ענו בכבל רגלו ברזל באה נפשו, עד שלאחר כך הוציאו הקב\"ה לחירות והשליטו על כל ארץ מצרים. וע\"כ כתוב, ולא יעזוב את חסידיו לעולם נשמרו. \u0003חסידו\u0004 כתוב, ונתבאר. והקב\"ה מגין על הצדיקים בעולם הזה ובעולם הבא. שכתוב, וישמחו כל חוסי בך וגו'."]],[[0,"","שְׁלשָה מַחֲנוֹת הֵם, וְחַיָּה קְדוֹשָׁה אַחַת מְמֻנָּה עֲלֵיהֶם וְעוֹמֶדֶת עֲלֵיהֶם, וְכֻלָּם מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁבָּא הַבֹּקֶר. כְּשֶׁבָּא הַבֹּקֶר, כָּל אוֹתָם שֶׁבְּצַד דָּרוֹם וְכָל הַכּוֹכָבִים שֶׁמְּאִירִים, כֻּלָּם מְשַׁבְּחִים וְאוֹמְרִים שִׁירָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא, כְּמוֹ שֶׁנֶּאֱמַר (איוב לח) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. בְּרָן יַחַד כֹּכְבֵי בֹקֶר - אֵלּוּ הַכּוֹכָבִים שֶׁבְּצַד דָּרוֹם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית יט) וַיַּשְׁכֵּם אַבְרָהָם"],[1,"","בַּבּקֶר. וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים - אֵלּוּ הֵם שֶׁבְּצַד שְׂמֹאל שֶׁנִּכְלְלוּ בַּיָּמִין. וְאָז מֵאִיר הַבּקֶר, וְיִשְׂרָאֵל נוֹשְׂאִים שִׁירָה וּמְשַׁבְּחִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא בַּיּוֹם, שָׁלֹשׁ פְּעָמִים בַּיּוֹם כְּנֶגֶד שָׁלֹשׁ פְּעָמִים שֶׁל הַלַּיְלָה, וְעוֹמְדִים אֵלֶּה כְּנֶגֶד אֵלֶּה, עַד שֶׁמִּתְעַלֶּה כְבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּיּוֹם וּבַלַּיְלָה כָּרָאוּי, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַלֶּה בַּשֵּׁשׁ הַלָּלוּ."],[2,"","אוֹתָהּ הַחַיָּה הַקְּדוֹשָׁה שֶׁעוֹמֶדֶת עֲלֵיהֶם לְמַעְלָה, עוֹמֶדֶת עַל יִשְׂרָאֵל לְמַטָּה כְּדֵי לְתַקֵּן הַכֹּל כָּרָאוּי. מַה כָּתוּב בָּהּ? (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ. וַתִּתֵּן טֶרֶף לְבֵיתָהּ - אֵלּוּ אוֹתָם הַמַּחֲנוֹת שֶׁלְּמַעְלָה. וְחֹק לְנַעֲרֹתֶיהָ - אֵלּוּ הַמַּחֲנוֹת שֶׁל יִשְׂרָאֵל לְמַטָּה. וּמִשּׁוּם כָּךְ כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַלֶּה מִכָּל הַצְּדָדִים, מִמַּעְלָה וּמִמַּטָּה, וְעַל כֵּן הַכֹּל הָיָה (הוא) עוֹמֵד בִּרְשׁוּתוֹ וְהַכֹּל הוּא בִּרְצוֹנוֹ."],[3,"","(איוב ט) הָאֹמֵר לַחֶרֶס וְלֹא יִזְרָח - רַבִּי שִׁמְעוֹן אָמַר זֶה יוֹסֵף. וּבְעַד כּוֹכָבִים יַחְתֹּם - אֵלּוּ הֵם אֶחָיו, שֶׁכָּתוּב בָּהֶם וְאַחַד עָשָׂר כּוֹכָבִים מִשְׁתַּחֲוִים לוֹ. דָּבָר אַחֵר, הָאֹמֵר לַחֶרֶס - זֶה יַעֲקֹב בְּשָׁעָה שֶׁאָמְרוּ לוֹ הַכֶּר נָא. וְלֹא יִזְרָח - בְּשָׁעָה שֶׁהִסְתַּלְּקָה מִמֶּנּוּ הַשְּׁכִינָה. וּבְעַד כּוֹכָבִים יַחְתֹּם - מִשּׁוּם בָּנָיו נֶחְתַּם וְנִסְתַּם הָאוֹר שֶׁלּוֹ, הַשֶּׁמֶשׁ חָשַׁךְ וְהַכּוֹכָבִים לֹא הֵאִירוּ, מִשּׁוּם שֶׁיּוֹסֵף נִפְרַד מֵאָבִיו. וּבֹא וּרְאֵה, מֵאוֹתוֹ הַיּוֹם שֶׁל אוֹתוֹ הַמַּעֲשֶׂה שֶׁל יוֹסֵף, נִפְרַד יַעֲקֹב מִשִּׁמּוּשׁ הַמִּטָּה, וְנִשְׁאַר אָבֵל עַד אוֹתוֹ הַיּוֹם שֶׁהִתְבַּשֵּׂר בְּשׂוֹרַת יוֹסֵף."],[4,"","וַיְהִי ה' אֶת יוֹסֵף וַיְהִי אִישׁ מַצְלִיחַ וַיְהִי בְּבֵית אֲדנָיו וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (תהלים לז) כִּי ה' אֹהֵב מִשְׁפָּט וְלֹא יַעֲזֹב אֶת חֲסִידָיו לְעוֹלָם נִשְׁמָרוּ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ בְּאַבְרָהָם. אֶת חֲסִידָיו, כָּתוּב חֲסִידוֹ, וַהֲרֵי נִתְבָּאֵר."],[5,"","בֹּא רְאֵה, בְּכָל מָקוֹם שֶׁהַצַּדִּיקִים הוֹלְכִים, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתָם וְלֹא עוֹזֵב אוֹתָם. דָּוִד אָמַר (שם כג) גַּם כִּי אֵלֵךְ בְּגֵיא צַלְמָוֶת לֹא אִירָא רָע כִּי אַתָּה עִמָּדִי שִׁבְטְךְ וּמִשְׁעַנְתֶּךְ וְגוֹ'. בְּכָל מָקוֹם שֶׁהַצַּדִּיקִים הוֹלְכִים, הַשְּׁכִינָה הוֹלֶכֶת עִמָּהֶם וְלֹא עוֹזֶבֶת אוֹתָם."],[6,"","יוֹסֵף הָלַךְ בְּגֵיא צַלְמָוֶת וְהוֹרִידוֹ אוֹתוֹ לְמִצְרַיִם - הַשְּׁכִינָה הָיְתָה עִמּוֹ, זֶהוּ שֶׁכָּתוּב וַיְהִי ה' אֶת יוֹסֵף. וּמִשּׁוּם שֶׁשְּׁכִינָה הָיְתָה עִמּוֹ - בְּכָל מַה שֶּׁהָיָה עוֹשֶׂה, הָיָה מַצְלִיחַ בְּיָדוֹ. שֶׁאֲפִלּוּ מַה שֶּׁהָיָה בְּיָדוֹ וְהָיָה מְבַקֵּשׁ אוֹתוֹ אֲדוֹנוֹ בְּגָוֶן אַחֵר - הָיָה מִתְהַפֵּךְ בְּיָדוֹ לְאוֹתָהּ הַצּוּרָה שֶׁרְצוֹן אֲדוֹנוֹ הָיָה רוֹצֶה בָהּ, כְּמוֹ שֶׁנֶּאֱמַר וַיַּרְא אֲדנָיו כִּי ה' אִתּוֹ וְכֹל אֲשֶׁר הוּא עֹשֶׂה ה' מַצְלִיחַ בְּיָדוֹ. מַצְלִיחַ בְּיָדוֹ וַדַּאי, כִּי ה' אִתּוֹ."],[7,"","בֹּא רְאֵה, וַיֵּדַע אֲדנָיו כִּי ה' אִתּוֹ לֹא כָתוּב, אֶלָּא וַיַּרְא אֲדנָיו, שֶׁהֲרֵי בְּעֵינוֹ הָיָה רוֹאֶה מַעֲשֵׂה נִסִּים בְּכָל יוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה בְּיָדוֹ, וְעַל כֵּן וַיְבָרֶךְ ה' אֶת בֵּית הַמִּצְרִי בִּגְלַל יוֹסֵף. הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אֶת הַצַּדִּיקִים, וּבִגְלָלָם הוּא שׁוֹמֵר אֶת הָרְשָׁעִים, שֶׁהֲרֵי הָרְשָׁעִים מִתְבָּרְכִים מִשּׁוּם הַצַּדִּיקִים. כְּמוֹ כֵן כָּתוּב (שמואל ב ו) וַיְבָרֶךְ ה', אֶת בֵּית עֹבֵד אֱדם, (הגתי) בַּעֲבוּר אֲרוֹן הָאֱלֹהִים."],[8,"","הַצַדִּיקִים, מִתְבָּרְכִים הָאֲחֵרִים בִּגְלָלָן, וְהֵם לֹא יָכְלוּ לְהִזּוֹן (ס\"א להנצל) בִּזְכוּתָם, וַהֲרֵי פֵּרְשׁוּהָ. יוֹסֵף הִתְבָּרֵךְ אֲדוֹנוֹ בִּגְלָלוֹ, וְהוּא לֹא יָכֹל לְהִנָּצֵל מִמֶּנּוּ בִּזְכוּתוֹ וְלָצֵאת לְחֵרוּת."],[9,"","וְאַחַר כָּךְ הִכְנִיס אוֹתוֹ לְבֵית הַסֹּהַר, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קה) עִנּוּ בַכֶּבֶל רַגְלוֹ בַּרְזֶל בָּאָה נַפְשׁוֹ, עַד שֶׁלְּאַחַר מִכֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹצִיא אוֹתוֹ לַחֵרוּת וְהִשְׁלִיט אוֹתוֹ עַל כָּל אֶרֶץ מִצְרַיִם. וּמִשּׁוּם כָּךְ כָּתוּב וְלֹא יַעֲזב אֶת חֲסִידָיו לְעוֹלָם נִשְׁמָרוּ. כָּתוּב חֲסִידוֹ וְנִתְבָּאֵר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מֵגֵן עַל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁכָּתוּב (תהלים ה) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנֵּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךְ אֹהֲבֵי שְׁמֶךְ."]]],[["וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וַתִּשָּׂא אֵשֶׁת אֲדֹנָיו אֶת עֵינֶיהָ אֶל יוֹסֵף. רִבִּי חִיָּיא פָּתַח וְאֲמַר, (תהילים ק״ג:כ׳) בָּרְכוּ יְיָ מַלְאָכָיו גִּבּוֹרֵי כֹחַ עוֹשֵׂי דְבָרוֹ לִשְׁמוֹעַ בְּקוֹל דְּבָרוֹ. תָּא חֲזֵי, כַּמָּה אִצְטְרִיךְ לֵיהּ לְבַר נָשׁ לְאִסְתַּמְּרָא מֵחוֹבוֹי, וּלְמֵיהַךְ בְּאֹרַח מִתְתַּקְּנָא. בְּגִין דְּלָא יִסְטֵי לֵיהּ הַהוּא יֵצֶר הָרָע, דְּאִיהוּ מְקַטְרְגָא לֵיהּ כָּל יוֹמָא וְיוֹמָא, כְּמָה דְאִתְּמָר.","וּבְגִין דְּאִיהוּ מְקַטְרְגָא לֵיהּ תָּדִיר, בָּעֵי בַּר נָשׁ לְאִתְתַּקְּפָא עֲלֵיהּ, וּלְאִסְתַּלְּקָא עֲלֵיהּ בְּאֲתַר תָּקִּיפוּ. דְּבָעֵי לְמֶהֱוֵי גָּבַר עֲלֵיהּ, וּלְאִשְׁתַּתְּפָא בְּאֲתַר דִּגְבוּרָה. בְּגִין דְּכַד בַר נָשׁ אִתְקַף עֲלֵיהּ, כְּדֵין אִיהוּ בִּסְטַר גְּבוּרָה, וְאִתְדָּבַּק בֵּיהּ לְאִתְתַּקְּפָא. וּבְגִין דְּהַהוּא יֵצֶר הָרָע תַּקִּיף, בָּעֵי בַר נָשׁ דִּיהֵא תַּקִּיף מִינֵיהּ.","וְאִלֵּין בְּנֵי נָשָׁא דְּאִתְתַּקְּפוּ עֲלֵיהּ, אִקְרוּן גִּבּוֹרֵי כֹחַ, לְאִשְׁתַּכְּחָא זִינָא עִם זִינֵיהּ. וְאִלֵּין אִינוּן מַלְאָכָיו דְּקוּדְשָׁא בְּרִיךְ הוּא, דְאַתְיָין מִסִּטְרָא דִגְבוּרָה קַשְׁיָא, לְאִתְתַּקְּפָא עֲלֵיהּ, גִּבּוֹרֵי כֹּחַ עוֹשֵׂי דְבָרוֹ. בָּרְכוּ יְיָ מַלְאָכָיו, כְּיוֹסֵף, דְּאִקְרֵי צַדִּיק וְגִבּוֹר וְנָטַר בְּרִית קַדִּישָׁא דְּאִתְרְשִׁים בְּגַוֵּיהּ.","רִבִּי אֶלְעָזָר אָמַר, וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה, מַאי הִיא, הָא אוּקְמוּהָ אֲתַר דָּא דְּיֵצֶר הָרָע מְקַטְרֵג, דְּאִיהוּ דַרְגָּא אַחַר הַדְּבָרִים. בְּגִין דְּיוֹסֵף יָהַב לֵיהּ דּוּכְתָּא לְקַטְרָגָא, דְּהֲוָה יוֹסֵף מְסַלְסֵל בְּשַׂעֲרֵיהּ וְאַתְקִין גַּרְמֵיהּ וְקַשִּׁיט לֵיהּ, כְּדֵין אִתְיְהִיב דּוּכְתָּא לַיֵצֶר הָרָע לְקַטְרְגָא. דְּאָמַר, וּמַה אֲבוֹי דְּאִיהוּ מִתְאַבֵּל עֲלֵיהּ, וְיוֹסֵף מְקַשִּׁיט גַּרְמֵיהּ, וּמְסַלְסֵל בְּשַׂעֲרֵיהּ, כְּדֵין אִתְגָּרֵי בֵּיהּ דּוּבָּא וְקַטְרִיג לֵיהּ:","וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה. תָּא חֲזֵי, בְּזִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא אַשְׁגַּח בֵּיהּ בְּעַלְמָא, לְמֵידַן יָתֵיהּ, וְאַשְׁכַּח חַיָּיבִין בְּעַלְמָא, מַה כְּתִיב, (דברים י״א:י״ז) וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר וְהָאֲדָמָה לֹא תִתֵּן אֶת יְבוּלָהּ, וּכְדֵין וַאֲבַדְתֶּם מְהֵרָה. דְּהָא בְּגִין חוֹבִין דִּבְנֵי נָשָׁא, שְׁמַיָא וְאַרְעָא אִתְעֲצָרוּ, וְלָא נָהֲגֵי נִמּוּסֵיהוֹן כְּדְקָא יְאוּת.","וְתָּא חֲזֵי, אִינוּן דְּלָא נָטְרוּ לְהַאי קְיָימָא דְקוּדְשָׁא, גָּרְמֵי פְּרִישׁוּ בֵּין יִשְׂרָאֵל לַאֲבוּהוֹן דְּבִשְׁמַיָא, בְּגִין דִּכְתִיב וְסַרְתֶּם וַעֲבַדְתֶּם אֱלֹהִים אֲחֵרִים וְהִשְׁתַּחֲוִיתֶם לָהֶם, וּכְתִיב וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר. דְּהַאי אִיהוּ כְּמַאן דְּסָגִיד לֵאלָהָא אָחֳרָא, דִּמְשַׁקֵּר בְּהַאי אָת קְיָימָא קַדִּישָׁא.","וְכַד קְיָימָא קַדִּישָׁא אִתְנְטִיר בְּעַלְמָא כְּדְקָא יָאוֹת, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא יָהִיב בִּרְכָאן לְעֵילָא לְאַתְרָקָא בְּעַלְמָא. כְּמָה דְאַתְּ אָמֵר, (תהילים ס״ח:י׳) גֶּשֶׁם נְדָבוֹת תָּנִיף אֱלהִים נַחֲלָתְךָ וְנִלְאָה אַתָּה כוֹנַנְתָּה. גֶּשֶׁם נְדָבוֹת, דָּא גֶּשֶׁם דִּרְעוּתָא. כַּד אִתְרָעֵי קוּדְשָׁא בְּרִיךְ הוּא בִּכְנְסֶת יִשְׂרָאֵל, וּבָעֵי לַאֲרָקָא לָהּ בִּרְכָאן, כְּדֵין נַחֲלָתְךָ וְנִלְאָה אַתָּה כוֹנַנְתָּה.","נַחֲלָתְךָ, אִינוּן יִשְׂרָאֵל, דְּאִינוּן אַחְסַנְתֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא. כְּמָה דְאַתְּ אָמֵר, (דברים ל״ב:ט׳) יַעֲקֹב חֶבֶל נַחֲלָתוֹ. וְנִלְאָה, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי נִלְאָה בְּאַרְעָא אָחֳרָא, דְּאִיהִי צַחְיָא לְמִשְׁתֵּי, וּכְדֵין אִיהִי נִלְאָה. וְכַד הַהוּא גֶשֶׁם דִּרְעוּתָא אִתְיְהִיב, כְּדֵין אַתָּה כּוֹנַנְתָּה.","וְעַל דָּא, שְׁמַיָא וְאַרְעָא, וְכָל חֵילֵיהוֹן, כֻּלְּהוּ קָיְימָא עַל קִיּוּמָא דָא. דִּכְתִיב (ירמיהו ל״ג:כ״ה) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. וּבְּגִין כָּךְ בָּעֵי לְאִזְדַּהֲרָא בְּדָא, וְהָא אוּקְמוּהָ. וּבְגִין כָּךְ כְּתִיב, וַיְהִי יוֹסֵף יְפֵה תֹאַר וִיפֵה מַרְאֶה, וּבַתְרֵיהּ כְּתִיב וַתִּשָּׂא אֵשֶׁת אֲדֹנָיו אֶת עֵינֶיהָ אֶל יוֹסֵף.","וַיְהִי כְּדַבְּרָהּ אֵלָיו יוֹם יוֹם. רִבִּי אֶלְעָזָר פָּתַח וְאֲמַר, (משלי ו׳:כ״ד) לִשְׁמָרְךָ מֵאֵשֶׁת רָע וְגו', זַכָּאִין אִינוּן צַדִּיקַיָּא, דְּיָדְעֵי אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, לְמֵיזַל בְּהוּ. בְּגִין דְּאִינוּן מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא. דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא יוֹמֵי וְלֵילֵי, אַחְסִין תְּרֵין עָלְמִין, עַלְמָא עִלָּאָה, וְעַלְמָא תַּתָּאָה. אַחְסִין הַאי עַלְמָא, אַף עַל גַּב דְּלָא אִתְעַסַּק בָּהּ בַּר נָשׁ לִשְׁמָהּ, וְאַחְסִין הַהוּא עַלְמָא עִלָּאָה, כַּד אִתְעַסַּק בָּהּ בַּר נָשׁ לִשְׁמָהּ."],[[0,"ויהי אחר הדברים האלה וגו':","רבי חייא פתח ואמר ברכו ה' מלאכיו גבורי כח וגו'. בוא וראה, כמה צריך האדם להשמר מחטאיו וללכת בדרך מתוקן, כדי שלא ישטה אותו היצר הרע, שהוא מקטרג עליו כל יום ויום, כמו שלמדנו."],[1,"ובגין דאיהו מקטרגא וכו':","ומשום שהוא מקטרג עליו תמיד, צריך האדם להתגבר עליו, ולעלות עליו במקום מוצק, שהיצר הרע לא יוכל להזיזו ממקומו, כי צריך להיות גבור ממנו, ולהתחבר במקום הגבורה, משום, כאשר האדם מתגבר עליו, הוא אז בצד הגבורה, ומתדבק, בצד ההוא, כדי להתחזק. ומשום שהיצר הרע הוא גבור, צריך האדם להיות גבור ממנו."],[2,"ואלין בני נשא וכו:","ועל כן אלו האנשים המתגברים עליו נקראים \u0003גבורי כח,\u0004 להיותם נמצאים מין עם מינו, שמשום שנתגברו על גבור כנ\"ל, נעשו לבחינת גבורה כמוהו. ואלו הם מלאכיו של הקב\"ה, דהיינו הצדיקים, הבאים מצד גבורה הקשה, כדי להתגבר עליו על היצר הרע, ונקראים גבורי כח עושי דברו. \u0003ברכו ה' מלאכיו,\u0004 היינו הצדיקים כמו יוסף, שנקרא צדיק וגבור, ושמר ברית קודש שנרשם בו."],[3,"ר' אלעזר אמר וכו':","רא\"א, ויהי אחר הדברים האלה מהו פירושו. ואומר, הרי בארוה, מקום זה שהיצר הרע מקטרג שם היא המדרגה שנקרא \u0003אחר הדברים.\u0004 פירוש. המלכות נקראת \u0003דברים,\u0004 שהיא מדרגה אחרונה שבקדושה, ואחריה היצר הרע והקליפות, וע\"כ \u0003אחר הדברים,\u0004 הוא היצר הרע. (כנ\"ל וירא דף קמ\"ו אות תפ\"ח)."],[3,"בגין דיוסף וכו':","משום שיוסף נתן לו מקום שיקטרג עליו. כי אמר היצר הרע, ומה אביו, שהוא מתאבל עליו, ויוסף, הוא מפאר את עצמו ומסלסל בשערו. אז גירה בו הדוב, דהיינו אשת פוטיפר, וקטרג עליו."],[4,"ויהי אחר הדברים האלה:","בוא וראה בזמן שהקב\"ה משגיח על העולם לדון אותו, ומוצא רשעים בעולם, מה כתוב, ועצר וגו' ואבדתם מהרה וגו'. כי משום עונות בני אדם נעצרים שמים וארץ, וחוקיהם אינם נוהגים כראוי."],[5,"ותא חזי אינון וכו':","ובוא וראה, אלו שאינם שומרים ברית קדש, גורמים פירוד בין ישראל לאביהם שבשמים. כי כתוב, וסרתם ועבדתם אלהים אחרים והשתחויתם להם, וכתוב ועצר את השמים ולא יהיה מטר. שזה, שאינו שומר ברית, הוא כמשתחוה לאל אחר, שמשקר באות ברית קודש."],[6,"וכד קיימא קדישא וכו':","וכשברית קודש נשמר בעולם כראוי. אז הקב\"ה נותן ברכות למעלה, שתהיינה מורקות בעולם, כמש\"א, גשם נדבות תניף וגו', \u0003גשם נדבות,\u0004 זהו גשמי רצון, בעת שחפץ הקב\"ה בכנסת ישראל, וחפץ להריק לה ברכות. אז, נחלתך ונלאה אתה כוננתה."],[7,"נחלתך","הוא ישראל, שהם נחלת הקב\"ה, כמש\"א, יעקב חבל נחלתו, \u0003ונלאה,\u0004 זו היא כנסת ישראל, שהיא נלאה, בארץ נכריה, שהיא צמאה לשתות, ואין לה, ואז היא נלאה. וכאשר ניתנו גשמי רצון, אז \u0003אתה כוננתה.\u0004"],[8,"ועל דא שמיא וכו':","ועל כן שמים וארץ וכל צבאם, כולם עומדים על ברית הזה. שכתוב, אם לא בריתי וגו'. ומשום זה צריכים להזהר בזה. וכבר בארוה. ומשום זה כתוב, ויהי יוסף יפה תואר ויפה מראה. ואח\"כ כתוב, ותשא אשת אדניו את עיניה אל יוסף. כלומר, כיון שלא נשמר, והיה מפאר את עצמו שהיה מסלסל בשערו כנ\"ל, והיה יפה תאר ויפה מראה, ע\"כ ותשא אשת אדניו וגו'."],[9,"ויהי כדברה אליו יום יום:","ר' אלעזר פתח ואמר, לשמרך מאשת רע וגו'.אשרי הם הצדיקים היודעים דרכיו של הקב\"ה, ללכת בהם, משום שהם עוסקים בתורה יום ולילה, שכל מי שמשתדל בתורה ימים ולילות נוחל שני עולמים: עולם העליון ועולם התחתון. נוחל עולם הזה אע\"פ שלא עסק בתורה לשמה, ונוחל עולם העליון בעת שעסק בה לשמה."]],[[0,"","וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וַתִּשָּׂא אֵשֶׁת אֲדנָיו אֶת עֵינֶיהָ אֶל יוֹסֵף. רַבִּי חִיָּיא פָּתַח וְאָמַר, (שם קג) בָּרְכוּ ה' מַלְאָכָיו גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ לִשְׁמֹעַ בְּקוֹל דְּבָרוֹ בּא רְאֵה כַּמָּה צָרִיךְ הָאָדָם לְהִשָּׁמֵר מֵחֲטָאָיו וְלָלֶכֶת בְּדֶרֶךְ מְתֻקֶּנֶת, כְּדֵי שֶׁלֹּא יָסִיט אוֹתוֹ הַיֵּצֶר הָרָע הַהוּא, שֶׁהוּא מְקַטְרֵג לוֹ כָּל יוֹם וָיוֹם, כְּמוֹ שֶׁנֶּאֱמַר."],[1,"","וּמִשּׁוּם שֶׁהוּא מְקַטְרֵג לוֹ תָּמִיד, צָרִיךְ הָאָדָם לְהִתְגַּבֵּר עָלָיו וּלְהִתְעַלּוֹת עָלָיו בְּמָקוֹם שֶׁל חֹזֶק, שֶׁצָּרִיךְ לִהְיוֹת גּוֹבֵר עָלָיו וּלְהִשְׁתַּתֵּף בְּמָקוֹם שֶׁל גְּבוּרָה, מִשּׁוּם שֶׁכַּאֲשֶׁר אָדָם גּוֹבֵר עָלָיו, אָז הוּא בְּצַד הַגְּבוּרָה וְנִדְבָּק בּוֹ לְהִתְגַּבֵּר, וּמִשּׁוּם שֶׁאוֹתוֹ יֵצֶר הָרָע תַּקִּיף, צָרִיךְ הָאָדָם לִהְיוֹת תַּקִּיף מִמֶּנּוּ."],[2,"","וּבְנֵי הָאָדָם הַלָּלוּ שֶׁמִּתְגַּבְּרִים, נִקְרָאִים גִּבּוֹרֵי כֹחַ, שֶׁיִּמְצָא מִין עִם מִינוֹ, וְאֵלּוּ הֵם מַלְאָכָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבָּאִים מִצַּד הַגְּבוּרָה הַקָּשָׁה, לְהִתְגַּבֵּר עָלָיו, גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ. בָּרְכוּ ה' מַלְאָכָיו - כְּמוֹ יוֹסֵף שֶׁנִּקְרָא צַדִּיק וְגִבּוֹר וְשָׁמַר בְּרִית הַקֹּדֶשׁ הָרְשׁוּמָה בְּתוֹכוֹ."],[3,"","רַבִּי אֶלְעָזָר אָמַר, וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה, מַה זֶּה הִיא? הֲרֵי פֵּרְשׁוּהָ, מָקוֹם זֶה שֶׁיֵּצֶר הָרָע מְקַטְרֵג, שֶׁהוּא הַדַּרְגָּה אַחַר הַדְּבָרִים. מִשּׁוּם שֶׁיּוֹסֵף נָתַן לוֹ מָקוֹם לְקַטְרֵג, שֶׁהָיָה יוֹסֵף מְסַלְסֵל בִּשְׂעָרוֹ וּמְתַקֵּן אֶת עַצְמוֹ וּמְקַשֵּׁט אוֹתוֹ, אָז נָתַן מָקוֹם לַיֵּצֶר הָרָע לְקַטְרֵג, שֶׁאָמַר: וּמָה אָבִיו מִתְאַבֵּל עָלָיו, וְיוֹסֵף מְקַשֵּׁט אֶת עַצְמוֹ וּמְסַלְסֵל בִּשְׂעָרוֹ!? אָז הִתְגָּרָה בּוֹ הַדֹּב וְקִטְרֵג לוֹ."],[4,"","וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה. בֹּא רְאֵה, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ בָּעוֹלָם לָדוּן אוֹתוֹ וּמוֹצֵא רְשָׁעִים בָּעוֹלָם, מַה כָּתוּב? (דברים יא) וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר וְהָאֲדָמָה לֹא תִתֵּן אֶת יְבוּלָהּ. וְאָז - וַאֲבַדְתֶּם מְהֵרָה. שֶׁהֲרֵי מִשּׁוּם חֲטָאֵי בְּנֵי הָאָדָם הַשָּׁמַיִם נֶעֱצָרִים וְלֹא נוֹהֲגִים בְּחֻקּוֹתֵיהֶם כָּרָאוּי."],[5,"","וּבֹא וּרְאֵה, אוֹתָם שֶׁלֹּא שׁוֹמְרִים אֶת בְּרִית הַקֹּדֶשׁ הַזּוֹ, גּוֹרְמִים הִתְפָּרְדוּת בֵּין יִשְׂרָאֵל לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם, מִשּׁוּם שֶׁכָּתוּב וְסַרְתֶּם וַעֲבַדְתֶּם אֱלֹהִים אֲחֵרִים וְהִשְׁתַּחֲוִיתֶם לָהֶם, וְכָתוּב וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר. שֶׁזֶּהוּ כְּמוֹ שֶׁמִּשְׁתַּחֲוֶה לֵאלוֹהַּ אַחֵר, שֶׁמְּשַׁקֵּר בְּאוֹת הַבְּרִית הַקְּדוֹשָׁה הַזּוֹ."],[6,"","וְכַאֲשֶׁר הַבְּרִית הַקְּדוֹשָׁה נִשְׁמֶרֶת בָּעוֹלָם כָּרָאוּי, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן בְּרָכוֹת לְמַעְלָה לְהָרִיק בָּעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סח) גֶּשֶׁם נְדָבוֹת תָּנִיף אֱלֹהִים נַחֲלָתְךְ וְנִלְאָה אַתָּה כוֹנַנְתָּה. גֶּשֶׁם נְדָבוֹת - זֶהוּ גִּשְׁמֵי רָצוֹן, כְּשֶׁמִּתְרַצֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא עִם כְּנֶסֶת יִשְׂרָאֵל וְרוֹצֶה לְהָרִיק לָהּ בְּרָכוֹת, אֲזַי נַחֲלָתְךְ וְנִלְאָה אַתָּה כוֹנַנְתָּה."],[7,"","נַחֲלָתְךָ - הֵם יִשְׂרָאֵל, שֶׁהֵם נַחֲלָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) יַעֲקֹב חֶבֶל נַחֲלָתוֹ. וְנִלְאָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא נִלְאָה בְּאֶרֶץ אַחֶרֶת. שֶׁהִיא צְמֵאָה לִשְׁתּוֹת, וְאָז הִיא נִלְאָה. וּכְשֶׁאוֹתוֹ גֶשֶׁם שֶׁל רָצוֹן נִתָּן, אָז אַתָּה כוֹנַנְתָּה."],[8,"","וְעַל כֵּן שָׁמַיִם וָאָרֶץ וְכָל צְבָאָם, כֻּלָּם עוֹמְדִים עַל הַקִּיּוּם הַזֶּה, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי, וּמִשּׁוּם כָּךְ צָרִיךְ לְהִזָּהֵר בָּזֶה, וַהֲרֵי פֵּרְשׁוּהָ. וּמִשּׁוּם כָּךְ כָּתוּב וַיְהִי יוֹסֵף יְפֵה תֹאַר וִיפֵה מַרְאֶה, וְאַחֲרָיו כָּתוּב וַתִּשָּׂא אֵשֶׁת אֲדנָיו אֶת עֵינֶיהָ אֶל יוֹסֵף."],[9,"","וַיְהִי כְּדַבְּרָהּ אֶל יוֹסֵף יוֹם יוֹם. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (משלי ו) לִשְׁמָרְךְ מֵאֵשֶׁת רָע וְגוֹ'. אַשְׁרֵי הַצַּדִּיקִים שֶׁיּוֹדְעִים אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לָלֶכֶת בָּהֶם, מִשּׁוּם שֶׁהֵם מִשְׁתַּדְּלִים בַּתּוֹרָה יוֹמָם וָלַיְלָה, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה יָמִים וְלֵילוֹת, נוֹחֵל שְׁנֵי עוֹלָמוֹת - הָעוֹלָם הָעֶלְיוֹן וְהָעוֹלָם הַתַּחְתּוֹן. נוֹחֵל אֶת הָעוֹלָם הַזֶּה - אַף עַל גַּב שֶׁאֵין הָאָדָם מִתְעַסֵּק בָּהּ לִשְׁמָהּ. וְיוֹרֵשׁ הָעוֹלָם הָעֶלְיוֹן הַהוּא - כְּשֶׁמִּתְעַסֵּק בָּהּ הָאָדָם לִשְׁמָהּ."]]],[["תָּא חֲזֵי, מַה כְּתִיב, (משלי ג׳:ט״ז) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ עשֶׁר וְכָבוֹד. אֹרֶךְ יָמִים בִּימִינָהּ, מַאן דְּאָזִיל לִימִינָא דְאוֹרַיְיתָא, אָרְכָא דְחַיִּין אִיהוּ לְעַלְמָא דְאָתֵי. דְּזָכֵי תַּמָּן לִיקָרָא דְאוֹרַיְיתָא, דְּאִיהוּ יְקָרָא וְכִתְרָא, לְאִתְעַטְּרָא עַל כֹּלָּא. דְּכִתְרָא דְאוֹרַיְיתָא בְּהַהוּא עַלְמָא אִיהוּ. בִּשְׂמֹאלָהּ עשֶׁר וְכָבוֹד, בְּהַאי עַלְמָא, דְּאַף עַל גַּב דְּלָא אִתְעַסַּק בָּהּ לִשְׁמָהּ, זָכֵי בְּהַאי עַלְמָא בְּעוּתְרָא וִיקָרָא.","דְּהָא רִבִּי חִיָּיא כַּד אֲתָא מֵהָתָם לְאַרְעָא דְיִשְׂרָאֵל, קָרָא בְּאוֹרַיְיתָא, עַד דְּהֲווּ אַנְפּוֹי נְהִירִין כְּשִׁמְשָׁא. וְכַד הֲווּ קָיְימִין קַמֵּיהּ כָּל אִינוּן דְּלָעָאן בְּאוֹרַיְיתָא. הֲוָה אָמַר, דָּא אִשְׁתַּדַּל בְּאוֹרַיְיתָא לִשְׁמָהּ, וְדָא לָא אִשְׁתַּדַּל לִשְׁמָהּ, וְהֲוָה צַלֵּי עַל הַהוּא דְּאִתְעַסַּק לִשְׁמָהּ, דְּלֶיהוֵי הָכִי תָּדִיר, וְיִזְכֵּי לְעַלְמָא דְאָתֵי. וְצַלֵּי עַל הַהוּא דְּלָא אִתְעַסַּק בָּהּ לִשְׁמָהּ, דְּיֵיתֵי לְאִתְעַסְּקָא בָּהּ לִשְׁמָהּ, וְיִזְכֵּי לְחַיֵּי עָלְמָא.","יוֹמָא חַד, חָמָא חַד תַּלְמִיד דְּהֲוָה לָעֵי בְּאוֹרַיְיתָא, וְאַנְפּוֹי מוֹרִיקָן. אָמַר, וַדַּאי מְהַרְהֵר בְּחֶטְאָה אִיהוּ דְּנָא. אָחִיד לֵיהּ לְקַמֵּיהּ, וְאַמְשִׁיךְ עֲלֵיהּ בְּמִלִּין דְּאוֹרַיְיתָא, עַד דְּאִתְיַישַׁב רוּחֵיהּ בְּגַוֵּיהּ. מִן הַהוּא יוֹמָא וּלְהָלְאָה, שַׁוֵּי עַל רוּחֵיהּ, דְּלָא יִרְדֹּף בָּתַר אִינוּן הִרְהוּרִין בִּישִׁין, וְיִשְׁתַּדַּל בְּאוֹרַיְיתָא לִשְׁמָהּ.","אָמַר רִבִּי יוֹסֵי, כַּד חָמֵי בַר נָשׁ דְּהִרְהוּרִין בִּישִׁין אַתְיָין לְגַבֵּיהּ, יִתְעַסַּק בְּאוֹרַיְיתָא, וּכְדֵין יִתְעַבְרוּן מִנֵּיהּ. אָמַר רִבִּי אֶלְעָזָר, כַּד הַהוּא סִטְרָא בִּישָׁא אָתֵי לְמִפְתֵּי לֵיהּ לְבַר נָשׁ, יְהֵא מָשִׁיךְ לֵיהּ לְגַבֵּי אוֹרַיְיתָא, וְיִתְפְּרַשׁ מִנֵּיהּ.","תָּא חֲזֵי, דְּהָא תָּנִינָן, דְּכַד הַאי סִטְרָא בִישָׁא קָיְימָא קַמֵּיהּ דְקוּדְשָׁא בְּרִיךְ הוּא לְאַסְטָאָה עַל עַלְמָא בְּגִין עוֹבָדִין בִּישִׁין. קוּדְשָׁא בְּרִיךְ הוּא חָס עַל עַלְמָא, וְיָהִיב עֵיטָא לִבְנֵי נָשָׁא, לְאִשְׁתְּזָבָא מִנֵּיהּ. וְלָא יָכִיל לְשַׁלְטָאָה עֲלֵיהוֹן וְלָא עַל עוֹבָדֵיהוֹן, וּמַאי אִיהוּ עֵיטָא, לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, וְאִשְׁתֵּזָבוּ מִנֵּיהּ. מְנָלָן, דִּכְתִיב, (משלי ו׳:כ״ג) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר. מַה כְּתִיב בַּתְרֵיהּ לִשְׁמָרְךָ מֵאֵשֶׁת רָע מֵחֶלְקַת לָשׁוֹן נָכְרִיָּה.","וְדָא הוּא סִטְרָא מְסָאֲבָא, סִטְרָא אָחֳרָא. דְאִיהִי קָיְימָא תָּדִיר קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, לְאַסְטָאָה עַל חוֹבֵיהוֹן דִּבְנֵי נָשָׁא. וְקָיְימָא תָּדִיר לְאַסְטָאָה לְתַתָּא לִבְנִי נָשָׁא. קָיְימָא תָּדִיר לְעֵילָא, בְּגִין לְאַדְכָּרָא חוֹבֵיהוֹן דִּבְנִי נָשָׁא, וּלְאַסְטָאָה לוֹן עַל עוֹבָדֵיהוֹן. וּבְגִין דְּאִתְיְהִיבוּ בִּרְשׁוּתֵיהּ, כְּמָה דְּעֲבַד לֵיהּ לְאִיּוֹב.","וְכֵן קָיְימָא עֲלַיְיהוּ לְאַסְטָאָה וּלְאַדְכָּרָא חוֹבֵיהוֹן בְּכָל מַה דְּעֲבָדוּ, בְּאִינוּן זִמְנִין דְּקוּדְשָׁא בְּרִיךְ הוּא קָיְימָא עֲלַיְיהוּ בְּדִינָא. כְּדֵין קָאִים לְאַסְטָאָה לוֹן וּלְאַדְכָּרָא חוֹבֵיהוֹן. וְקוּדְשָׁא בְּרִיךְ הוּא חָס עֲלַיְיהוּ דְיִשְׂרָאֵל, וְיָהַב לוֹן עֵיטָא לְאִשְׁתְּזָבָא מִנֵּיהּ. וּבְמָּה, בַּשּׁוֹפָר בְּיוֹמָא דְרֹאשׁ הַשָּׁנָה, וּבְיוֹמָא דְכִפּוּרֵי בְּשָׂעִיר הַמִּשְׁתַּלֵּחַ דְּיָהֲבִין לֵיהּ, בְּגִין לְאִתְפְּרָשָׁא מִנַּיְיהוּ, וּלְאִשְׁתַּדְּלָא בְּהַהוּא חוּלָקֵיהּ, וְהָא אוּקְמוּהָ.","תָּא חֲזֵי, מַה כְּתִיב, (משלי ה׳:ה׳) רַגְלֶיהָ יוֹרְדוֹת מָוֶת שְׁאוֹל צְעָדֶיהָ יִתְמוֹכוּ. וּבְרָזָא דִּמְהֵימְנוּתָא מַה כְּתִיב, (משלי ג׳:י״ז) דְּרָכֶיהָ דַרְכֵי נוֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. וְאִלֵּין אִינוּן אָרְחִין וּשְׁבִילִין דְּאוֹרַיְיתָא, וְכֹלָּא חַד. הַאי שָׁלוֹם וְהַאי מָוְת, וְכֹלָּא הִפּוּכָן דָּא מִן דָּא.","זַכָּאָה חוּלְקֵהוֹן דְּיִשְׂרָאֵל, דְּאִינוּן מִתְדַּבְּקִין בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא כְּדְקָא חָזֵי, וְיָהִיב לוֹן עֵיטָא לְאִשְׁתְּזָבָא מִכָּל סִטְרִין אָחֳרָנִין דְּעַלְמָא. בְּגִין דְּאִינוּן עַמָּא קַדִּישָׁא לְאַחְסַנְתֵּיהּ וְחוּלָקֵיהּ, וְעַל דָּא יָהִיב לוֹן עֵיטָא בְּכֹלָּא. זַכָּאִין אִינוּן בְּעַלְמָא דֵין, וּבְעַלְמָא דְאָתֵי.","תָּא חֲזֵי, כַּד הַאי סִטְרָא בִּישָׁא נָחַת וְשָׁאט בְּעַלְמָא, וְחָמֵי עוֹבָדִין דִּבְנֵי נָשָׁא, דְּאִינוּן כֻּלְּהוּ סָטְאִין אָרְחַיְיהוּ בְּעַלְמָא. סָלִיק לְעֵילָא וְאַסְטִין לוֹן, וְאִלְמָלֵא דְּקוּדְשָׁא בְּרִיךְ הוּא חָיִיס עַל עוֹבָדֵי יְדוֹי, לָא יִשְׁתָּאֲרוּן בְּעַלְמָא.","מַה כְּתִיב וַיְהִי כְּדַבְּרָהּ אֶל יוֹסֵף יוֹם יוֹם. כְּדַבְּרָהּ, דְסָלְקָא וְסָאטֵי בְּכָל יוֹמָא וְיוֹמָא, וְאָמַר קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, כַּמָּה בִּישִׁין כַּמָּה דִּלְטוֹרִין, בְּגִין לְשֵׁיצָאָה בְּנִי עַלְמָא."],[[0,"תא חזי מה וכו':","בוא וראה מה כתוב, ארך ימים בימינה בשמאלה עשר וכבוד. \u0003ארך ימים בימינה,\u0004 היינו מי שהולך בימין התורה, דהיינו שעוסק בה לשמה יש לו אריכת ימים לעולם הבא, שהוא זוכה שם לכבוד התורה, שהוא כבוד וכתר להתעטר על כל, כי כתר התורה רק בעולם הבא הוא. \u0003בשמאלה עשר וכבוד,\u0004 היינו בעולם הזה, שאף על פי שלא עסק בה לשמה, זוכה בעולם הזה בעושר וכבוד."],[1,"דהא רבי חייא וכו':","כי ר\"ח כשבא משם מבבל לארץ ישראל, קרא בתורה עד שפניו היו מאירים כשמש. וכשהיו עומדים לפניו כל אלו שלמדו תורה, היה אמר זה עסק בתורה לשמה, וזה לא עסק בה לשמה. והיה מתפלל על אותו שעסק בה לשמה, שיהיה כן תמיד, ויזכה לעולם הבא. והתפלל על אותו שלא עסק בה לשמה, שיבא לעסוק בה לשמה, ויזכה לחיי עולם."],[2,"יומא חד חמא וכו':","יום אחד, ראה תלמיד אחד, שהיה לומד תורה ופניו מוריקים, אמר, ודאי, מהרהר בחטא הוא, זה. החזיק אותו לפניו, והמשיך עליו בדברי תורה, עד שנתישב רוחו בו. מיום ההוא ולהלאה, שם על רוחו, שלא ירדוף עוד אחר הרהורים רעים, ויעסוק בתורה לשמה."],[3,"אמר ר' יוסי וכו':","אר\"י, כשאדם רואה, שהרהורים רעים באים אליו יעסוק בתורה, ואז יעברו ממנו. אמר ר' אלעזר, כשאותו צד הרע בא לפתות את האדם, ימשיך אותו אל התורה, ויפרד ממנו."],[4,"תא חזי דהא וכו':","בוא וראה, כי למדנו, כאשר צד הרע הזה, עומד לפני הקב\"ה להשטין על העולם, על מעשים רעים שעשו, הקב\"ה מרחם על העולם, ונותן עצה לבני אדם להנצל ממנו, שלא יוכל לשלוט עליהם, ולא על מעשיהם. ומהו העצה. הוא להשתדל בתורה, וינצלו ממנו, ושואל, מאין לנו זה. ומשיב, שכתוב כי נר מצוה ותורה אור וגו', ומה כתוב אחריו, לשמרך מאשת רע מחלקת לשון נכריה. הרי שהתורה משמרת מפני יצר הרע."],[5,"ודא הוא סטרא וכו':","וזה הוא צד הטומאה, צד האחר, שהוא עומד תמיד לפני הקב\"ה להסטין על עונותיהם של בני אדם, ועומד תמיד להשטות למטה את בני אדם. ומפרש, הוא עומד למעלה, כדי להזכיר עונות בני אדם ולהשטין עליהם על מעשיהם, משום שנתנו ברשותו כמו שעשה לאיוב. שאמר הקב\"ה אל השטן הנו בידך. (איוב ב')."],[6,"וכן קיימא עלייהו וכו':","וכן עומד עליהם, להסטין ולהזכיר עונותיהם בכל מה שעשו, באלו הזמנים שהקב\"ה נמצא עליהם בדין. דהיינו בראש השנה ויום הכפורים, אז הוא עומד להסטין עליהם ולהזכיר עונותיהם, והקב\"ה מרחם על ישראל, ונותן להם עצה להנצל ממנו. ובמה. בשופר, ביום ראש השנה. וביום הכפורים, בשעיר המשתלח שנותנים לו, כדי שיפרוש מהם ויעסוק באותו חלק שנתנו לו, וכבר בארוה."],[7,"תא חזי מה כתיב וכו':","בוא וראה מה כתוב, רגליה יורדות מות וגו'. ובסוד האמונה, מה כתוב דרכיה דרכי נועם וגו'. ואלו הם ארחות ושבילים של התורה. וכולם אחד. כלומר, כל הדרכים הן של הטומאה והן של הקדושה הם אחד: זה שלום, וזה מות, ולגמרי, הם בהפכיות זה מזה, שכל דרך ודרך של הטומאה, הוא בהפכיות מן הדרך שכנגדו בקדושה."],[8,"זכאה חולקהון וכו':","אשרי חלקם של ישראל, שהם מתדבקים בהקב\"ה כראוי, ונותן להם עצה להנצל מכל צדדים אחרים שבעולם, משום שהם עם קדוש לנחלתו וחלקו, ועל כן נותן להם עצה בכל דבר ודבר. אשרי הם בעולם הזה ובעולם הבא."],[9,"ת\"ח כד האי וכו':","בוא וראה, כשצד הרע הזה, יורד ומשוטט בעולם, ורואה מעשי בני אדם, שכולם הטו דרכיהם בעולם. עולה למעלה ומשטין עליהם, ואלמלא שהקב\"ה מרחם על מעשי ידיו, לא היו נשארים בעולם."],[10,"מה כתיב, ויהי וגו':","מה כתוב ויהי כדברה אל יוסף יום יום. \u0003כדברה\u0004 היינו צד הרע, שעולה ומסטין בכל יום ויום, ואומר לפני הקב\"ה, כי יוסף רומז על הקב\"ה, כמה רעות, כמה רכילות, כדי לכלות בני העולם."]],[[0,"","בֹּא רְאֵה מַה כָּתוּב, (משלי ג) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ עֹשֶׁר וְכָבוֹד. אֹרֶךְ יָמִים בִּימִינָהּ - מִי שֶׁהוֹלֵךְ לִימִין הַתּוֹרָה, אֹרֶךְ שֶׁל חַיִּים הוּא לָעוֹלָם הַבָּא, שֶׁזּוֹכֶה שָׁם לִכְבוֹד הַתּוֹרָה, שֶׁהוּא כָּבוֹד וְכֶתֶר לְהִתְעַטֵּר עַל הַכֹּל, שֶׁכֶּתֶר הַתּוֹרָה הוּא בָּעוֹלָם הַהוּא. בִּשְׂמֹאלָהּ עֹשֶׁר וְכָבוֹד - בָּעוֹלָם הַזֶּה, שֶׁאַף עַל גַּב שֶׁאֵינוֹ מִתְעַסֵּק בָּהּ לִשְׁמָהּ, זוֹכֶה בָּעוֹלָם הַזֶּה לְעֹשֶׁר וְכָבוֹד."],[1,"","שֶׁהֲרֵי רַבִּי חִיָּיא, כַּאֲשֶׁר בָּא מִשָּׁם לְאֶרֶץ יִשְׂרָאֵל, קָרָא בַּתּוֹרָה, עַד שֶׁהָיוּ פָנָיו מְאִירִים כְּמוֹ הַשֶּׁמֶשׁ, וּכְשֶׁהָיוּ עוֹמְדִים לְפָנָיו כָּל אוֹתָם שֶׁעָסְקוּ בַתּוֹרָה, הָיָה אוֹמֵר: זֶה הִשְׁתַּדֵּל בַּתּוֹרָה לִשְׁמָהּ, וְזֶה לֹא הִשְׁתַּדֵּל לִשְׁמָהּ. וְהָיָה מִתְפַּלֵּל עַל אוֹתוֹ שֶׁמִּתְעַסֵּק לִשְׁמָהּ, שֶׁכָּךְ יִהְיֶה תָמִיד וְיִזְכֶּה לָעוֹלָם הַבָּא. וּמִתְפַּלֵּל עַל אוֹתוֹ שֶׁלֹּא הִתְעַסֵּק לִשְׁמָהּ, שֶׁיָּבא לְהִתְעַסֵּק בָּהּ לִשְׁמָהּ וְיִזְכֶּה לְחַיֵּי עוֹלָם."],[2,"","יוֹם אֶחָד רָאָה תַלְמִיד אֶחָד שֶׁהָיָה עוֹסֵק בַּתּוֹרָה וּפָנָיו מוֹרִיקִים. אָמַר, וַדַּאי מְהַרְהֵר בַּעֲבֵרָה הוּא זֶה. אָחַז אוֹתוֹ לְפָנָיו, וְהִמְשִׁיךְ עָלָיו דִּבְרֵי תוֹרָה עַד שֶׁהִתְיַשְּׁבָה רוּחוֹ בְּתוֹכוֹ. מֵאוֹתוֹ הַיּוֹם וָהָלְאָה שָׂם עַל רוּחוֹ שֶׁלֹּא יִרְדֹּף אַחַר אוֹתָם הַהִרְהוּרִים הָרָעִים וְיִשְׁתַּדֵּל בַּתּוֹרָה לִשְׁמָהּ."],[3,"","אָמַר רַבִּי יוֹסֵי, כְּשֶׁאָדָם רוֹאֶה שֶׁבָּאִים אֵלָיו הִרְהוּרִים רָעִים, יִתְעַסֵּק בַּתּוֹרָה, וְאָז יַעַבְרוּ מִמֶּנּוּ. אָמַר רַבִּי אֶלְעָזָר, כְּשֶׁאוֹתוֹ הַצַּד הָרָע בָּא לְפַתּוֹת אֶת הָאָדָם, יִמְשֹׁךְ אוֹתוֹ לַתּוֹרָה, וְיִפָּרֵד מִמֶּנּוּ."],[4,"","בֹּא רְאֵה, שֶׁהִנֵּה שָׁנִינוּ, שֶׁכַּאֲשֶׁר הַצַּד הָרָע הַזֶּה עוֹמֵד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׂטִין עַל הָעוֹלָם מִשּׁוּם מַעֲשִׂים רָעִים, הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל הָעוֹלָם, וְנוֹתֵן עֵצָה לִבְנֵי אָדָם לְהִנָּצֵל מִמֶּנּוּ, וְלֹא יוּכַל לִשְׁלֹט עֲלֵיהֶם וְלֹא עַל מַעֲשֵׂיהֶם. וּמַה הִיא הָעֵצָה? לְהִשְׁתַּדֵּל בַּתּוֹרָה, וְנִצּוֹלִים מִמֶּנּוּ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שם ו) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר. מַה כָּתוּב אַחֲרָיו? לִשְׁמָרְךְ מֵאֵשֶׁת רָע מֵחֶלְקַת לָשׁוֹן נָכְרִיָּה."],[5,"","זֶהוּ צַד הַטֻּמְאָה. הַצַּד הָאַחֵר - שֶׁעוֹמֵד תָּמִיד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׂטִין עַל חֲטָאֵי בְּנֵי הָאָדָם, וְעוֹמֵד תָּמִיד לְהַשְׂטִין לְמַטָּה לִבְנֵי אָדָם. עוֹמֵד תָּמִיד לְמַעְלָה כְּדֵי לְהַזְכִּיר חֲטָאֵי בְּנֵי הָאָדָם וּלְהַשְׂטִין לָהֶם עַל מַעֲשֵׂיהֶם, וּמִשּׁוּם שֶׁנִּתְּנוּ בִּרְשׁוּתוֹ, כְּמוֹ שֶׁעָשָׂה לוֹ לְאִיּוֹב."],[6,"","וְכֵן עוֹמֵד עֲלֵיהֶם לְהַשְׂטִין אֶת יִשְׂרָאֵל וּלְהַזְכִּיר חֲטָאֵיהֶם בְּכָל מַה שֶּׁעָשׂוּ בְּאוֹתָן הַפְּעָמִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹמֵד עֲלֵיהֶם בְּדִין, אֲזַי עוֹמֵד לְהַשְׂטִין לָהֶם וּלְהַזְכִּיר חֲטָאֵיהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל יִשְׂרָאֵל וְנוֹתֵן לָהֶם עֵצָה לְהִנָּצֵל מִמֶּנּוּ, וּבַמֶּה? בַּשּׁוֹפָר, בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה, וּבְיוֹם הַכִּפּוּרִים בַּשָּׂעִיר הַמִּשְׁתַּלֵּחַ שֶׁנּוֹתְנִים לוֹ, כְּדֵי לְהִפָּרֵד מֵהֶם וּלְהִשְׁתַּדֵּל בְּאוֹתוֹ הַחֵלֶק שֶׁלּוֹ, וַהֲרֵי בֵּאֲרוּהָ."],[7,"","בֹּא רְאֵה מַה כָּתוּב, (שם ה) רַגְלֶיהָ יֹרְדוֹת מָוֶת שְׁאוֹל צְעָדֶיהָ יִתְמֹכוּ. וּבְסוֹד הָאֱמוּנָה מַה כָּתוּב? (שם ג) דְּרָכֶיהָ דַרְכֵי נֹעַם וְכָל נְתִיבֹתֶיהָ שָׁלוֹם. וְאֵלּוּ הֵם דַּרְכֵי וּשְׁבִילֵי הַתּוֹרָה, וְהַכֹּל אֶחָד. זֶה שָׁלוֹם וְזֶה מָוֶת, וְהַכֹּל הֲפוּכִים זֶה מִזֶּה."],[8,"","אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁנִּדְבָּקִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא כָּרָאוּי וְנוֹתֵן לָהֶם עֵצָה לְהִנָּצֵל מִכָּל הַצְּדָדִים הָאֲחֵרִים שֶׁל הָעוֹלָם, מִשּׁוּם שֶׁהֵם עַם קָדוֹשׁ לְנַחֲלָתוֹ וְחֶלְקוֹ, וְעַל כֵּן נוֹתֵן לָהֶם עֵצָה בַּכֹּל. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[9,"","בֹּא רְאֵה, כְּשֶׁהַצַּד הָרָע הַזֶּה יוֹרֵד וּמְשׁוֹטֵט בָּעוֹלָם וְרוֹאֶה אֶת מַעֲשֵׂי בְּנֵי הָאָדָם, שֶׁהֵם כֻּלָּם סוֹטִים דַּרְכֵיהֶם בָּעוֹלָם, הוּא עוֹלֶה וּמַשְׂטִין עֲלֵיהֶם, וְאִלְמָלֵא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל מַעֲשֵׂי יָדָיו, הֵם לֹא הָיוּ נִשְׁאָרִים בָּעוֹלָם."],[10,"","מַה כָּתוּב? וַיְהִי כְּדַבְּרָהּ אֶל יוֹסֵף יוֹם יוֹם. כְּדַבְּרָהּ - שֶׁעוֹלֶה וּמַעֲלֶה בְּכָל יוֹם וָיוֹם, וְאוֹמֵר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כַּמָּה רָעוֹת, כַּמָּה מַלְשִׁינוּת, כְּדֵי לְכַלּוֹת בְּנֵי אָדָם."]]],[["מַה כְּתִיב, וְלֹא שָׁמַע אֵלֶיהָ לִשְׁכַּב אֶצְלָהּ לִהְיוֹת עִמָּהּ. וְלא שָׁמַע אֵלֶיהָ, בְּגִין דְּאִיהוּ חָיִיס עַל עַלְמָא. לִשְׁכַּב אֶצְלָהּ, מַהוּ לִשְׁכַּב אֶצְלָהּ. בְּגִין לְנָסְבָא שָׁלְטָנוּ, לְשַׁלְּטָאָה עַל עַלְמָא, וְשָׁלְטָנוּ לָא שָׁלְטָא, עַד דְּאִתְיְהִיב לֵיהּ רְשׁוּ.","דָּבָר אַחֵר לִשְׁכַּב אֶצְלָהּ, כְּמָה דְאַתְּ אָמֵר, (ויקרא ט״ו:ל״ג) וּלְאִישׁ אֲשֶׁר יִשְׁכַּב עִם טְמֵאָה. לִהְיוֹת עִמָּהּ לְמֵיהַב לָהּ רְבוּ וּבִרְכָאן וְסִיַּיעְתָּא. דְּאִלְּמָלֵא סִיּוּעָא הֲוָה לָהּ מִלְּעֵילָא, לָא אִשְׁתָּאַר בְּעַלְמָא אֲפִילּוּ חַד. אֲבָל בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא חָיִיס עַל עַלְמָא, אִשְׁתָּאַר עַלְמָא בְּקִיּוּמֵיהּ.","רִבִּי אַבָּא אָמַר, כֹּלָּא אִיהוּ אָרְחָא חָדָא, אֲבָל יֵצֶר הָרָע הוּא דְקָא אָזִיל וּמְפַתֵּי לוֹן לִבְנֵי נָשָׁא, בְּגִין לְאַסְטָאָה אָרְחַיְיהוּ וּלְאִתְדַּבְּקָא בְּהוּ, בְּכָל יוֹמָא וְיוֹמָא, וּבְכָל עִידָן וְעִידָן. סָטֵי לֵיהּ לְבַר נָשׁ מֵאָרְחָא דִקְשׁוֹט, בְּגִין לְדַחְיָיא לֵיהּ מֵאָרְחָא דְחַיֵּי, לְאַמְשָׁכָא לֵיהּ לַגֵּיהִנֹּם.","זַכָּאָה אִיהוּ מַאן דְּעָבִיד וְנָטִיר (נ\"א זכאה מאי עביד, נטיר) אָרְחוֹי וּשְׁבִילוֹי, בְּגִין דְּלָא יִתְדַּבַּק בֵּיהּ. הַיְינוּ דִכְתִיב וַיְהִי כְּדַבְּרָהּ אֶל יוֹסֵף יוֹם יוֹם וְלא שָׁמַע אֵלֶיהָ, כְּמָּה (נ\"א במה) דְּאִיהִי אֲמְרַת לֵיהּ בְּכָל יוֹמָא. דְּהָא רוּחַ מְסָאֲבָא, יֵצֶר הָרָע, אִיהוּ מְפַתֵּי לֵיהּ לְבַר נָשׁ, בְּכָל יוֹמָא, לִשְׁכַּב אֶצְלָהּ, גּוֹ גֵּיהִנֹּם, וּלְאִתְדָּנָא תַּמָּן, לִהְיוֹת עִמָּהּ.","תָּא חֲזֵי, כַּד בַר נָשׁ אִתְדָּבַּק בְּהַהוּא סִטְרָא, אִתְמְשַׁךְ אֲבַתְרָהּ, וְאִסְתָּאַב עִמָּהּ בְּהַאי עַלְמָא, וְאִסְתָּאַב עִמָּהּ בְּעַלְמָא אָחֳרָא. תָּא חֲזֵי, הַאי סִטְרָא מְסָאֲבָא, מְנוּוָלָא אִיהוּ, לִכְלוּכָא אִיהוּ. כְּדִּכְתִיב, (ישעיהו ל׳:כ״ב) צֵא תֹּאמַר לוֹ, צוֹאָה מַמָּשׁ. וּבֵיהּ אִתְדָּן מַאן דְּאַסְטֵי אָרְחוֹי מִן אוֹרַיְיתָא, וּבֵיהּ אִתְדָנוּ אִינוּן חַיָּיבִין דְּעַלְמָא, דְּלֵית לוֹן מְהֵימְנוּתָא בְּקוּדְשָׁא בְּרִיךְ הוּא.","מַה כְּתִיב, וַיְהִי כְּהַיּוֹם הַזֶּה וַיָּבֹא הַבַּיְתָה לַעֲשׂוֹת מְלַאכְתּוֹ וְאֵין אִישׁ מֵאַנְשֵׁי הַבַּיִת שָׁם בַּבָּיִת. וַיְהִי כְּהַיּוֹם הַזֶּה, יוֹמָא דְיֵצֶר הָרָע שָׁלְטָא בְּעַלְמָא, וְנָחֲתָא לְאַסְטָאָה לִבְנֵי נָשָׁא. אֵימָתַי, יוֹמָא דְאָתֵי בַּר נָשׁ לְאֲתָבָא בִּתְיוּבְתָּא עַל חוֹבוֹי, אוֹ לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, וּלְמֶעְבַּד פִּקּוּדֵי דְאוֹרַיְיתָא. וּכְדֵין בְּהַהוּא זִמְנָא נָחֲתָא, בְּגִין לְאַסְטָאָה לִבְנֵי עָלְמָא.","וַיָּבֹא הַבַּיְתָה לַעֲשׂוֹת מְלַאכְתּוֹ, בְּגִין לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא וּלְמֶעְבַּד פִּקּוּדֵי דְאוֹרַיְיתָא, דְּאִיהוּ מְלַאכְתּוֹ דְּבַר נָשׁ בְּהַאי עַלְמְא. וְכֵיוָן דְּעֲבִידְתָּא דְּבַר נָשׁ בְּהַאי עַלְמָא, הוּא עֲבִידְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא. בָּעֵי לֵיה לְבַר נָשׁ, לְמֶהֱוֵי תַּקִּיפָא כְּאַרְיָא בְּכָל סִטְרוֹי, בְּגִין דְּלָא יִשְׁלוֹט עֲלוֹי סִטְרָא אָחֳרָא, וְלָא יָכִיל לְמִפְתֵּי לֵיהּ. מַה כְּתִיב וְאֵין אִישׁ, לֵית גְּבַר דְּיֵקוּם לְקֳבְלֵיהּ דְּיֵצֶר הָרָע, וְיִגַּח בֵּיהּ קְרָבָא כְּדְקָא יָאוֹת.","מַאי אוֹרְחֵיהּ דְּיֵצֶר הָרָע, כֵּיוָן דְּחָמֵי דְּלֵית בַּר נָשׁ קָאִים לְקֳבְלֵיהּ וּלְאַגָּחָא בֵּיהּ קְרָבָא, מִיָּד: וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ לֵאמֹר שִׁכְבָה עִמִּי. וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ, בְּגִין דְּכַד שַׁלִּיט יֵצֶר הָרָע עֲלֵיהּ דְּבַר נָשׁ, אַתְקִין לֵיהּ, וְקַשִּׁיט לֵיהּ לְבוּשׁוֹי, מְסַלְסֵל בְּשַׂעֲרֵיהּ. הֲדָא הוּא דִכְתִיב וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ לֵאמֹר שִׁכְבָה עִמִּי, אִתְדָּבַּק עִמִּי.","מַאן דְּאִיהוּ זַכָּאָה, אִתְתַּקַּף לְקֳבְלֵיהּ, וְאַגַּח בֵּיהּ קְרָבָא. מַה כְּתִיב, וַיַּעֲזֹב בִּגְדוֹ בְּיָדָהּ וַיָּנָס וַיֵּצֵא הַחוּצָה, יִשְׁבּוֹק לֵיהּ, וְיִתְתַּקַּף לְקֳבְלֵיהּ. (ס\"א ואגח ביה קרבא) וְיֵעֲרוֹק מִנֵּיהּ, בְּגִין לְאִשְׁתְּזָבָא מִנֵּיהּ, וְלָא יִשְׁלוֹט עֲלוֹי.","אָמַר רִבִּי יִצְחָק, זְמִינִין אִינוּן צַדִּיקַיָא לְמֶחמֵי לְיֵצֶר הָרָע, כְּחַד טוּרָא רַבְרְבָא, וְיִתְמְהוּן וְיֵימְרוּן. אֵיךְ יָכִילְנָא לְאַכְּפְיָא לֵיהּ לְטוּרָא רַבְרְבָא הָדֵין עִלָּאָה. וּזְמִינִין רַשִּׁיעַיָא לְמֶחֱמֵי לֵיהּ לְיֵצֶר הָרָע, דַּקִּיק כְּחוּטָא דְּשַׂעֲרָא, וְיִתְמְהוּן וְיֵימְרוּן. הֵיךְ לָא יָכִילְנָא לְאַכְּפְיָא לְחוּטָא דְשַׂעֲרָא כְּדָא דַּקִּיק. אִלֵּין יִבְכּוּן וְאִלֵּין יִבְכּוּן. וְקוּדְשָׁא בְּרִיךְ הוּא יְבַעֵר לֵיהּ מֵעַלְמָא, וְיִכּוֹס לֵיהּ לְעֵינַיְיהוּ, וְלָא יִשְׁלוֹט עוֹד בְּעַלְמָא, וְיֶחמוּן צַדִּיקַיָא וְיֶחֱדוּן. כְּמָה דְאַתְּ אָמֵר, (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ."],[[0,"מה כתיב, ולא וגו':","מה כתוב, ולא שמע אליה לשכב אצלה להיות עמה, \u0003ולא שמע אליה,\u0004 משום שהקב\"ה מרחם על העולם. \u0003לשכב אצלה,\u0004 שואל, מהו לשכב אצלה. ומשיב כדי שתקבל ממשלה למשול על העולם, וממשלה אינה מושלת, עד שניתן לה רשות."],[0,"","פירוש. לשכב אצלה, פירושו זווג. ומתמיה, היתכן שהקדושה תזדווג עם הטומאה, ועל זה משיב, כי שפע קבלת הכח מן הקב\"ה, שצד הרע מקבל כדי להעניש, נבחן כמו זווג. כי אין שפע נמשך רק ע\"י זווג. וע\"כ כתוב \u0003לשכב אצלה.\u0004 כלומר, להשפיע לה שפע הממשלה."],[1,"ד\"א לשכב וכו':","פירוש אחר על הכתוב \u0003לשכב אצלה,\u0004 הוא כמו שאתה אומר, ולאיש אשר ישכב עם טמאה. \u0003להיות עמה,\u0004 היינו לתת לה ממשלה וברכות ועזרה, כי אלמלא העזרה שהיה לה מלמעלה, לא נשאר בעולם אפילו אדם אחד. אבל משום שהקב\"ה מרחם על העולם, ונותן עזרה לעולם ע\"י הס\"א, דהיינו, בשעה שהס\"א מושלת בעולם, נשאר העולם על קיומו."],[1,"","ההפרש מפירוש הזה לפירוש הקודם, הוא, כי בפירוש הקודם, אומר שענין אצלה, הוא השפעת שפע הממשלה ונתינת רשות לס\"א להעניש. ופירוש הזה אומר, שלשכב אצלה סובב על שפע הנהגת העולם שניתנה לס\"א בזמן שהיא מושלת בעולם, כדי שהעולם יתקיים, שז\"ס ואיש אשר ישכב עם טמאה."],[2,"ר' אבא אמר וכו':","רא\"א, הכל הוא ענין אחד, דהיינו ב' הפירושים הנ\"ל, אבל היצה\"ר, הוא שהולך ומפתה בני אדם, כדי להטות דרכם ולהתדבק בהם, ובכל יום ויום ובכל עת ועת, מטה בני אדם מדרך האמת, כדי לדחותם מדרך החיים, ולהמשיכם לגיהנם."],[3,"זכאה איהו מאן וכו':","אשרי הוא, מי שעושה מעשים טובים, ושומר דרכיו ושביליו כדי שלא יתדבק בו ביצר הרע, היינו דכתיב, \u0003ויהי כדברה אל יוסף יום יום ולא שמע אליה,\u0004 שלא שמע מה שהיא אמרה לו בכל יום ויום, כי רוח הטומאה שהוא יצר הרע, מפתה את האדם בכל יום ויום. \u0003לשכב אצלה,\u0004 תוך הגיהנם, ולהיות נידון שם \u0003להיות עמה.\u0004"],[4,"תא חזי כד וכו':","בוא וראה, כשאדם מתדבק בצד ההוא, נמשך אחריה ונטמא עמה בעולם הזה, ונטמא עמה בעולם האחר."],[4,"תא חזי האי וכו':","בוא וראה, צד הטומאה הזה הוא מנוול, הוא טנופת, כמו שכתוב \u0003צא\u0004 תאמר לו, צואה ממש. ובו, בצואה זו, נידון, מי שמטה דרכיו מן התורה. ובו נידונו אלו רשעי עולם שאין להם אמונה בהקב\"ה."],[5,"מה כתיב, ויהי כהיום הזה ויבא וגו':","ויהי כהיום הזה, היינו היום שיצה\"ר שולט בעולם, ויורד להשטות בני אדם. ושואל מתי זה. ומשיב, זהו היום שאדם בא לשוב בתשובה על עונותיו, או שבא לעסוק בתורה ולעשות מצות התורה, ואז באותו זמן יורד יצר הרע כדי להשטות בני העולם. ולמנוע אותם מתשובה מעסק התורה, ומעשיית המצות."],[6,"ויבא הביתה לעשות מלאכתו:","כדי לעסוק בתורה ולעשות מצות התורה, שהוא \u0003מלאכתו\u0004 של האדם בעולם הזה. וכיון שמלאכתו של האדם בעולם הזה, הוא מלאכתו של הקב\"ה, דהיינו העסק בתורה ומצוות, צריך האדם להיות גבור כארי בכל צדדיו, כדי שלא ישלוט עליו הס\"א, ולא יוכל לפתותו. \u0003מה כתיב, ואין איש:\u0004 היינו, אין איש שיקום לפני היצה\"ר, ויעשה עמו מלחמה כראוי."],[7,"מאי אורחיה דיצר הרע וכו':","מהו דרכו של יצר הרע, כיון שרואה שאין איש עומד לנגדו, ולערוך עמו מלחמה, מיד, ותתפשתו בבגדו לאמר שכבה עמי. \u0003ותתפשהו בבגדו,\u0004 כי כשהיצר הרע שולט על האדם, ראשית מעשיו, הוא מתקן ומפאר את \u0003בגדיו,\u0004 מסלסל בשערו, זהו שכתוב ותתפשהו בבגדו לאמר, \u0003שכבה עמי,\u0004 התדבק עמי."],[8,"מאן דאיהו זכאה וכו':","מי שהוא צדיק, מתגבר כנגדו ועושה עמו מלחמה, מה כתוב, \u0003ויעזוב בגדו בידה וינס ויצא החוצה,\u0004 יעזוב אותו ויתגבר לנגדו, וינוס מפניו, כדי להנצל ממנו שלא ישלוט עליו."],[9,"אמר רבי יצחק וכו':","עתידים הצדיקים לראות לעתיד לבוא, את יצר הרע, כהר גבוה, ויתמהו ויאמרו, איך יכולנו לכבוש הר גבוה עליון הזה. ועתידים הרשעים לראות לעתיד לבוא, את יצר הרע, דק כחוט השערה, ויתמהו ויאמרו, איך לא יכולנו לכבוש את חוט השערה הדק כזה, הללו בוכים והללו בוכים. והקב\"ה יבער אותו מן העולם, וישחט אותו לעיניהם, ולא ישלוט עוד בעולם, צדיקים וישמחו. כמש\"א, אך צדיקים יודו לשמך וגו'."]],[[0,"","מַה כָּתוּב? וְלֹא שָׁמַע אֵלֶיהָ לִשְׁכַּב אֶצְלָהּ לִהְיוֹת עִמָּהּ. וְלֹא שָׁמַע אֵלֶיהָ - מִשּׁוּם שֶׁהוּא חָס עַל הָעוֹלָם. לִשְׁכַּב אֶצְלָהּ, מַהוּ לִשְׁכַּב אֶצְלָהּ? כְּדֵי לָקַחַת שִׁלְטוֹן לִשְׁלֹט עַל הָעוֹלָם, וְהַשִּׁלְטוֹן לֹא שׁוֹלֵט עַד שֶׁנִּתֶּנֶת לוֹ רְשׁוּת."],[1,"","דָּבָר אַחֵר לִשְׁכַּב אֶצְלָהּ - כְּמוֹ שֶׁנֶּאֱמַר (ויקרא טו) וּלְאִישׁ אֲשֶׁר יִשְׁכַּב עִם טְמֵאָה. לִהְיוֹת עִמָּהּ - לָתֵת לָהּ גַּדְלוּת וּבְרָכוֹת וְסִיּוּעַ, שֶׁאִלְמָלֵא הָיָה לָהּ סִיּוּעַ מִלְמַעְלָה, לֹא נִשְׁאָר בָּעוֹלָם אֲפִלּוּ אֶחָד, אֲבָל מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל הָעוֹלָם, נִשְׁאָר הָעוֹלָם בְּקִיּוּמוֹ."],[2,"","רַבִּי אַבָּא אָמַר, הַכֹּל הוּא דֶּרֶךְ אַחַת, אֲבָל יֵצֶר הָרָע הוּא שֶׁהוֹלֵךְ וּמְפַתֶּה אֶת בְּנֵי הָאָדם כְּדֵי לְהַסְטוֹת אֶת דַּרְכֵיהֶם וּלְהִדָּבֵק בָּהֶם בְּכָל יוֹם וָיוֹם, וּבְכָל עִדָּן וְעִדָּן. מַסְטֶה אֶת הָאָדָם מִדֶּרֶךְ הָאֱמֶת כְּדֵי לִדְחוֹתוֹ מִדֶּרֶךְ הַחַיִּים, לִמְשּךְ אוֹתוֹ לַגֵּיהִנֹּם."],[3,"","אַשְׁרָיו מִי שֶׁעוֹשֶׂה וְשׁוֹמֵר (אשרי מי שעושה, שומר) דְּרָכָיו וּשְׁבִילָיו כְּדֵי שֶׁלֹּא יִדְבַּק בּוֹ, הַיְנוּ מַה שֶּׁכָּתוּב וַיְהִי כְּדַבְּרָהּ אֶל יוֹסֵף יוֹם יוֹם וְלֹא שָׁמַע אֵלֶיהָ, כְּמוֹ (במה) שֶׁהִיא אוֹמֶרֶת לוֹ בְּכָל יוֹם. שֶׁהֲרֵי רוּחַ הַטֻּמְאָה, יֵצֶר הָרָע, מְפַתֶּה אֶת הָאָדָם בְּכָל יוֹם לִשְׁכַּב אֶצְלָהּ, בְּתוֹךְ הַגֵּיהִנֹּם, וּלְהִדּוֹן שָׁם, לִהְיוֹת עִמָּהּ."],[4,"","בֹּא רְאֵה, כְּשֶׁאָדָם נִדְבָּק לְאוֹתוֹ הַצַּד, נִמְשָׁךְ אַחֲרֶיהָ, וְנִטְמָא עִמָּהּ בָּעוֹלָם הַזֶּה וְנִטְמָא עִמָּהּ בָּעוֹלָם הָאַחֵר. בּא רְאֵה, צַד הַטֻּמְאָה הַזֶּה הוּא מְנֻוָּל, הוּא מְלֻכְלָךְ, כַּכָּתוּב (ישעיה ל) צֵא תֹּאמַר לוֹ, צוֹאָה מַמָּשׁ, וּבוֹ נִדּוֹן מִי שֶׁמַּסְטֶה דַרְכּוֹ מֵהַתּוֹרָה, וּבוֹ נִדּוֹנִים אוֹתָם הָרְשָׁעִים שֶׁל הָעוֹלָם שֶׁאֵין לָהֶם אֱמוּנָה בַּקָּדוֹשׁ-בָּרוּךְ-הוּא."],[5,"","מַה כָּתוּב? וַיְהִי כְּהַיּוֹם הַזֶּה וַיָּבֹא הַבַּיְתָה לַעֲשׂוֹת מְלַאכְתּוֹ וְאֵין אִישׁ מֵאַנְשֵׁי הַבַּיִת שָׁם בַּבָּיִת. וַיְהִי כְּהַיּוֹם הַזֶּה - הַיּוֹם שֶׁיֵּצֶר הָרָע שׁוֹלֵט בָּעוֹלָם וְיוֹרֵד לְהַשְׂטִין לִבְנֵי הָאָדָם. מָתַי? הַיּוֹם שֶׁבָּא אָדָם לָשׁוּב בִּתְשׁוּבָה עַל חֲטָאָיו, אוֹ לְהִשְׁתַּדֵּל בַּתּוֹרָה וְלַעֲשׂוֹת מִצְווֹת הַתּוֹרָה, וְאָז יוֹרֵד בְּאוֹתוֹ הַזְּמַן כְּדֵי לְהַשְׂטִין לִבְנֵי הָאָדָם."],[6,"","וַיָּבֹא הַבַּיְתָה לַעֲשׂוֹת מְלַאכְתּוֹ, כְּדֵי לְהִשְׁתַּדֵּל בַּתּוֹרָה וְלַעֲשׂוֹת מִצְווֹת הַתּוֹרָה, שֶׁהִיא מְלַאכְתּוֹ שֶׁל הָאָדָם בָּעוֹלָם הַזֶּה. וְכֵיוָן שֶׁעֲבוֹדַת הָאָדָם בָּעוֹלָם הַזֶּה הִיא עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, צָרִיךְ לָאָדָם לִהְיוֹת תַּקִּיף כְּאַרְיֵה בְּכָל צְדָדָיו כְּדֵי שֶׁלֹּא יִשְׁלֹט עָלָיו הַצַּד הָאַחֵר וְלֹא יוּכַל לְפַתּוֹת אוֹתוֹ. מַה כָּתוּב? וְאֵין אִישׁ, אֵין גֶּבֶר שֶׁיַּעֲמֹד לִפְנֵי הַיֵּצֶר הָרָע וְיִלָּחֵם בּוֹ קְרָב כָּרָאוּי."],[7,"","מַה דַּרְכּוֹ שֶׁל יֵצֶר הָרָע? כֵּיוָן שֶׁרוֹאֶה שֶׁאֵין הָאָדָם עוֹמֵד כְּנֶגְדּוֹ וְיוֹצֵא לִקְרָב אִתּוֹ, מִיָּד - וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ לֵאמֹר שִׁכְבָה עִמִּי. וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ, מִשּׁוּם שֶׁכַּאֲשֶׁר יֵצֶר הָרָע שׁוֹלֵט עַל הָאָדָם, מַתְקִין אוֹתוֹ וּמְקַשֵּׁט לוֹ אֶת לְבוּשׁוֹ, מְסַלְסֵל בִּשְׂעָרוֹ. זֶהוּ שֶׁכָּתוּב וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ לֵאמֹר שִׁכְבָה עִמִּי, הִדָּבֵק עִמִּי."],[8,"","מִי שֶׁהוּא צַדִּיק, מִתְגַּבֵּר כְּנֶגְדּוֹ וְנִלְחָם בּוֹ קְרָב. מַה כָּתוּב? וַיַּעֲזֹב בִּגְדוֹ בְּיָדָהּ וַיָּנָס וַיֵּצֵא הַחוּצָה. יַעֲזֹב אוֹתוֹ וְיִתְגַּבֵּר כְּנֶגְדּוֹ (וילחם בו קרב) וְיִבְרַח מִמֶּנּוּ כְּדֵי לְהִנָּצֵל מִמֶּנּוּ, וְלֹא יִשְׁלֹט עָלָיו."],[9,"","אָמַר רַבִּי יִצְחָק, עֲתִידִים הֵם הַצַּדִּיקִים לִרְאוֹת אֶת יֵצֶר הָרָע כְּמוֹ הַר גָּדוֹל, וְיִתְמְהוּ וְיֹאמְרוּ, אֵיךְ יָכֹלְנוּ לְהַכְנִיעַ אֶת הָהָר הַגָּדוֹל הָעֶלְיוֹן הַזֶּה!? וַעֲתִידִים הָרְשָׁעִים לִרְאוֹת אֶת הַיֵּצֶר הָרָע דַּקִּיק כְּמוֹ חוּט שֶׁל שַׂעֲרָה, וְיִתְמְהוּ וְיֹאמְרוּ, אֵיךְ לֹא יָכֹלְנוּ לְהַכְנִיעַ אֶת חוּט הַשַּׂעֲרָה כָּזֶה דַּקִּיק!? אֵלּוּ יִבְכּוּ וְאֵלּוּ יִבְכּוּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא יְבַעֵר אוֹתוֹ מִן הָעוֹלָם וְיִשְׁחַט אוֹתוֹ לְעֵינֵיהֶם, וְלֹא יִשְׁלֹט עוֹד בָּעוֹלָם, וְיִרְאוּ הַצַּדִּיקִים וְיִשְׂמְחוּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ."]]],[["וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה חָטְאוּ מַשְׁקֵה מֶלֶךְ מִצְרַיִם וְגו'. רִבִּי יְהוּדָה פָּתַח, (עמוס ג׳:ד׳) הֲיִשְׁאַג אַרְיֵה בַּיַּעַר וְטֶרֶף אֵין לוֹ הֲיִתֵּן כְּפִיר קוֹלוֹ מִמְּעוֹנָתוֹ בִּלְתִּי אִם לָכָד. הֲיִשְׁאַג אַרְיֵה בַּיַּעַר. תָּא חֲזֵי, כַּמָּה אִית לוֹן לִבְנֵי נָשָׁא לְאַשְׁגָּחָא בְּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא. דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, וּבְפוּלְחָנָא דְקוּדְשָׁא בְּרִיךְ הוּא, דַּחַלְתֵּיהּ וְאֵימָתֵיהּ הוּא עַל כֹּלָּא. דְּהָא כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, עֲבַד כָּל בִּרְיָין דְּעַלְמָא, כָּל חַד וְחַד בְּדִיוּקְנֵיהּ כְּדְקָא חָזֵי לֵיהּ. וּלְבָתַר בָּרָא לֵיהּ לְבַר נָשׁ בְּדִיוּקְנָא עִלָּאָה, וְשַׁלְטֵיהּ עַל כֻּלְּהוּ, בְּדִיוּקְנָא דָא.","דְּכָל זִמְנָא דְּבַר נָשׁ קָאִים בְּעַלְמָא, כָּל אִינוּן בִּרְיָין דְּעַלְמָא זָקְפִין רֵישָׁא, וּמִסְתַּכְּלָן בְּדִיוּקְנָא עִלָּאָה דְּבַר נָשׁ. כְּדֵין כֻּלְּהוּ דַּחֲלִין וְזָעִין מִקַּמֵּיהּ, כְּמָה דְאַתְּ אָמֵר, (בראשית ט׳:ב׳) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְעַל כָּל עוֹף הַשָּׁמַיִם וְגו', וְהַנֵּי מִילֵי, כַּד מִסְתַּכְּלָן וְחָמָאן בֵּיהּ, הַאי דִיוּקְנָא, וְנִשְׁמָתָא בֵּיהּ.","אָמַר רִבִּי אֶלְעָזָר, אַף עַל גַּב דְּנִשְׁמָתָא לָאו בֵּיהּ, צַדִּיקַיָא לָא מִשְׁתַּנְיָין מִכְּמָה דְּהֲוָה דְיוּקְנְהוֹן בְּקַדְמִיתָא. וְכַד בַּר נָשׁ לָא אָזִיל בְּאָרְחוֹי דְאוֹרַיְיתָא, הַאי דִיוּקְנָא קַדִּישָׁא אִתְחַלַּף לֵיהּ. וּכְדֵין חֵיוַת בְּרָא וְעוֹפָא דִשְׁמַיָא יָכְלִין לְשַׁלְּטָאָה עֲלֵיהּ, בְּגִין דְּאִתְחַלַּף לֵיהּ הַאי דִיוּקְנָא קַדִּישָׁא, אִתְחַלַּף לֵיהּ הַאי דִיוּקְנָא דְבַר נָשׁ.","וְתָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא אַחְלַף עוֹבָדִין דִּלְעֵילָא וְתַתָּא, בְּגִין לְאַהֲדָרָא מִלִּין לְאַתְרַיְיהוּ, וּלְאִשְׁתַּכְּחָא רְעוּתֵיהּ בְּכָל עוֹבָדֵי דְעַלְמָא. דָּנִיֵּאל לָא אִשְׁתַּנֵּי דִיוּקְנֵיהּ כַּד אַפִּילוּ לֵיהּ בְּגוּבָא דְאַרְיְוָתָא, וּבְגִין כָּךְ אִשְׁתֵּזִיב. אָמַר רִבִּי חִזְקִיָּה, אִי הָכִי, הָא כְּתִיב, (דניאל ו׳:כ״ג) אֱלָהִי שְׁלַח מַלְאֲכֵיהּ וּסֲגַר פּוּם אַרְיָוָתָא וְלָא חַבְּלוּנִי. מַשְׁמַע דִּבְגִין מַלְאָכָא דְּאַסְגַּר לְפוּמַיְיהוּ, לָא אִתְחַבַּל.","אָמַר לֵיהּ, בְּגִין דָא לָא אִתְחַבַּל, דְּהָא הַהוּא דִיוּקְנֵיהּ דְּבַר נָשׁ זַכָּאָה, אִיהוּ מַלְאָכָא מַמָּשׁ, דִּסְגִיר פּוּמָא, וְקָשִׁיר לוֹן, לְנַטְרָא לֵיהּ, דְּלָא יְחַבְּלוּן לֵיהּ. וּבְּגִין כָּךְ אֱלָהִי שְׁלַח מַלְאֲכֵיהּ, הַהוּא דְּכָל דִּיוּקְנִין דְּעַלְמָא מִתְחַקְּקָן בֵּיהּ, וְאִיהוּ אַתְקִיף דִּיוּקְנִי בִּי, וְלָא יָכִילוּ לְשַׁלְטָאָה בִּי, וְסָגַר פּוּמַיְיהוּ, וְעַל דָּא שָׁלַח מַלְאֲכֵיהּ וַדַּאי.","וְהַאי מַלְאֲכָא, הַהוּא דְּכָל דִּיוּקְנִין מִתְחַקְּקָן בֵּיהּ. דִּכְתִיב, (תהילים ק״י:ו׳) יָדִין בַּגּוֹיִם מָלֵא גְוִיּוֹת, אִיהוּ דְּלָא אִשְׁתַּנֵּי קַמֵּיהּ כָּל דִּיוּקְנִין דְּעַלְמָא. וְעַל דָּא מִבָּעֵי לֵיהּ לְבַר נָשׁ, לְאִסְתַּמְּרָא אָרְחוֹי וּשְׁבִילוֹי, בְּגִין דְּלָא יֶחטָא קַמֵּיהּ דְּמָארֵיהּ, וְיִתְקַיַּים בְּדִיוּקְנָא דְאָדָם.","תָּא חֲזֵי, יְחֶזְקֵאל נָטַר פּוּמֵיהּ מִמַּאֲכָלֵי דְאִיסּוּרֵי, דִּכְתִיב, (יחזקאלד) וְלָא בָּא בְּפִי בְּשַׂר פִּגּוּל, זָכָה וְאִקְרֵי בֶּן אָדָם. דָּנִיֵּאל מַה כְּתִיב בֵּיהּ, (דניאל א׳:ח׳) וַיָּשֶׂם דָּנִיֵּאל עַל לִבּוֹ אֲשֶׁר לא יִתְגָּאַל בְּפַת בַּג הַמֶּלֶךְ וּבְיֵין מִשְׁתָּיו, זָכָה הוּא, וְאִתְקְיַּים בִּדִיוּקְנֵיהּ דְּאָדָם. בְּגִין דְּכָל מִלִּין דְּעַלְמָא, כֻּלְּהוּ דַּחֲלִין מִקַּמֵּי דִּיוּקְנָא דְאָדָם, דְּאִיהוּ שַׁלִּיטָא עַל כֻּלְּהוּ, וְאִיהוּ מַלְכָּא עַל כֹּלָּא.","אָמַר רִבִּי יוֹסֵי, בְּגִין דָּא אִצְטְרִיךְ לֵיהּ לְבַר נָשׁ, לְאִסְתַּמְּרָא מֵחוֹבוֹי, וְלָא יִסְטֵי לִימִינָא וְלִשְׂמָאלָא. וְעִם כָּל דָּא, בָּעֵי לֵיהּ לְבַר נָשׁ לְמִבְדַּק בְּחוֹבוֹי בְּכָל יוֹמָא וְיוֹמָא. דְּהָא כַּד בַר נָשׁ קָאִים מֵעַרְסֵיהּ, תְּרֵין סַהֲדִין קָיְימִין קַמֵּיהּ, וְאָזְלֵי בַּהֲדֵיהּ כָּל יוֹמָא.","בָּעֵי בַּר נָשׁ לְמֵיקַם, אִינוּן סַהֲדֵי אָמְרִין לֵיהּ בְּשַׁעְתָּא דְּאַפְתַּח עֵינוֹי, (משלי ד׳:כ״ה) עֵינֶיךָ לְנֹכַח יַבִּיטוּ וְעַפְעַפֶּיךָ יַיְשִׁירוּ נְגְדֶּךָ. קָם וְאַתְקִין רַגְלוֹי לְמֵהַךְ, אִינוּן סַהֲדִין אָמְרִין לֵיהּ, (שם) פַּלֵּס מַעְגַּל רַגְלֶךָ וְגו'. וְעַל דָּא כַּד אָזִיל בַר נָשׁ, בְּכָל יוֹמָא, בָּעֵי לֵיהּ לְאִסְתַּמְּרָא מֵחוֹבוֹי.","בְּכָל יוֹמָא וְיוֹמָא, כַּד אָתֵי לֵילְיָא, בָּעֵי לְאִסְתַּכְּלָא וּלְמִבְדַּק, בְּכָל מַה דְּעֲבַד כָּל הַהוּא יוֹמָא. בְּגִין דְּיֵיתוּב מִנַּיְיהוּ, וְיִסְתַּכֵּל בְּהוּ תָּדִיר, בְּגִין דְּיֵיתוּב קַמֵּי מָארֵיהּ. כְּמָה דְאַתְּ אָמֵר (תהילים נ״א:ה׳) וְחַטָּאתִי נֶגְדִּי תָמִיד, בְּגִין דְּיֵיתוּב מִנַּיְיהוּ.","וְתָּא חֲזֵי, בְּזִמְנָא דְּהֲווּ יִשְׂרָאֵל בְּאַרְעָא קַדִּישָׁא, לָא אִשְׁתַּכַּח בִּידַיְיהוּ חוֹבָא, כְּמָה דְּאוּקְמוּהָ. בְּגִין דְּאִינוּן קָרְבָּנִין, דְּהֲווּ מַקְרִבִין בְּכָל יוֹמָא, הֲווּ מְכַפְּרֵי עֲלַיְיהוּ. הַשְׁתָּא דְּאִתְגָּלוֹן יִשְׂרָאֵל מֵאַרְעָא, וְלֵית מַאן דִּמְכַפֵּר עֲלַיְיהוּ, אוֹרַיְיתָא הִיא מְכַפְּרָא עֲלַיְיהוּ, וְעוֹבָדִין דְּכַשְׁרָן, בְּגִין דִּשְׁכִינְתָּא עִמְּהוֹן בְּגָלוּתָא. וּמַאן דְּאִיהוּ לָא מִסְתַּכַּל בְּאָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, גָּרִים לִשְׁכִינְתָּא לְאִתְכַּפְיָא בְּגוֹ עַפְרָא, כְּמָה דְאַתְּ אָמֵר, (ישעיהו כ״ו:ה׳) יַשְׁפִּילֶנָּה יַשְׁפִּילָהּ עַד אָרֶץ וְגו'."],[[0,"ויהי אחר הדברים וגו':","ר' יהודה פתח הישאג אריה ביער וטרף אין לו וגו'. \u0003הישאג אריה ביער,\u0004 בוא וראה, כמה יש לבני אדם להשגיח בעבודת הקב\"ה, כי כל מי שמשתדל בתורה ובעבודת הקב\"ה, פחדו ואימתו מוטל על כל."],[1,"דהא כד ברא וכו':","כי כשברא הקב\"ה את העולם, עשה כל בריות העולם, כל אחד ואחד בצורתו כראוי לו, ואחר כך ברא את האדם בצורה עליונה, והמשילו בכח צורה זו על כל הבריות, וכל זמן שהאדם עומד בעולם, כל הבריות, כשנושאים ראשם ומסתכלים בצורה העליונה של האדם, כולם מפחדים אז ורועדים מפניו, כמש\"א \u0003ומוראכם\u0004 וחתכם יהיה על כל חית הארץ וגו'. והדברים נאמרים, רק כשמסתכלים ורואים בו צורה הזו, והנשמה נמצאת בו."],[2,"אמר ר' אלעזר:","אר\"א, אע\"פ שאין בו הנשמה, הצדיקים, אין צורתם משתנה ממה שהיו בתחילה. וכשהאדם אינו הולך בדרכי התורה, נחלפת לו צורה הקדושה הזו, ואז, חיות השדה ועוף השמים יכולים לשלוט עליו. כי משום שנחלפה צורתו הקדושה, נחלפה והלכה ממנו צורת אדם, וקבל צורת שאר בעלי החי, וע\"כ אין הבריות מפחדים עוד ממנו ויכולים למשול עליו."],[3,"ות\"ח קב\"ה אחלף וכו':","ובוא וראה, הקב\"ה מחליף המעשים למעלה ולמטה, דהיינו שמחליף צורה הקדושה שלמעלה ודמות אדם שלמטה כנ\"ל, כדי להחזיר הדברים לשורשם, כמו שהיו מטרם החטא דעצה\"ד, ובכדי שימצא רצונו בכל מעשי העולם. פירוש, שעל ידי העונשים, מתתקנים כל מעשי העולם, ואפילו הרחוקים ביותר."],[3,"דניאל לא אשתני וכו':","דניאל, לא נשתנה צורתו כשהפילוהו בבור האריות, ומשום זה נצל. אמר ר' חזקיה, אם כן, הרי כתוב, אלקי שלח מלאכיה וגו', נשמע, שמשום שהמלאך סגר את פיהם לא נחבל, ולא משום צורתו הקדושה."],[4,"א\"ל בגין דא וכו':","אמר לו, משום זה לא נחבל, כי אותו הצורה הקדושה של אדם צדיק, הוא מלאך ממש, שסגר פה האריות, וקשרם, לשמרו שלא יחבלו בו, ומשום זה אמר דניאל, \u0003אלקי שלח מלאכיה,\u0004 היינו אותו המלאך, שכל צורות העולם נחקקות בו, והוא הגביר את צורתו בי, ולא יכלו האריות למשול בי, וסגר את פיהם. וע\"כ ודאי, ששלח מלאכו."],[5,"והאי מלאכא, ההוא וכו':","ומלאך הזה, הוא אותו, שכל הצורות נחקקות בו, שה\"ס הנוקבא, שנקראת מלאך, שממנה כל הצורות שבעולם, שכתוב \u0003ידין בגוים מלא גויות,\u0004 שצורותיהם של כל הגויות לפניו, כי כל הצורות שבעולם אינן משתנות לפניו. וע\"כ צריך האדם לשמור דרכיו ושביליו כדי שלא יחטא לפני רבונו ויתקיים בצורת אדם."],[6,"ת\"ח יחזקאל וכו':","בוא וראה, יחזקאל שמר את פיו ממאכלות אסורות, שכתוב, ולא בא בפי בשר פגול, זכה ונקרא משום זה בן אדם. דניאל מה כתוב בו, וישם דניאל על לבו, אשר לא יתגאל בפת בג המלך וביין משתיו. ע\"כ זכה הוא ונתקיים בצורת אדם. כי כל דברי העולם, כולם מפחדים מפני צורת אדם, שהוא מושל על כולם והוא מלך על כולם."],[7,"א\"ר יוסי וכו':","אר\"י, משום זה צריך האדם להשמר מעונותיו, ולא יטה ימין ושמאל. ועם כל זה, אע\"פ ששומר את עצמו, צריך האדם לבדוק את עצמו מעונותיו בכל יום ויום. כי כשהאדם קם ממטתו, שני עדים עומדים לפניו, והולכים עמו כל היום."],[8,"בעי בר נש וכו':","רוצה האדם לקום, אלו העדים אומרים לו, בשעה שפתח עיניו, עיניך לנכח יביטו וגו'. קם והכין את רגליו ללכת, אלו העדים אומרים לו, פלס מעגל רגלך וגו'. וע\"כ כשהאדם הולך, צריך בכל היום להשמר מעונותיו."],[9,"בכל יומא ויומא וכו':","בכל יום ויום כשבא הלילה, צריך להסתכל ולבדוק בכל מה שעשה כל אותו היום, כדי שישוב בתשובה עליהם. ויסתכל בהם תמיד, כדי שישוב לפני רבונו, כמש\"א, וחטאתי נגדי תמיד, כדי שישוב עליהם."],[10,"ות\"ח בזמנא וכו':","ובוא וראה, בזמן שהיו ישראל בארץ הקדש, לא היה נמצא בידיהם עון, כמו שבארוה, משום שאלו הקרבנות שהיו מקריבים בכל יום, היו מכפרים עליהם, עתה שנגלו ישראל מן הארץ, ואין מי שיכפר עליהם, התורה היא מכפרת עליהם, והמעשים טובים. משום שהשכינה עמהם בגלות, ומי שאינו מסתכל בדרכיו של הקב\"ה, גורם לשכינה להשתוחח עד עפר כמש\"א, ישפילנה ישפילה עד ארץ."]],[[0,"","וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה חָטְאוּ מַשְׁקֵה מֶלֶךְ מִצְרַיִם וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (עמוס ג) הֲיִשְׁאַג אַרְיֵה בַּיַּעַר וְטֶרֶף אֵין לוֹ הֲיִתֵּן כְּפִיר קוֹלוֹ מִמְּעוֹנתוֹ בִּלְתִּי אִם לָכָד. הֲיִשְׁאַג אַרְיֵה בַּיַּעַר. בֹּא רְאֵה כַּמָּה יֵשׁ לַאֲנָשִׁים לְהַשְׁגִּיחַ בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וּבַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, פַּחְדּוֹ וְיִרְאָתוֹ הֵם עַל הַכֹּל, שֶׁהֲרֵי כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה אֶת כָּל הַבְּרִיּוֹת שֶׁל הָעוֹלָם כָּל אֶחָד וְאֶחָד בִּדְמוּתוֹ כָּרָאוּי לוֹ, וְאַחַר כָּךְ בָּרָא אֶת הָאָדָם בִּדְמוּת עֶלְיוֹנָה, וְהִשְׁלִיט אוֹתוֹ עַל כֻּלָּם בַּדְּמוּת הַזּוֹ."],[1,"","שֶׁכָּל זְמַן שֶׁאָדָם עוֹמֵד בָּעוֹלָם, כָּל אוֹתָם הַבְּרִיּוֹת שֶׁל הָעוֹלָם זוֹקְפִים רֹאשָׁם וּמִסְתַּכְּלִים בַּדְּמוּת הָעֶלְיוֹנָה שֶׁל הָאָדָם, אָז כֻּלָּם פּוֹחֲדִים וְזָעִים מִלְּפָנָיו, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְעַל כָּל עוֹף הַשָּׁמַיִם וְגוֹ'. וְהַדְּבָרִים הַלָּלוּ, כְּשֶׁמִּסְתַּכְּלִים וְרוֹאִים אוֹתוֹ, הַדְּמוּת הַזּוֹ, וְהַנְּשָׁמָה בּוֹ."],[2,"","אָמַר רַבִּי אֶלְעָזָר, אַף עַל גַּב שֶׁאֵין בּוֹ נְשָׁמָה, הַצַּדִּיקִים לֹא מִשְׁתַּנִּים מִכְּמוֹ שֶׁהָיְתָה דְמוּתָם בַּהַתְחָלָה, וּכְשֶׁאָדָם לֹא הוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה, הַדְּמוּת הַקְּדוֹשָׁה הַזּוֹ מִתְחַלֶּפֶת לוֹ, וְאָז חַיַּת הַבָּר וְעוֹף הַשָּׁמַיִם יְכוֹלִים לִשְׁלֹט עָלָיו, מִשּׁוּם שֶׁהַדְּמוּת הַקְּדוֹשָׁה הַזּוֹ הִתְחַלְּפָה לוֹ, הִתְחַלְּפָה לוֹ הַדְּמוּת הַזּוֹ שֶׁל בֶּן אָדָם."],[3,"","וּבֹא וּרְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲלִיף הַמַּעֲשִׂים שֶׁלְּמַעְלָה וּמַטָּה כְּדֵי לְהַחֲזִיר הַדְּבָרִים לִמְקוֹמָם, וְשֶׁיִּמָּצֵא רְצוֹנוֹ בְּכָל מַעֲשֵׂי הָעוֹלָם. הַדְּמוּת שֶׁל דָּנִיֵּאל לֹא הִשְׁתַּנְּתָה כְּשֶׁהִפִּילוּ אוֹתוֹ לְגֹב הָאֲרָיוֹת, וּמִשּׁוּם כָּךְ נִצּוֹל. אָמַר רַבִּי חִזְקִיָּה, אִם כָּךְ, הִנֵּה כָּתוּב (דניאל ו) אֱלֹהַי שָׁלַח אֶת מַלְאָכוֹ וְסָגַר אֶת פִּי הָאֲרָיוֹת וְלֹא חִבְּלוּ אוֹתִי. מַשְׁמָע שֶׁמִּשּׁוּם הַמַּלְאָךְ שֶׁסָּגַר אֶת פִּיהֶם, לֹא נִזּוֹק."],[4,"","אָמַר לוֹ, מִשּׁוּם זֶה לֹא נִזּוֹק, שֶׁהֲרֵי אוֹתָהּ דְּמוּת הָאָדָם הַצַּדִּיק הִיא הַמַּלְאָךְ מַמָּשׁ, שֶׁסּוֹגֵר אֶת הַפֶּה וְקוֹשֵׁר אוֹתָם לִשְׁמֹר אוֹתוֹ שֶׁלֹּא יַזִּיקוּ לוֹ, וּמִשּׁוּם כָּךְ אֱלָהִי שְׁלַח מַלְאֲכֵהּ, אוֹתוֹ שֶׁכָּל הַדְּמֻיּוֹת שֶׁבָּעוֹלָם חֲקוּקוֹת בּוֹ, וְהוּא הֶחֱזִיק בִּי אֶת דְּמוּתִי וְלֹא יָכְלוּ לִשְׁלֹט בִּי, וְסָגַר אֶת פִּיהֶם. וְעַל זֶה שָׁלַח וַדַּאי אֶת מַלְאָכוֹ."],[5,"","וְהַמַּלְאָךָ הַזֶּה, אוֹתוֹ שֶׁכָּל הַדְּמֻיּוֹת חֲקוּקוֹת בּוֹ, שֶׁכָּתוּב (תהלים קי) יָדִין בַּגּוֹיִם מָלֵא גְוִיּוֹת, הוּא שֶׁלֹּא מִשְׁתַּנֶּה לְפָנָיו כָּל דְּמֻיּוֹת הָעוֹלָם, וְעַל כֵּן צָרִיךְ הָאָדָם לִשְׁמֹר דְּרָכָיו וּשְׁבִילָיו כְּדֵי שֶׁלֹּא יֶחֱטָא לִפְנֵי רִבּוֹנוֹ, וְיִתְקַיֵּם בִּדְמוּת שֶׁל אָדָם."],[6,"","בֹּא רְאֵה, יְחֶזְקֵאל שָׁמַר אֶת פִּיו מִמַּאֲכָלוֹת אֲסוּרִים, שֶׁכָּתוּב (יחזקאל ד) וְלֹא בָא בְּפִי בְּשַׂר פִּגּוּל, זָכָה וְנִקְרָא בֶּן אָדָם. מַה כָּתוּב בְּדָנִיֵּאל? (דניאל א) וַיָּשֶׂם דָּנִיֵּאל עַל לִבּוֹ אֲשֶׁר לֹא יִתְגָּאַל בְּפַת בַּג הַמֶּלֶךְ וּבְיֵין מִשְׁתָּיו, זָכָה הוּא וְהִתְקַיֵּם בִּדְמוּת שֶׁל אָדָם. מִשּׁוּם שֶׁכָּל דִּבְרֵי הָעוֹלָם, כֻּלָּם מְפַחֲדִים מִלִּפְנֵי דְמוּתוֹ שֶׁל אָדָם, שֶׁהוּא שַׁלִּיט עַל כֻּלָּם וְהוּא הַמֶּלֶךְ עַל הַכֹּל."],[7,"","אָמַר רַבִּי יוֹסֵי, מִשּׁוּם זֶה צָרִיךְ לָאָדָם לְהִשָּׁמֵר מֵחֲטָאָיו וְלֹא יִסְטֶה לְיָמִין וְלִשְׂמֹאל, וְעִם כָּל זֶה צָרִיךְ לָאָדָם לִבְדּק בַּחֲטָאָיו בְּכָל יוֹם וָיוֹם, שֶׁהֲרֵי כְּשֶׁאָדָם עוֹמֵד מִמִּטָּתוֹ, שְׁנֵי עֵדִים עוֹמְדִים לְפָנָיו וְהוֹלְכִים עִמּוֹ כָּל הַיּוֹם."],[8,"","רוֹצֶה הָאָדָם לָקוּם - אוֹתָם הָעֵדִים אוֹמְרִים לוֹ בְּשָׁעָה שֶׁפּוֹתֵחַ עֵינָיו: (משלי ד) עֵינֶיךְ לְנֹכַח יַבִּיטוּ וְעַפְעַפֶּיךְ יַיְשִׁירוּ נֶגְדֶּךְ. קָם וּמְסַדֵּר רַגְלָיו לָלֶכֶת - אוֹתָם הָעֵדִים אוֹמְרִים לוֹ: (שם) פַּלֵּס מַעְגַּל רַגְלֶךְ וְגוֹ'. וְעַל כֵּן, כְּשֶׁהוֹלֵךְ הָאָדָם בְּכָל יוֹם, צָרִיךְ לוֹ לְהִשָּׁמֵר מֵחֲטָאָיו."],[9,"","בְּכָל יוֹם וָיוֹם, כְּשֶׁבָּא הַלַּיְלָה, צָרִיךְ לְהִתְבּוֹנֵן וְלִבְדֹּק בְּכָל מַה שֶּׁעָשָׂה כָּל הַיּוֹם הַהוּא כְּדֵי שֶׁיָּשׁוּב מֵהֶם וְיִסְתַּכֵּל בָּהֶם תָּמִיד, כְּדֵי שֶׁיָּשׁוּב לִפְנֵי רִבּוֹנוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים נא) וְחַטָּאתִי נֶגְדִּי תָמִיד, כְּדֵי שֶׁיָּשׁוּב מֵהֶם."],[10,"","וּבֹא וּרְאֵה, בִּזְמַן שֶׁיִּשְׂרָאֵל הָיוּ בָּאָרֶץ הַקְּדוֹשָׁה, לֹא נִמְצָא בִידֵיהֶם חֵטְא, כְּמוֹ שֶׁבֵּאֲרוּהוּ, מִשּׁוּם שֶׁאוֹתָם הַקָּרְבָּנוֹת שֶׁהָיוּ מַקְרִיבִים בְּכָל יוֹם הָיוּ מְכַפְּרִים עֲלֵיהֶם. עַכְשָׁו שֶׁיִּשְׂרָאֵל גָּלוּ מִן הָאָרֶץ וְאֵין מִי שֶׁמְּכַפֵּר עֲלֵיהֶם, הַתּוֹרָה מְכַפֶּרֶת עֲלֵיהֶם וּמַעֲשִׂים כְּשֵׁרִים, מִשּׁוּם שֶׁהַשְּׁכִינָה עִמָּהֶם בַּגָּלוּת, וּמִי שֶׁאֵינוֹ מִסְתַּכֵּל בְּדַרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, גּוֹרֵם לַשְּׁכִינָה לְהִכָּנַע בְּתוֹךְ הֶעָפָר, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כו) יַשְׁפִּילֶנָּה יַשְׁפִּילָהּ עַד אֶרֶץ וְגוֹ'."]]],[["אָמַר רִבִּי יִצְחָק, וְכֵן מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא וּבְעוֹבָדִין דְּכַשְׁרָן, גָּרִים לָהּ לְכְּנֶסֶת יִשְׂרָאֵל, לַאֲרָמָא רֵישָׁא בְּגוֹ גָלוּתָא. זַכָּאָה חוּלָקֵיהוֹן דְּאִינוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי.","תָּא חֲזֵי, גִּלְגֵּל קוּדְשָׁא בְּרִיךְ הוּא גִּלְגּוּלִין בְּעַלְמָא, בְּגִין לַאֲרָמָא רֵישָׁא דְצַדִּיקַיָיא, דְּהָא בְּגִין דְּיָרִים יוֹסֵף רֵישֵׁיהּ בְּעַלְמָא, עַל דְּאִשְׁתַּכַּח זַכָּאָה קַמֵּיהּ, אַרְגִּיז רִבּוֹנָא עַל עַבְדוֹי. כְּמָה דְאַתְּ אָמֵר חָטְאוּ מַשְׁקֵה מֶלֶךְ מִצְרַיִם וְהָאוֹפֶה לַאֲדוֹנֵיהֶם לְמֶלֶךְ מִצְרַיִם. וְכֹלָּא בְּגִין לַאֲרָמָא רֵישָׁא דְיוֹסֵף זַכָּאָה. וְתָּא חֲזֵי, עַל יְדָא דְחֶלְמָא, אִתְכַּפְיָיא מֵעִם אֲחוֹי, וְעַל יְדָא דְחֶלְמָא אִתְרַבֵּי עַל אֲחוֹי, וְאִתְרַבֵּי עַל כָּל עַלְמָא:","וַיַּחַלְמוּ חֲלוֹם שְׁנֵיהֶם אִישׁ חֲלוֹמוֹ בְּלַיְלָה אֶחָד אִישׁ כְּפִתְרוֹן וְגו', תָּא חֲזֵי, דְּהָא אִתְּמָר דְּכָל חֶלְמִין אָזְלִין בָּתַר פּוּמָא, יוֹסֵף כַּד פָּשַׁר לְהוּ חֶלְמָא, אַמַּאי פָּשַׁר לְהַאי פִּישְׁרָא טָבָא, וּלְהַאי פִּישְׁרָא בִּישָׁא. אֶלָּא, אִינוּן חֶלְמִין עֲלֵיהּ דְּיוֹסֵף הֲוָה, וּבְגִין דְּיָדַע מִלָּה עַל עִקָּרָא וְשָׁרְשָׁא דִילָהּ, בְּגִין כָּךְ פָּשַׁר חֶלְמָא לְהוּ כְּמָה דְאִצְטְרִיךְ. לְכָל חַד וְחַד פָּשַׁר לְהוֹן פִּישְׁרָא, לְאַהֲדָרָא מִלָּה עַל אַתְרֵיהּ.","מַה כְּתִיב וַיֹּאמֶר אֲלֵיהֶם יוֹסֵף הֲלֹא לֵאלהִים פִּתְרוֹנִים סַפְּרוּ נָא לִי. מַאי טַעְמָא, בְּגִין דְּהָכִי מִבָּעֵי לֵיהּ לְמִפְשַׁר חֶלְמָא, לְפָקְדָא פִּישְׁרָא לְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּתַמָּן אִיהוּ קִיּוּמָא דְּכֹלָּא, וּבֵיהּ קָיְימָא פִּישְׁרָא.","תָּא חֲזֵי, הָא אִתְּמָר דְּדַרְגָּא דְחֶלְמָא לְתַתָּא אִיהוּ, וְאִיהוּ דַרְגָּא שְׁתִיתָאָה. בְּגִין דְּהָא מֵאֲתַר דִּנְבוּאָה שַׁרְיָא עַד הַאי דַּרְגָּא דְחֶלְמָא, שִׁיתָּא דַרְגִּין אִינוּן. וְסָלְקָא פִּישְׁרָא מִדַּרְגָּא דְחֶלְמָא, לְדַרְגָּא אָחֳרָא. חֶלְמָא אִיהוּ דַרְגָּא דִלְתַתָּא, וּפִישְׁרָא קָיְימָא עֲלַיְיהוּ. וּפִישְׁרָא קָיְימָא בְּדִבּוּר, וְעַל דָּא בְּדִבּוּר קָיְימָא מִלָּה. דִּכְתִיב הֲלֹא לֵאלהִים פִּתְרוֹנִים, הֲלא לֵאלהִים וַדַּאי.","תָּא חֲזֵי, מַה כְּתִיב, וַיְסַפֵּר שַׂר הַמַּשְׁקִים אֶת חֲלוֹמוֹ לְיוֹסֵף וְגו'. רִבִּי אֶלְעָזָר פָּתַח וְאֲמַר, (מלכים ב ב׳:ט׳) וַיְהִי בְּעָבְרָם וְאֵלִיָּהוּ אָמַר אֶל אֱלִישָׁע שְׁאַל מָה אֶעֱשֶׂה לָךְ בְּטֶרֶם אֶלָּקַח מֵעִמָּךְ וַיֹּאמֶר אֱלִישָׁע וִיהִי נָא פִּי שְׁנַיִם בְּרוּחֲךָ אֵלָי. הָכָא אִית לְאִסְתַּכָּלָא, וְהַאי קְרָא תְּוָוהָא אִיהוּ. וְאֵלִיָּהוּ אָמַר אֶל אֱלִישָׁע שְׁאַל מָה אֶעֱשֶׂה לָךְ, וְכִי בִּרְשׁוּתֵיהּ קָיְימָא, וְהָא בִּרְשׁוּתֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ. וְתוּ, דֶּאֱלִישָׁע הָכִי נָמֵי אִיהוּ הֲוָה יָדַע, מַאי טַעְמָא אָמַר, וִיהִי נָא פִּי שְׁנַיִם בְּרוּחֲךָ אֵלַי.","אֶלָּא וַדַּאי, מַאן דְּאָחִיד בִּשְׁמַיָא וְאַרְעָא וְכָל עָלְמִין, הֵיךְ לָא יְהֵא בִּרְשׁוּתֵיהּ דָּא. וַדַּאי אֵלִיָּהוּ, וּשְׁאָר צַדִּיקִים, קוּדְשָׁא בְּרִיךְ הוּא עָבִיד רְעוּתְהוֹן דְּצַדִּיקַיָּיא תָּדִיר. דִּכְתִיב, (תהילים קמ״ה:י״ט) רְצוֹן יְרֵאָיו יַעֲשֶׂה, וְכָל שֶׁכֵּן דְּהַהוּא רוּחָא קַדִּישָׁא, דִּי עֲלֵיהּ, יָרִית לֵיהּ לְצַדִּיקָא דֶּאֱלִישָׁע, דְּהֲוָה שַׁמָּשָׁא דִילֵיהּ. וְהָא קוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ (מלכים א י״ט:ט״ז) וְאֶת אֱלִישָׁע בֶּן שָׁפָט מֵאָבֵל מְחוֹלָה תִּמְשַׁח לְנָבִיא תַּחְתֶּיךָ, וְעַל דָּא הֲוָה לֵיהּ לֶאֱלִישָׁע לְיָרְתָא לֵיהּ.","פִּי שְׁנַיִם בְּרוּחֲךָ, מַאי פִּי שְׁנַיִם בְּרוּחֲךָ אֵלַי, וְכִי סַלְקָא דַעְתָּךְ, דְּעַל חַד תְּרֵין שָׁאִיל, וּמַה דְּלָא הֲוָה בִּרְשׁוּתֵיהּ, הֵיךְ שָׁאַל מִינֵיהּ. אֶלָּא, אִיהוּ לָא שָׁאִיל רוּחַ עַל חַד תְּרֵין, אֶלָא (איהו) הָכִי שָׁאַל מִינֵּיהּ, בְּהַהוּא רוּחָא דְּהֲוָה לֵיהּ, דְּיַעֲבִיד (ד\"א ל\"ג חד) תְּרֵין נִמּוּסִין בְּעַלְמָא, בְּהַהוּא רוּחָא.","מַה כְּתִיב וַיֹּאמֶר הִקְשֵׁיתָ לִשְׁאוֹל אִם תִּרְאֶה אוֹתִי לֻקָּח מֵאִתָּךְ יְהִי לְךָ כֵן וְאִם אַיִן לא יִהְיֶה. מַאי טַעְמָא אִם תִּרְאֶה אוֹתִי. אֶלָּא אָמַר לֵיהּ, אִם תֵּיכוּל לְמֵיקַם עַל עִקָּרָא דְרוּחָא דִּשָׁבַקְנָא לָךְ, בְּשַׁעְתָּא דְּאִתְנָסִיבְנָא מִינָךְ, יְהֵא לְךָ כְּדֵין. דְהָא כָּל הַהוּא עִקָּרָא דְרוּחָא בְּשַׁעְתָּא דְיִסְתַּכֵּל בֵּיהּ, כַּד חָמֵי לֵיהּ לְאֵלִיָּהוּ, יֶהֱוֵי דְבֵיקוּתָא בֵּיהּ, כְּדְקָא יְאוּת."],[[0,"א\"ר יצחק וכו':","אר\"י, וכן מי שמשתדל בתורה ובמעשים טובים גורם לכנסת ישראל שהיא השכינה, להרים ראשה תוך הגלות. אשרי חלקם של המשתדלים בתורה יום ולילה."],[1,"ת\"ח גלגל וכו':","בוא וראה גלגל הקב\"ה גלגולים בעולם כדי להרים ראשם של הצדיקים. כי כדי שירים יוסף ראשו בעולם על שהיה צדיק לפניו, הרגיז את האדון על עבדיו, כמש\"א, חטאו משקה מלך מצרים והאופה לאדוניהם למלך מצרים. והכל היה כדי להרים ראש של יוסף הצדיק, ובוא וראה, על ידי החלום נשפל מאחיו, ועל ידי החלום התגדל על אחיו, והתגדל על כל העולם. דהיינו ע\"י חלום פרעה"],[2,"ויחלמו חלום שניהם וגו':","בוא וראה, כי למדנו, שכל החלומות הולכים אחר הפה, ושואל לפי\"ז, יוסף כשפתר להם החלום, למה פתר לזה פתרון טוב ולזה פתרון רע, למה לא פתר לשניהם פתרון טוב. ומשיב, אלא אלו החלומות, על יוסף היו, ומשום שידע הדבר בעקרו ושרשו, משום זה פתר להם החלום כמו שצריך, ופתר לכל אחד ואחד פתרון, כדי להחזיר דבר למקומו ושורשו."],[3,"מה כתיב, ויאמר וגו' לאלקים פתרונים וגו':","שואל, מהו הטעם שאמר כן. ואומר, כי כן צריכים לפתור החלום, לתלות הפתרון בהקב\"ה. כי שם הוא קיום הכל ובו נמצא הפתרון."],[4,"ת\"ח הא אתמר וכו':","בוא וראה הרי למדנו, שמדרגת החלום הוא למטה, והוא מדרגה הששית לנבואה, משום, שממקום שהנבואה שורה עד מדרגת החלום, הן שש מדרגות. (כנ\"ל ויצא דף כ\"ו ד\"ה ואמר ע\"ש) והפתרון עולה ממדרגת החלום, למדרגה אחרת, ומפרש, החלום היא מדרגה שלמטה, בגבריאל, והפתרון עומד עליו, כי הפתרון תלוי בדבור, שהיא הנוקבא. ועל כן בדבור תלוי הדבר, שכתוב, הלא לאלקים פתרונים, \u0003הלא לאלקים\u0004, ודאי, שהיא הנוקבא הנקראת אלקים."],[5,"ויספר שר המשקים את חלומו וגו':","ר' אלעזר פתח ואמר ויהי בעברם וגו' ויהי נא פי שנים ברוחך אלי. כאן יש להסתכל, ומקרא הזה פליאה הוא, שכתוב, ואליהו אמר אל אלישע, שאל מה אעשה לך. וכי ברשותו הוא, הלא ברשותו של הקב\"ה הוא. ועוד, שאלישע גם כן, היה יודע, שבקשה זו אינה ברשותו אלא ברשות הקב\"ה, מהו הטעם, שאמר, ויהי נא פי שנים ברוחך אלי."],[6,"אלא ודאי מאן וכו':","ומשיב, אלא ודאי, מי שנתאחד בשמים וארץ וכל העולם, איך לא יהיה זה ברשותו. ודאי הוא, שאליהו ושאר צדיקים, הקב\"ה עושה רצונם של הצדיקים תמיד, שכתוב, רצון יראיו יעשה. וכל שכן, אותו רוח הקדוש שעליו, שיורש אותו הצדיק אלישע, כי אלישע היה המשמש שלו, וראוי ליורשו, והרי הקב\"ה א\"ל, ואת אלישע בן שפט מאבל מחולה תמשח לנביא תחתיך. וע\"כ היה לאלישע לרשת אותו."],[7,"פי שנים ברוחך אלי:","ושואל, מה פי שנים ברוחך אלי, וכי יעלה על דעתך, ששאל על אחד שנים, דהיינו שיגדל רוחו פי שנים מרוחו של אליהו, איך שאל ממנו מה שלא היה ברשותו, כי אין לך נותן מה שאין לו."],[7,"אלא איהו לא וכו':","ומשיב, אלא הוא לא שאל רוח על אחד שנים, אלא כך שאל ממנו, שאותו הרוח שהיה לו יעשה באותו הרוח, על אחד, שנים ניסים בעולם ממה שעשה עמו אליהו."],[8,"מה כתיב ויאמר הקשית לשאול וגו':","שואל, מהו הטעם \u0003אם תראה אותי,\u0004 למה תלה לו בקשתו בזה. ומשיב, אלא אמר לו, אם תוכל לעמוד על עיקרו של הרוח, שהנחתי לך בשעה שלוקחתי ממך יהי לך כן, כי כל עיקרו של הרוח ההוא, הוא, בעת שיסתכל בו, ברוח, כשרואה את אליהו, שתהיה הדבקות בו כראוי."],[8,"","פירוש, להיות, שאליהו הוא שורשו של הרוח, אין הרוח בכל שלמותו אלא כשהוא מחובר עם שורשו, שהוא אליהו. לפיכך, כשמסתכל ברוח, צריך לראות עמו את שורשו, שהוא צורת אליהו. והיינו דוקא, שיראה צורתו בו, בעת שהניח לו את הרוח, דהיינו בעת שלוקח ממנו. וזהו שאמר לו אליהו, \u0003אם תראה אותי לקח מאתך יהי לך כן,\u0004 כי אז יפעל הרוח בכל שלמותו."],[8,"","אבל יש לשאול על התירוץ הזה, שאומר, שבקש ממנו שיוכל לפעול באותו הרוח שלו פי שנים משפעל עמו אליהו. הלא סוף סוף בקש ממנו מה שאין לו, כי כיון שאליהו לא פעל הרי לא היה לו כח הפעולה ואיך יתן כח הזה לאלישע. ואם תאמר שכל אחד יכול לפעול עם הרוח כמה שרוצה, ואינו צריך לתוספת כח עליון, א\"כ לא היה צריך כלל לבקש זה מאליהו, כיון שמעצמו היה יכול לפעול כמה שרוצה."],[8,"","ולהבין זה צריכים להעמיק יותר בפנימיות הדברים. והענין הוא, כי נודע, שבשבירת הכלים נפלו ש\"ך ניצוצין לקליפות, שמכל ספירה שבע\"ס דנקודים, נפלו שמונה מלכים: דעת חג\"ת נהי\"מ, שבכל אחד ד' בחינות חו\"ב תו\"מ, דהיינו ל\"ב בחינות מכל ספירה, ועשר פעמים ל\"ב הן ש\"ך בחינות. ורק רפ\"ח ניצוצין מהם ניתנו לבירור ולתקון במשך שתא אלפי שני, שהם רק ט\"ס ראשונות שבע\"ס דנקודים, שט' פעמים ל\"ב הם רפ\"ח, אבל ל\"ב ניצוצין שבמלכות שלהם, לא ניתנו לבירור ואסור לנגוע בהם, ונשארו מוטלים בקליפות בכל משך שתא אלפי שני דהוו עלמא, עד לגמר התקון. ולפי שכל גוף מעורב בו מל\"ב העשירי הזה, שאין לו תקנה, לכן מוכרח כל אדם למות, ובגמר התקון כשיתברר ל\"ב העשירי, אז נאמר, ובלע המות לנצח, כי כל הקליפות יתבטלו, וכל המאורות יתגלו."],[8,"","ואין לשאול, כיון שאסור לברר ולנגוע בל\"ב העשירי הזה המוטל בקליפות מזמן שבירת הכלים, א\"כ איך אפשר שיתוקן לעתיד. והאמת הוא, שאין צורך כלל לברר אותו ולתקנו, כי עם גמר בירורם ותקונם של כל רפ\"ח ניצוצין, מתתקן ל\"ב העשירי מאליו, ואינו צריך לשום בירור מיוחד."],[8,"","והנה בחינת אליהו, הוא, להביא בחינת הסיום והגמר של בירור ותקון רפ\"ח הניצוצין שעמו מתתקן תכף ל\"ב האבן, וז\"ס שאליהו בגי' ב\"ן שכל ענינו היה לתקן את שם ב\"ן, שהוא מדת המלכות ולהוציא ל\"ב העשירי מן הקליפות, וכל צדיק וצדיק יש לו תפקידו, וכשגומר תפקידו תכף נסתלק למעלה. ולפיכך אע\"פ שאליהו הוא המגלה את תקון של ל\"ב האבן, מ\"מ אינו פועל מאומה בהאורות השלמים המתגלים על ידו, כי תכף נסתלק לשמים, כי נגמר תפקידו."],[8,"","וזהו שמתרץ הזהר, \u0003איהו לא שאיל רוח על חד תרין,\u0004 דהיינו שיהיה לו ב' רוחות, אחד מבחינת רפ\"ח ניצוצין ואחד מבחינת ל\"ב האבן, כי אין לך נותן מה שאין לו, \u0003אלא הכי שאל מניה בההוא רוחא דהוה ליה, דיעביד תרין נמוסין,\u0004 כי בקש ממנו שאותו הרוח שהיה לו לאליהו, דהיינו הרוח מרפ\"ח ניציצין, יעשה פי שנים, דהיינו שאותו הרוח יגלה לו גם האורות והפעולות של ל\"ב העשירי, כי אין כלל רוח מיוחד לל\"ב העשירי, אלא הוא מתגלה עם סיום וגמר בירור של רפ\"ח ניצוצין, כנ\"ל. ואע\"פ שאליהו עצמו לא גילה האורות והפעולות של ל\"ב העשירי, אין זה נבחן שאינו ברשותו. אלא הוא משום שלא היה תפקידו אלא לגלות הבירור והתקון של ל\"ב העשירי בכללו, ואלישע ביקש ממנו שמלבד הרוח דרפ\"ח שלו, יזכה להשיג ממנו גם את תקון ל\"ב העשירי, בכללו, וממילא יוכל הוא לגלות מעצמו הפעולות והאורות \u0003פי שנים,\u0004 הן הארות הרפ\"ח, והן הארות ל\"ב האבן."],[8,"","וזה אמרו \u0003מאי טעמא אם תראה אותי,\u0004 למה תלה אליהו ההשגה של פי שנים, באם יראה אותו לוקח ממנו, ומשיב, \u0003אלא אמר ליה, אם תיכול למיקם על עקרא דרוחא דשבקנא לך בשעתא דאתנסיבנא מינך, יהא לך כדין,\u0004 כי זמן הגילוי של תקון הרוח דל\"ב העשירי, הוא ברגע האחרון של היותו בעולם הזה כי תכף אחר שגילה אותו עלה לשמים, כי נגמר תפקידו כנ\"ל, וע\"כ אמר לו אם תוכל לעמוד על עיקר הרוח, דהיינו הרוח דל\"ב האבן, שהנחתי לך בעת שאהיה לוקח ממך, דהיינו בדיוק ברגע האחרון של היותי עמך בעולם הזה, אז יהי לך כן, פי שנים. אבל אם תפסיד רגע הזה מלראות אותי, לא תשיג פי שנים, כי הרוח דל\"ב העשירי אינו מתגלה מקודם לכן. וז\"ש, \u0003דהא כל ההוא עקרא דרוחא,\u0004 דהיינו הרוח דל\"ב העשירי, \u0003בשעתא דיסתכל ביה כד חמי ליה לאליהו,\u0004 בשעה שאלישע יסתכל בו, להשיגו, בעת שראה את אליהו לוקח ממנו, \u0003יהו דבקותא ביה כדקא יאות,\u0004 יתדבק וישיג אותו כראוי. כי רק ברגע הזה שראה אותו לוקח ממנו אז שעת הגלותו, ולא מקודם לכן. כמבואר."]],[[0,"","אָמַר רַבִּי יִצְחָק, וְכֵן מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וּבְמַעֲשִׂים כְּשֵׁרִים, גּוֹרֵם לִכְנֶסֶת יִשְׂרָאֵל לְהָרִים רֹאשׁ בְּתוֹךְ הַגָּלוּת. אַשְׁרֵי חֶלְקָם שֶׁל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה יָמִים וְלֵילוֹת."],[1,"","בֹּא רְאֵה, גִּלְגֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא גִּלְגּוּלִים בָּעוֹלָם כְּדֵי לְהָרִים אֶת רֹאשׁ הַצַּדִּיקִים, שֶׁהֲרֵי כְּדֵי שֶׁיּוֹסֵף יָרִים אֶת רֹאשׁוֹ בָּעוֹלָם עַל שֶׁנִּמְצָא צַדִּיק לְפָנָיו, הִרְגִּיז אֶת הָאָדוֹן עַל עֲבָדָיו, כְּמוֹ שֶׁנֶּאֱמַר חָטְאוּ מַשְׁקֵה מֶלֶךְ מִצְרַיִם וְהָאֹפֶה לַאֲדנֵיהֶם לְמֶלֶךְ מִצְרָיִם, וְהַכֹּל כְּדֵי לְהָרִים אֶת רֹאשׁוֹ שֶׁל יוֹסֵף הַצַּדִּיק. וּבֹא וּרְאֵה, עַל יְדֵי הַחֲלוֹם נִכְנַע מֵעִם אֶחָיו, וְעַל יְדֵי הַחֲלוֹם הִתְגַּדֵּל עַל אֶחָיו, וְהִתְגַּדֵּל עַל כָּל הָעוֹלָם."],[2,"","וַיַּחְלְמוּ חֲלוֹם שְׁנֵיהֶם אִישׁ חֲלֹמוֹ בְּלַיְלָה אֶחָד אִישׁ כְּפִתְרוֹן וְגוֹ'. בֹּא רְאֵה שֶׁהִנֵּה נֶאֱמַר שֶׁכָּל הַחֲלוֹמוֹת הוֹלְכִים אַחֲרֵי הַפֶּה. כַּאֲשֶׁר יוֹסֵף פָּתַר לָהֶם אֶת הַחֲלוֹם, לָמָּה לָזֶה פָּתַח פִּתְרוֹן טוֹב, וְלָזֶה פִּתְרוֹן רַע? אֶלָּא שֶׁאוֹתָם הַחֲלוֹמוֹת הָיוּ עַל יוֹסֵף, וּמִשּׁוּם שֶׁיָּדַע הַדָּבָר עַל עִקָּרוֹ וְשָׁרְשׁוֹ, מִשּׁוּם כָּךְ פָּתַר לָהֶם הַחֲלוֹם כְּמוֹ שֶׁצָּרִיךְ, לְכָל אֶחָד וְאֶחָד פָּתַר לָהֶם פִּתְרוֹן לְהַחֲזִיר הַדָּבָר עַל מְקוֹמוֹ."],[3,"","מַה כָּתוּב? וַיֹּאמֶר אֲלֵיהֶם יוֹסֵף הֲלוֹא לֵאלֹהִים פִּתְרֹנִים סַפְּרוּ נָא לִי. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּךְ צָרִיךְ לוֹ לִפְתֹּר הַחֲלוֹם - לְהַפְקִיד אֶת הַפִּתְרוֹן לַקָּדוֹשׁ-בָּרוּךְ-הוּא, מִשּׁוּם שֶׁשָּׁם הוּא הַקִּיּוּם שֶׁל הַכֹּל וּבוֹ עוֹמֵד הַפִּתְרוֹן."],[4,"","בֹּא רְאֵה, הֲרֵי נֶאֱמַר שֶׁדַּרְגַּת הַחֲלוֹם לְמַטָּה הִיא, וְהִיא הַדַּרְגָּה הַשִּׁשִּׁית, מִשּׁוּם שֶׁהֲרֵי מִמְּקוֹם הַנְּבוּאָה הִיא שׁוֹרָה, עַד הַדַּרְגָּה הַזּוֹ שֶׁל הַחֲלוֹם, שֵׁשׁ דְּרָגוֹת הֵן, וְעוֹלֶה הַפִּתְרוֹן מִדַּרְגַּת הַחֲלוֹם לְדַרְגָּה אַחֶרֶת. הַחֲלוֹם הוּא הַדַּרְגָּה שֶׁלְּמַטָּה, וְהַפִּתְרוֹן עוֹמֵד עֲלֵיהֶם, וְהַפִּתְרוֹן עוֹמֵד בַּדִּבּוּר, וְעַל כֵּן בַּדִּבּוּר עוֹמֵד הַדָּבָר, שֶׁכָּתוּב הֲלוֹא לֵאלֹהִים פִּתְרֹנִים. הֲלוֹא לֵאלֹהִים וַדַּאי."],[5,"","בֹּא רְאֵה מַה כָּתוּב. וַיְסַפֵּר שַׂר הַמַּשְׁקִים אֶת חֲלוֹמוֹ לְיוֹסֵף וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (מלכים ב ב) וַיְהִי כְעָבְרָם וְאֵלִיָּהוּ אָמַר אֶל אֱלִישָׁע שְׁאַל מָה אֶעֱשֶׂה לָּךְ בְּטֶרֶם אֶלָּקַח מֵעִמָּךְ וַיֹּאמֶר אֱלִישָׁע וִיהִי נָא פִּי שְׁנַיִם בְּרוּחֲךְ אֵלָי. כָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁהַפָּסוּק הַזֶּה הוּא תְמִיהָה. וְאֵלִיָּהוּ אָמַר אֶל אֱלִישָׁע שְׁאַל מָה אֶעֱשֶׂה לָּךְ, וְכִי בִּרְשׁוּתוֹ זֶה עוֹמֵד? וַהֲרֵי הוּא בִּרְשׁוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא! וְעוֹד, שֶׁאֱלִישָׁע גַּם כֵּן הָיָה יוֹדֵעַ, מָה הַטַּעַם שֶׁאָמַר וִיהִי נָא פִּי שְׁנַיִם בְּרוּחֲךְ אֵלָי?"],[6,"","אֶלָּא וַדַּאי, מִי שֶׁאוֹחֵז בַּשָּׁמַיִם וָאָרֶץ וְכָל הָעוֹלָמוֹת, אֵיךְ זֶה לֹא יִהְיוּ בִּרְשׁוּתוֹ? וַדַּאי שֶׁאֵלִיָּהוּ וּשְׁאָר הַצַּדִּיקִים, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה תָמִיד אֶת רְצוֹנָם, שֶׁכָּתוּב (תהלים קמה) רְצוֹן יְרֵאָיו יַעֲשֶׂה, וְכָל שֶׁכֵּן שֶׁאוֹתָהּ רוּחַ הַקֹּדֶשׁ שֶׁעָלָיו הוֹרִישׁ לֶאֱלִישָׁע הַצַּדִּיק, שֶׁהָיָה הַשַּׁמָּשׁ שֶׁלּוֹ, וְהִנֵּה הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ (מלכים א יט) וְאֶת אֱלִישָׁע בֶּן שָׁפָט מֵאָבֵל מְחוֹלָה תִּמְשַׁח לְנָבִיא תַּחְתֶּיךְ, וְעַל כֵּן הָיָה לֶאֱלִישָׁע לָרֶשֶׁת אוֹתוֹ."],[7,"","פִּי שְׁנַיִם בְּרוּחֲךְ, מַה זֶּה פִּי שְׁנַיִם בְּרוּחֲךְ אֵלָי? וְכִי יַעֲלֶה עַל דַּעְתְּךְ שֶׁעַל אֶחָד בִּקֵּשׁ שְׁנַיִם? וּמַה שֶּׁלֹּא הָיָה בִּרְשׁוּתוֹ אֵיךְ בִּקֵּשׁ מִמֶּנּוּ? אֶלָּא הוּא לֹא בִקֵּשׁ רוּחַ עַל כָּל אֶחָד שְׁנַיִם, אֶלָּא (הוא) כָּךְ בִּקֵּשׁ מִמֶּנּוּ - בְּאוֹתָהּ הָרוּחַ שֶׁהָיְתָה לוֹ, שֶׁיַּעֲשֶׂה שְׁתֵּי הַנְהָגוֹת בָּעוֹלָם בְּאוֹתָהּ הָרוּחַ."],[8,"","מַה כָּתוּב? וַיֹּאמֶר הִקְשֵׁיתָ לִשְׁאוֹל אִם תִּרְאֶה אֹתִי לֻקָּח מֵאִתְּךְ יְהִי לְךְ כֵן וְאִם אַיִן לֹא יִהְיֶה. מָה הַטַּעַם אִם תִּרְאֶה אֹתִי? אֶלָּא אָמַר לוֹ, אִם תּוּכַל לַעֲמֹד עַל עִקַּר הָרוּחַ שֶׁהִשְׁאַרְתִּי לְךְ בְּשָׁעָה שֶׁאֶלָּקַח מִמְּךְ - יִהְיֶה לְךְ כָּזֶה, שֶׁהֲרֵי כָּל אוֹתוֹ הָעִקָּר שֶׁל הָרוּחַ בְּשָׁעָה שֶׁיִּתְבּוֹנֵן בּוֹ, כַּאֲשֶׁר יִרְאֶה אֶת אֵלִיָּהוּ, תִּהְיֶה דְבֵקוּת בּוֹ כָּרָאוּי."]]],[["תָּא חֲזֵי, הַאי מַאן דְּאִסְתַּכַּל בְּמָּה דְאוֹלִיף מֵרַבֵּיהּ, וְחָמֵי לֵיהּ בְּהַהוּא חָכְמְתָא, יָכִיל לְאִתּוֹסְפָא בְּהַהוּא רוּחָא יַתִּיר. תָּא חֲזֵי, דְהָא יוֹסֵף בְּכָל מַה דְּאִיהוּ עָבִיד, הֲוֵי חָמֵי בְּרוּחָא דְחָכְמְתָא לְהַהוּא דִיוּקְנָא דְּאֲבוֹי, הֲוָה מִסְתַּכַּל. וּבְגִין כָּךְ הֲוָה מִסְתַּיְיעָא לֵיהּ מִלְּתָא, וְאִתּוֹסְפָא לֵיהּ רוּחָא אָחֳרָא, בִּנְהִירוּ עִלָּאָה יַתִּיר.","בְּשַׁעְתָּא דְּאָמַר לֵיהּ הַהוּא רָשָׁע, וְהִנֵּה גֶּפֶן לְפָנָי, אִזְדַּעְזַע יוֹסֵף. דְּלָא הֲוָה יָדַע עַל מַה תֵּיתֵי מִלָּה, כֵּיוָן דְּאָמַר וּבַגֶּפֶן שְׁלשָׁה שָׂרִיגִים, מִיָּד אִתְעַר רוּחֵיהּ, וְאִתּוֹסַף בִּנְהִירוּ, וְאִסְתַּכַּל בְּדִיוּקְנָא דְּאֲבוֹי, כְּדֵין אִתְנְהִיר רוּחֵיהּ, וְיָדַע מִלָּה.","מַה כְּתִיב, וּבַגֶּפֶן שְׁלשָׁה שָׂרִיגִים. אָמַר יוֹסֵף, הָא וַדַּאי בְּשׂוֹרָה דְחֶדְוָה בִּשְׁלִימוּ אִיהוּ, מַאי טַעְמָא, בְּגִין דְּהַאי גֶפֶן עַל כְּנֶסֶת יִשְׂרָאֵל אִתְחֲזֵי לֵיהּ, וְאִתְבַּשַּׂר יוֹסֵף בְּהַאי. וּבַגֶּפֶן שְׁלשָׁה שָׂרִיגִים, אִלֵּין אִינוּן תְּלָתָא דַרְגִּין עִלָאִין, דְּנָפְקֵי מֵהַאי גֶפֶן, כַּהֲנֵי לֵיוָאֵי וְיִשְׂרְאֵלֵי.","וְהִיא כְפוֹרַחַת עָלְתָה נִצָּהּ, דְּהָא בְגִינֵיהוֹן סָלְקָא כְּנֶסֶת יִשְׂרָאֵל, וְאִתְבָּרְכַת מֵעִם מַלְכָּא עִלָּאָה. הִבְשִׁילוּ אַשְׁכְּלוֹתֶיהָ עֲנָבִים, אִלֵּין אִינוּן צַדִּיקַיָא דְעַלְמָא, דְּאִינוּן כַּעֲנָבִים מְבוּשָׁלִים כְּדְקָא חָזֵי. דָּבָר אַחֵר הִבְשִׁילוּ אַשְׁכְּלוֹתֶיהָ עֲנָבִים, דָּא הוּא יַיִן דְּאִתְנְטִיר בְּעִנְבַיְיהוּ מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית.","עַד הָכָא אִתְבַּשַּׂר יוֹסֵף בְּחֶלְמֵיהּ, מִכָּאן וּלְהָלְאָה חֶלְמָא אִיהוּ דִילֵיהּ, בְּגִין דְּאִית חֶלְמִין לֵיהּ, וּלְאַחֲרָנִין. וָאֶקַח אֶת הָעֲנָבִים, דְּאִיהוּ לֵיהּ לְגַרְמֵיהּ.","תָּנִינָן, (שמות קמד א) הַאי מַאן דְּחָמֵי עִנְבִין חִוָּורִין בְּחֶלְמָא, סִימָן יָפֶה לוֹ, אוּכָמֵי לָא. מַאי טַעְמָא, בְּגִין דְּאִיהוּ רָזָא דִתְרֵין דַּרְגִּין יְדִיעָן, אִינוּן אוּכָמֵי וְחִוָּורֵי. הַאי אִיהוּ טַב, וְהַאי אִיהוּ דְּלָא טַב, וְכֻלְּהוּ עִנְבִין בְּרָזָא דִמְהֵימְנוּתָא תַּלְיָין. וְעַל דָּא מִתְפַּרְשָׁן בְּחָכְמְתָא, הֵן לְטַב, הֵן לְבִישׁ. אִלֵּין צְרִיכִין רַחֲמֵי, וְאִלֵּין אַשְׁגָּחוּתָא דְרַחֲמֵי.","תָּא חֲזֵי, אָדָם הָרִאשׁוֹן, אִנְתְּתֵיהּ סָחֲטָא לֵיהּ עִנְבִין, וְגָרִימַת לֵיהּ מוֹתָא, וּלְכָל יִשְׂרָאֵל, וּלְכָל עַלְמָא. נֹחַ אֲתָא לְהַנֵּי עִנְבִין, וְלָא אִתְנְטַר כְּדְקָא יְאוּת, מַה כְּתִיב, (בראשיתט) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגָּל בְּתוֹךְ אָהֳלֹה, בְּהֵ\"א. בְּנֵי אַהֲרֹן, שָׁתוּ חַמְרָא מִנַּיְיהוּ, וְקָרִיבוּ קָרְבָּנָא בְּהַהוּא חַמְרָא, וּמִיתוּ, וְהָא אִתְּמָר. וּבְגִין כָּךְ כְּתִיב, (דברים ל״ב:ל״ב) עֲנָבֵימוֹ עִנְבֵי רֹאשׁ אַשְׁכְּלוֹת מְרוֹרוֹת לָמּוֹ, בְּגִין דְּאִינוּן עִנְבִין גָּרְמֵי הַאי.","חָמָא עִנְבִין דְּאִינוּן טָבִין, בְּהַהוּא כֶּרֶם, דְּקָא סָלְקִין נַיְיחָא וְרֵיחָא בְּדַרְגִּין שְׁלֵימִין, כְּדְקָא יְאוּת. וְעַל דָּא יוֹסֵף יָדַע מִלָּה, וְאִסְתַּכַּל בְּעִקָּרָא, וּפָשַׁר חֶלְמָא עַל בּוּרְיֵיהּ. בְּגִין דְּאִתְבַּשַּׂר בְּהַהוּא חֶלְמָא, כְּדְקָא יְאוּת. וּבְגִין כָּךְ פָּשַׁר פִּשְׁרָא לְטַב, וְאִתְקְיַּים הָכִי.","מַה כְּתִיב. וַיַּרְא שַׂר הָאוֹפִים כִּי טוֹב פָּתָר וַיֹּאמֶר אֶל יוֹסֵף אַף אֲנִי בַּחֲלוֹמִי וְהִנִּה שְׁלשָׁה סַלֵּי חֹרִי עַל רֹאשִׁי. תָּא חֲזֵי, אֲרוּרִין אִינוּן רַשִּׁיעַיָא, דְּכָל עוֹבָדֵיהוֹן כֻּלְּהוֹן לְבִישׁ. וְכָל אִינוּן מִלִּין דְאִינוּן אָמְרִין, כֻּלְּהוּ לְבִישׁ, וּלְאַבְאָשָׁא.","כֵּיוָן דְּפָתַח פּוּמֵיהּ בְּאַף, מִיָּד דָּחִיל יוֹסֵף, וְיָדַע דְּכָל מִלּוֹי אִינוּן לְאַבְאָשָׁא, וּבְשׂוֹרָה דְּבִישׁ בְּפוּמֵיהּ. וְהִנִּה שְׁלשָׁה סַלֵּי חֹרִי עַל רֹאשִׁי, כְּדֵין יָדַע יוֹסֵף דְּאִתְבַּשַּׂר עַל חֲרִיבוּ דְּבֵי מַקְדְּשָׁא, וְיִשְׂרָאֵל בְּגָלוּתָא, דְּיִתְגָּלוּן מֵאַרְעָא קַדִּישָׁא.","חָמֵי מַה כְּתִיב, וּבַסַּל הָעֶלְיוֹן מִכָּל מַאֲכַל פַּרְעֹה מַעֲשֵׂה אוֹפֶה וְהָעוֹף אוֹכֵל אוֹתָם מִן הַסַּל מֵעַל רֹאשִׁי. אִלֵּין אִינוּן שְׁאָר עַמִין, דְּמִתְכַּנְשֵׁי עֲלַיְיהוּ דְיִשְׂרָאֵל, וְקָטְלֵי לוֹן, וְחָרְבֵי בֵיתַיְיהוּ, וּמְפַזְּרֵי לוֹן לְאַרְבַּע סִטְרֵי דְעַלְמָא. וְכֹלָּא אִסְתַּכַּל יוֹסֵף, וְיָדַע דְּהַהוּא חֶלְמָא עַל יִשְׂרָאֵל, כַּד יְהוֹן בְּחִיּוּבָא קַמֵּי מַלְכָּא, מִיָּד פָּשַׁר לֵיהּ פִּשְׁרָא לְבִישׁ, וְאִתְקְיַּים בֵּיהּ."],[[0,"תא חזי האי וכו':","בוא וראה, מי שמסתכל במה שלמד מרבו, ורואה אותו עם החכמה ההוא שלמד ממנו, יכול להתוסף יותר ברוח ההוא."],[0,"תא חזי דהא וכו':","בוא וראה, כי יוסף, בכל מה שהיה עושה היה רואה ברוח החכמה את צורתו של אביו, ועל כן הצליח בדבר, ונתוסף לו רוח אחר בהארה עליונה יותר, פירוש. כי יעקב האיר רק חסדים מכוסים, בהיותו מבחי' מחזה ולמעלה דז\"א, אבל יוסף האיר, בחסדים מגולים בהארת חכמה, להיותו קו האמצעי שמחזה ולמטה דז\"א. הרי שהאיר יותר מיעקב אביו."],[1,"בשעתא דאמר וכו':","בשעה שאמר לו אותו רשע \u0003והנה גפן לפני,\u0004 נזדעזע יוסף, כי לא ידע על מה סובב הדבר, פירוש. שהיה חושש שהמדובר היא בגפן דס\"א, הנמשך משמאל שאינו מיוחד בימין ע\"י קו אמצעי. כיון שאמר \u0003ובגפן שלשה שריגים,\u0004 שפירושו שהשמאל מיוחד בימין ע\"י קו אמצעי, מיד נתעורר רוחו, ונתוסף בהארה, והסתכל בצורתו של אביו, שה\"ס קו אמצעי, אז האיר רוחו וידע הדבר."],[2,"מה כתיב, ובגפן שלשה שריגים:","אמר יוסף, זה ודאי בשורה משמחת הוא בשלימות. מה הטעם. הוא משום, שגפן זה, נראה לו על כנסת ישראל. שהיא הנוקבא, ונתבשר יוסף בזה, שהגיע זמנה לשליטה, \u0003ובגפן שלשה שריגים,\u0004 אלו הם שלשה מדרגות עליונות היוצאות מגפן הזה, כהנים לוים ישראלים, שהם, חסד גבורה ת\"ת דז\"א, המאירים בנוקבא בעת שלמותה."],[3,"והיא כפורחת עלתה נצה:","כי בשבילם עולה כנסת ישראל, לז\"א, ומתברכת מן מלך העליון, שהוא ז\"א. \u0003הבשילו אשכלותיה ענבים,\u0004 אלו הם צדיקי העולם, שהם כענבים בשלים כראוי. דבר אחר. \u0003הבשילו אשכלותיה ענבים,\u0004 זהו יין המשומר בענביו מששת ימי בראשית. פירוש, ה\"ס מוחין השלמים שמקבלת מו\"ק הגדולים דז\"א ששמשו בימי בראשית לפני החטא דעצה\"ד, שהם משומרים מכל אחיזה לקליפות מטעם שעוד לא נסחט היין, כלומר שמוחין הללו עוד לא נגלו לחוץ, ועודו בתוך ענביו, ע\"כ לא יוכלו הקליפות להתאחז בו. וכבר ידעת שמוחין דהארת השמאל דבינה מכונה יין. והמשכתו ממעלה למטה, שה\"ס החטא דעץ הדעת, מכונה סחיטה. וז\"ס שאמרו בעצה\"ד, שחוה סחטה ענבים ונתנה לו, כמ\"ש לפנינו."],[4,"עד הכא אתבשר וכו':","עד כאן נתבשר יוסף בחלומו, דשר המשקים, מכאן ולהלאה החלום היא שלו, לשר המשקים עצמו, כי יש חלומות שהם לו ולאחרים, כלומר, שמקצתם מורים לעתידות של החולם, ומקצתם לעתידות של אחרים, \u0003ואקח את הענבים,\u0004 הוא לו לעצמו, ולא בשביל יוסף."],[5,"תנינן האי מאן וכו':","למדנו, מי שראה ענבים לבנים בחלום סימן יפה לו. ענבים שחורים, לא. אינם סימן יפה. מהו הטעם. הוא משום, שה\"ס שתי מדרגות ידועות, שהם שחור ולבן, שזה טוב וזה אינו טוב. כי לבן יורה שהוא רחמים, ושחור על דין. וכל הענבים, בין לבן ובין שחור, תלוים בסוד האמונה, שהיא הנוקבא, שמלכות דמדת הדין ה\"ס שחור, ומלכות הממותקת בבינה ה\"ס לבן, וע\"כ מתבארים בחכמה הן לטוב והן לרע, אלו, השחורים, מורים שהם צריכים רחמים, שהם צריכים להתמתק במדת הרחמים שהיא בינה, ואלו, הלבנים מורים שהם השגחה של רחמים. כי כבר נתמתקה המלכות בבינה, ונעשתה רחמים."],[6,"ת\"ח אדם הראשון וכו':","בוא וראה \u0003אדם הראשון,\u0004 אשתו סחטה לו ענבים וגרמה לו מות, ולכל ישראל, ולכל העולם. \u0003נח,\u0004 בא לענבים האלו ולא נשמר כראוי, מה כתוב, וישת מן היין וישכר ויתגל בתוך אהלה, שכתוב, \u0003אהלה\u0004 ב \u0003ה'\u0004 ולא אהלו ב \u0003ו',\u0004 (עי' לעיל פרשת נח דף ק\"ח אות ש\"ח, ובהסולם שם, שכל המאמר הזה נתבאר שם באורך, ע\"ש שאין להכפיל דברים). \u0003בני אהרן,\u0004 שתו יין מהם, מן הענבים, והקריבו קרבן עם יין ההוא, ומתו. וכבר נתבאר. וע\"כ כתיב ענבימו ענבי ראש אשכלות מרורות למו. משום שהענבים גרמו לכל זה הנ\"ל."],[7,"חמא ענבין דאינון וכו':","שר המשקים ראה בחלומו, ענבים שהם טובים, דהיינו ענבים לבנים הנ\"ל. באותו הכרם, שהם מעלים שם נחת וריח במדרגות שלמות כראוי. פירוש. \u0003ענבים\u0004 הם מדרגות הנוקבא כנ\"ל. \u0003כרם\u0004 ה\"ס הנוקבא עצמה. ובעת שהיא ממותקת בבינה, הענבים שלה לבנים, ומעלים נחת וריח וכו'."],[7,"וע\"ד יוסף ידע וכו':","וע\"כ, יוסף ידע הדבר, והסתכל בשורש הדברים, ופתר החלום על בוריו, משום שנתבשר בחלום הזה כראוי להיות, וע\"כ פתר פתרון לטוב, ונתקיים כן."],[8,"מה כתיב, וירא שר האופים וגו':","בוא וראה ארורים הם הרשעים, שכל מעשיהם כולם לרע, וכל הדבורים שהם אומרים כולם לרע ולהרע."],[9,"כיון דפתח פומיה וכו':","כיון שפתח פיו ב \u0003אף,\u0004 דהיינו \u0003אף\u0004 אני בחלומי, מיד פחד יוסף, וידע שכל דבריו הם להרע, ובשורה רעה בפיו. \u0003והנה שלשה סלי חרי על ראשי,\u0004 בזה ידע יוסף, שנתבשר על חורבן בית המקדש, וגלות ישראל, שיגלו מארץ הקדושה."],[10,"חמי מה כתיב:","ראה מה שכתוב, \u0003ובסל העליון\u0004 וגו' \u0003והעוף אוכל\u0004 אותם מן הסל מעל ראשי. אלו הם שאר העמים, שמתאספים על ישראל והורגים אותם, ומחריבים ביתם, ומפזרים אותם לארבע רוחות העולם."],[10,"וכלא אסתכל וכו':","והכל נסתכל יוסף, וידע שחלום ההוא יורה על ישראל, כשידונו לחוב לפני המלך, מיד פתר לו פתרון לרע, ונתקיים בו."]],[[0,"","בֹּא רְאֵה, מִי שֶׁמִּסְתַּכֵּל בְּמַה שֶּׁלּוֹמֵד מֵרַבּוֹ וְרוֹאֶה אוֹתוֹ בְּאוֹתָהּ הַחָכְמָה, יָכוֹל לְהִתּוֹסֵף יוֹתֵר בְּאוֹתָהּ הָרוּחַ. בֹּא רְאֵה, שֶׁהֲרֵי יוֹסֵף בְּכָל מַה שֶּׁעָשָׂה הָיָה רוֹאֶה בָּרוּחַ שֶׁל הַחָכְמָה אֶת אוֹתָהּ הַדְּמוּת שֶׁל אָבִיו. הָיָה מִתְבּוֹנֵן, וּמִשּׁוּם כָּךְ הָיָה הַדָּבָר מִסְתַּיֵּעַ לוֹ, וְנוֹסְפָה לוֹ רוּחַ אַחֶרֶת בְּאוֹר יוֹתֵר עֶלְיוֹן."],[1,"","בְּשָׁעָה שֶׁאָמַר לוֹ אוֹתוֹ הָרָשָׁע וְהִנֵּה גֶפֶן לְפָנָי, הִזְדַּעֲזַע יוֹסֵף, שֶׁלֹּא הָיָה יוֹדֵעַ עַל מַה יָּבֹא הַדָּבָר. כֵּיוָן שֶׁאָמַר וּבַגֶּפֶן שְׁלֹשָׁה שָׂרִיגִם, מִיָּד הִתְעוֹרְרָה רוּחוֹ וְנוֹסַף בְּאוֹר, וְהִסְתַּכֵּל בִּדְמוּת אָבִיו, וְאָז הֵאִירָה רוּחוֹ וְיָדַע אֶת הַדָּבָר."],[2,"","מַה כָּתוּב? וּבַגֶּפֶן שְׁלֹשָׁה שָׂרִיגִם. אָמַר יוֹסֵף, הִנֵּה וַדַּאי בְּשׂוֹרָה שֶׁל שִׂמְחָה בִּשְׁלֵמוּת הִיא. מָה הַטַּעַם? מִשּׁוּם שֶׁהַגֶּפֶן הַזּוֹ נִרְאֵית עַל כְּנֶסֶת יִשְׂרָאֵל, וְהִתְבַּשֵּׂר יוֹסֵף עַל זֶה. וּבַגֶּפֶן שְׁלֹשָׁה שָׂרִיגִם - אֵלּוּ הֵם שָׁלֹשׁ דְּרָגוֹת עֶלְיוֹנוֹת שֶׁיּוֹצְאוֹת מִן הַגֶּפֶן הַזּוֹ, כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים."],[3,"","וְהִיא כְפֹרַחַת עָלְתָה נִצָּהּ, שֶׁהֲרֵי בִּגְלָלָם עוֹלָה כְּנֶסֶת יִשְׂרָאֵל וּמִתְבָּרֶכֶת מֵעִם הַמֶּלֶךְ הָעֶלְיוֹן. הִבְשִׁילוּ אַשְׁכְּלֹתֶיהָ עֲנָבִים - אֵלּוּ הַצַּדִּיקִים שֶׁל הָעוֹלָם, שֶׁהֵם כְּמוֹ עֲנָבִים מְבֻשָּׁלִים כָּרָאוּי. דָּבָר אַחֵר הִבְשִׁילוּ אַשְׁכְּלֹתֶיהָ עֲנָבִים - זֶהוּ הַיַּיִן הַמְשֻׁמָּר בַּעֲנָבָיו מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית."],[4,"","עַד כָּאן הִתְבַּשֵּׂר יוֹסֵף בַּחֲלוֹמוֹ, מִכָּאן וָהָלְאָה הַחֲלוֹם הוּא שֶׁלּוֹ, מִשּׁוּם שֶׁיֵּשׁ לוֹ חֲלוֹמוֹת, וְלַאֲחֵרִים. וָאֶקַּח אֶת הָעֲנָבִים, שֶׁהוּא לוֹ, לְעַצְמוֹ."],[5,"","שָׁנִינוּ, מִי שֶׁרוֹאֶה עֲנָבִים לְבָנִים בַּחֲלוֹם, סִימָן יָפֶה לוֹ. שְׁחוֹרִים - לֹא. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא הַסּוֹד שֶׁל שְׁתֵּי דְרָגוֹת יְדוּעוֹת, אוֹתָם שְׁחוֹרִים וּלְבָנִים. זֶה הוּא טוֹב, וְזֶה הוּא לֹא טוֹב, וְכָל הָעֲנָבִים תְּלוּיִים בְּסוֹד הָאֱמוּנָה, וְעַל כֵּן נִפְרָדִים בְּחָכְמָה, הֵן לְטוֹב הֵן לְרַע. אֵלּוּ צְרִיכִים רַחֲמִים, וְאֵלּוּ הַשְׁגָּחָה שֶׁל רַחֲמִים."],[6,"","בֹּא רְאֵה, אָדָם הָרִאשׁוֹן, אִשְׁתּוֹ סָחֲטָה לוֹ עֲנָבִים וְגָרְמָה לוֹ מָוֶת וּלְכָל יִשְׂרָאֵל וּלְכָל הָעוֹלָם. נֹחַ בָּא לָעֲנָבִים הַלָּלוּ, וְלֹא נִשְׁמַר כָּרָאוּי, מַה כָּתוּב? (בראשית ט) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה, בְּהֵ\"א. בְּנֵי אַהֲרֹן שָׁתוּ יַיִן מֵהֶם, וְהִקְרִיבוּ קָרְבָּן בְּאוֹתוֹ הַיַּיִן וּמֵתוּ, וַהֲרֵי נִתְבָּאֵר. וּמִשּׁוּם כָּךְ כָּתוּב (דברים לב) עֲנָבֵמוֹ עִנְּבֵי רוֹשׁ אַשְׁכְּלֹת מְרֹרֹת לָמוֹ, מִשּׁוּם שֶׁאוֹתָם הָעֲנָבִים גָּרְמוּ אֶת זֶה."],[7,"","רָאָה עֲנָבִים שֶׁהֵם טוֹבִים בְּאוֹתוֹ הַכֶּרֶם שֶׁמַּעֲלִים נַחַת וְרֵיחַ בִּדְרָגוֹת שְׁלֵמוֹת כָּרָאוּי. וְעַל זֶה יוֹסֵף יָדַע אֶת הַדָּבָר וְהִסְתַּכֵּל בָּעִקָּר וּפָתַר הַחֲלוֹם עַל בֻּרְיוֹ, מִשּׁוּם שֶׁהִתְבַּשֵּׂר בְּאוֹתוֹ הַחֲלוֹם כָּרָאוּי, וּמִשּׁוּם כָּךְ פָּתַר הַפִּתְרוֹן לְטוֹב וְכָךְ הִתְקַיֵּם."],[8,"","מַה כָּתוּב? וַיַּרְא שַׂר הָאֹפִים כִּי טוֹב פָּתָר וַיֹּאמֶר אֶל יוֹסֵף אַף אֲנִי בַּחֲלוֹמִי וְהִנֵּה שְׁלֹשָׁה סַלֵּי חֹרִי עַל רֹאשִׁי. בֹּא רְאֵה, אֲרוּרִים הֵם הָרְשָׁעִים, שֶׁכָּל מַעֲשֵׂיהֶם כֻּלָּם לְרַע, וְכָל אוֹתָם הַדְּבָרִים שֶׁהֵם אוֹמְרִים, כֻּלָּם לְרַע וּלְהָרַע."],[9,"","כֵּיוָן שֶׁפָּתַח אֶת פִּיו בְּאַף, מִיָּד פָּחַד יוֹסֵף, וְיָדַע שֶׁכָּל דְּבָרָיו הֵם לְהָרַע וּבְשׂוֹרָה שֶׁל רַע בְּפִיו. וְהִנֵּה שְׁלֹשָׁה סַלֵּי חֹרִי עַל רֹאשִׁי. אָז יָדַע יוֹסֵף שֶׁהִתְבַּשֵּׂר עַל חֻרְבַּן בֵּית הַמִּקְדָּשׁ, וְיִשְׂרָאֵל בַּגָּלוּת, שֶׁיִּגְלוּ מִן הָאָרֶץ הַקְּדוֹשָׁה."],[10,"","רְאֵה מַה כָּתוּב, וּבַסַּל הָעֶלְיוֹן מִכֹּל מַאֲכַל פַּרְעֹה מַעֲשֵׂה אֹפֶה וְהָעוֹף אֹכֵל אֹתָם מִן הַסַּל מֵעַל רֹאשִׁי. אֵלּוּ הֵם שְׁאָר הָעַמִּים שֶׁמִּתְכַּנְּסִים עַל יִשְׂראֵל וְהוֹרְגִים אוֹתָם וּמַחֲרִיבִים בֵּיתָם וּמְפַזְּרִים אוֹתָם לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. וְהַכֹּל הִסְתַּכֵּל יוֹסֵף, וְיָדַע שֶׁאוֹתוֹ הַחֲלוֹם עַל יִשְׂרָאֵל כְּשֶׁיִּהְיוּ בְּחִיּוּב לִפְנֵי הַמֶּלֶךְ. מִיָּד פָּתַר לוֹ פִּתְרוֹן לְרַע, וְהִתְקַיֵּם בּוֹ."]]],[["וְתָּא חֲזֵי, תְּרֵין דַּרְגִּין אִלֵּין, דְּקָא חָמָא הַאי, וְחָמָא הַאי. דָּא חָמָא (דהא) כַּד סָלִיק, וְקָא שַׁלִּיט דַּרְגָּא עִלָּאָה, וְאִתְנְהִיר סִהֲרָא. וְדָא חָמָא, דְּאִתְחַשַּׁךְ וְשַׁלִּיט עֲלָהּ חִיוְיָא בִישָׁא. וּבְגִין כָּךְ אִסְתַּכַּל יוֹסֵף בְּהַהוּא חֶלְמָא, וּפָשַׁר לֵיהּ פִּשְׁרָא לְבִישׁ. וְעַל דָּא, כֹּלָּא בְּפִישְׁרָא קָיְימָא, וְדָא וְדָא חָמוּ, בְּאִלֵּין תְּרֵין דַּרְגִּין, דְּשַׁלִּיט דָּא, וְשַׁלִּיט דָּא.","רִבִּי יְהוּדָה פָּתַח, (תהילים נ״א:י״ב) לֵב טָהוֹר בְּרָא לִי אֱלהִים וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי, הַאי קְרָא אוּקְמוּהָ, אֲבָל לֵב טָהוֹר, כְּמָה דְאַתְּ אָמֵר, (מלכים א ג׳:ט׳) וְנָתַתָּ לְעַבְדְּךָ לֵב שׁוֹמֵעַ וְגו', וּכְתִיב (משלי ט״ו:ט״ו) וְטוֹב לֵב מִשְׁתֶּה תָּמִיד, וּבְגִין כָּךְ לֵב טָהוֹר וַדַּאי.","וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי, דָּא הוּא רוּחַ נָכוֹן וַדַּאי. כְּמָה דְאַתְּ אָמֵר, (בראשית א׳:ב׳) וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנִי הַמָּיִם. וְאִתְעָרוּ, זֶה רוּחוֹ שֶׁל מָשִׁיחַ. וְאִתְעָרוּ, (יחזקאל י״א:י״ט) וְרוּחַ חֲדָשָׁה אֶתֵּן בְּקִרְבְּכֶם. וְצַלֵּי דָוִד, הַהוּא רוּחַ נָכוֹן, חַדֵּשׁ בְּקִרְבִּי.","בְּגִין דְּאִית מִסִּטְרָא אָחֳרָא, לֵב טָמֵא וְרוּחַ עִוְעִים, דְּאַסְטֵי לִבְנֵי עַלְמָא, וְדָא הוּא רוּחַ טוּמְאָה, דְּאִקְרֵי רוּחַ עִוְעִים. כְּמָה דְאַתְּ אָמֵר, (ישעיהו י״ט:י״ד) יְיָ מָסַךְ בְּקִרְבָּהּ רוּחַ עִוְעִים. וְעַל דָּא וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי. מַאי חָדֵּשׁ. דָּא חִדּוּשָׁא דְּסִיהֲרָא. בְּשַׁעְתָּא דְּאִתְחַדַּשׁ סִיהֲרָא, דָּוִד מֶלֶךְ יִשְׂרָאֵל חַי וְקַיָּים וּבְגִין כָּךְ חָדֵּשׁ.","רִבִּי אֶלְעָזָר וְרִבִּי יוֹסֵי הֲווּ אָזְלֵי בְאָרְחָא. אָמַר רִבִּי יוֹסֵי לְרִבִּי אֶלְעָזָר, הַאי דִּכְתִיב, (מלכים א כ״ב:כ״א-כ״ב) וַיֵּצֵא הָרוּחַ וַיַּעֲמֹד לִפְנֵי יְיָ וַיֹּאמֶר אֲנִי אֲפַתֶּנּוּ וַיֹּאמֶר יְיָ אֵלָיו בְּמָּה וַיֹּאמֶר אֵצֵא וְהָיִיתִי רוּחַ שֶׁקֶר בְּפִי כָּל נְבִיאָיו וַיֹּאמֶר תְּפַתֶּה וְגַם תּוּכָל צֵא וַעֲשֵׂה כֵן. וְתָנִינָן דְּהֲוָה רוּחַ נָבוֹת הַיִּזְרְעֵאלִי. וְכִי נִשְׁמָתִין, כֵּיוָן דְּסָלְקִין וְקָיְימִין לְעֵילָא, אִינוּן יָכְלִין לְאֲתָבָא בְּהַאי עַלְמָא, וּמִלָּה תְּמִיהָה, דְּאָמַר אֵצֵא וְהָיִיתִי רוּחַ שֶׁקֶר בְּפִי וְגו'.","וְתוּ, מַאי טַעְמָא אִתְעֲנַשׁ עֲלֵיהּ אַחְאָב, דְּהָא דִינָא דְאוֹרַיְיתָא, דְּשַׁוֵּי שְׁמוּאֵל קַמַּיְיהוּ דְיִשְׂרָאֵל, הָכִי הוּא. דִּכְתִיב, (שמואל א ח׳:י״ד) אֶת שְׂדוֹתֵיכֶם וְכַרְמֵיכֶם וְזֵיתֵיכֶם הַטּוֹבִים יִקָּח. וְאִי אַחְאָב נָטַל הַהוּא כֶּרְם בְּנָבוֹת, דִּינָא הֲוָה. וְתוּ, דְּהֲוָה יָהִיב לֵיהּ כַּרְמָא אָחֳרָא, אוֹ דַּהֲבָא, וְלָא בָעָא.","אָמַר לֵיהּ, יָאוֹת שְׁאַלְתְּ. תָּא חֲזֵי, הַאי רוּחַ דְּקָאֲמְרוּ דְאִיהוּ רוּחַ דְּנָבוֹת, הָכָא אִית לְאִסְתַּכָּלָא. וְכִי רוּחָא דְנָבוֹת יָכִיל לְסַלְּקָא וּלְקַיְּימָא קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, לְמִתְבַּע שִׁקְרָא. דִּכְתִיב וַיֵּצֵא הָרוּחַ. וְאִי צַדִּיקָא הוּא, אֵיךְ יִבָּעֵי שִׁקְרָא בְּהַהוּא עַלְמָא, דְּאִיהוּ עַלְמָא דִקְשׁוֹט. וּמַה בְּהַאי עַלְמָא, לָא בָעֵי זַכָּאָה שִׁקְרָא, בְּהַהוּא עַלְמָא, לָא כָל שֶׁכֵּן. וְאִי לָאו זַכָּאָה אִיהוּ, הֵיךְ יָכִיל לְקָיְימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא.","אֶלָּא וַדַּאי נָבוֹת לָאו זַכָּאָה הֲוָה כָּל כָּךְ לְקָיְימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא רוּחָא אָחֳרָא הֲוָה, דְּשָׁלְטָא בְּעַלְמָא. דְּדָא הוּא רוּחָא דְּקָיְימָא תָּדִיר וְסָלְקָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וְדָא הוּא דְאַסְטֵי לִבְנִי עַלְמָא בְּשִׁקְרָא. וּמַאן דְּאִיהוּ רָגִיל בְּשִׁקְרָא, אִשְׁתַּדַּל תָּדִיר בְּשִׁקְרָא. וְעַל דָּא אָמַר אֵצֵא וְהָיִיתִי רוּחַ שֶׁקֶר וְגו'. וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ, צֵא וַעֲשֵׂה כֵן. פּוּק מֵהָכָא, כְּמָה דְאוּקְמוּהָ דִּכְתִיב, (תהילים ק״א:ז׳) דּוֹבֵר שְׁקָרִים לא יִכּוֹן לְנֶגֶד עֵינָי. וּבְגִין דָּא אִיהוּ רוּחַ שֶׁקֶר וַדַּאי.","וְתוּ, עַל מַה דְּקָטַל לֵיהּ לְנָבוֹת וְנָטַל כַּרְמָא דִילֵיהּ, קָטוּלָא אַמַּאי קָטִיל לֵיהּ. אֶלָּא עַל דְּקָטִיל לֵיהּ בְּלָא דִינָא, אִתְעַנַּשׁ. קָטַל לֵיהּ בְּלָא דִינָא, וְנָסִיב כַּרְמָא דִילֵיהּ. וּבְגִין כָּךְ כְּתִיב, (מלכים א כ״א:י״ט) הֲרָצַחְתָּ וְגַם יָרַשְׁתָּ, וְעַל דָּא אִתְעַנַּשׁ. וְתָּא חֲזֵי, כַּמָּה אִינוּן בְּנֵי נָשָׁא בְּעַלְמָא, דְאַסְטֵי לוֹן הַאי רוּחַ שִׁקְרָא בְּשִׁקְרָא. וְשַׁלִּיט אִיהוּ בְּעַלְמָא בְּכַמָּה סִטְרִין וּבְכַמָּה עוֹבָדִין, וְהָא אוֹקִימְנָא מִלֵּי.","וְעַל דָּא דָּוִד מַלְכָּא בָּעָא לְאִסְתַּמְרָא מִנֵּיהּ, ובָעָא לְאֲפָקָא מִגּוֹ מְסָאֲבוּ. דִּכְתִיב, (תהילים נ״א:י״ב) לֵב טָהוֹר בְּרָא לִי אֱלֹהִים וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי. דָּא הוּא רוּחַ נָכוֹן, וְאָחֳרָא אִיהוּ רוּחַ שֶׁקֶר. וְעַל דָּא תְּרֵין דַּרְגִּין אִינוּן, חַד קַדִּישָׁא, וְחַד מְסָאֲבָא.","פָּתַח וְאֲמַר, (יואל ב׳:י״א) וַיְיָ נָתַן קוֹלוֹ לִפְנֵי חֵילוֹ כִּי רַב מְאֹד מַחֲנִהוּ וְכִי עָצוּם עוֹשֵׂה דְבָרוֹ וְגו', הַאי קְרָא אוּקְמוּהָ. אֲבָל וַיְיָ, בְּכָל אֲתַר הוּא וּבֵי דִינֵיהּ. נָתַן קוֹלוֹ, דָּא הוּא קָלָא דִּכְתִיב, (דברים ד׳:י״ב) קוֹל דְּבָרִים. וּכְתִיב הָתָם, (שמות ד׳:י׳) לֹא אִישׁ דְּבָרִים. מַאן אִישׁ דְּבָרִים. כְּמָה דְאַתְּ אָמֵר, (דברים ל״ג:א׳) אִישׁ הָאֱלֹהִים. לִפְנֵי חֵילוֹ, אִלֵּין אִינוּן יִשְׂרָאֵל."],[[0,"ות\"ח תרין דרגין וכו':","ובוא וראה, שתי מדרגות היו מה שראה זה וראה זה, זה ראה, היינו שר המשקים, כשעולה ושולטת מדרגה עליונה, ז\"א, והאירה הלבנה. הנוקבא. וזה ראה, היינו שר האופים, שנחשך ושולט עליה, על הנוקבא, נחש הרע, וע\"כ נסתכל יוסף בחלום ההוא ופתר לו פתרון לרע, וע\"כ הכל תלוי בפתרון. וזה וזה ראו באלו ב' המדרגות השולטים על הנוקבא, שדם ז\"א או נחש הרע כנ\"ל, שזה שולט, ז\"א, וזה שולט, הנחש הרע."],[1,"ר' יהודה פתח וכו':","ר\"י פתח, לב טהור ברא לי אלקים ורוח נכון חדש בקרבי. מקרא זה בארוהו. אבל \u0003לב טהור,\u0004 הוא כמש\"א, ונתת לעבדך לב שומע וגו', וכתוב, וטוב לב משתה תמיד, ובשביל זה הוא ודאי לב טהור."],[2,"ורוח נכון חדש בקרבי:","זה הוא ודאי רוח נכון, כמו שאומר הכתוב, ורוח אלקים מרחפת על פני המים, והעירו, שזהו רוחו של משיח. והעירו, שעל רוח הזה אומה\"כ, ורוח חדשה אתן בקרבכם. והתפלל דוד, אותו רוח נכון, דהיינו רוחו של משיח, חדש בקרבי."],[3,"בגין דאית מסטרא וכו':","משום שיש מצד האחר, לב טמא ורוח עועים, המסית בני העולם לחטא, וזה הוא רוח הטומאה הנקרא רוח עועים, כמש\"א, ה' מסך בקרבה רוח עועים. ועל כן בקש דוד, \u0003ורוח נכון חדש בקרבי,\u0004 שואל מהו \u0003חדש,\u0004 ומשיב, זהו התחדשות הלבנה, דהיינו התחדשות הזווג של הנוקבא עם ז\"א, שבשעה שהלבנה מתחדשת, נבחן שדוד מלך ישראל, דהיינו נוקבא, חי וקיים, דהיינו שמשגת אז מוחין דאור החיה, ועל זה אמר \u0003חדש.\u0004 דהיינו שיחדש הזווג עם ז\"א."],[4,"ר' אלעזר ור' יוסי וכו':","ר\"א ור\"י היו הולכים בדרך, א\"ר יוסי לר' אלעזר, זה שכתוב, ויצא הרוח וגו' והייתי רוח שקר בפי כל נביאיו וגו'. ולמדנו, שהיה הרוח של נבות היזרעאלי. ושואל, וכי הנשמות, אחר שעלו ועומדות למעלה, תוכלנה לשוב לעולם הזה. ודבר פלא הוא שאמר אצא והייתי רוח שקר בפי וגו'."],[5,"ותו מ\"ט אתענש וכו':","ועוד, מהו הטעם שאחאב נענש עליו. הרי דין התורה ששם שמואל לפני ישראל היה כן, שכתוב, את שדותיכם וכרמיכם וזיתיכם הטובים יקח. ואם אחאב לקח הכרם מנבות, מן הדין היה. ועוד, שאחאב היה נותן לו כרם אחר או זהב ולא רצה לקחת. ולמה נענש."],[6,"א\"ל יאות שאלת וכו':","א\"ל ר\"א יפה שאלת. בוא וראה, זה שאמרו שרוח ההוא הוא רוח של נבות, יש להסתכל כאן, וכי רוחו של נבות היה יכול לעלות ולעמוד לפני הקב\"ה לבקש ממנו שקר, שכתוב ויצא הרוח וגו' והייתי רוח שקר וגו'. ואם צדיק היה, איך יבקש שקר בעולם ההוא, שהוא עולם האמת. ומה בעולם הזה לא יבקש הצדיק שקר, בעולם ההוא לא כל שכן. ואם לא היה צדיק, איך היה יכול לעמוד לפני הקב\"ה."],[7,"אלא ודאי וכו':","אלא ודאי נבות לא היה צדיק כל כך, שיעמוד לפני הקב\"ה, אלא רוח אחר היה, השולט בעולם, שזה הוא הרוח העולה והעומד תמיד לפני הקב\"ה, דהיינו השטן, וזה הוא שמשטה לבני העולם עם שקר, שמשקר בשם הקדוש, ומי שהוא רגיל בשקר עוסק תמיד בשקר, וע\"כ אמר, אצא והייתי רוח שקר וגו', א\"ל הקב\"ה, צא ועשה כן, צא מכאן, כמו שבארוה, דובר שקרים לא יכון לנגד עיני, וע\"כ הוא רוח שקר ודאי."],[8,"ותו על מה דקטל וכו':","ועוד יש לתרץ דע\"כ נענש, משום שהרג את נבות, ואם לקח הכרם שלו. הרוג למה הרג אותו. ומשום שהרגו בלי דין ע\"כ נענש. כי הרגו כלי דין ולקח את כרמו, וע\"כ כתוב, הרצחת וגם ירשת. וע\"כ נענש. ובוא וראה כמה הם בני אדם בעולם, שרוח שקר הזה השטה אותם בשקר, והוא שולט על העולם בכמה אופנים, ובכמה מעשים. וכבר בארנו הדברים."],[9,"וע\"ד דוד מלכא וכו':","וע\"כ דוד המלך רצה להשמר ממנו, מרוח שקר, ורצה להתרחק מן הטומאה, שכתוב, לב טהור ברא לי אלקים ורוח נכון חדש בקרבי, זה הוא רוח נכון, והאחר הוא רוח שקר. וע\"כ שתי מדרגות הן, אחת קדושה שהוא רוח נכון, ואחת טמאה, שהיא רוח שקר."],[10,"פתח ואמר וה' נתן קולו וגו':","מקרא זה בארוה. אבל \u0003והויה.\u0004 בכל מקום יורה הוא, ז\"א, ובית דינו, הנוקבא. \u0003נתן קולו,\u0004 זהו הקול שכתוב. קול דברים, וכתוב שם לא איש דברים, מהו איש דברים, הוא כמו שאתה אומר, איש האלקים, \u0003לפני חילו,\u0004 אלו הם ישראל."],[10,"","פירוש, \u0003והויה,\u0004 יורה על ז\"א ונוקביה שהם בזווג בהארת השמאל ששם בית דינו דז\"א, \u0003נתן קולו,\u0004 היינו הארת ז\"א, שהוא קו אמצעי ובחינת חסדים מכוסים, הנקרא \u0003קול,\u0004 וז\"ש, \u0003דא הוא קלא דכתיב, קול דברים,\u0004 כי הנוקבא נקראת \u0003דברים,\u0004 שה\"ס חסדים מגולים בהארת חכמה, בזמן שז\"א שנקרא \u0003קול\u0004 מתחבר עמה, ואז הם נקראים שניהם \u0003קול דברים,\u0004 וז\"ש \u0003וכתיב התם איש דברים,\u0004 אשר \u0003איש\u0004 ה\"ס ז\"א, אף \u0003קול\u0004 הנאמר ב \u0003קול דברים\u0004 הוא ג\"כ ז\"א. ושואל, \u0003מהו איש דברים,\u0004 כלומר מאין לנו שאיש פירושו ז\"א, ומשיב \u0003כד\"א איש האלקים,\u0004 שנאמר על משה שה\"ס ז\"א, בעלה דמטרונותא, הנקראת אלקים, אף \u0003איש דברים,\u0004 פירושו בעלה של \u0003דברים\u0004 שהוא ז\"א."]],[[0,"","וּבֹא וּרְאֵה, שְׁתֵּי הַדְּרָגוֹת הַלָּלוּ שֶׁרָאָה זֶה וְרָאָה זֶה - זֶה רָאָה כְּשֶׁעוֹלָה וְשׁוֹלֶטֶת הַדַּרְגָּה הָעֶלְיוֹנָה וּמְאִירָה הַלְּבָנָה, וְזֶה רָאָה שֶׁנֶּחְשָׁךְ וְשׁוֹלֵט עָלֶיהָ הַנָּחָשׁ הָרַע, וּמִשּׁוּם כָּךְ הִסְתַּכֵּל יוֹסֵף בַּחֲלוֹם הַהוּא, וּפָתַר אוֹתוֹ פִּתְרוֹן לְרַע. וְעַל כֵּן הַכֹּל עוֹמֵד בְּפִתְרוֹן, וְזֶה וָזֶה רָאוּ, בִּשְׁתֵּי הַדְּרָגוֹת הַלָּלוּ, שֶׁשּׁוֹלֵט זֶה וְשׁוֹלֵט זֶה."],[1,"","רַבִּי יְהוּדָה פָּתַח, (תהלים נא) לֵב טָהוֹר בְּרָא לִי אֱלֹהִים וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, אֲבָל לֵב טָהוֹר, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ג) וְנָתַתָּ לְעַבְדְּךְ לֵב שּמֵעַ וְגוֹ', וְכָתוּב (משלי טו) וְטוֹב לֵב מִשְׁתֶּה תָּמִיד, וּמִשּׁוּם כָּךְ לֵב טָהוֹר וַדַּאי."],[2,"","וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי - זֶהוּ רוּחַ נָכוֹן וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר (בראשית א) וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, וְהִתְעוֹרְרוּ, זוֹ רוּחוֹ שֶׁל הַמָּשִׁיחַ, וְהִתְעוֹרְרוּ (יחזקאל יא) וְרוּחַ חֲדָשָׁה אֶתֵּן בְּקִרְבְּכֶם. וְדָוִד הִתְפַּלֵּל, אוֹתוֹ רוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי."],[3,"","מִשּׁוּם שֶׁיֵּשׁ מֵהַצַּד הָאַחֵר לֵב טָמֵא וְרוּחַ עִוְעִים שֶׁמַּסְטֶה אֶת בְּנֵי הָעוֹלָם, וְזוֹ הִיא רוּחַ טֻמְאָה שֶׁנִּקְרֵאת רוּחַ עִוְעִים, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה יט) ה' מָסַךְ בְּקִרְבָּהּ רוּחַ עִוְעִים, וְעַל כֵּן וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי. מַה זֶּה חַדֵּשׁ? זֶה חִדּוּשׁ הַלְּבָנָה. בְּשָׁעָה שֶׁמִּתְחַדֶּשֶׁת הַלְּבָנָה, דָּוִד מֶלֶךְ יִשְׂרָאֵל חַי וְקַיָּם, וּמִשּׁוּם כָּךְ חַדֵּשׁ."],[4,"","רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבִּי אֶלְעָזָר, זֶה שֶׁכָּתוּב (מלכים א כב) וַיֵּצֵא הָרוּחַ וַיַּעֲמֹד לִפְנֵי ה' וַיֹּאמֶר אֲנִי אֲפַתֶּנּוּ וַיֹּאמֶר ה' אֵלָיו בַּמָּה. וַיֹּאמֶר אֵצֵא וְהָיִיתִי רוּחַ שֶׁקֶר בְּפִי כָּל נְבִיאָיו וַיֹּאמֶר תְּפַתֶּה וְגַם תּוּכָל צֵא וַעֲשֵׂה כֵן. וְשָׁנִינוּ שֶׁהָיְתָה רוּחַ נָבוֹת הַיִּזְרְעֵאלִי. וְכִי הַנְּשָׁמוֹת, כֵּיוָן שֶׁעוֹלוֹת וְעוֹמְדוֹת לְמַעְלָה, הֵן יְכוֹלוֹת לָשׁוּב לָעוֹלָם הַזֶּה? וְהַדָּבָר תָּמוּהַּ שֶׁאָמַר, אֵצֵא וְהָיִיתִי רוּחַ שֶׁקֶר בְּפִי וְגוֹ'."],[5,"","וְעוֹד, מָה הַטַּעַם נֶעֱנַשׁ עָלָיו אַחְאָב? שֶׁהֲרֵי דִּין הַתּוֹרָה שֶׁשָּׂם שְׁמוּאֵל לִפְנֵי יִשְׂרָאֵל כָּךְ הוּא, שֶׁכָּתוּב (שמואל א ח) אֶת שְׂדוֹתֵיכֶם וְכַרְמֵיכֶם וְזֵיתֵיכֶם הַטּוֹבִים יִקָּח, וְאִם אַחְאָב נָטַל אוֹתָהּ כֶּרֶם בְּנָבוֹת, דִּין הָיָה! וְעוֹד, שֶׁהָיְתָה לוֹ כֶּרֶם אַחֶרֶת, אוֹ זָהָב, וְלֹא רָצָה!"],[6,"","אָמַר לוֹ, יָפֶה שָׁאַלְתָּ. בֹּא רְאֵה, הָרוּחַ הַזּוֹ שֶׁאָמְרוּ שֶׁהִיא רוּחַ שֶׁל נָבוֹת, כָּאן יֵשׁ לְהִסְתַּכֵּל - וְכִי הָרוּחַ שֶׁל נָבוֹת יְכוֹלָה לַעֲלוֹת וְלַעֲמֹד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַקֵּשׁ שֶׁקֶר, שֶׁכָּתוּב וַיֵּצֵא הָרוּחַ? וְאִם הוּא צַדִּיק, אֵיךְ יְבַקֵּשׁ שֶׁקֶר בָּעוֹלָם הַהוּא, שֶׁהוּא עוֹלָם שֶׁל אֱמֶת? וּמָה בָּעוֹלָם הַזֶּה לֹא צָרִיךְ צַדִּיק שֶׁקֶר, בָּעוֹלָם הַהוּא לֹא כָּל שֶׁכֵּן? וְאִם אֵינוֹ צַדִּיק, אֵיךְ יָכוֹל לַעֲמֹד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא?"],[7,"","אֶלָּא וַדַּאי נָבוֹת לֹא הָיָה כָּל כָּךְ צַדִּיק לַעֲמֹד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, אֶלָּא רוּחַ אַחֶרֶת הָיְתָה שֶׁשָּׁלְטָה בָּעוֹלָם, שֶׁזּוֹהִי רוּחַ שֶׁתָּמִיד עוֹמֶדֶת וְעוֹלָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזוֹהִי שֶׁמַּסְטָה אֶת בְּנֵי הָעוֹלָם לְשַׁקֵּר, וּמִי שֶׁהוּא רָגִיל בְּשֶׁקֶר, מִשְׁתַּדֵּל תָּמִיד בְּשֶׁקֶר, וְעַל זֶה אָמַר אֵצֵא וְהָיִיתִי רוּחַ שֶׁקֶר וְגוֹ', וְעַל כֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ צֵא וַעֲשֵׂה כֵן. צֵא מִכָּאן, כְּמוֹ שֶׁבֵּאֲרוּהוּ שֶׁכָּתוּב (תהלים קא) דֹּבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עֵינָי, וּמִשּׁוּם זֶה הִיא רוּחַ שֶׁקֶר וַדַּאי."],[8,"","וְעוֹד, עַל מַה שֶּׁהָרַג אֶת נָבוֹת וְנָטַל אֶת כַּרְמוֹ, לָמָּה הָרַג אוֹתוֹ הֶרֶג? אֶלָּא שֶׁהָרַג אוֹתוֹ בְּלִי דִין נֶעֱנַשׁ. הָרַג אוֹתוֹ בְּלִי דִין וְנָטַל אֶת כַּרְמוֹ, וּמִשּׁוּם כָּךְ כָּתוּב (מלכים א כא) הֲרָצַחְתָּ וְגַם יָרָשְׁתָּ, וְעַל כֵּן נֶעֱנַשׁ. וּבא וּרְאֵה כַּמָּה הֵם בְּנֵי אָדָם בָּעוֹלָם שֶׁרוּחַ הַשֶּׁקֶר הַזּוֹ מַסְטָה אוֹתָם בְּשֶׁקֶר, וְהוּא שׁוֹלֵט בָּעוֹלָם בְּכַמָּה צְדָדִים וּבְכַמָּה מַעֲשִׂים, וְהִנֵּה בֵּאַרְנוּ אֶת הַדְּבָרִים."],[9,"","וְעַל כֵּן דָּוִד הַמֶּלֶךְ בִּקֵּשׁ לְהִשָּׁמֵר מִמֶּנּוּ וְרָצָה לָצֵאת מִתּוֹךְ הַטֻּמְאָה, שֶׁכָּתוּב (תהלים נא) לֵב טָהוֹר בְּרָא לִי אֱלֹהִים וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי. זוֹ הִיא רוּחַ נָכוֹן, וְהָאַחֵר הוּא רוּחַ שֶׁקֶר. וְעַל כֵּן שְׁתֵּי דְרָגוֹת הֵן, אַחַת קְדוֹשָׁה וְאַחַת טְמֵאָה."],[10,"","פָּתַח וְאָמַר, (יואל ב) וַה' נָתַן קוֹלוֹ לִפְנֵי חֵילוֹ כִּי רַב מְאֹד מַחֲנֵהוּ כִּי עָצוּם עֹשֵׂה דְבָרוֹ וְגוֹ'. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ. אֲבָל וַה', בְּכָל מָקוֹם הוּא וּבֵית דִּינוֹ. נָתַן קוֹלוֹ - זֶהוּ הַקּוֹל שֶׁכָּתוּב (דברים ד) קוֹל דְּבָרִים. וְכָתוּב שָׁם (שמות ד) לֹא אִישׁ דְּבָרִים. מִי אִישׁ הַדְּבָרִים? כְּמוֹ שֶׁנֶּאֱמַר (דברים לג) אִישׁ הָאֱלֹהִים. לִפְנֵי חֵילוֹ - אֵלּוּ הֵם יִשְׂרָאֵל."]]],[["כִּי רַב מְאֹד מַחֲנֵהוּ, כְּמָה דְאַתְּ אָמֵר (איוב כ״ה:ג׳) הֲיֵשׁ מִסְפָּר לִגְדוּדָיו. דְּכַמָּה מְמַנָּן וּשְׁלִיחָן אִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ קָיְימֵי לְאַסְטָאָה עֲלַיְיהוּ דְיִשְׂרָאֵל (זהר חדש ל\"ג בגין לאסתאבא להו). וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא אִזְדַּמַּן קַמַּיְיהוּ דְיִשְׂרָאֵל בְּגִין לְנַטְרָא לְהוּ, וְלָא יָכִילוּ לְקַטְרְגָא לְהוּ.","כִּי עָצוּם עוֹשֵׂה דְבָרוֹ. מַאן עָצוּם, דָּא הוּא זַכָּאָה הַהוּא דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא קַדִּישָׁא יְמָמָא וְלֵילֵי. דָּבָר אַחֵר כִּי עָצוּם, דָּא הוּא מְקַטְרְגָא דְּאִשְׁתַּכַּח קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאִיהוּ תַּקִּיפָא כְּפַרְזְלָא תַּקִּיפָא כְּטִינָרָא. עוֹשֵׂה דְבָרוֹ, דְּנָטִיל רְשׁוּת מִלְּעֵילָא וְנָטִיל נִשְׁמָתָא מִתַּתָּא.","כִּי גָדוֹל יוֹם יְיָ וְנוֹרָא מְאֹד וּמִי יְכִילֶנּוּ. דְּאִיהוּ שַׁלִּיט עַל כֹּלָּא, וְעִלָּאָה וְתַקִּיפָא עַל כֻּלְּהוּ, וְכֻלְּהוּ תְּחוֹת שָׁלְטָנֵיהּ. זַכָּאִין אִינוּן צַדִּיקַיָּיא, דְקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ תָּדִיר, לְזַכָּאָה לוֹן לְעַלְמָא דְאָתֵי וּלְמֶחֱדֵי לְהוּ בְּחֵידוּ דְצַדִּיקַיָיא דִּזְמִינִין לְמֶחדֵי בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִיב, (תהילים ה׳:י״ב) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנִּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךָ אוֹהֲבֵי שְׁמֶךָ. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן ואָמֵן:"],[[0,"כי רב מאד מחנהו:","הוא כמו שאתה אומר היש מספר לגדודיו, שכמה ממונים ושליחים יש להקב\"ה, וכולם עומדים להשטין על ישראל, וע\"כ נזדמן הקב\"ה לפני ישראל, כמ\"ש לעיל, והויה נתן קולו לפני חילו, כדי לשמרם ולא יוכלו לקטרג עליהם."],[1,"כי עצום עושה דברו:","שואל מי הוא עצום. ומשיב זהו אותו הצדיק שעוסק בתורה ימים ולילות. פירוש אחר. \u0003כי עצום,\u0004 זהו המקטרג הנמצא לפני הקב\"ה, והוא חזק כברזל, וחזק כאבן. \u0003עושה דברו,\u0004 שמקבל רשות מלמעלה מהקב\"ה, ומוציא הנשמה למטה."],[2,"כי גדול יום ה' וגו':","שהוא שולט על כל, ועליון ותקיף על כל, והכל נמצאים תחת ממשלתו, אשריהם הצדיקים, שהקב\"ה חפץ בהם תמיד, לזכותם לעולם הבא ולשמחם בשמחת הצדיקים העתידים לשמוח בהקב\"ה, שכתוב, וישמחו כל חוסי בך וגו'. ברוך ה' לעולם אמן ואמן."]],[[0,"","כִּי רַב מְאֹד מַחֲנֵהוּ - כְּמוֹ שֶׁנֶּאֱמַר (איוב כה) הֲיֵשׁ מִסְפָּר לִגְדוּדָיו. שֶׁכַּמָּה מְמֻנִּים וּשְׁלוּחִים יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְכֻלָּם עוֹמְדִים לְהַשְׂטִין עַל יִשְׂרָאֵל (ז\"ח כדי לטמא אותם), וְעַל כֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא מִזְדַּמֵּן לִפְנֵי יִשְׂרָאֵל כְּדֵי לִשְׁמֹר אוֹתָם, וְלֹא יוּכְלוּ לְקַטְרֵג לָהֶם."],[1,"","כִּי עָצוּם עֹשֵׂה דְבָרוֹ, מִי עָצוּם? זֶהוּ הַצַּדִּיק, אוֹתוֹ שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה הַקְּדוֹשָׁה יוֹמָם וָלַיְלָה. דָּבָר אַחֵר כִּי עָצוּם - זֶה הַמְקַטְרֵג שֶׁנִּמְצָא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא חָזָק כְּבַרְזֶל, קָשֶׁה כַּסֶּלַע. עֹשֵׂה דְבָרוֹ - שֶׁנּוֹטֵל רְשׁוּת מִלְמַעְלָה, וְנוֹטֵל אֶת הַנְּשָׁמָה מִלְּמַטָּה."],[2,"","כִּי גָדוֹל יוֹם ה' וְנוֹרָא מְאֹד וּמִי יְכִילֶנּוּ - שֶׁהוּא שׁוֹלֵט עַל הַכֹּל וְעֶלְיוֹן וְתַקִּיף עַל כֻּלָּם, וְכֻלָּם תַּחַת שִׁלְטוֹנוֹ. אַשְׁרֵי הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָהֶם תָּמִיד לְזַכּוֹת אוֹתָם לָעוֹלָם הַבָּא וּלְשַׂמֵּחַ אוֹתָם בְּשִׂמְחַת הַצַּדִּיקִים שֶׁעֲתִידִים לִשְׂמֹחַ עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (תהלים ה) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנֵּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךְ אֹהֲבֵי שְׁמֶךְ. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."]]]]};
